INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-1-u1-C1','math',6,1,'u1',2,'나누어떨어지지 않는 나눗셈 — 몫과 나머지로만 두면 한 사람 몫을 알 수 없음을 알고, 남은 것까지 똑같이 나누면 몫을 분수로 적을 수 있음을 알며 약분·분수의 곱셈을 되짚기',ARRAY['6수01-10']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-1-u1-C2','math',6,1,'u1',2,'몫이 1보다 작은 (자연수)÷(자연수) — 1을 나누는 수만큼 똑같이 나눈 한 조각을 바탕으로 나누어지는 수는 분자, 나누는 수는 분모로 몫을 나타내고, 나누어지는 수가 더 작아도 나눌 수 있음을 알기',ARRAY['6수01-10']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-1-u1-C3','math',6,1,'u1',3,'몫이 1보다 큰 (자연수)÷(자연수) — 먼저 1씩 나누고 남은 것을 마저 나누거나 모두 똑같이 잘라 나누어, 몫을 대분수와 가분수로 나타내고 두 몫이 같은 수임을 알기',ARRAY['6수01-10']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-1-u1-C4','math',6,1,'u1',4,'(자연수)÷(자연수)를 분수의 곱셈으로 — ÷(자연수)는 그 수만큼 똑같이 나눈 것 중의 1이므로 나누는 수를 분모로 하는 단위분수를 곱하는 것과 같고, 나누는 수를 그대로 곱하면 커져 안 됨을 알기',ARRAY['6수01-10']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-1-u1-C5','math',6,1,'u1',5,'(진분수)÷(자연수) — 분자가 나누어떨어지면 분자만 나누어도 되고, 나누어떨어지지 않으면 (진분수) × (단위분수)로 바꾸어 계산하며, 1보다 큰 자연수로 나눈 몫은 처음 분수보다 작음을 알기',ARRAY['6수01-10']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-1-u1-C6','math',6,1,'u1',6,'(대분수)÷(자연수) — 대분수를 먼저 가분수로 고친 뒤 나누는 수의 단위분수를 곱하고, 자연수 부분이나 분수 부분만 나누는 실수를 피하며 몫을 약분해 대분수로 나타내기',ARRAY['6수01-10']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-1-u1-C7','math',6,1,'u1',7,'문제 해결 — 수평인 저울에서 양쪽의 같은 것을 덜어 내 「노란 뚜껑 1개 = 파란 뚜껑 몇 개」 관계를 찾고, 그 수로 무게를 나누어 한 개의 무게를 구하며 조건을 바꾸어 새 문제를 풀기',ARRAY['6수01-10']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u1-X01','math',6,'u1',ARRAY['M6-1-u1-C1','M6-1-u1-C2','M6-1-u1-C3']::text[],'몫을 분수로 적을 때 분자·분모 자리를 잘못 둔다(2 ÷ 3을 ⟨3/2⟩나 ⟨1/3⟩로)','나누어지는 수가 분자, 나누는 수가 분모') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u1-X02','math',6,'u1',ARRAY['M6-1-u1-C1','M6-1-u1-C3']::text[],'나누어떨어지지 않으면 더 나눌 수 없다고 보거나 몫과 나머지로만 둔다','남은 것도 마저 나누면 분수') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u1-X03','math',6,'u1',ARRAY['M6-1-u1-C1','M6-1-u1-C2','M6-1-u1-C3']::text[],'작은 수를 큰 수로는 나눌 수 없다고 보거나, 몫이 1보다 작은지·큰지를 잘못 가린다','나누어지는 수가 작으면 몫은 1보다 작아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u1-X04','math',6,'u1',ARRAY['M6-1-u1-C3']::text[],'몫을 대분수로 나타낼 때 자연수 부분·분자·분모 자리를 잘못 둔다(13 ÷ 5를 ⟨3 2/5⟩나 ⟨2 3/13⟩로)','몫은 자연수, 나머지는 분자') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u1-X05','math',6,'u1',ARRAY['M6-1-u1-C3','M6-1-u1-C6','M6-1-u1-C7']::text[],'대분수를 가분수로 잘못 고친다(자연수와 분자를 더하거나 곱하고, 분모를 곱하지 않는다)','자연수 × 분모 + 분자') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u1-X06','math',6,'u1',ARRAY['M6-1-u1-C4','M6-1-u1-C5','M6-1-u1-C6','M6-1-u1-C7']::text[],'÷(자연수)를 ×(자연수)로 바꾸어 나누는 수를 그대로 곱한다','나누면 작아져요 — 단위분수를 곱해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u1-X07','math',6,'u1',ARRAY['M6-1-u1-C4','M6-1-u1-C5','M6-1-u1-C6']::text[],'곱셈으로 바꿀 때 단위분수를 잘못 만든다(나누어지는 수를 단위분수로 하거나 분수를 뒤집는다)','나누는 수를 분모로 하는 단위분수') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u1-X08','math',6,'u1',ARRAY['M6-1-u1-C5']::text[],'(분수)÷(자연수)에서 분모를 자연수로 나누거나 분자와 분모를 함께 나눈다','분모가 아니라 분자를 나눠요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u1-X09','math',6,'u1',ARRAY['M6-1-u1-C5','M6-1-u1-C6']::text[],'나눗셈 대신 분모에 나누는 수를 더하거나 분자에서 뺀다(연산을 섞는다)','나누기는 단위분수를 곱하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u1-X10','math',6,'u1',ARRAY['M6-1-u1-C6','M6-1-u1-C7']::text[],'대분수를 가분수로 고치지 않고 자연수 부분만 또는 분수 부분만 나눈다','대분수는 먼저 가분수로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u1-X11','math',6,'u1',ARRAY['M6-1-u1-C2','M6-1-u1-C3','M6-1-u1-C4','M6-1-u1-C5','M6-1-u1-C6']::text[],'몫을 견줄 때 나누는 수가 클수록 몫이 크다고 여기거나, 나누어지는 수만 보고 판단한다','같은 양을 더 많이 나누면 작아져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u1-X12','math',6,'u1',ARRAY['M6-1-u1-C1','M6-1-u1-C3','M6-1-u1-C5','M6-1-u1-C6']::text[],'계산 마무리 실수 — 약분하지 않거나 가분수·대분수로 잘못 고친다','몫은 약분해서 대분수로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u1-X13','math',6,'u1',ARRAY['M6-1-u1-C7']::text[],'저울에서 양쪽의 같은 것을 덜어 내지 않고 관계를 잘못 찾는다(노란 1개 = 파란 5개로 본다)','양쪽에서 같은 것을 덜어 내기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u1-X14','math',6,'u1',ARRAY['M6-1-u1-C1','M6-1-u1-C2','M6-1-u1-C4','M6-1-u1-C5','M6-1-u1-C7']::text[],'문장에서 식을 거꾸로 세우거나 나눗셈 대신 다른 연산을 쓴다','「무엇을 몇으로」 나누나요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u1-X15','math',6,'u1',ARRAY['M6-1-u1-C1','M6-1-u1-C2','M6-1-u1-C3','M6-1-u1-C4','M6-1-u1-C5','M6-1-u1-C6','M6-1-u1-C7']::text[],'묻는 말을 거꾸로 읽거나 놓친다 — 잘못된↔알맞은, 큰↔작은, 분자↔분모·합','물음의 「잘못·가장·분모」에 동그라미') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L02_basic#1','math',6,1,'u1','L02','g6_1_math_u1_L02_basic','lesson_basic','M6-1-u1-C1',1,'mc','auto','과자 반죽 2개를 3명이 똑같이 나누어 가지려고 해요. 한 명이 가지는 과자 반죽을 구하는 식으로 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u1-X14']::text[],true,'{"seq":1,"concept":"M6-1-u1-C1","difficulty":1,"kind":"mc","stem":"과자 반죽 2개를 3명이 똑같이 나누어 가지려고 해요. 한 명이 가지는 과자 반죽을 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"2 ÷ 3","correct":true},{"t":"3 ÷ 2","mis":"M6-1-u1-X14"},{"t":"2 × 3","mis":"M6-1-u1-X14"},{"t":"2 + 3","mis":"M6-1-u1-X14"}],"explanation":["전체 2개를 3으로 똑같이 나누는 거예요.","나누어지는 수 2가 앞, 나누는 수 3이 뒤에 와요.","그래서 식은 2 ÷ 3이에요."],"variant_rule":{"alt":[{"stem":"시루떡 3개를 4명이 똑같이 나누어 먹으려고 해요. 한 명이 먹는 시루떡을 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"3 ÷ 4","correct":true},{"t":"4 ÷ 3","mis":"M6-1-u1-X14"},{"t":"3 × 4","mis":"M6-1-u1-X14"},{"t":"3 + 4","mis":"M6-1-u1-X14"}],"explanation":["전체 3개를 4로 똑같이 나누는 거예요.","나누어지는 수 3이 앞, 나누는 수 4가 뒤에 와요.","그래서 식은 3 ÷ 4예요."]},{"stem":"흰 종이 2장을 5명이 똑같이 나누어 가지려고 해요. 한 명이 가지는 흰 종이를 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"2 ÷ 5","correct":true},{"t":"5 ÷ 2","mis":"M6-1-u1-X14"},{"t":"2 × 5","mis":"M6-1-u1-X14"},{"t":"2 + 5","mis":"M6-1-u1-X14"}],"explanation":["전체 2장을 5로 똑같이 나누는 거예요.","나누어지는 수 2가 앞, 나누는 수 5가 뒤에 와요.","그래서 식은 2 ÷ 5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L02_basic#2','math',6,1,'u1','L02','g6_1_math_u1_L02_basic','lesson_basic','M6-1-u1-C2',1,'mc','auto','시루떡 1개를 4명이 똑같이 나누어 먹으려고 해요. 한 명이 먹는 시루떡은 몇 개인지 분수로 나타내면 얼마인가요?',ARRAY['M6-1-u1-X01','M6-1-u1-X09']::text[],true,'{"seq":2,"concept":"M6-1-u1-C2","difficulty":1,"kind":"mc","stem":"시루떡 1개를 4명이 똑같이 나누어 먹으려고 해요. 한 명이 먹는 시루떡은 몇 개인지 분수로 나타내면 얼마인가요?","options":[{"t":"⟨1/4⟩","correct":true},{"t":"4","mis":"M6-1-u1-X01"},{"t":"⟨1/5⟩","mis":"M6-1-u1-X09"},{"t":"1","mis":"M6-1-u1-X01"}],"explanation":["시루떡 1개를 4로 똑같이 나누는 것은 1 ÷ 4예요.","나누어지는 수 1은 분자, 나누는 수 4는 분모가 돼요.","1 ÷ 4 = ⟨1/4⟩ — ⟨1/4⟩개예요."],"variant_rule":{"alt":[{"stem":"식빵 1개를 6명이 똑같이 나누어 먹으려고 해요. 한 명이 먹는 식빵은 몇 개인지 분수로 나타내면 얼마인가요?","options":[{"t":"⟨1/6⟩","correct":true},{"t":"6","mis":"M6-1-u1-X01"},{"t":"⟨1/7⟩","mis":"M6-1-u1-X09"},{"t":"1","mis":"M6-1-u1-X01"}],"explanation":["식빵 1개를 6으로 똑같이 나누는 것은 1 ÷ 6이에요.","나누어지는 수 1은 분자, 나누는 수 6은 분모가 돼요.","1 ÷ 6 = ⟨1/6⟩ — ⟨1/6⟩개예요."]},{"stem":"과자 반죽 2개를 3명이 똑같이 나누어 가지려고 해요. 한 명이 가지는 과자 반죽은 몇 개인지 분수로 나타내면 얼마인가요?","options":[{"t":"⟨2/3⟩","correct":true},{"t":"⟨1 1/2⟩","mis":"M6-1-u1-X01"},{"t":"⟨1/3⟩","mis":"M6-1-u1-X01"},{"t":"⟨2/5⟩","mis":"M6-1-u1-X09"}],"explanation":["과자 반죽 2개를 3으로 똑같이 나누는 것은 2 ÷ 3이에요.","나누어지는 수 2는 분자, 나누는 수 3은 분모가 돼요.","2 ÷ 3 = ⟨2/3⟩ — ⟨2/3⟩개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L02_basic#3','math',6,1,'u1','L02','g6_1_math_u1_L02_basic','lesson_basic','M6-1-u1-C2',1,'sa','auto','3 ÷ 5의 몫을 분수로 나타낼 때 분자에 오는 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M6-1-u1-C2","difficulty":1,"kind":"sa","stem":"3 ÷ 5의 몫을 분수로 나타낼 때 분자에 오는 수는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["(자연수)÷(자연수)의 몫은 분수로 나타낼 수 있어요.","나누어지는 수 3은 분자, 나누는 수 5는 분모예요.","3 ÷ 5 = ⟨3/5⟩이니 분자는 3이에요."],"mis":"M6-1-u1-X01","variant_rule":{"alt":[{"stem":"2 ÷ 7의 몫을 분수로 나타낼 때 분모에 오는 수는 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["(자연수)÷(자연수)의 몫은 분수로 나타낼 수 있어요.","나누어지는 수 2는 분자, 나누는 수 7은 분모예요.","2 ÷ 7 = ⟨2/7⟩니 분모는 7이에요."]},{"stem":"4 ÷ 9의 몫을 분수로 나타낼 때 분자에 오는 수는 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["(자연수)÷(자연수)의 몫은 분수로 나타낼 수 있어요.","나누어지는 수 4는 분자, 나누는 수 9는 분모예요.","4 ÷ 9 = ⟨4/9⟩니 분자는 4예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L02_basic#4','math',6,1,'u1','L02','g6_1_math_u1_L02_basic','lesson_basic','M6-1-u1-C1',1,'mc','auto','⟨9/36⟩를 약분하여 가장 간단한 분수로 나타내면 어느 것인가요?',ARRAY['M6-1-u1-X01','M6-1-u1-X12']::text[],true,'{"seq":4,"concept":"M6-1-u1-C1","difficulty":1,"kind":"mc","stem":"⟨9/36⟩를 약분하여 가장 간단한 분수로 나타내면 어느 것인가요?","options":[{"t":"⟨1/4⟩","correct":true},{"t":"⟨4/1⟩","mis":"M6-1-u1-X01"},{"t":"⟨1/5⟩","mis":"M6-1-u1-X12"},{"t":"⟨1/2⟩","mis":"M6-1-u1-X12"}],"explanation":["분모와 분자를 같은 수로 나누는 것이 약분이에요.","9와 36의 최대공약수는 9예요.","9 ÷ 9 = 1, 36 ÷ 9 = 4라 ⟨9/36⟩ = ⟨1/4⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨12/18⟩를 약분하여 가장 간단한 분수로 나타내면 어느 것인가요?","options":[{"t":"⟨2/3⟩","correct":true},{"t":"⟨3/2⟩","mis":"M6-1-u1-X01"},{"t":"⟨1/2⟩","mis":"M6-1-u1-X12"},{"t":"1","mis":"M6-1-u1-X12"}],"explanation":["분모와 분자를 같은 수로 나누는 것이 약분이에요.","12와 18의 최대공약수는 6이에요.","12 ÷ 6 = 2, 18 ÷ 6 = 3이라 ⟨12/18⟩ = ⟨2/3⟩예요."]},{"stem":"⟨15/45⟩를 약분하여 가장 간단한 분수로 나타내면 어느 것인가요?","options":[{"t":"⟨1/3⟩","correct":true},{"t":"⟨3/1⟩","mis":"M6-1-u1-X01"},{"t":"⟨1/4⟩","mis":"M6-1-u1-X12"},{"t":"⟨2/3⟩","mis":"M6-1-u1-X12"}],"explanation":["분모와 분자를 같은 수로 나누는 것이 약분이에요.","15와 45의 최대공약수는 15예요.","15 ÷ 15 = 1, 45 ÷ 15 = 3이라 ⟨15/45⟩ = ⟨1/3⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L02_basic#5','math',6,1,'u1','L02','g6_1_math_u1_L02_basic','lesson_basic','M6-1-u1-C1',2,'mc','auto','2 ÷ 3은 나누어떨어지지 않아요. 이 나눗셈의 몫을 나타내는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u1-X02','M6-1-u1-X14']::text[],true,'{"seq":5,"concept":"M6-1-u1-C1","difficulty":2,"kind":"mc","stem":"2 ÷ 3은 나누어떨어지지 않아요. 이 나눗셈의 몫을 나타내는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"남은 것도 똑같이 나누어 몫을 분수로 적는다","correct":true},{"t":"나눌 수 없다고 적는다","mis":"M6-1-u1-X02"},{"t":"몫 0, 나머지 2로만 적고 끝낸다","mis":"M6-1-u1-X02"},{"t":"나누어지는 수를 3으로 바꾸어 나눈다","mis":"M6-1-u1-X14"}],"explanation":["2 ÷ 3을 몫과 나머지로만 두면 한 사람이 실제로 얼마를 가지는지 알 수 없어요.","남은 2도 3으로 똑같이 나누어 줄 수 있어요.","그러면 몫을 ⟨2/3⟩처럼 분수로 적을 수 있어요."],"variant_rule":{"alt":[{"stem":"3 ÷ 5는 나누어떨어지지 않아요. 이 나눗셈의 몫을 나타내는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"남은 것도 똑같이 나누어 몫을 분수로 적는다","correct":true},{"t":"나눌 수 없다고 적는다","mis":"M6-1-u1-X02"},{"t":"몫 0, 나머지 3로만 적고 끝낸다","mis":"M6-1-u1-X02"},{"t":"나누어지는 수를 5로 바꾸어 나눈다","mis":"M6-1-u1-X14"}],"explanation":["3 ÷ 5를 몫과 나머지로만 두면 한 사람이 실제로 얼마를 가지는지 알 수 없어요.","남은 3도 5로 똑같이 나누어 줄 수 있어요.","그러면 몫을 ⟨3/5⟩처럼 분수로 적을 수 있어요."]},{"stem":"5 ÷ 4는 나누어떨어지지 않아요. 이 나눗셈의 몫을 나타내는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"남은 것도 똑같이 나누어 몫을 분수로 적는다","correct":true},{"t":"나눌 수 없다고 적는다","mis":"M6-1-u1-X02"},{"t":"몫 1, 나머지 1로만 적고 끝낸다","mis":"M6-1-u1-X02"},{"t":"나누어지는 수를 4로 바꾸어 나눈다","mis":"M6-1-u1-X14"}],"explanation":["5 ÷ 4를 몫과 나머지로만 두면 한 사람이 실제로 얼마를 가지는지 알 수 없어요.","남은 1도 4로 똑같이 나누어 줄 수 있어요.","그러면 몫을 ⟨1 1/4⟩처럼 분수로 적을 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L02_basic#6','math',6,1,'u1','L02','g6_1_math_u1_L02_basic','lesson_basic','M6-1-u1-C1',2,'sa','auto','과자 반죽 2개를 3명이 나누려고 과자 반죽을 하나씩 모두 3조각으로 잘랐어요. 조각은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M6-1-u1-C1","difficulty":2,"kind":"sa","stem":"과자 반죽 2개를 3명이 나누려고 과자 반죽을 하나씩 모두 3조각으로 잘랐어요. 조각은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["과자 반죽 하나를 3조각으로 잘라요.","과자 반죽 2개 모두 자르면 2 × 3 = 6조각이에요.","그래서 조각은 모두 6개예요."],"mis":"M6-1-u1-X15","variant_rule":{"alt":[{"stem":"시루떡 3개를 4명이 나누려고 시루떡을 하나씩 모두 4조각으로 잘랐어요. 한 명이 가지는 조각은 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["조각은 모두 3 × 4 = 12개예요.","12조각을 4명이 똑같이 나누면 12 ÷ 4 = 3조각씩이에요.","한 조각이 ⟨1/4⟩이니 한 명 몫은 ⟨3/4⟩이에요."]},{"stem":"피자 2판을 5명이 나누려고 피자를 하나씩 모두 5조각으로 잘랐어요. 조각은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["피자 하나를 5조각으로 잘라요.","피자 2판 모두 자르면 2 × 5 = 10조각이에요.","그래서 조각은 모두 10개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L02_basic#7','math',6,1,'u1','L02','g6_1_math_u1_L02_basic','lesson_basic','M6-1-u1-C2',2,'mc','auto','3 ÷ 8의 몫을 분수로 나타내면 얼마인가요?',ARRAY['M6-1-u1-X01','M6-1-u1-X09']::text[],true,'{"seq":7,"concept":"M6-1-u1-C2","difficulty":2,"kind":"mc","stem":"3 ÷ 8의 몫을 분수로 나타내면 얼마인가요?","options":[{"t":"⟨3/8⟩","correct":true},{"t":"⟨2 2/3⟩","mis":"M6-1-u1-X01"},{"t":"⟨1/8⟩","mis":"M6-1-u1-X01"},{"t":"⟨3/11⟩","mis":"M6-1-u1-X09"}],"explanation":["1 ÷ 8 = ⟨1/8⟩ — 1을 8로 나눈 한 조각이에요.","3 ÷ 8은 그 조각이 3개예요.","3 ÷ 8 = ⟨3/8⟩이에요."],"variant_rule":{"alt":[{"stem":"5 ÷ 9의 몫을 분수로 나타내면 얼마인가요?","options":[{"t":"⟨5/9⟩","correct":true},{"t":"⟨1 4/5⟩","mis":"M6-1-u1-X01"},{"t":"⟨1/9⟩","mis":"M6-1-u1-X01"},{"t":"⟨5/14⟩","mis":"M6-1-u1-X09"}],"explanation":["1 ÷ 9 = ⟨1/9⟩ — 1을 9로 나눈 한 조각이에요.","5 ÷ 9는 그 조각이 5개예요.","5 ÷ 9 = ⟨5/9⟩예요."]},{"stem":"4 ÷ 7의 몫을 분수로 나타내면 얼마인가요?","options":[{"t":"⟨4/7⟩","correct":true},{"t":"⟨1 3/4⟩","mis":"M6-1-u1-X01"},{"t":"⟨1/7⟩","mis":"M6-1-u1-X01"},{"t":"⟨4/11⟩","mis":"M6-1-u1-X09"}],"explanation":["1 ÷ 7 = ⟨1/7⟩ — 1을 7로 나눈 한 조각이에요.","4 ÷ 7은 그 조각이 4개예요.","4 ÷ 7 = ⟨4/7⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L02_basic#8','math',6,1,'u1','L02','g6_1_math_u1_L02_basic','lesson_basic','M6-1-u1-C2',2,'mc','auto','몫이 1보다 작은 나눗셈은 어느 것인가요?',ARRAY['M6-1-u1-X03']::text[],true,'{"seq":8,"concept":"M6-1-u1-C2","difficulty":2,"kind":"mc","stem":"몫이 1보다 작은 나눗셈은 어느 것인가요?","options":[{"t":"5 ÷ 8","correct":true},{"t":"3 ÷ 3","mis":"M6-1-u1-X03"},{"t":"9 ÷ 7","mis":"M6-1-u1-X03"},{"t":"11 ÷ 4","mis":"M6-1-u1-X03"}],"explanation":["나누어지는 수가 나누는 수보다 작으면 몫은 1보다 작고, 크면 1보다 커요.","5 ÷ 8 = ⟨5/8⟩, 3 ÷ 3 = 1, 9 ÷ 7 = ⟨1 2/7⟩, 11 ÷ 4 = ⟨2 3/4⟩이에요.","그래서 몫이 1보다 작은 것은 5 ÷ 8이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 몫이 1보다 작은 나눗셈은 어느 것인가요?","options":[{"t":"4 ÷ 9","correct":true},{"t":"7 ÷ 6","mis":"M6-1-u1-X03"},{"t":"5 ÷ 5","mis":"M6-1-u1-X03"},{"t":"8 ÷ 3","mis":"M6-1-u1-X03"}],"explanation":["나누어지는 수가 나누는 수보다 작으면 몫은 1보다 작고, 크면 1보다 커요.","7 ÷ 6 = ⟨1 1/6⟩, 4 ÷ 9 = ⟨4/9⟩, 5 ÷ 5 = 1, 8 ÷ 3 = ⟨2 2/3⟩예요.","그래서 몫이 1보다 작은 것은 4 ÷ 9예요."]},{"stem":"이번에는 다른 보기예요. 몫이 1보다 작은 나눗셈은 어느 것인가요?","options":[{"t":"2 ÷ 11","correct":true},{"t":"6 ÷ 6","mis":"M6-1-u1-X03"},{"t":"10 ÷ 9","mis":"M6-1-u1-X03"},{"t":"13 ÷ 5","mis":"M6-1-u1-X03"}],"explanation":["나누어지는 수가 나누는 수보다 작으면 몫은 1보다 작고, 크면 1보다 커요.","6 ÷ 6 = 1, 10 ÷ 9 = ⟨1 1/9⟩, 2 ÷ 11 = ⟨2/11⟩, 13 ÷ 5 = ⟨2 3/5⟩이에요.","그래서 몫이 1보다 작은 것은 2 ÷ 11이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L02_basic#9','math',6,1,'u1','L02','g6_1_math_u1_L02_basic','lesson_basic','M6-1-u1-C2',2,'match','auto','나눗셈과 몫을 알맞게 이으세요.','{}'::text[],true,'{"seq":9,"concept":"M6-1-u1-C2","difficulty":2,"kind":"match","stem":"나눗셈과 몫을 알맞게 이으세요.","pairs":[{"l":"1 ÷ 3","r":"⟨1/3⟩"},{"l":"2 ÷ 5","r":"⟨2/5⟩"},{"l":"4 ÷ 7","r":"⟨4/7⟩"}],"mis":"M6-1-u1-X01","explanation":["나누어지는 수가 분자, 나누는 수가 분모예요.","1 ÷ 3 = ⟨1/3⟩, 2 ÷ 5 = ⟨2/5⟩, 4 ÷ 7 = ⟨4/7⟩예요.","분자와 분모 자리를 바꾸지 않도록 해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 나눗셈과 몫을 알맞게 이으세요.","pairs":[{"l":"3 ÷ 4","r":"⟨3/4⟩"},{"l":"1 ÷ 6","r":"⟨1/6⟩"},{"l":"5 ÷ 8","r":"⟨5/8⟩"}],"explanation":["나누어지는 수가 분자, 나누는 수가 분모예요.","3 ÷ 4 = ⟨3/4⟩, 1 ÷ 6 = ⟨1/6⟩, 5 ÷ 8 = ⟨5/8⟩예요.","분자와 분모 자리를 바꾸지 않도록 해요."]},{"stem":"이번에는 다른 보기예요. 나눗셈과 몫을 알맞게 이으세요.","pairs":[{"l":"2 ÷ 9","r":"⟨2/9⟩"},{"l":"7 ÷ 10","r":"⟨7/10⟩"},{"l":"3 ÷ 11","r":"⟨3/11⟩"}],"explanation":["나누어지는 수가 분자, 나누는 수가 분모예요.","2 ÷ 9 = ⟨2/9⟩, 7 ÷ 10 = ⟨7/10⟩, 3 ÷ 11 = ⟨3/11⟩이에요.","분자와 분모 자리를 바꾸지 않도록 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L02_basic#10','math',6,1,'u1','L02','g6_1_math_u1_L02_basic','lesson_basic','M6-1-u1-C2',3,'mc','auto','가 모둠은 시루떡 3개를 4명이, 나 모둠은 시루떡 4개를 5명이 똑같이 나누었어요. 한 명이 가지는 시루떡이 더 많은 모둠은 어디인가요?',ARRAY['M6-1-u1-X11','M6-1-u1-X03']::text[],true,'{"seq":10,"concept":"M6-1-u1-C2","difficulty":3,"kind":"mc","stem":"가 모둠은 시루떡 3개를 4명이, 나 모둠은 시루떡 4개를 5명이 똑같이 나누었어요. 한 명이 가지는 시루떡이 더 많은 모둠은 어디인가요?","options":[{"t":"나 모둠","correct":true},{"t":"가 모둠","mis":"M6-1-u1-X11"},{"t":"두 모둠이 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X03"}],"explanation":["가 모둠 한 명 몫은 3 ÷ 4 = ⟨3/4⟩, 나 모둠은 4 ÷ 5 = ⟨4/5⟩예요.","20으로 통분하면 ⟨3/4⟩ = ⟨15/20⟩, ⟨4/5⟩ = ⟨16/20⟩이에요.","⟨3/4⟩ < ⟨4/5⟩라 나 모둠이 더 많아요."],"variant_rule":{"alt":[{"stem":"가 모둠은 빵 2개를 3명이, 나 모둠은 빵 3개를 5명이 똑같이 나누었어요. 한 명이 가지는 빵이 더 많은 모둠은 어디인가요?","options":[{"t":"가 모둠","correct":true},{"t":"나 모둠","mis":"M6-1-u1-X11"},{"t":"두 모둠이 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X03"}],"explanation":["가 모둠 한 명 몫은 2 ÷ 3 = ⟨2/3⟩, 나 모둠은 3 ÷ 5 = ⟨3/5⟩이에요.","15로 통분하면 ⟨2/3⟩ = ⟨10/15⟩, ⟨3/5⟩ = ⟨9/15⟩예요.","⟨2/3⟩ > ⟨3/5⟩이라 가 모둠이 더 많아요."]},{"stem":"가 모둠은 주스 5 L를 6명이, 나 모둠은 주스 3 L를 4명이 똑같이 나누었어요. 한 명이 가지는 주스가 더 많은 모둠은 어디인가요?","options":[{"t":"가 모둠","correct":true},{"t":"나 모둠","mis":"M6-1-u1-X11"},{"t":"두 모둠이 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X03"}],"explanation":["가 모둠 한 명 몫은 5 ÷ 6 = ⟨5/6⟩, 나 모둠은 3 ÷ 4 = ⟨3/4⟩이에요.","12로 통분하면 ⟨5/6⟩ = ⟨10/12⟩, ⟨3/4⟩ = ⟨9/12⟩예요.","⟨5/6⟩ > ⟨3/4⟩이라 가 모둠이 더 많아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L02_challenge#1','math',6,1,'u1','L02','g6_1_math_u1_L02_challenge','lesson_challenge','M6-1-u1-C2',2,'sa','auto','주스 5 L를 8명이 똑같이 나누어 마시려고 해요. 한 명이 마시는 주스를 분수로 나타낼 때 분모와 분자의 합은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M6-1-u1-C2","difficulty":2,"kind":"sa","stem":"주스 5 L를 8명이 똑같이 나누어 마시려고 해요. 한 명이 마시는 주스를 분수로 나타낼 때 분모와 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["주스 5 L를 8로 나누니 5 ÷ 8이에요.","5 ÷ 8 = ⟨5/8⟩예요.","분모와 분자의 합은 8 + 5 = 13이에요."],"mis":"M6-1-u1-X15","variant_rule":{"alt":[{"stem":"색 테이프 3 m를 7명이 똑같이 나누어 가지려고 해요. 한 명이 가지는 색 테이프를 분수로 나타낼 때 분모와 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["색 테이프 3 m를 7로 나누니 3 ÷ 7이에요.","3 ÷ 7 = ⟨3/7⟩이에요.","분모와 분자의 합은 7 + 3 = 10이에요."]},{"stem":"색 모래 4 kg을 9모둠이 똑같이 나누어 가지려고 해요. 한 모둠이 가지는 색 모래를 분수로 나타낼 때 분모와 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["색 모래 4 kg을 9로 나누니 4 ÷ 9예요.","4 ÷ 9 = ⟨4/9⟩예요.","분모와 분자의 합은 9 + 4 = 13이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L02_challenge#2','math',6,1,'u1','L02','g6_1_math_u1_L02_challenge','lesson_challenge','M6-1-u1-C1',2,'ox','auto','2 ÷ 3을 「몫 0, 나머지 2」로만 적어도 한 사람이 실제로 얼마를 가지는지 알 수 있어요.',ARRAY['M6-1-u1-X02']::text[],true,'{"seq":2,"concept":"M6-1-u1-C1","difficulty":2,"kind":"ox","stem":"2 ÷ 3을 「몫 0, 나머지 2」로만 적어도 한 사람이 실제로 얼마를 가지는지 알 수 있어요.","answer":"X","reason_options":[{"t":"남은 2도 마저 나눌 수 있는데 나누지 않아 한 사람 몫을 알 수 없어서","correct":true},{"t":"몫과 나머지만 알면 한 사람 몫을 모두 알 수 있어서","mis":"M6-1-u1-X02"}],"mis":"M6-1-u1-X02","explanation":["나머지 2는 아직 나누지 않은 양이에요.","남은 것도 3으로 똑같이 나누어야 한 사람 몫이 정해져요.","2 ÷ 3 = ⟨2/3⟩ — 몫을 분수로 적으면 한 사람 몫이 보여요."],"variant_rule":{"alt":[{"stem":"3 ÷ 4를 「몫 0, 나머지 3」로만 적어도 한 사람이 실제로 얼마를 가지는지 알 수 있어요.","answer":"X","reason_options":[{"t":"남은 3도 마저 나눌 수 있는데 나누지 않아 한 사람 몫을 알 수 없어서","correct":true},{"t":"몫과 나머지만 알면 한 사람 몫을 모두 알 수 있어서","mis":"M6-1-u1-X02"}],"explanation":["나머지 3은 아직 나누지 않은 양이에요.","남은 것도 4로 똑같이 나누어야 한 사람 몫이 정해져요.","3 ÷ 4 = ⟨3/4⟩ — 몫을 분수로 적으면 한 사람 몫이 보여요."]},{"stem":"5 ÷ 6을 「몫 0, 나머지 5」로만 적어도 한 사람이 실제로 얼마를 가지는지 알 수 있어요.","answer":"X","reason_options":[{"t":"남은 5도 마저 나눌 수 있는데 나누지 않아 한 사람 몫을 알 수 없어서","correct":true},{"t":"몫과 나머지만 알면 한 사람 몫을 모두 알 수 있어서","mis":"M6-1-u1-X02"}],"explanation":["나머지 5는 아직 나누지 않은 양이에요.","남은 것도 6으로 똑같이 나누어야 한 사람 몫이 정해져요.","5 ÷ 6 = ⟨5/6⟩ — 몫을 분수로 적으면 한 사람 몫이 보여요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L02_challenge#3','math',6,1,'u1','L02','g6_1_math_u1_L02_challenge','lesson_challenge','M6-1-u1-C2',3,'error','auto','(자연수)÷(자연수)에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u1-X03','M6-1-u1-X15']::text[],true,'{"seq":3,"concept":"M6-1-u1-C2","difficulty":3,"kind":"error","stem":"(자연수)÷(자연수)에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「나누어지는 수가 나누는 수보다 커야만 나눌 수 있어.」","correct":true,"mis_target":"M6-1-u1-X03"},{"t":"도윤 — 「나누는 수가 분모, 나누어지는 수가 분자가 돼.」","mis":"M6-1-u1-X15"},{"t":"하린 — 「몫이 1보다 작을 수도 있어.」","mis":"M6-1-u1-X15"}],"explanation":["1 ÷ 4처럼 나누어지는 수가 더 작아도 똑같이 나눌 수 있어요.","그때 한 명 몫은 1보다 작은 ⟨1/4⟩이 될 뿐이에요.","수아는 작은 수는 나눌 수 없다고 잘못 말했어요."],"variant_rule":{"alt":[{"stem":"3 ÷ 5의 몫을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민준 — 「몫은 ⟨5/3⟩야.」","correct":true,"mis_target":"M6-1-u1-X01"},{"t":"서연 — 「몫은 ⟨3/5⟩이야.」","mis":"M6-1-u1-X15"},{"t":"지호 — 「몫은 1보다 작아.」","mis":"M6-1-u1-X15"}],"explanation":["3 ÷ 5에서 나누어지는 수 3은 분자, 나누는 수 5는 분모예요.","3 ÷ 5 = ⟨3/5⟩ — 1보다 작아요.","민준은 분자와 분모를 거꾸로 적었어요."]},{"stem":"4 ÷ 9의 몫을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「몫은 ⟨9/4⟩야.」","correct":true,"mis_target":"M6-1-u1-X01"},{"t":"나린 — 「몫은 ⟨4/9⟩야.」","mis":"M6-1-u1-X15"},{"t":"유진 — 「몫은 1보다 작아.」","mis":"M6-1-u1-X15"}],"explanation":["4 ÷ 9에서 나누어지는 수 4는 분자, 나누는 수 9는 분모예요.","4 ÷ 9 = ⟨4/9⟩ — 1보다 작아요.","가온은 분자와 분모를 거꾸로 적었어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L02_challenge#4','math',6,1,'u1','L02','g6_1_math_u1_L02_challenge','lesson_challenge','M6-1-u1-C2',3,'sa','auto','□ ÷ 7 = ⟨3/7⟩일 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M6-1-u1-C2","difficulty":3,"kind":"sa","stem":"□ ÷ 7 = ⟨3/7⟩일 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["(자연수)÷(자연수)의 몫에서 나누어지는 수가 분자예요.","⟨3/7⟩의 분자는 3이에요.","3 ÷ 7 = ⟨3/7⟩이니 □는 3이에요."],"mis":"M6-1-u1-X01","variant_rule":{"alt":[{"stem":"5 ÷ □ = ⟨5/8⟩일 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["(자연수)÷(자연수)의 몫에서 나누는 수가 분모예요.","⟨5/8⟩의 분모는 8이에요.","5 ÷ 8 = ⟨5/8⟩니 □는 8이에요."]},{"stem":"□ ÷ 11 = ⟨4/11⟩일 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["(자연수)÷(자연수)의 몫에서 나누어지는 수가 분자예요.","⟨4/11⟩의 분자는 4예요.","4 ÷ 11 = ⟨4/11⟩니 □는 4예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L02_challenge#5','math',6,1,'u1','L02','g6_1_math_u1_L02_challenge','lesson_challenge','M6-1-u1-C2',3,'mc','auto','(자연수)÷(자연수)의 몫이 1보다 작아지는 때는 언제인가요?',ARRAY['M6-1-u1-X03']::text[],true,'{"seq":5,"concept":"M6-1-u1-C2","difficulty":3,"kind":"mc","stem":"(자연수)÷(자연수)의 몫이 1보다 작아지는 때는 언제인가요?","options":[{"t":"나누어지는 수가 나누는 수보다 작을 때","correct":true},{"t":"나누어지는 수가 나누는 수보다 클 때","mis":"M6-1-u1-X03"},{"t":"두 수가 같을 때","mis":"M6-1-u1-X03"},{"t":"나누는 수가 1일 때","mis":"M6-1-u1-X03"}],"explanation":["(자연수)÷(자연수)의 몫은 (나누어지는 수)를 분자, (나누는 수)를 분모로 하는 분수예요.","분자가 분모보다 작으면 1보다 작고, 같으면 1, 크면 1보다 커요.","예를 들어 3 ÷ 5 = ⟨3/5⟩이 돼요 — 그래서 답은 「나누어지는 수가 나누는 수보다 작을 때」예요."],"variant_rule":{"alt":[{"stem":"(자연수)÷(자연수)의 몫이 1보다 커지는 때는 언제인가요?","options":[{"t":"나누어지는 수가 나누는 수보다 클 때","correct":true},{"t":"나누어지는 수가 나누는 수보다 작을 때","mis":"M6-1-u1-X03"},{"t":"두 수가 같을 때","mis":"M6-1-u1-X03"},{"t":"나누는 수가 나누어지는 수보다 클 때","mis":"M6-1-u1-X03"}],"explanation":["(자연수)÷(자연수)의 몫은 (나누어지는 수)를 분자, (나누는 수)를 분모로 하는 분수예요.","분자가 분모보다 작으면 1보다 작고, 같으면 1, 크면 1보다 커요.","예를 들어 7 ÷ 4 = ⟨1 3/4⟩이 돼요 — 그래서 답은 「나누어지는 수가 나누는 수보다 클 때」예요."]},{"stem":"(자연수)÷(자연수)의 몫이 1이 되는 때는 언제인가요?","options":[{"t":"나누어지는 수와 나누는 수가 같을 때","correct":true},{"t":"나누어지는 수가 나누는 수보다 작을 때","mis":"M6-1-u1-X03"},{"t":"나누어지는 수가 나누는 수보다 클 때","mis":"M6-1-u1-X03"},{"t":"나누는 수가 1일 때","mis":"M6-1-u1-X03"}],"explanation":["(자연수)÷(자연수)의 몫은 (나누어지는 수)를 분자, (나누는 수)를 분모로 하는 분수예요.","분자가 분모보다 작으면 1보다 작고, 같으면 1, 크면 1보다 커요.","예를 들어 5 ÷ 5 = ⟨5/5⟩ = 1이 돼요 — 그래서 답은 「나누어지는 수와 나누는 수가 같을 때」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L02_challenge#6','math',6,1,'u1','L02','g6_1_math_u1_L02_challenge','lesson_challenge','M6-1-u1-C2',3,'ox','auto','1 ÷ 4의 몫은 ⟨1/4⟩이에요.',ARRAY['M6-1-u1-X03']::text[],true,'{"seq":6,"concept":"M6-1-u1-C2","difficulty":3,"kind":"ox","stem":"1 ÷ 4의 몫은 ⟨1/4⟩이에요.","answer":"O","reason_options":[{"t":"1을 4로 똑같이 나눈 한 조각이 ⟨1/4⟩이므로","correct":true},{"t":"나누어지는 수가 더 작아 나눌 수 없으므로","mis":"M6-1-u1-X03"}],"mis":"M6-1-u1-X03","explanation":["1을 4조각으로 똑같이 나누면 한 조각은 ⟨1/4⟩이에요.","나누어지는 수가 작아도 나눌 수 있어요.","1 ÷ 4 = ⟨1/4⟩ — 맞아요."],"variant_rule":{"alt":[{"stem":"2 ÷ 7의 몫은 ⟨7/2⟩이에요.","answer":"X","reason_options":[{"t":"나누어지는 수 2가 분자, 나누는 수 7이 분모라 ⟨2/7⟩이므로","correct":true},{"t":"큰 수를 분자에 두어야 하므로","mis":"M6-1-u1-X01"}],"explanation":["나누어지는 수가 분자, 나누는 수가 분모예요.","2 ÷ 7 = ⟨2/7⟩예요.","⟨7/2⟩은 거꾸로 적은 거예요."]},{"stem":"5 ÷ 8과 8 ÷ 5의 몫은 같아요.","answer":"X","reason_options":[{"t":"5 ÷ 8 = ⟨5/8⟩, 8 ÷ 5 = ⟨1 3/5⟩으로 서로 달라서","correct":true},{"t":"같은 두 수로 나누었으니 몫이 같아서","mis":"M6-1-u1-X01"}],"explanation":["5 ÷ 8 = ⟨5/8⟩ — 1보다 작아요.","8 ÷ 5 = ⟨1 3/5⟩ — 1보다 커요.","나누는 순서가 바뀌면 몫도 달라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L02_challenge#7','math',6,1,'u1','L02','g6_1_math_u1_L02_challenge','lesson_challenge','M6-1-u1-C2',3,'mc','auto','가 모둠은 피자 2판을 3명이, 나 모둠은 피자 3판을 4명이 똑같이 나누었어요. 한 명이 가지는 피자가 더 많은 모둠은 어디인가요?',ARRAY['M6-1-u1-X11','M6-1-u1-X03']::text[],true,'{"seq":7,"concept":"M6-1-u1-C2","difficulty":3,"kind":"mc","stem":"가 모둠은 피자 2판을 3명이, 나 모둠은 피자 3판을 4명이 똑같이 나누었어요. 한 명이 가지는 피자가 더 많은 모둠은 어디인가요?","options":[{"t":"나 모둠","correct":true},{"t":"가 모둠","mis":"M6-1-u1-X11"},{"t":"두 모둠이 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X03"}],"explanation":["가 모둠 한 명 몫은 2 ÷ 3 = ⟨2/3⟩, 나 모둠은 3 ÷ 4 = ⟨3/4⟩이에요.","12로 통분하면 ⟨2/3⟩ = ⟨8/12⟩, ⟨3/4⟩ = ⟨9/12⟩예요.","⟨2/3⟩ < ⟨3/4⟩이라 나 모둠이 더 많아요."],"variant_rule":{"alt":[{"stem":"가 모둠은 시루떡 4개를 7명이, 나 모둠은 시루떡 3개를 5명이 똑같이 나누었어요. 한 명이 가지는 시루떡이 더 많은 모둠은 어디인가요?","options":[{"t":"나 모둠","correct":true},{"t":"가 모둠","mis":"M6-1-u1-X11"},{"t":"두 모둠이 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X03"}],"explanation":["가 모둠 한 명 몫은 4 ÷ 7 = ⟨4/7⟩, 나 모둠은 3 ÷ 5 = ⟨3/5⟩이에요.","35로 통분하면 ⟨4/7⟩ = ⟨20/35⟩, ⟨3/5⟩ = ⟨21/35⟩이에요.","⟨4/7⟩ < ⟨3/5⟩이라 나 모둠이 더 많아요."]},{"stem":"가 모둠은 과자 반죽 5개를 8명이, 나 모둠은 과자 반죽 2개를 3명이 똑같이 나누었어요. 한 명이 가지는 과자 반죽이 더 많은 모둠은 어디인가요?","options":[{"t":"나 모둠","correct":true},{"t":"가 모둠","mis":"M6-1-u1-X11"},{"t":"두 모둠이 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X03"}],"explanation":["가 모둠 한 명 몫은 5 ÷ 8 = ⟨5/8⟩, 나 모둠은 2 ÷ 3 = ⟨2/3⟩예요.","24로 통분하면 ⟨5/8⟩ = ⟨15/24⟩, ⟨2/3⟩ = ⟨16/24⟩이에요.","⟨5/8⟩ < ⟨2/3⟩라 나 모둠이 더 많아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L02_challenge#8','math',6,1,'u1','L02','g6_1_math_u1_L02_challenge','lesson_challenge','M6-1-u1-C2',4,'sa','auto','□ ÷ 9의 몫이 1보다 작을 때, □에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M6-1-u1-C2","difficulty":4,"kind":"sa","stem":"□ ÷ 9의 몫이 1보다 작을 때, □에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["□ ÷ 9 = ⟨□/9⟩이에요.","몫이 1보다 작으려면 □가 9보다 작아야 해요.","1부터 8까지 8개예요."],"mis":"M6-1-u1-X03","variant_rule":{"alt":[{"stem":"□ ÷ 12의 몫이 1보다 작을 때, □에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["□ ÷ 12 = ⟨□/12⟩이에요.","몫이 1보다 작으려면 □가 12보다 작아야 해요.","1부터 11까지 11개예요."]},{"stem":"□ ÷ 15의 몫이 1보다 작을 때, □에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["□ ÷ 15 = ⟨□/15⟩이에요.","몫이 1보다 작으려면 □가 15보다 작아야 해요.","1부터 14까지 14개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L02_challenge#9','math',6,1,'u1','L02','g6_1_math_u1_L02_challenge','lesson_challenge','M6-1-u1-C2',4,'sa','auto','색 테이프 5 m를 몇 명이 똑같이 나누었더니 한 명이 ⟨5/8⟩ m씩 가졌어요. 나눈 사람은 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M6-1-u1-C2","difficulty":4,"kind":"sa","stem":"색 테이프 5 m를 몇 명이 똑같이 나누었더니 한 명이 ⟨5/8⟩ m씩 가졌어요. 나눈 사람은 몇 명인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["색 테이프 5 m를 □명이 나누면 한 명 몫은 5 ÷ □예요.","5 ÷ □ = ⟨5/8⟩ — 나누는 수가 분모예요.","그래서 8명이 나누었어요."],"mis":"M6-1-u1-X01","variant_rule":{"alt":[{"stem":"주스 3 L를 몇 명이 똑같이 나누었더니 한 명이 ⟨3/7⟩ L씩 가졌어요. 나눈 사람은 몇 명인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["주스 3 L를 □명이 나누면 한 명 몫은 3 ÷ □예요.","3 ÷ □ = ⟨3/7⟩ — 나누는 수가 분모예요.","그래서 7명이 나누었어요."]},{"stem":"시루떡 4개를 몇 명이 똑같이 나누었더니 한 명이 ⟨4/9⟩개씩 가졌어요. 나눈 사람은 몇 명인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["시루떡 4개를 □명이 나누면 한 명 몫은 4 ÷ □예요.","4 ÷ □ = ⟨4/9⟩ — 나누는 수가 분모예요.","그래서 9명이 나누었어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L02_challenge#10','math',6,1,'u1','L02','g6_1_math_u1_L02_challenge','lesson_challenge','M6-1-u1-C1',4,'essay','teacher','과자 반죽 2개를 3명이 똑같이 나누려고 해요. 2 ÷ 3을 「몫 0, 나머지 2」로 적으면 무엇이 부족한지 쓰고, 한 명 몫을 분수로 나타내는 방법을 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-1-u1-C1","difficulty":4,"kind":"essay","stem":"과자 반죽 2개를 3명이 똑같이 나누려고 해요. 2 ÷ 3을 「몫 0, 나머지 2」로 적으면 무엇이 부족한지 쓰고, 한 명 몫을 분수로 나타내는 방법을 설명해 보세요.","answer_guide":{"answer":"예: 몫 0, 나머지 2로 적으면 한 명이 실제로 얼마를 가지는지 알 수 없고, 남은 반죽 2개를 나누지 않고 둔 셈이 된다. 반죽 2개를 각각 3조각으로 자르면 조각은 모두 6개이고, 한 명은 2조각씩 가진다. 한 조각이 ⟨1/3⟩개이므로 한 명 몫은 ⟨2/3⟩개, 곧 2 ÷ 3 = ⟨2/3⟩이다.","scoring_points":["몫과 나머지로는 한 명 몫을 알 수 없다고 썼는가","남은 것도 똑같이 나누는 방법(조각으로 자르기)을 설명했는가","2 ÷ 3 = ⟨2/3⟩를 구했는가"]},"explanation":["몫 0, 나머지 2로는 한 명 몫이 보이지 않아요.","반죽을 3조각씩 자르면 한 명은 2조각씩 가져요.","2 ÷ 3 = ⟨2/3⟩예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L03_basic#1','math',6,1,'u1','L03','g6_1_math_u1_L03_basic','lesson_basic','M6-1-u1-C3',1,'mc','auto','빵 7개를 4명이 똑같이 나누어 먹으려고 해요. 한 명이 먹는 빵을 대분수로 나타내면 몇 개인가요?',ARRAY['M6-1-u1-X01','M6-1-u1-X02','M6-1-u1-X04']::text[],true,'{"seq":1,"concept":"M6-1-u1-C3","difficulty":1,"kind":"mc","stem":"빵 7개를 4명이 똑같이 나누어 먹으려고 해요. 한 명이 먹는 빵을 대분수로 나타내면 몇 개인가요?","options":[{"t":"⟨1 3/4⟩","correct":true},{"t":"⟨4/7⟩","mis":"M6-1-u1-X01"},{"t":"⟨3/4⟩","mis":"M6-1-u1-X02"},{"t":"⟨1 3/7⟩","mis":"M6-1-u1-X04"}],"explanation":["먼저 1씩 나누어 주면 3이 남아요 — 7 ÷ 4는 몫 1, 나머지 3이에요.","남은 3도 4로 똑같이 나누면 ⟨3/4⟩씩 더 가져요.","7 ÷ 4 = ⟨1 3/4⟩ — ⟨1 3/4⟩개예요."],"variant_rule":{"alt":[{"stem":"흰 종이 4장을 3명이 똑같이 나누어 가지려고 해요. 한 명이 가지는 흰 종이를 대분수로 나타내면 몇 장인가요?","options":[{"t":"⟨1 1/3⟩","correct":true},{"t":"⟨3/4⟩","mis":"M6-1-u1-X01"},{"t":"⟨1/3⟩","mis":"M6-1-u1-X02"},{"t":"⟨1 1/4⟩","mis":"M6-1-u1-X04"}],"explanation":["먼저 1씩 나누어 주면 1이 남아요 — 4 ÷ 3은 몫 1, 나머지 1이에요.","남은 1도 3으로 똑같이 나누면 ⟨1/3⟩씩 더 가져요.","4 ÷ 3 = ⟨1 1/3⟩ — ⟨1 1/3⟩장예요."]},{"stem":"시루떡 5개를 2명이 똑같이 나누어 먹으려고 해요. 한 명이 먹는 시루떡을 대분수로 나타내면 몇 개인가요?","options":[{"t":"⟨2 1/2⟩","correct":true},{"t":"⟨2/5⟩","mis":"M6-1-u1-X01"},{"t":"⟨1/2⟩","mis":"M6-1-u1-X02"},{"t":"⟨2 1/5⟩","mis":"M6-1-u1-X04"}],"explanation":["먼저 2씩 나누어 주면 1이 남아요 — 5 ÷ 2는 몫 2, 나머지 1이에요.","남은 1도 2로 똑같이 나누면 ⟨1/2⟩씩 더 가져요.","5 ÷ 2 = ⟨2 1/2⟩ — ⟨2 1/2⟩개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L03_basic#2','math',6,1,'u1','L03','g6_1_math_u1_L03_basic','lesson_basic','M6-1-u1-C3',1,'sa','auto','9 ÷ 5의 몫을 가분수로 나타낼 때 분자에 오는 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-1-u1-C3","difficulty":1,"kind":"sa","stem":"9 ÷ 5의 몫을 가분수로 나타낼 때 분자에 오는 수는 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["몫이 1보다 커도 나누어지는 수가 분자, 나누는 수가 분모예요.","9 ÷ 5 = ⟨9/5⟩예요.","그래서 분자는 9예요."],"mis":"M6-1-u1-X01","variant_rule":{"alt":[{"stem":"11 ÷ 4의 몫을 가분수로 나타낼 때 분자에 오는 수는 얼마인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["몫이 1보다 커도 나누어지는 수가 분자, 나누는 수가 분모예요.","11 ÷ 4 = ⟨11/4⟩이에요.","그래서 분자는 11이에요."]},{"stem":"13 ÷ 6의 몫을 가분수로 나타낼 때 분자에 오는 수는 얼마인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["몫이 1보다 커도 나누어지는 수가 분자, 나누는 수가 분모예요.","13 ÷ 6 = ⟨13/6⟩이에요.","그래서 분자는 13이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L03_basic#3','math',6,1,'u1','L03','g6_1_math_u1_L03_basic','lesson_basic','M6-1-u1-C3',1,'mc','auto','⟨1 2/3⟩를 가분수로 나타내면 어느 것인가요?',ARRAY['M6-1-u1-X01','M6-1-u1-X05']::text[],true,'{"seq":3,"concept":"M6-1-u1-C3","difficulty":1,"kind":"mc","stem":"⟨1 2/3⟩를 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨5/3⟩","correct":true},{"t":"⟨3/5⟩","mis":"M6-1-u1-X01"},{"t":"⟨3/3⟩","mis":"M6-1-u1-X05"},{"t":"⟨2/3⟩","mis":"M6-1-u1-X05"}],"explanation":["자연수 1은 ⟨3/3⟩이에요 — 1 × 3 = 3.","여기에 ⟨2/3⟩를 더하면 분자는 3 + 2 = 5예요.","⟨1 2/3⟩ = ⟨5/3⟩예요."],"variant_rule":{"alt":[{"stem":"⟨2 1/4⟩을 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨9/4⟩","correct":true},{"t":"⟨4/9⟩","mis":"M6-1-u1-X01"},{"t":"⟨3/4⟩","mis":"M6-1-u1-X05"},{"t":"⟨2/4⟩","mis":"M6-1-u1-X05"}],"explanation":["자연수 2는 ⟨8/4⟩이에요 — 2 × 4 = 8.","여기에 ⟨1/4⟩을 더하면 분자는 8 + 1 = 9예요.","⟨2 1/4⟩ = ⟨9/4⟩예요."]},{"stem":"⟨1 3/5⟩을 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨8/5⟩","correct":true},{"t":"⟨5/8⟩","mis":"M6-1-u1-X01"},{"t":"⟨4/5⟩","mis":"M6-1-u1-X05"},{"t":"⟨3/5⟩","mis":"M6-1-u1-X05"}],"explanation":["자연수 1은 ⟨5/5⟩예요 — 1 × 5 = 5.","여기에 ⟨3/5⟩을 더하면 분자는 5 + 3 = 8이에요.","⟨1 3/5⟩ = ⟨8/5⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L03_basic#4','math',6,1,'u1','L03','g6_1_math_u1_L03_basic','lesson_basic','M6-1-u1-C3',1,'sa','auto','13 ÷ 5의 몫을 대분수로 나타낼 때 자연수 부분에 오는 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M6-1-u1-C3","difficulty":1,"kind":"sa","stem":"13 ÷ 5의 몫을 대분수로 나타낼 때 자연수 부분에 오는 수는 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["13 ÷ 5는 몫 2, 나머지 3이에요.","남은 3도 5로 나누면 ⟨3/5⟩ — 몫은 ⟨2 3/5⟩이에요.","그래서 자연수 부분은 2예요."],"mis":"M6-1-u1-X04","variant_rule":{"alt":[{"stem":"11 ÷ 3의 몫을 대분수로 나타낼 때 자연수 부분에 오는 수는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["11 ÷ 3은 몫 3, 나머지 2예요.","남은 2도 3으로 나누면 ⟨2/3⟩ — 몫은 ⟨3 2/3⟩예요.","그래서 자연수 부분은 3이에요."]},{"stem":"17 ÷ 4의 몫을 대분수로 나타낼 때 분자에 오는 수는 얼마인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["17 ÷ 4는 몫 4, 나머지 1이에요.","남은 1도 4로 나누면 ⟨1/4⟩ — 몫은 ⟨4 1/4⟩이에요.","그래서 분자는 1이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L03_basic#5','math',6,1,'u1','L03','g6_1_math_u1_L03_basic','lesson_basic','M6-1-u1-C3',2,'mc','auto','⟨11/4⟩을 대분수로 나타내면 어느 것인가요?',ARRAY['M6-1-u1-X04','M6-1-u1-X12']::text[],true,'{"seq":5,"concept":"M6-1-u1-C3","difficulty":2,"kind":"mc","stem":"⟨11/4⟩을 대분수로 나타내면 어느 것인가요?","options":[{"t":"⟨2 3/4⟩","correct":true},{"t":"⟨3 2/4⟩","mis":"M6-1-u1-X04"},{"t":"⟨2 3/11⟩","mis":"M6-1-u1-X04"},{"t":"⟨2 1/4⟩","mis":"M6-1-u1-X12"}],"explanation":["분모 4만큼 모이면 1이에요.","11을 4씩 묶으면 2묶음이고 3이 남아요.","⟨11/4⟩ = ⟨2 3/4⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨13/5⟩을 대분수로 나타내면 어느 것인가요?","options":[{"t":"⟨2 3/5⟩","correct":true},{"t":"⟨3 2/5⟩","mis":"M6-1-u1-X04"},{"t":"⟨2 3/13⟩","mis":"M6-1-u1-X04"},{"t":"⟨2 2/5⟩","mis":"M6-1-u1-X12"}],"explanation":["분모 5만큼 모이면 1이에요.","13을 5씩 묶으면 2묶음이고 3이 남아요.","⟨13/5⟩ = ⟨2 3/5⟩이에요."]},{"stem":"⟨17/6⟩을 대분수로 나타내면 어느 것인가요?","options":[{"t":"⟨2 5/6⟩","correct":true},{"t":"⟨5 2/6⟩","mis":"M6-1-u1-X04"},{"t":"⟨2 5/17⟩","mis":"M6-1-u1-X04"},{"t":"⟨2 1/6⟩","mis":"M6-1-u1-X12"}],"explanation":["분모 6만큼 모이면 1이에요.","17을 6씩 묶으면 2묶음이고 5가 남아요.","⟨17/6⟩ = ⟨2 5/6⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L03_basic#6','math',6,1,'u1','L03','g6_1_math_u1_L03_basic','lesson_basic','M6-1-u1-C3',2,'mc','auto','몫이 1보다 큰 나눗셈은 어느 것인가요?',ARRAY['M6-1-u1-X03']::text[],true,'{"seq":6,"concept":"M6-1-u1-C3","difficulty":2,"kind":"mc","stem":"몫이 1보다 큰 나눗셈은 어느 것인가요?","options":[{"t":"11 ÷ 4","correct":true},{"t":"5 ÷ 8","mis":"M6-1-u1-X03"},{"t":"3 ÷ 3","mis":"M6-1-u1-X03"},{"t":"7 ÷ 9","mis":"M6-1-u1-X03"}],"explanation":["나누어지는 수가 나누는 수보다 작으면 몫은 1보다 작고, 크면 1보다 커요.","5 ÷ 8 = ⟨5/8⟩, 3 ÷ 3 = 1, 7 ÷ 9 = ⟨7/9⟩, 11 ÷ 4 = ⟨2 3/4⟩이에요.","그래서 몫이 1보다 큰 것은 11 ÷ 4예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 몫이 1보다 큰 나눗셈은 어느 것인가요?","options":[{"t":"9 ÷ 7","correct":true},{"t":"4 ÷ 9","mis":"M6-1-u1-X03"},{"t":"6 ÷ 6","mis":"M6-1-u1-X03"},{"t":"2 ÷ 5","mis":"M6-1-u1-X03"}],"explanation":["나누어지는 수가 나누는 수보다 작으면 몫은 1보다 작고, 크면 1보다 커요.","4 ÷ 9 = ⟨4/9⟩, 6 ÷ 6 = 1, 9 ÷ 7 = ⟨1 2/7⟩, 2 ÷ 5 = ⟨2/5⟩예요.","그래서 몫이 1보다 큰 것은 9 ÷ 7이에요."]},{"stem":"이번에는 다른 보기예요. 몫이 1보다 큰 나눗셈은 어느 것인가요?","options":[{"t":"13 ÷ 6","correct":true},{"t":"8 ÷ 8","mis":"M6-1-u1-X03"},{"t":"3 ÷ 10","mis":"M6-1-u1-X03"},{"t":"5 ÷ 7","mis":"M6-1-u1-X03"}],"explanation":["나누어지는 수가 나누는 수보다 작으면 몫은 1보다 작고, 크면 1보다 커요.","8 ÷ 8 = 1, 3 ÷ 10 = ⟨3/10⟩, 13 ÷ 6 = ⟨2 1/6⟩, 5 ÷ 7 = ⟨5/7⟩예요.","그래서 몫이 1보다 큰 것은 13 ÷ 6이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L03_basic#7','math',6,1,'u1','L03','g6_1_math_u1_L03_basic','lesson_basic','M6-1-u1-C3',2,'ox','auto','4 ÷ 3의 몫은 ⟨4/3⟩로도 ⟨1 1/3⟩로도 나타낼 수 있어요.',ARRAY['M6-1-u1-X11']::text[],true,'{"seq":7,"concept":"M6-1-u1-C3","difficulty":2,"kind":"ox","stem":"4 ÷ 3의 몫은 ⟨4/3⟩로도 ⟨1 1/3⟩로도 나타낼 수 있어요.","answer":"O","reason_options":[{"t":"⟨4/3⟩ = ⟨1 1/3⟩ — 같은 수를 가분수와 대분수로 적은 것이므로","correct":true},{"t":"두 수는 크기가 달라 하나만 맞으므로","mis":"M6-1-u1-X11"}],"mis":"M6-1-u1-X11","explanation":["4 ÷ 3 = ⟨4/3⟩예요.","⟨4/3⟩ = ⟨1 1/3⟩이에요.","그래서 둘 다 맞아요."],"variant_rule":{"alt":[{"stem":"7 ÷ 2의 몫은 「3 나머지 1」로만 나타낼 수 있어요.","answer":"X","reason_options":[{"t":"남은 1도 2로 나누면 몫을 ⟨3 1/2⟩로 나타낼 수 있으므로","correct":true},{"t":"나머지가 있으면 분수로 나타낼 수 없으므로","mis":"M6-1-u1-X02"}],"explanation":["7 ÷ 2는 몫 3, 나머지 1이에요.","남은 1을 2로 나누면 ⟨1/2⟩이에요.","7 ÷ 2 = ⟨3 1/2⟩이에요."]},{"stem":"13 ÷ 6의 몫을 가분수로 나타내면 ⟨6/13⟩이에요.","answer":"X","reason_options":[{"t":"나누어지는 수 13이 분자, 나누는 수 6이 분모라 ⟨13/6⟩이므로","correct":true},{"t":"몫이 1보다 크면 분모가 더 커야 하므로","mis":"M6-1-u1-X01"}],"explanation":["나누어지는 수가 분자예요.","13 ÷ 6 = ⟨13/6⟩이에요.","⟨6/13⟩은 1보다 작아 몫이 될 수 없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L03_basic#8','math',6,1,'u1','L03','g6_1_math_u1_L03_basic','lesson_basic','M6-1-u1-C3',2,'match','auto','나눗셈과 몫을 대분수로 나타낸 것을 알맞게 이으세요.','{}'::text[],true,'{"seq":8,"concept":"M6-1-u1-C3","difficulty":2,"kind":"match","stem":"나눗셈과 몫을 대분수로 나타낸 것을 알맞게 이으세요.","pairs":[{"l":"7 ÷ 2","r":"⟨3 1/2⟩"},{"l":"8 ÷ 3","r":"⟨2 2/3⟩"},{"l":"9 ÷ 4","r":"⟨2 1/4⟩"}],"mis":"M6-1-u1-X04","explanation":["몫과 나머지를 먼저 구하고 남은 것을 나누어요.","7 ÷ 2 = ⟨3 1/2⟩, 8 ÷ 3 = ⟨2 2/3⟩, 9 ÷ 4 = ⟨2 1/4⟩이에요.","나머지가 분자, 나누는 수가 분모예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 나눗셈과 몫을 대분수로 나타낸 것을 알맞게 이으세요.","pairs":[{"l":"5 ÷ 3","r":"⟨1 2/3⟩"},{"l":"11 ÷ 4","r":"⟨2 3/4⟩"},{"l":"7 ÷ 5","r":"⟨1 2/5⟩"}],"explanation":["몫과 나머지를 먼저 구하고 남은 것을 나누어요.","5 ÷ 3 = ⟨1 2/3⟩, 11 ÷ 4 = ⟨2 3/4⟩, 7 ÷ 5 = ⟨1 2/5⟩예요.","나머지가 분자, 나누는 수가 분모예요."]},{"stem":"이번에는 다른 보기예요. 나눗셈과 몫을 대분수로 나타낸 것을 알맞게 이으세요.","pairs":[{"l":"13 ÷ 6","r":"⟨2 1/6⟩"},{"l":"10 ÷ 3","r":"⟨3 1/3⟩"},{"l":"9 ÷ 2","r":"⟨4 1/2⟩"}],"explanation":["몫과 나머지를 먼저 구하고 남은 것을 나누어요.","13 ÷ 6 = ⟨2 1/6⟩, 10 ÷ 3 = ⟨3 1/3⟩, 9 ÷ 2 = ⟨4 1/2⟩이에요.","나머지가 분자, 나누는 수가 분모예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L03_basic#9','math',6,1,'u1','L03','g6_1_math_u1_L03_basic','lesson_basic','M6-1-u1-C3',2,'sa','auto','쌀 17 kg을 5봉지에 똑같이 나누어 담으려고 해요. 한 봉지에 담는 쌀을 대분수로 나타낼 때, 자연수 부분과 분자의 합은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M6-1-u1-C3","difficulty":2,"kind":"sa","stem":"쌀 17 kg을 5봉지에 똑같이 나누어 담으려고 해요. 한 봉지에 담는 쌀을 대분수로 나타낼 때, 자연수 부분과 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["17 ÷ 5는 몫 3, 나머지 2예요.","남은 2도 나누면 17 ÷ 5 = ⟨3 2/5⟩예요.","자연수 부분과 분자의 합은 3 + 2 = 5예요."],"mis":"M6-1-u1-X15","variant_rule":{"alt":[{"stem":"끈 13 m를 4도막으로 똑같이 나누어 자르려고 해요. 한 도막의 길이를 대분수로 나타낼 때, 자연수 부분과 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["13 ÷ 4는 몫 3, 나머지 1이에요.","남은 1도 나누면 13 ÷ 4 = ⟨3 1/4⟩이에요.","자연수 부분과 분자의 합은 3 + 1 = 4예요."]},{"stem":"색 모래 11 kg을 3모둠이 똑같이 나누어 가지려고 해요. 한 모둠이 가지는 색 모래를 대분수로 나타낼 때, 자연수 부분과 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["11 ÷ 3은 몫 3, 나머지 2예요.","남은 2도 나누면 11 ÷ 3 = ⟨3 2/3⟩예요.","자연수 부분과 분자의 합은 3 + 2 = 5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L03_basic#10','math',6,1,'u1','L03','g6_1_math_u1_L03_basic','lesson_basic','M6-1-u1-C3',3,'mc','auto','가 모둠은 시루떡 9개를 4명이, 나 모둠은 시루떡 7개를 3명이 똑같이 나누었어요. 한 명이 가지는 시루떡이 더 많은 모둠은 어디인가요?',ARRAY['M6-1-u1-X11','M6-1-u1-X03']::text[],true,'{"seq":10,"concept":"M6-1-u1-C3","difficulty":3,"kind":"mc","stem":"가 모둠은 시루떡 9개를 4명이, 나 모둠은 시루떡 7개를 3명이 똑같이 나누었어요. 한 명이 가지는 시루떡이 더 많은 모둠은 어디인가요?","options":[{"t":"나 모둠","correct":true},{"t":"가 모둠","mis":"M6-1-u1-X11"},{"t":"두 모둠이 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X03"}],"explanation":["가 모둠 한 명 몫은 9 ÷ 4 = ⟨2 1/4⟩, 나 모둠은 7 ÷ 3 = ⟨2 1/3⟩이에요.","12로 통분하면 ⟨2 1/4⟩ = ⟨27/12⟩, ⟨2 1/3⟩ = ⟨28/12⟩이에요.","⟨2 1/4⟩ < ⟨2 1/3⟩이라 나 모둠이 더 많아요."],"variant_rule":{"alt":[{"stem":"가 모둠은 빵 7개를 5명이, 나 모둠은 빵 4개를 3명이 똑같이 나누었어요. 한 명이 가지는 빵이 더 많은 모둠은 어디인가요?","options":[{"t":"가 모둠","correct":true},{"t":"나 모둠","mis":"M6-1-u1-X11"},{"t":"두 모둠이 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X03"}],"explanation":["가 모둠 한 명 몫은 7 ÷ 5 = ⟨1 2/5⟩, 나 모둠은 4 ÷ 3 = ⟨1 1/3⟩이에요.","15로 통분하면 ⟨1 2/5⟩ = ⟨21/15⟩, ⟨1 1/3⟩ = ⟨20/15⟩이에요.","⟨1 2/5⟩ > ⟨1 1/3⟩이라 가 모둠이 더 많아요."]},{"stem":"가 모둠은 피자 11판을 4명이, 나 모둠은 피자 8판을 3명이 똑같이 나누었어요. 한 명이 가지는 피자가 더 많은 모둠은 어디인가요?","options":[{"t":"가 모둠","correct":true},{"t":"나 모둠","mis":"M6-1-u1-X11"},{"t":"두 모둠이 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X03"}],"explanation":["가 모둠 한 명 몫은 11 ÷ 4 = ⟨2 3/4⟩, 나 모둠은 8 ÷ 3 = ⟨2 2/3⟩예요.","12로 통분하면 ⟨2 3/4⟩ = ⟨33/12⟩, ⟨2 2/3⟩ = ⟨32/12⟩예요.","⟨2 3/4⟩ > ⟨2 2/3⟩라 가 모둠이 더 많아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L03_challenge#1','math',6,1,'u1','L03','g6_1_math_u1_L03_challenge','lesson_challenge','M6-1-u1-C3',2,'sa','auto','19 ÷ 4의 몫을 대분수로 나타낼 때 분자에 오는 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M6-1-u1-C3","difficulty":2,"kind":"sa","stem":"19 ÷ 4의 몫을 대분수로 나타낼 때 분자에 오는 수는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["19 ÷ 4는 몫 4, 나머지 3이에요.","남은 3도 4로 나누면 ⟨3/4⟩ — 몫은 ⟨4 3/4⟩이에요.","그래서 분자는 3이에요."],"mis":"M6-1-u1-X04","variant_rule":{"alt":[{"stem":"23 ÷ 6의 몫을 대분수로 나타낼 때 자연수 부분에 오는 수는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["23 ÷ 6은 몫 3, 나머지 5예요.","남은 5도 6으로 나누면 ⟨5/6⟩ — 몫은 ⟨3 5/6⟩예요.","그래서 자연수 부분은 3이에요."]},{"stem":"26 ÷ 7의 몫을 대분수로 나타낼 때 분자에 오는 수는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["26 ÷ 7은 몫 3, 나머지 5예요.","남은 5도 7로 나누면 ⟨5/7⟩ — 몫은 ⟨3 5/7⟩예요.","그래서 분자는 5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L03_challenge#2','math',6,1,'u1','L03','g6_1_math_u1_L03_challenge','lesson_challenge','M6-1-u1-C3',2,'mc','auto','흰 종이 4장을 3명이 나누어요. 「먼저 1장씩 나누고 남은 것을 또 나누기」로 구한 ⟨1 1/3⟩과 「모두 3조각씩 잘라 나누기」로 구한 ⟨4/3⟩는 어떤 관계인가요?',ARRAY['M6-1-u1-X11','M6-1-u1-X02']::text[],true,'{"seq":2,"concept":"M6-1-u1-C3","difficulty":2,"kind":"mc","stem":"흰 종이 4장을 3명이 나누어요. 「먼저 1장씩 나누고 남은 것을 또 나누기」로 구한 ⟨1 1/3⟩과 「모두 3조각씩 잘라 나누기」로 구한 ⟨4/3⟩는 어떤 관계인가요?","options":[{"t":"같은 양을 다르게 적은 것이다","correct":true},{"t":"대분수 쪽이 더 많다","mis":"M6-1-u1-X11"},{"t":"가분수 쪽이 더 많다","mis":"M6-1-u1-X11"},{"t":"한 가지 방법만 맞다","mis":"M6-1-u1-X02"}],"explanation":["방법 ①은 1씩 나누고 남은 1을 3으로 나누어 ⟨1 1/3⟩이에요.","방법 ②는 ⟨1/3⟩ 조각을 4개씩 가져 ⟨4/3⟩예요.","⟨4/3⟩ = ⟨1 1/3⟩ — 같은 수예요."],"variant_rule":{"alt":[{"stem":"시루떡 5개를 2명이 나누어요. 「먼저 2개씩 나누고 남은 것을 또 나누기」로 구한 ⟨2 1/2⟩과 「모두 2조각씩 잘라 나누기」로 구한 ⟨5/2⟩는 어떤 관계인가요?","options":[{"t":"같은 양을 다르게 적은 것이다","correct":true},{"t":"대분수 쪽이 더 많다","mis":"M6-1-u1-X11"},{"t":"가분수 쪽이 더 많다","mis":"M6-1-u1-X11"},{"t":"한 가지 방법만 맞다","mis":"M6-1-u1-X02"}],"explanation":["방법 ①은 2씩 나누고 남은 1을 2로 나누어 ⟨2 1/2⟩이에요.","방법 ②는 ⟨1/2⟩ 조각을 5개씩 가져 ⟨5/2⟩예요.","⟨5/2⟩ = ⟨2 1/2⟩ — 같은 수예요."]},{"stem":"빵 7개를 3명이 나누어요. 「먼저 2개씩 나누고 남은 것을 또 나누기」로 구한 ⟨2 1/3⟩과 「모두 3조각씩 잘라 나누기」로 구한 ⟨7/3⟩은 어떤 관계인가요?","options":[{"t":"같은 양을 다르게 적은 것이다","correct":true},{"t":"대분수 쪽이 더 많다","mis":"M6-1-u1-X11"},{"t":"가분수 쪽이 더 많다","mis":"M6-1-u1-X11"},{"t":"한 가지 방법만 맞다","mis":"M6-1-u1-X02"}],"explanation":["방법 ①은 2씩 나누고 남은 1을 3으로 나누어 ⟨2 1/3⟩이에요.","방법 ②는 ⟨1/3⟩ 조각을 7개씩 가져 ⟨7/3⟩이에요.","⟨7/3⟩ = ⟨2 1/3⟩ — 같은 수예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L03_challenge#3','math',6,1,'u1','L03','g6_1_math_u1_L03_challenge','lesson_challenge','M6-1-u1-C3',3,'error','auto','11 ÷ 3의 몫을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u1-X02','M6-1-u1-X15']::text[],true,'{"seq":3,"concept":"M6-1-u1-C3","difficulty":3,"kind":"error","stem":"11 ÷ 3의 몫을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「몫 3, 나머지 2야. 더는 나눌 수 없어.」","correct":true,"mis_target":"M6-1-u1-X02"},{"t":"도윤 — 「몫은 ⟨11/3⟩이야.」","mis":"M6-1-u1-X15"},{"t":"하린 — 「몫은 ⟨3 2/3⟩야.」","mis":"M6-1-u1-X15"}],"explanation":["남은 2도 3으로 똑같이 나눌 수 있어요.","그러면 11 ÷ 3 = ⟨11/3⟩ = ⟨3 2/3⟩예요.","수아는 남은 것을 나눌 수 없다고 잘못 말했어요."],"variant_rule":{"alt":[{"stem":"9 ÷ 2의 몫을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민준 — 「몫 4, 나머지 1이야. 더는 나눌 수 없어.」","correct":true,"mis_target":"M6-1-u1-X02"},{"t":"서연 — 「몫은 ⟨9/2⟩야.」","mis":"M6-1-u1-X15"},{"t":"지호 — 「몫은 ⟨4 1/2⟩이야.」","mis":"M6-1-u1-X15"}],"explanation":["남은 1도 2로 똑같이 나눌 수 있어요.","그러면 9 ÷ 2 = ⟨9/2⟩ = ⟨4 1/2⟩이에요.","민준은 남은 것을 나눌 수 없다고 잘못 말했어요."]},{"stem":"14 ÷ 5의 몫을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「몫 2, 나머지 4야. 더는 나눌 수 없어.」","correct":true,"mis_target":"M6-1-u1-X02"},{"t":"나린 — 「몫은 ⟨14/5⟩야.」","mis":"M6-1-u1-X15"},{"t":"유진 — 「몫은 ⟨2 4/5⟩야.」","mis":"M6-1-u1-X15"}],"explanation":["남은 4도 5로 똑같이 나눌 수 있어요.","그러면 14 ÷ 5 = ⟨14/5⟩ = ⟨2 4/5⟩예요.","가온은 남은 것을 나눌 수 없다고 잘못 말했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L03_challenge#4','math',6,1,'u1','L03','g6_1_math_u1_L03_challenge','lesson_challenge','M6-1-u1-C3',3,'mc','auto','가 모둠은 주스 7 L를 4명이, 나 모둠은 주스 9 L를 5명이 똑같이 나누었어요. 한 명이 가지는 주스가 더 많은 모둠은 어디인가요?',ARRAY['M6-1-u1-X11','M6-1-u1-X03']::text[],true,'{"seq":4,"concept":"M6-1-u1-C3","difficulty":3,"kind":"mc","stem":"가 모둠은 주스 7 L를 4명이, 나 모둠은 주스 9 L를 5명이 똑같이 나누었어요. 한 명이 가지는 주스가 더 많은 모둠은 어디인가요?","options":[{"t":"나 모둠","correct":true},{"t":"가 모둠","mis":"M6-1-u1-X11"},{"t":"두 모둠이 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X03"}],"explanation":["가 모둠 한 명 몫은 7 ÷ 4 = ⟨1 3/4⟩, 나 모둠은 9 ÷ 5 = ⟨1 4/5⟩예요.","20으로 통분하면 ⟨1 3/4⟩ = ⟨35/20⟩, ⟨1 4/5⟩ = ⟨36/20⟩이에요.","⟨1 3/4⟩ < ⟨1 4/5⟩라 나 모둠이 더 많아요."],"variant_rule":{"alt":[{"stem":"가 모둠은 색 모래 10 kg을 3명이, 나 모둠은 색 모래 13 kg을 4명이 똑같이 나누었어요. 한 명이 가지는 색 모래가 더 많은 모둠은 어디인가요?","options":[{"t":"가 모둠","correct":true},{"t":"나 모둠","mis":"M6-1-u1-X11"},{"t":"두 모둠이 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X03"}],"explanation":["가 모둠 한 명 몫은 10 ÷ 3 = ⟨3 1/3⟩, 나 모둠은 13 ÷ 4 = ⟨3 1/4⟩이에요.","12로 통분하면 ⟨3 1/3⟩ = ⟨40/12⟩, ⟨3 1/4⟩ = ⟨39/12⟩예요.","⟨3 1/3⟩ > ⟨3 1/4⟩이라 가 모둠이 더 많아요."]},{"stem":"가 모둠은 시루떡 8개를 5명이, 나 모둠은 시루떡 5개를 3명이 똑같이 나누었어요. 한 명이 가지는 시루떡이 더 많은 모둠은 어디인가요?","options":[{"t":"나 모둠","correct":true},{"t":"가 모둠","mis":"M6-1-u1-X11"},{"t":"두 모둠이 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X03"}],"explanation":["가 모둠 한 명 몫은 8 ÷ 5 = ⟨1 3/5⟩, 나 모둠은 5 ÷ 3 = ⟨1 2/3⟩예요.","15로 통분하면 ⟨1 3/5⟩ = ⟨24/15⟩, ⟨1 2/3⟩ = ⟨25/15⟩예요.","⟨1 3/5⟩ < ⟨1 2/3⟩라 나 모둠이 더 많아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L03_challenge#5','math',6,1,'u1','L03','g6_1_math_u1_L03_challenge','lesson_challenge','M6-1-u1-C3',3,'sa','auto','쌀 23 kg을 6봉지에 똑같이 나누어 담으려고 해요. 한 봉지에 담는 쌀을 대분수로 나타낼 때, 자연수 부분과 분자의 합은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M6-1-u1-C3","difficulty":3,"kind":"sa","stem":"쌀 23 kg을 6봉지에 똑같이 나누어 담으려고 해요. 한 봉지에 담는 쌀을 대분수로 나타낼 때, 자연수 부분과 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["23 ÷ 6은 몫 3, 나머지 5예요.","남은 5도 나누면 23 ÷ 6 = ⟨3 5/6⟩예요.","자연수 부분과 분자의 합은 3 + 5 = 8이에요."],"mis":"M6-1-u1-X15","variant_rule":{"alt":[{"stem":"색 테이프 19 m를 7명이 똑같이 나누어 가지려고 해요. 한 명이 가지는 색 테이프를 대분수로 나타낼 때, 자연수 부분과 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["19 ÷ 7은 몫 2, 나머지 5예요.","남은 5도 나누면 19 ÷ 7 = ⟨2 5/7⟩예요.","자연수 부분과 분자의 합은 2 + 5 = 7이에요."]},{"stem":"주스 22 L를 9명이 똑같이 나누어 마시려고 해요. 한 명이 마시는 주스를 대분수로 나타낼 때, 자연수 부분과 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["22 ÷ 9는 몫 2, 나머지 4예요.","남은 4도 나누면 22 ÷ 9 = ⟨2 4/9⟩예요.","자연수 부분과 분자의 합은 2 + 4 = 6이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L03_challenge#6','math',6,1,'u1','L03','g6_1_math_u1_L03_challenge','lesson_challenge','M6-1-u1-C3',3,'sa','auto','29 ÷ 6의 몫은 어떤 두 자연수 사이에 있어요. 두 수 가운데 작은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M6-1-u1-C3","difficulty":3,"kind":"sa","stem":"29 ÷ 6의 몫은 어떤 두 자연수 사이에 있어요. 두 수 가운데 작은 수는 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["6 × 4 = 24, 6 × 5 = 30이에요.","29 ÷ 6 = ⟨4 5/6⟩예요.","4와 5 사이에 있으니 작은 수는 4예요."],"mis":"M6-1-u1-X03","variant_rule":{"alt":[{"stem":"38 ÷ 7의 몫은 어떤 두 자연수 사이에 있어요. 두 수 가운데 작은 수는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["7 × 5 = 35, 7 × 6 = 42예요.","38 ÷ 7 = ⟨5 3/7⟩이에요.","5와 6 사이에 있으니 작은 수는 5예요."]},{"stem":"47 ÷ 9의 몫은 어떤 두 자연수 사이에 있어요. 두 수 가운데 작은 수는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["9 × 5 = 45, 9 × 6 = 54예요.","47 ÷ 9 = ⟨5 2/9⟩예요.","5와 6 사이에 있으니 작은 수는 5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L03_challenge#7','math',6,1,'u1','L03','g6_1_math_u1_L03_challenge','lesson_challenge','M6-1-u1-C3',3,'ox','auto','9 ÷ 4의 몫은 ⟨2 4/9⟩예요.',ARRAY['M6-1-u1-X04']::text[],true,'{"seq":7,"concept":"M6-1-u1-C3","difficulty":3,"kind":"ox","stem":"9 ÷ 4의 몫은 ⟨2 4/9⟩예요.","answer":"X","reason_options":[{"t":"9 ÷ 4 = ⟨2 1/4⟩ — 나머지 1을 4로 나누어야 하므로","correct":true},{"t":"몫 2 뒤에 나누어지는 수를 분모로 쓰므로","mis":"M6-1-u1-X04"}],"mis":"M6-1-u1-X04","explanation":["9 ÷ 4는 몫 2, 나머지 1이에요.","남은 1을 4로 나누면 ⟨1/4⟩이에요.","9 ÷ 4 = ⟨2 1/4⟩이에요."],"variant_rule":{"alt":[{"stem":"11 ÷ 5의 몫은 2보다 크고 3보다 작아요.","answer":"O","reason_options":[{"t":"11 ÷ 5 = ⟨2 1/5⟩이므로","correct":true},{"t":"11이 5보다 크니 몫은 5보다 크므로","mis":"M6-1-u1-X03"}],"explanation":["5 × 2 = 10, 5 × 3 = 15예요.","11 ÷ 5 = ⟨2 1/5⟩이에요.","그래서 2와 3 사이 — 맞아요."]},{"stem":"몫이 1보다 큰 나눗셈은 나누어지는 수가 나누는 수보다 커요.","answer":"O","reason_options":[{"t":"분자가 분모보다 커야 1보다 큰 분수가 되므로","correct":true},{"t":"나누는 수가 커야 몫이 커지므로","mis":"M6-1-u1-X11"}],"explanation":["몫 = (나누어지는 수)/(나누는 수)예요.","분자가 분모보다 크면 1보다 큰 분수예요.","그래서 맞아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L03_challenge#8','math',6,1,'u1','L03','g6_1_math_u1_L03_challenge','lesson_challenge','M6-1-u1-C3',4,'sa','auto','□ ÷ 6의 몫을 대분수로 나타내면 ⟨2 5/6⟩예요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M6-1-u1-C3","difficulty":4,"kind":"sa","stem":"□ ÷ 6의 몫을 대분수로 나타내면 ⟨2 5/6⟩예요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["17"],"explanation":["□ ÷ 6 = ⟨□/6⟩이니 ⟨2 5/6⟩를 가분수로 고치면 돼요.","2 × 6 + 5 = 17이에요.","⟨2 5/6⟩ = ⟨17/6⟩이니 □는 17이에요."],"mis":"M6-1-u1-X05","variant_rule":{"alt":[{"stem":"□ ÷ 7의 몫을 대분수로 나타내면 ⟨3 2/7⟩예요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["23"],"explanation":["□ ÷ 7 = ⟨□/7⟩이니 ⟨3 2/7⟩를 가분수로 고치면 돼요.","3 × 7 + 2 = 23이에요.","⟨3 2/7⟩ = ⟨23/7⟩이니 □는 23이에요."]},{"stem":"□ ÷ 8의 몫을 대분수로 나타내면 ⟨4 3/8⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["35"],"explanation":["□ ÷ 8 = ⟨□/8⟩이니 ⟨4 3/8⟩을 가분수로 고치면 돼요.","4 × 8 + 3 = 35예요.","⟨4 3/8⟩ = ⟨35/8⟩니 □는 35예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L03_challenge#9','math',6,1,'u1','L03','g6_1_math_u1_L03_challenge','lesson_challenge','M6-1-u1-C3',4,'sa','auto','□ ÷ 4의 몫이 2보다 크고 3보다 작을 때, □에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M6-1-u1-C3","difficulty":4,"kind":"sa","stem":"□ ÷ 4의 몫이 2보다 크고 3보다 작을 때, □에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["8 ÷ 4 = 2, 12 ÷ 4 = 3이에요.","□는 8보다 크고 12보다 작아야 해요.","9부터 11까지 3개예요."],"mis":"M6-1-u1-X03","variant_rule":{"alt":[{"stem":"□ ÷ 5의 몫이 3보다 크고 4보다 작을 때, □에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["15 ÷ 5 = 3, 20 ÷ 5 = 4예요.","□는 15보다 크고 20보다 작아야 해요.","16부터 19까지 4개예요."]},{"stem":"□ ÷ 6의 몫이 2보다 크고 3보다 작을 때, □에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["12 ÷ 6 = 2, 18 ÷ 6 = 3이에요.","□는 12보다 크고 18보다 작아야 해요.","13부터 17까지 5개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L03_challenge#10','math',6,1,'u1','L03','g6_1_math_u1_L03_challenge','lesson_challenge','M6-1-u1-C3',4,'essay','teacher','흰 종이 4장을 3명이 똑같이 나누어 가지려고 해요. 서로 다른 두 가지 방법으로 한 명 몫을 구하고, 두 몫이 같은 수인 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-1-u1-C3","difficulty":4,"kind":"essay","stem":"흰 종이 4장을 3명이 똑같이 나누어 가지려고 해요. 서로 다른 두 가지 방법으로 한 명 몫을 구하고, 두 몫이 같은 수인 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 방법 ① 3장을 1장씩 나누면 1장이 남고, 남은 1장을 3명이 나누면 ⟨1/3⟩장씩 더 가져 ⟨1 1/3⟩장이다. 방법 ② 4장을 모두 3조각씩 자르면 한 조각은 ⟨1/3⟩장이고 한 명은 4조각을 가져 ⟨4/3⟩장이다. ⟨4/3⟩를 대분수로 고치면 ⟨1 1/3⟩이므로 두 몫은 같은 양을 다르게 적은 것이다.","scoring_points":["먼저 1장씩 나누고 남은 것을 나누는 방법으로 ⟨1 1/3⟩장을 구했는가","모두 3조각씩 잘라 ⟨4/3⟩장을 구했는가","⟨4/3⟩ = ⟨1 1/3⟩이라 같다고 설명했는가"]},"explanation":["방법 ①은 ⟨1 1/3⟩장이에요.","방법 ②는 ⟨4/3⟩장이에요.","⟨4/3⟩ = ⟨1 1/3⟩ — 같은 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L04_basic#1','math',6,1,'u1','L04','g6_1_math_u1_L04_basic','lesson_basic','M6-1-u1-C4',1,'mc','auto','7 ÷ 4를 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M6-1-u1-X06','M6-1-u1-X07']::text[],true,'{"seq":1,"concept":"M6-1-u1-C4","difficulty":1,"kind":"mc","stem":"7 ÷ 4를 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"7 × ⟨1/4⟩","correct":true},{"t":"7 × 4","mis":"M6-1-u1-X06"},{"t":"4 × ⟨1/7⟩","mis":"M6-1-u1-X07"},{"t":"⟨1/7⟩ × ⟨1/4⟩","mis":"M6-1-u1-X07"}],"explanation":["÷ 4는 4로 똑같이 나눈 것 중의 1이에요.","× ⟨1/4⟩도 4로 똑같이 나눈 것 중의 1이에요.","그래서 7 ÷ 4 = 7 × ⟨1/4⟩ = ⟨1 3/4⟩이에요."],"variant_rule":{"alt":[{"stem":"3 ÷ 2를 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"3 × ⟨1/2⟩","correct":true},{"t":"3 × 2","mis":"M6-1-u1-X06"},{"t":"2 × ⟨1/3⟩","mis":"M6-1-u1-X07"},{"t":"⟨1/3⟩ × ⟨1/2⟩","mis":"M6-1-u1-X07"}],"explanation":["÷ 2는 2로 똑같이 나눈 것 중의 1이에요.","× ⟨1/2⟩도 2로 똑같이 나눈 것 중의 1이에요.","그래서 3 ÷ 2 = 3 × ⟨1/2⟩ = ⟨1 1/2⟩이에요."]},{"stem":"5 ÷ 8을 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"5 × ⟨1/8⟩","correct":true},{"t":"5 × 8","mis":"M6-1-u1-X06"},{"t":"8 × ⟨1/5⟩","mis":"M6-1-u1-X07"},{"t":"⟨1/5⟩ × ⟨1/8⟩","mis":"M6-1-u1-X07"}],"explanation":["÷ 8은 8로 똑같이 나눈 것 중의 1이에요.","× ⟨1/8⟩도 8로 똑같이 나눈 것 중의 1이에요.","그래서 5 ÷ 8 = 5 × ⟨1/8⟩ = ⟨5/8⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L04_basic#2','math',6,1,'u1','L04','g6_1_math_u1_L04_basic','lesson_basic','M6-1-u1-C4',1,'sa','auto','9 ÷ 4 = 9 × ⟨1/□⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-1-u1-C4","difficulty":1,"kind":"sa","stem":"9 ÷ 4 = 9 × ⟨1/□⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["÷ 4는 4로 나눈 것 중의 1이에요.","그래서 ⟨1/4⟩을 곱하는 것과 같아요.","9 ÷ 4 = 9 × ⟨1/4⟩ — □는 4예요."],"mis":"M6-1-u1-X07","variant_rule":{"alt":[{"stem":"5 ÷ 6 = 5 × ⟨1/□⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["÷ 6은 6으로 나눈 것 중의 1이에요.","그래서 ⟨1/6⟩을 곱하는 것과 같아요.","5 ÷ 6 = 5 × ⟨1/6⟩ — □는 6이에요."]},{"stem":"8 ÷ 3 = 8 × ⟨1/□⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["÷ 3은 3으로 나눈 것 중의 1이에요.","그래서 ⟨1/3⟩을 곱하는 것과 같아요.","8 ÷ 3 = 8 × ⟨1/3⟩ — □는 3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L04_basic#3','math',6,1,'u1','L04','g6_1_math_u1_L04_basic','lesson_basic','M6-1-u1-C4',1,'sa','auto','매듭 장식을 만들려고 끈 6 m를 7도막으로 똑같이 나누어 잘랐어요. 한 도막의 길이는 6 × ⟨1/□⟩ m예요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M6-1-u1-C4","difficulty":1,"kind":"sa","stem":"매듭 장식을 만들려고 끈 6 m를 7도막으로 똑같이 나누어 잘랐어요. 한 도막의 길이는 6 × ⟨1/□⟩ m예요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["한 도막의 길이는 6 ÷ 7이에요.","÷ 7은 × ⟨1/7⟩과 같아요.","6 ÷ 7 = 6 × ⟨1/7⟩ = ⟨6/7⟩ — □는 7이에요."],"mis":"M6-1-u1-X07","variant_rule":{"alt":[{"stem":"매듭 장식을 만들려고 끈 3 m를 5도막으로 똑같이 나누어 잘랐어요. 한 도막의 길이는 3 × ⟨1/□⟩ m예요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["한 도막의 길이는 3 ÷ 5예요.","÷ 5는 × ⟨1/5⟩과 같아요.","3 ÷ 5 = 3 × ⟨1/5⟩ = ⟨3/5⟩ — □는 5예요."]},{"stem":"매듭 장식을 만들려고 끈 8 m를 9도막으로 똑같이 나누어 잘랐어요. 한 도막의 길이는 8 × ⟨1/□⟩ m예요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["한 도막의 길이는 8 ÷ 9예요.","÷ 9는 × ⟨1/9⟩과 같아요.","8 ÷ 9 = 8 × ⟨1/9⟩ = ⟨8/9⟩ — □는 9예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L04_basic#4','math',6,1,'u1','L04','g6_1_math_u1_L04_basic','lesson_basic','M6-1-u1-C4',1,'ox','auto','5 ÷ 3 = 5 × 3이에요.',ARRAY['M6-1-u1-X06']::text[],true,'{"seq":4,"concept":"M6-1-u1-C4","difficulty":1,"kind":"ox","stem":"5 ÷ 3 = 5 × 3이에요.","answer":"X","reason_options":[{"t":"÷ 3은 3으로 나눈 것 중의 1이라 5 × ⟨1/3⟩이 되어야 하므로","correct":true},{"t":"나눗셈을 곱셈으로 바꾸면 나누는 수를 그대로 곱하므로","mis":"M6-1-u1-X06"}],"mis":"M6-1-u1-X06","explanation":["5를 3으로 나누면 양이 작아져야 해요.","5 × 3 = 15는 오히려 커요.","5 ÷ 3 = 5 × ⟨1/3⟩ = ⟨1 2/3⟩예요."],"variant_rule":{"alt":[{"stem":"7 ÷ 4 = 7 × ⟨1/4⟩이에요.","answer":"O","reason_options":[{"t":"÷ 4는 4로 나눈 것 중의 1, × ⟨1/4⟩과 뜻이 같으므로","correct":true},{"t":"분모와 분자를 바꾸어 곱하므로","mis":"M6-1-u1-X07"}],"explanation":["÷ 4는 4로 똑같이 나눈 것 중의 1이에요.","× ⟨1/4⟩도 4로 나눈 것 중의 1이에요.","7 ÷ 4 = 7 × ⟨1/4⟩ = ⟨1 3/4⟩ — 맞아요."]},{"stem":"6 ÷ 7과 6 × ⟨1/7⟩은 계산 결과가 같아요.","answer":"O","reason_options":[{"t":"두 식 모두 6을 7로 똑같이 나눈 것 중의 1이므로","correct":true},{"t":"6 × 7을 7로 한 번 더 나누므로","mis":"M6-1-u1-X06"}],"explanation":["6 ÷ 7 = ⟨6/7⟩이에요.","6 × ⟨1/7⟩ = ⟨6/7⟩이에요.","둘 다 ⟨6/7⟩ — 맞아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L04_basic#5','math',6,1,'u1','L04','g6_1_math_u1_L04_basic','lesson_basic','M6-1-u1-C4',2,'mc','auto','13 ÷ 4를 분수의 곱셈으로 나타내어 계산하면 얼마인가요?',ARRAY['M6-1-u1-X06','M6-1-u1-X07']::text[],true,'{"seq":5,"concept":"M6-1-u1-C4","difficulty":2,"kind":"mc","stem":"13 ÷ 4를 분수의 곱셈으로 나타내어 계산하면 얼마인가요?","options":[{"t":"⟨3 1/4⟩","correct":true},{"t":"52","mis":"M6-1-u1-X06"},{"t":"⟨4/13⟩","mis":"M6-1-u1-X07"},{"t":"⟨1/52⟩","mis":"M6-1-u1-X07"}],"explanation":["13 ÷ 4 = 13 × ⟨1/4⟩이에요.","13 × ⟨1/4⟩ = ⟨13/4⟩이에요.","⟨13/4⟩ = ⟨3 1/4⟩이에요."],"variant_rule":{"alt":[{"stem":"5 ÷ 3을 분수의 곱셈으로 나타내어 계산하면 얼마인가요?","options":[{"t":"⟨1 2/3⟩","correct":true},{"t":"15","mis":"M6-1-u1-X06"},{"t":"⟨3/5⟩","mis":"M6-1-u1-X07"},{"t":"⟨1/15⟩","mis":"M6-1-u1-X07"}],"explanation":["5 ÷ 3 = 5 × ⟨1/3⟩이에요.","5 × ⟨1/3⟩ = ⟨5/3⟩예요.","⟨5/3⟩ = ⟨1 2/3⟩예요."]},{"stem":"4 ÷ 9를 분수의 곱셈으로 나타내어 계산하면 얼마인가요?","options":[{"t":"⟨4/9⟩","correct":true},{"t":"36","mis":"M6-1-u1-X06"},{"t":"⟨2 1/4⟩","mis":"M6-1-u1-X07"},{"t":"⟨1/36⟩","mis":"M6-1-u1-X07"}],"explanation":["4 ÷ 9 = 4 × ⟨1/9⟩이에요.","4 × ⟨1/9⟩ = ⟨4/9⟩예요.","그래서 몫은 ⟨4/9⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L04_basic#6','math',6,1,'u1','L04','g6_1_math_u1_L04_basic','lesson_basic','M6-1-u1-C4',2,'match','auto','나눗셈과 같은 곱셈식을 알맞게 이으세요.','{}'::text[],true,'{"seq":6,"concept":"M6-1-u1-C4","difficulty":2,"kind":"match","stem":"나눗셈과 같은 곱셈식을 알맞게 이으세요.","pairs":[{"l":"2 ÷ 5","r":"2 × ⟨1/5⟩"},{"l":"4 ÷ 3","r":"4 × ⟨1/3⟩"},{"l":"7 ÷ 8","r":"7 × ⟨1/8⟩"}],"mis":"M6-1-u1-X07","explanation":["÷(자연수)는 그 수를 분모로 하는 단위분수를 곱해요.","2 ÷ 5 = 2 × ⟨1/5⟩, 4 ÷ 3 = 4 × ⟨1/3⟩, 7 ÷ 8 = 7 × ⟨1/8⟩이에요.","나누어지는 수는 그대로 두어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 나눗셈과 같은 곱셈식을 알맞게 이으세요.","pairs":[{"l":"5 ÷ 6","r":"5 × ⟨1/6⟩"},{"l":"3 ÷ 7","r":"3 × ⟨1/7⟩"},{"l":"9 ÷ 2","r":"9 × ⟨1/2⟩"}],"explanation":["÷(자연수)는 그 수를 분모로 하는 단위분수를 곱해요.","5 ÷ 6 = 5 × ⟨1/6⟩, 3 ÷ 7 = 3 × ⟨1/7⟩, 9 ÷ 2 = 9 × ⟨1/2⟩이에요.","나누어지는 수는 그대로 두어요."]},{"stem":"이번에는 다른 보기예요. 나눗셈과 같은 곱셈식을 알맞게 이으세요.","pairs":[{"l":"1 ÷ 4","r":"1 × ⟨1/4⟩"},{"l":"6 ÷ 5","r":"6 × ⟨1/5⟩"},{"l":"8 ÷ 9","r":"8 × ⟨1/9⟩"}],"explanation":["÷(자연수)는 그 수를 분모로 하는 단위분수를 곱해요.","1 ÷ 4 = 1 × ⟨1/4⟩, 6 ÷ 5 = 6 × ⟨1/5⟩, 8 ÷ 9 = 8 × ⟨1/9⟩이에요.","나누어지는 수는 그대로 두어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L04_basic#7','math',6,1,'u1','L04','g6_1_math_u1_L04_basic','lesson_basic','M6-1-u1-C4',2,'mc','auto','□ ÷ 7을 □ × ⟨1/7⟩로 바꾸어 계산해도 되는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u1-X06','M6-1-u1-X07','M6-1-u1-X14']::text[],true,'{"seq":7,"concept":"M6-1-u1-C4","difficulty":2,"kind":"mc","stem":"□ ÷ 7을 □ × ⟨1/7⟩로 바꾸어 계산해도 되는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"7로 똑같이 나눈 한 조각이 전체의 ⟨1/7⟩이기 때문","correct":true},{"t":"7로 나누는 것과 7배 하는 것이 같기 때문","mis":"M6-1-u1-X06"},{"t":"분모와 분자를 바꾸면 되기 때문","mis":"M6-1-u1-X07"},{"t":"나눗셈은 언제나 곱셈이기 때문","mis":"M6-1-u1-X14"}],"explanation":["÷ 7은 7로 똑같이 나눈 것 중의 1을 구해요.","× ⟨1/7⟩도 7로 나눈 것 중의 1을 구해요.","뜻이 같아서 바꾸어 계산할 수 있어요."],"variant_rule":{"alt":[{"stem":"□ ÷ 5를 □ × ⟨1/5⟩로 바꾸어 계산해도 되는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"5로 똑같이 나눈 한 조각이 전체의 ⟨1/5⟩이기 때문","correct":true},{"t":"5로 나누는 것과 5배 하는 것이 같기 때문","mis":"M6-1-u1-X06"},{"t":"분모와 분자를 바꾸면 되기 때문","mis":"M6-1-u1-X07"},{"t":"나눗셈은 언제나 곱셈이기 때문","mis":"M6-1-u1-X14"}],"explanation":["÷ 5는 5로 똑같이 나눈 것 중의 1을 구해요.","× ⟨1/5⟩도 5로 나눈 것 중의 1을 구해요.","뜻이 같아서 바꾸어 계산할 수 있어요."]},{"stem":"□ ÷ 9를 □ × ⟨1/9⟩로 바꾸어 계산해도 되는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"9로 똑같이 나눈 한 조각이 전체의 ⟨1/9⟩이기 때문","correct":true},{"t":"9로 나누는 것과 9배 하는 것이 같기 때문","mis":"M6-1-u1-X06"},{"t":"분모와 분자를 바꾸면 되기 때문","mis":"M6-1-u1-X07"},{"t":"나눗셈은 언제나 곱셈이기 때문","mis":"M6-1-u1-X14"}],"explanation":["÷ 9는 9로 똑같이 나눈 것 중의 1을 구해요.","× ⟨1/9⟩도 9로 나눈 것 중의 1을 구해요.","뜻이 같아서 바꾸어 계산할 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L04_basic#8','math',6,1,'u1','L04','g6_1_math_u1_L04_basic','lesson_basic','M6-1-u1-C4',2,'mc','auto','9 ÷ 5를 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M6-1-u1-X06','M6-1-u1-X07']::text[],true,'{"seq":8,"concept":"M6-1-u1-C4","difficulty":2,"kind":"mc","stem":"9 ÷ 5를 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"9 × ⟨1/5⟩","correct":true},{"t":"9 × 5","mis":"M6-1-u1-X06"},{"t":"5 × ⟨1/9⟩","mis":"M6-1-u1-X07"},{"t":"⟨1/9⟩ × ⟨1/5⟩","mis":"M6-1-u1-X07"}],"explanation":["÷ 5는 5로 똑같이 나눈 것 중의 1이에요.","× ⟨1/5⟩도 5로 똑같이 나눈 것 중의 1이에요.","그래서 9 ÷ 5 = 9 × ⟨1/5⟩ = ⟨1 4/5⟩예요."],"variant_rule":{"alt":[{"stem":"4 ÷ 7을 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"4 × ⟨1/7⟩","correct":true},{"t":"4 × 7","mis":"M6-1-u1-X06"},{"t":"7 × ⟨1/4⟩","mis":"M6-1-u1-X07"},{"t":"⟨1/4⟩ × ⟨1/7⟩","mis":"M6-1-u1-X07"}],"explanation":["÷ 7은 7로 똑같이 나눈 것 중의 1이에요.","× ⟨1/7⟩도 7로 똑같이 나눈 것 중의 1이에요.","그래서 4 ÷ 7 = 4 × ⟨1/7⟩ = ⟨4/7⟩예요."]},{"stem":"11 ÷ 6을 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"11 × ⟨1/6⟩","correct":true},{"t":"11 × 6","mis":"M6-1-u1-X06"},{"t":"6 × ⟨1/11⟩","mis":"M6-1-u1-X07"},{"t":"⟨1/11⟩ × ⟨1/6⟩","mis":"M6-1-u1-X07"}],"explanation":["÷ 6은 6으로 똑같이 나눈 것 중의 1이에요.","× ⟨1/6⟩도 6으로 똑같이 나눈 것 중의 1이에요.","그래서 11 ÷ 6 = 11 × ⟨1/6⟩ = ⟨1 5/6⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L04_basic#9','math',6,1,'u1','L04','g6_1_math_u1_L04_basic','lesson_basic','M6-1-u1-C4',2,'error','auto','다음 중 나눗셈을 분수의 곱셈으로 잘못 나타낸 것은 어느 것인가요?',ARRAY['M6-1-u1-X06','M6-1-u1-X15']::text[],true,'{"seq":9,"concept":"M6-1-u1-C4","difficulty":2,"kind":"error","stem":"다음 중 나눗셈을 분수의 곱셈으로 잘못 나타낸 것은 어느 것인가요?","options":[{"t":"7 ÷ 2 = 7 × 2","correct":true,"mis_target":"M6-1-u1-X06"},{"t":"5 ÷ 3 = 5 × ⟨1/3⟩","mis":"M6-1-u1-X15"},{"t":"1 ÷ 6 = 1 × ⟨1/6⟩","mis":"M6-1-u1-X15"}],"explanation":["÷(자연수)는 그 자연수를 분모로 하는 단위분수를 곱하는 것과 같아요.","7 ÷ 2 = 7 × ⟨1/2⟩이어야 해요.","7 × 2는 오히려 커져요 — 잘못 나타낸 거예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 다음 중 나눗셈을 분수의 곱셈으로 잘못 나타낸 것은 어느 것인가요?","options":[{"t":"6 ÷ 5 = 6 × 5","correct":true,"mis_target":"M6-1-u1-X06"},{"t":"9 ÷ 4 = 9 × ⟨1/4⟩","mis":"M6-1-u1-X15"},{"t":"2 ÷ 7 = 2 × ⟨1/7⟩","mis":"M6-1-u1-X15"}],"explanation":["÷(자연수)는 그 자연수를 분모로 하는 단위분수를 곱하는 것과 같아요.","6 ÷ 5 = 6 × ⟨1/5⟩이어야 해요.","6 × 5는 오히려 커져요 — 잘못 나타낸 거예요."]},{"stem":"이번에는 다른 보기예요. 다음 중 나눗셈을 분수의 곱셈으로 잘못 나타낸 것은 어느 것인가요?","options":[{"t":"3 ÷ 4 = 3 × 4","correct":true,"mis_target":"M6-1-u1-X06"},{"t":"4 ÷ 9 = 4 × ⟨1/9⟩","mis":"M6-1-u1-X15"},{"t":"8 ÷ 3 = 8 × ⟨1/3⟩","mis":"M6-1-u1-X15"}],"explanation":["÷(자연수)는 그 자연수를 분모로 하는 단위분수를 곱하는 것과 같아요.","3 ÷ 4 = 3 × ⟨1/4⟩이어야 해요.","3 × 4는 오히려 커져요 — 잘못 나타낸 거예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L04_basic#10','math',6,1,'u1','L04','g6_1_math_u1_L04_basic','lesson_basic','M6-1-u1-C4',3,'mc','auto','끈 8 m를 5도막으로 나눈 한 도막과 끈 5 m를 3도막으로 나눈 한 도막 가운데 더 긴 것은 어느 것인가요?',ARRAY['M6-1-u1-X11','M6-1-u1-X03']::text[],true,'{"seq":10,"concept":"M6-1-u1-C4","difficulty":3,"kind":"mc","stem":"끈 8 m를 5도막으로 나눈 한 도막과 끈 5 m를 3도막으로 나눈 한 도막 가운데 더 긴 것은 어느 것인가요?","options":[{"t":"끈 5 m를 3도막으로 나눈 한 도막","correct":true},{"t":"끈 8 m를 5도막으로 나눈 한 도막","mis":"M6-1-u1-X11"},{"t":"두 도막의 길이가 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X03"}],"explanation":["8 ÷ 5 = 8 × ⟨1/5⟩ = ⟨1 3/5⟩, 5 ÷ 3 = 5 × ⟨1/3⟩ = ⟨1 2/3⟩예요.","15로 통분하면 ⟨1 3/5⟩ = ⟨24/15⟩, ⟨1 2/3⟩ = ⟨25/15⟩예요.","그래서 더 긴 것은 끈 5 m를 3도막으로 나눈 한 도막이에요."],"variant_rule":{"alt":[{"stem":"끈 7 m를 4도막으로 나눈 한 도막과 끈 9 m를 5도막으로 나눈 한 도막 가운데 더 긴 것은 어느 것인가요?","options":[{"t":"끈 9 m를 5도막으로 나눈 한 도막","correct":true},{"t":"끈 7 m를 4도막으로 나눈 한 도막","mis":"M6-1-u1-X11"},{"t":"두 도막의 길이가 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X03"}],"explanation":["7 ÷ 4 = 7 × ⟨1/4⟩ = ⟨1 3/4⟩, 9 ÷ 5 = 9 × ⟨1/5⟩ = ⟨1 4/5⟩예요.","20으로 통분하면 ⟨1 3/4⟩ = ⟨35/20⟩, ⟨1 4/5⟩ = ⟨36/20⟩이에요.","그래서 더 긴 것은 끈 9 m를 5도막으로 나눈 한 도막이에요."]},{"stem":"끈 5 m를 6도막으로 나눈 한 도막과 끈 4 m를 5도막으로 나눈 한 도막 가운데 더 긴 것은 어느 것인가요?","options":[{"t":"끈 5 m를 6도막으로 나눈 한 도막","correct":true},{"t":"끈 4 m를 5도막으로 나눈 한 도막","mis":"M6-1-u1-X11"},{"t":"두 도막의 길이가 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X03"}],"explanation":["5 ÷ 6 = 5 × ⟨1/6⟩ = ⟨5/6⟩, 4 ÷ 5 = 4 × ⟨1/5⟩ = ⟨4/5⟩예요.","30으로 통분하면 ⟨5/6⟩ = ⟨25/30⟩, ⟨4/5⟩ = ⟨24/30⟩예요.","그래서 더 긴 것은 끈 5 m를 6도막으로 나눈 한 도막이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L04_challenge#1','math',6,1,'u1','L04','g6_1_math_u1_L04_challenge','lesson_challenge','M6-1-u1-C4',2,'sa','auto','13 ÷ 6 = 13 × ⟨1/□⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M6-1-u1-C4","difficulty":2,"kind":"sa","stem":"13 ÷ 6 = 13 × ⟨1/□⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["÷ 6은 6으로 나눈 것 중의 1이에요.","그래서 ⟨1/6⟩을 곱하는 것과 같아요.","13 ÷ 6 = 13 × ⟨1/6⟩ — □는 6이에요."],"mis":"M6-1-u1-X07","variant_rule":{"alt":[{"stem":"7 ÷ 9 = 7 × ⟨1/□⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["÷ 9는 9로 나눈 것 중의 1이에요.","그래서 ⟨1/9⟩을 곱하는 것과 같아요.","7 ÷ 9 = 7 × ⟨1/9⟩ — □는 9예요."]},{"stem":"11 ÷ 3 = 11 × ⟨1/□⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["÷ 3은 3으로 나눈 것 중의 1이에요.","그래서 ⟨1/3⟩을 곱하는 것과 같아요.","11 ÷ 3 = 11 × ⟨1/3⟩ — □는 3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L04_challenge#2','math',6,1,'u1','L04','g6_1_math_u1_L04_challenge','lesson_challenge','M6-1-u1-C4',2,'mc','auto','17 ÷ 5를 분수의 곱셈으로 나타내어 계산하면 얼마인가요?',ARRAY['M6-1-u1-X06','M6-1-u1-X07']::text[],true,'{"seq":2,"concept":"M6-1-u1-C4","difficulty":2,"kind":"mc","stem":"17 ÷ 5를 분수의 곱셈으로 나타내어 계산하면 얼마인가요?","options":[{"t":"⟨3 2/5⟩","correct":true},{"t":"85","mis":"M6-1-u1-X06"},{"t":"⟨5/17⟩","mis":"M6-1-u1-X07"},{"t":"⟨1/85⟩","mis":"M6-1-u1-X07"}],"explanation":["17 ÷ 5 = 17 × ⟨1/5⟩이에요.","17 × ⟨1/5⟩ = ⟨17/5⟩이에요.","⟨17/5⟩ = ⟨3 2/5⟩예요."],"variant_rule":{"alt":[{"stem":"7 ÷ 8을 분수의 곱셈으로 나타내어 계산하면 얼마인가요?","options":[{"t":"⟨7/8⟩","correct":true},{"t":"56","mis":"M6-1-u1-X06"},{"t":"⟨1 1/7⟩","mis":"M6-1-u1-X07"},{"t":"⟨1/56⟩","mis":"M6-1-u1-X07"}],"explanation":["7 ÷ 8 = 7 × ⟨1/8⟩이에요.","7 × ⟨1/8⟩ = ⟨7/8⟩이에요.","그래서 몫은 ⟨7/8⟩이에요."]},{"stem":"19 ÷ 6을 분수의 곱셈으로 나타내어 계산하면 얼마인가요?","options":[{"t":"⟨3 1/6⟩","correct":true},{"t":"114","mis":"M6-1-u1-X06"},{"t":"⟨6/19⟩","mis":"M6-1-u1-X07"},{"t":"⟨1/114⟩","mis":"M6-1-u1-X07"}],"explanation":["19 ÷ 6 = 19 × ⟨1/6⟩이에요.","19 × ⟨1/6⟩ = ⟨19/6⟩예요.","⟨19/6⟩ = ⟨3 1/6⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L04_challenge#3','math',6,1,'u1','L04','g6_1_math_u1_L04_challenge','lesson_challenge','M6-1-u1-C4',3,'mc','auto','5 ÷ 3을 계산할 때 5 × 3으로 하면 안 되는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u1-X15','M6-1-u1-X06','M6-1-u1-X07']::text[],true,'{"seq":3,"concept":"M6-1-u1-C4","difficulty":3,"kind":"mc","stem":"5 ÷ 3을 계산할 때 5 × 3으로 하면 안 되는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"나누면 양이 작아져야 하는데 3을 곱하면 오히려 커지기 때문","correct":true},{"t":"곱셈은 나눗셈보다 계산이 어렵기 때문","mis":"M6-1-u1-X15"},{"t":"5 × 3도 맞지만 답이 자연수라서","mis":"M6-1-u1-X06"},{"t":"나누어지는 수를 단위분수로 바꾸어야 하기 때문","mis":"M6-1-u1-X07"}],"explanation":["5를 3으로 나누면 ⟨1 2/3⟩로 5보다 작아져야 해요.","5 × 3 = 15는 오히려 커요.","그래서 5 × ⟨1/3⟩을 곱해요."],"variant_rule":{"alt":[{"stem":"7 ÷ 4를 계산할 때 7 × 4로 하면 안 되는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"나누면 양이 작아져야 하는데 4를 곱하면 오히려 커지기 때문","correct":true},{"t":"곱셈은 나눗셈보다 계산이 어렵기 때문","mis":"M6-1-u1-X15"},{"t":"7 × 4도 맞지만 답이 자연수라서","mis":"M6-1-u1-X06"},{"t":"나누어지는 수를 단위분수로 바꾸어야 하기 때문","mis":"M6-1-u1-X07"}],"explanation":["7을 4로 나누면 ⟨1 3/4⟩으로 7보다 작아져야 해요.","7 × 4 = 28은 오히려 커요.","그래서 7 × ⟨1/4⟩을 곱해요."]},{"stem":"9 ÷ 2를 계산할 때 9 × 2로 하면 안 되는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"나누면 양이 작아져야 하는데 2를 곱하면 오히려 커지기 때문","correct":true},{"t":"곱셈은 나눗셈보다 계산이 어렵기 때문","mis":"M6-1-u1-X15"},{"t":"9 × 2도 맞지만 답이 자연수라서","mis":"M6-1-u1-X06"},{"t":"나누어지는 수를 단위분수로 바꾸어야 하기 때문","mis":"M6-1-u1-X07"}],"explanation":["9를 2로 나누면 ⟨4 1/2⟩로 9보다 작아져야 해요.","9 × 2 = 18은 오히려 커요.","그래서 9 × ⟨1/2⟩을 곱해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L04_challenge#4','math',6,1,'u1','L04','g6_1_math_u1_L04_challenge','lesson_challenge','M6-1-u1-C4',3,'error','auto','다음 중 나눗셈을 분수의 곱셈으로 잘못 나타낸 것은 어느 것인가요?',ARRAY['M6-1-u1-X06','M6-1-u1-X15']::text[],true,'{"seq":4,"concept":"M6-1-u1-C4","difficulty":3,"kind":"error","stem":"다음 중 나눗셈을 분수의 곱셈으로 잘못 나타낸 것은 어느 것인가요?","options":[{"t":"9 ÷ 4 = 9 × 4","correct":true,"mis_target":"M6-1-u1-X06"},{"t":"8 ÷ 5 = 8 × ⟨1/5⟩","mis":"M6-1-u1-X15"},{"t":"3 ÷ 7 = 3 × ⟨1/7⟩","mis":"M6-1-u1-X15"}],"explanation":["÷(자연수)는 그 자연수를 분모로 하는 단위분수를 곱하는 것과 같아요.","9 ÷ 4 = 9 × ⟨1/4⟩이어야 해요.","9 × 4는 오히려 커져요 — 잘못 나타낸 거예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 다음 중 나눗셈을 분수의 곱셈으로 잘못 나타낸 것은 어느 것인가요?","options":[{"t":"4 ÷ 6 = 4 × 6","correct":true,"mis_target":"M6-1-u1-X06"},{"t":"5 ÷ 9 = 5 × ⟨1/9⟩","mis":"M6-1-u1-X15"},{"t":"7 ÷ 3 = 7 × ⟨1/3⟩","mis":"M6-1-u1-X15"}],"explanation":["÷(자연수)는 그 자연수를 분모로 하는 단위분수를 곱하는 것과 같아요.","4 ÷ 6 = 4 × ⟨1/6⟩이어야 해요.","4 × 6은 오히려 커져요 — 잘못 나타낸 거예요."]},{"stem":"이번에는 다른 보기예요. 다음 중 나눗셈을 분수의 곱셈으로 잘못 나타낸 것은 어느 것인가요?","options":[{"t":"10 ÷ 3 = 10 × 3","correct":true,"mis_target":"M6-1-u1-X06"},{"t":"2 ÷ 3 = 2 × ⟨1/3⟩","mis":"M6-1-u1-X15"},{"t":"6 ÷ 11 = 6 × ⟨1/11⟩","mis":"M6-1-u1-X15"}],"explanation":["÷(자연수)는 그 자연수를 분모로 하는 단위분수를 곱하는 것과 같아요.","10 ÷ 3 = 10 × ⟨1/3⟩이어야 해요.","10 × 3은 오히려 커져요 — 잘못 나타낸 거예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L04_challenge#5','math',6,1,'u1','L04','g6_1_math_u1_L04_challenge','lesson_challenge','M6-1-u1-C4',3,'mc','auto','끈 11 m를 4도막으로 나눈 한 도막과 끈 8 m를 3도막으로 나눈 한 도막 가운데 더 긴 것은 어느 것인가요?',ARRAY['M6-1-u1-X11','M6-1-u1-X03']::text[],true,'{"seq":5,"concept":"M6-1-u1-C4","difficulty":3,"kind":"mc","stem":"끈 11 m를 4도막으로 나눈 한 도막과 끈 8 m를 3도막으로 나눈 한 도막 가운데 더 긴 것은 어느 것인가요?","options":[{"t":"끈 11 m를 4도막으로 나눈 한 도막","correct":true},{"t":"끈 8 m를 3도막으로 나눈 한 도막","mis":"M6-1-u1-X11"},{"t":"두 도막의 길이가 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X03"}],"explanation":["11 ÷ 4 = 11 × ⟨1/4⟩ = ⟨2 3/4⟩, 8 ÷ 3 = 8 × ⟨1/3⟩ = ⟨2 2/3⟩예요.","12로 통분하면 ⟨2 3/4⟩ = ⟨33/12⟩, ⟨2 2/3⟩ = ⟨32/12⟩예요.","그래서 더 긴 것은 끈 11 m를 4도막으로 나눈 한 도막이에요."],"variant_rule":{"alt":[{"stem":"끈 9 m를 7도막으로 나눈 한 도막과 끈 4 m를 3도막으로 나눈 한 도막 가운데 더 긴 것은 어느 것인가요?","options":[{"t":"끈 4 m를 3도막으로 나눈 한 도막","correct":true},{"t":"끈 9 m를 7도막으로 나눈 한 도막","mis":"M6-1-u1-X11"},{"t":"두 도막의 길이가 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X03"}],"explanation":["9 ÷ 7 = 9 × ⟨1/7⟩ = ⟨1 2/7⟩, 4 ÷ 3 = 4 × ⟨1/3⟩ = ⟨1 1/3⟩이에요.","21로 통분하면 ⟨1 2/7⟩ = ⟨27/21⟩, ⟨1 1/3⟩ = ⟨28/21⟩이에요.","그래서 더 긴 것은 끈 4 m를 3도막으로 나눈 한 도막이에요."]},{"stem":"끈 13 m를 5도막으로 나눈 한 도막과 끈 8 m를 3도막으로 나눈 한 도막 가운데 더 긴 것은 어느 것인가요?","options":[{"t":"끈 8 m를 3도막으로 나눈 한 도막","correct":true},{"t":"끈 13 m를 5도막으로 나눈 한 도막","mis":"M6-1-u1-X11"},{"t":"두 도막의 길이가 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X03"}],"explanation":["13 ÷ 5 = 13 × ⟨1/5⟩ = ⟨2 3/5⟩, 8 ÷ 3 = 8 × ⟨1/3⟩ = ⟨2 2/3⟩예요.","15로 통분하면 ⟨2 3/5⟩ = ⟨39/15⟩, ⟨2 2/3⟩ = ⟨40/15⟩이에요.","그래서 더 긴 것은 끈 8 m를 3도막으로 나눈 한 도막이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L04_challenge#6','math',6,1,'u1','L04','g6_1_math_u1_L04_challenge','lesson_challenge','M6-1-u1-C4',3,'ox','auto','3 ÷ 8 = 8 × ⟨1/3⟩이에요.',ARRAY['M6-1-u1-X07']::text[],true,'{"seq":6,"concept":"M6-1-u1-C4","difficulty":3,"kind":"ox","stem":"3 ÷ 8 = 8 × ⟨1/3⟩이에요.","answer":"X","reason_options":[{"t":"나누는 수 8을 분모로 하는 단위분수를 곱해 3 × ⟨1/8⟩이어야 하므로","correct":true},{"t":"두 수를 바꾸어 써도 곱은 같으므로","mis":"M6-1-u1-X07"}],"mis":"M6-1-u1-X07","explanation":["3 ÷ 8 = ⟨3/8⟩이에요.","8 × ⟨1/3⟩ = ⟨2 2/3⟩로 값이 달라요.","바른 식은 3 ÷ 8 = 3 × ⟨1/8⟩이에요."],"variant_rule":{"alt":[{"stem":"9 ÷ 2를 곱셈으로 바꾸면 9 × ⟨1/2⟩이고, 몫은 ⟨4 1/2⟩이에요.","answer":"O","reason_options":[{"t":"9 × ⟨1/2⟩ = ⟨9/2⟩ = ⟨4 1/2⟩이므로","correct":true},{"t":"9 × 2 = 18의 반이 몫이므로","mis":"M6-1-u1-X06"}],"explanation":["9 ÷ 2 = 9 × ⟨1/2⟩이에요.","9 × ⟨1/2⟩ = ⟨9/2⟩예요.","⟨9/2⟩ = ⟨4 1/2⟩ — 맞아요."]},{"stem":"1 ÷ 5 = 5 × ⟨1/5⟩이에요.","answer":"X","reason_options":[{"t":"나누어지는 수 1에 ⟨1/5⟩을 곱해 1 × ⟨1/5⟩이어야 하므로","correct":true},{"t":"두 수의 자리를 바꾸어도 되므로","mis":"M6-1-u1-X07"}],"explanation":["1 ÷ 5는 1을 5로 나눈 한 조각이에요.","1 ÷ 5 = 1 × ⟨1/5⟩ = ⟨1/5⟩이에요.","5 × ⟨1/5⟩ = 1이라 값이 달라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L04_challenge#7','math',6,1,'u1','L04','g6_1_math_u1_L04_challenge','lesson_challenge','M6-1-u1-C4',3,'sa','auto','13 ÷ 4를 분수의 곱셈으로 나타내어 계산한 몫을 대분수로 나타냈어요. 자연수 부분과 분자의 합은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M6-1-u1-C4","difficulty":3,"kind":"sa","stem":"13 ÷ 4를 분수의 곱셈으로 나타내어 계산한 몫을 대분수로 나타냈어요. 자연수 부분과 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["13 ÷ 4 = 13 × ⟨1/4⟩ = ⟨13/4⟩이에요.","⟨13/4⟩ = ⟨3 1/4⟩이에요.","자연수 부분과 분자의 합은 3 + 1 = 4예요."],"mis":"M6-1-u1-X15","variant_rule":{"alt":[{"stem":"17 ÷ 3을 분수의 곱셈으로 나타내어 계산한 몫을 대분수로 나타냈어요. 자연수 부분과 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["17 ÷ 3 = 17 × ⟨1/3⟩ = ⟨17/3⟩이에요.","⟨17/3⟩ = ⟨5 2/3⟩예요.","자연수 부분과 분자의 합은 5 + 2 = 7이에요."]},{"stem":"23 ÷ 5를 분수의 곱셈으로 나타내어 계산한 몫을 대분수로 나타냈어요. 자연수 부분과 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["23 ÷ 5 = 23 × ⟨1/5⟩ = ⟨23/5⟩이에요.","⟨23/5⟩ = ⟨4 3/5⟩이에요.","자연수 부분과 분자의 합은 4 + 3 = 7이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L04_challenge#8','math',6,1,'u1','L04','g6_1_math_u1_L04_challenge','lesson_challenge','M6-1-u1-C4',4,'sa','auto','□ × ⟨1/6⟩ = ⟨2 1/6⟩일 때 □에 알맞은 자연수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M6-1-u1-C4","difficulty":4,"kind":"sa","stem":"□ × ⟨1/6⟩ = ⟨2 1/6⟩일 때 □에 알맞은 자연수는 얼마인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["□ × ⟨1/6⟩은 □ ÷ 6과 같고 몫은 ⟨□/6⟩이에요.","⟨2 1/6⟩을 가분수로 고치면 ⟨13/6⟩이에요 — 2 × 6 + 1 = 13.","그래서 □는 13이에요."],"mis":"M6-1-u1-X05","variant_rule":{"alt":[{"stem":"□ × ⟨1/5⟩ = ⟨3 2/5⟩일 때 □에 알맞은 자연수는 얼마인가요? 숫자로 쓰세요.","answer":["17"],"explanation":["□ × ⟨1/5⟩은 □ ÷ 5와 같고 몫은 ⟨□/5⟩이에요.","⟨3 2/5⟩를 가분수로 고치면 ⟨17/5⟩이에요 — 3 × 5 + 2 = 17.","그래서 □는 17이에요."]},{"stem":"□ × ⟨1/9⟩ = ⟨1 4/9⟩일 때 □에 알맞은 자연수는 얼마인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["□ × ⟨1/9⟩은 □ ÷ 9와 같고 몫은 ⟨□/9⟩이에요.","⟨1 4/9⟩를 가분수로 고치면 ⟨13/9⟩이에요 — 1 × 9 + 4 = 13.","그래서 □는 13이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L04_challenge#9','math',6,1,'u1','L04','g6_1_math_u1_L04_challenge','lesson_challenge','M6-1-u1-C4',4,'mc','auto','3 ÷ 4 ÷ 2를 분수의 곱셈으로 나타내어 계산하면 얼마인가요?',ARRAY['M6-1-u1-X06','M6-1-u1-X09']::text[],true,'{"seq":9,"concept":"M6-1-u1-C4","difficulty":4,"kind":"mc","stem":"3 ÷ 4 ÷ 2를 분수의 곱셈으로 나타내어 계산하면 얼마인가요?","options":[{"t":"⟨3/8⟩","correct":true},{"t":"24","mis":"M6-1-u1-X06"},{"t":"⟨1 1/2⟩","mis":"M6-1-u1-X06"},{"t":"⟨1/2⟩","mis":"M6-1-u1-X09"}],"explanation":["÷ 4는 × ⟨1/4⟩, ÷ 2는 × ⟨1/2⟩이에요.","3 ÷ 4 ÷ 2 = 3 × ⟨1/4⟩ × ⟨1/2⟩이에요.","3 × ⟨1/4⟩ × ⟨1/2⟩ = ⟨3/8⟩이에요."],"variant_rule":{"alt":[{"stem":"5 ÷ 2 ÷ 3을 분수의 곱셈으로 나타내어 계산하면 얼마인가요?","options":[{"t":"⟨5/6⟩","correct":true},{"t":"30","mis":"M6-1-u1-X06"},{"t":"⟨7 1/2⟩","mis":"M6-1-u1-X06"},{"t":"1","mis":"M6-1-u1-X09"}],"explanation":["÷ 2는 × ⟨1/2⟩, ÷ 3은 × ⟨1/3⟩이에요.","5 ÷ 2 ÷ 3 = 5 × ⟨1/2⟩ × ⟨1/3⟩이에요.","5 × ⟨1/2⟩ × ⟨1/3⟩ = ⟨5/6⟩예요."]},{"stem":"2 ÷ 3 ÷ 5를 분수의 곱셈으로 나타내어 계산하면 얼마인가요?","options":[{"t":"⟨2/15⟩","correct":true},{"t":"30","mis":"M6-1-u1-X06"},{"t":"⟨3 1/3⟩","mis":"M6-1-u1-X06"},{"t":"⟨1/4⟩","mis":"M6-1-u1-X09"}],"explanation":["÷ 3은 × ⟨1/3⟩, ÷ 5는 × ⟨1/5⟩이에요.","2 ÷ 3 ÷ 5 = 2 × ⟨1/3⟩ × ⟨1/5⟩이에요.","2 × ⟨1/3⟩ × ⟨1/5⟩ = ⟨2/15⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L04_challenge#10','math',6,1,'u1','L04','g6_1_math_u1_L04_challenge','lesson_challenge','M6-1-u1-C4',4,'essay','teacher','친구가 5 ÷ 3을 「5 × 3 = 15」로 계산했어요. 이 계산이 잘못된 까닭을 쓰고, 분수의 곱셈으로 바르게 계산해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-1-u1-C4","difficulty":4,"kind":"essay","stem":"친구가 5 ÷ 3을 「5 × 3 = 15」로 계산했어요. 이 계산이 잘못된 까닭을 쓰고, 분수의 곱셈으로 바르게 계산해 보세요.","answer_guide":{"answer":"예: 5를 3으로 나누면 3으로 똑같이 나눈 것 중의 1이므로 5보다 작아져야 하는데, 5 × 3 = 15는 오히려 커졌다. ÷ 3은 × ⟨1/3⟩과 같으므로 5 ÷ 3 = 5 × ⟨1/3⟩ = ⟨5/3⟩ = ⟨1 2/3⟩이다.","scoring_points":["나누면 작아져야 하는데 15는 커졌다고 썼는가","÷ 3 = × ⟨1/3⟩임을 밝혔는가","5 ÷ 3 = ⟨1 2/3⟩(또는 ⟨5/3⟩)를 구했는가"]},"explanation":["5를 3으로 나누면 5보다 작아져야 해요.","÷ 3은 × ⟨1/3⟩이에요.","5 ÷ 3 = 5 × ⟨1/3⟩ = ⟨1 2/3⟩예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L05_basic#1','math',6,1,'u1','L05','g6_1_math_u1_L05_basic','lesson_basic','M6-1-u1-C5',1,'mc','auto','⟨8/9⟩ ÷ 2를 계산하면 얼마인가요?',ARRAY['M6-1-u1-X06','M6-1-u1-X09','M6-1-u1-X07']::text[],true,'{"seq":1,"concept":"M6-1-u1-C5","difficulty":1,"kind":"mc","stem":"⟨8/9⟩ ÷ 2를 계산하면 얼마인가요?","options":[{"t":"⟨4/9⟩","correct":true},{"t":"⟨1 7/9⟩","mis":"M6-1-u1-X06"},{"t":"⟨8/11⟩","mis":"M6-1-u1-X09"},{"t":"⟨9/16⟩","mis":"M6-1-u1-X07"}],"explanation":["⟨8/9⟩은 ⟨1/9⟩이 8개예요.","분자 8을 2로 나누면 8 ÷ 2 = 4 — ⟨1/9⟩이 4개예요.","그래서 ⟨8/9⟩ ÷ 2 = ⟨4/9⟩예요."],"variant_rule":{"alt":[{"stem":"⟨6/7⟩ ÷ 3을 계산하면 얼마인가요?","options":[{"t":"⟨2/7⟩","correct":true},{"t":"⟨2 4/7⟩","mis":"M6-1-u1-X06"},{"t":"⟨3/5⟩","mis":"M6-1-u1-X09"},{"t":"⟨7/18⟩","mis":"M6-1-u1-X07"}],"explanation":["⟨6/7⟩은 ⟨1/7⟩이 6개예요.","분자 6을 3으로 나누면 6 ÷ 3 = 2 — ⟨1/7⟩이 2개예요.","그래서 ⟨6/7⟩ ÷ 3 = ⟨2/7⟩예요."]},{"stem":"⟨4/5⟩ ÷ 2를 계산하면 얼마인가요?","options":[{"t":"⟨2/5⟩","correct":true},{"t":"⟨1 3/5⟩","mis":"M6-1-u1-X06"},{"t":"⟨4/7⟩","mis":"M6-1-u1-X09"},{"t":"⟨5/8⟩","mis":"M6-1-u1-X07"}],"explanation":["⟨4/5⟩는 ⟨1/5⟩이 4개예요.","분자 4를 2로 나누면 4 ÷ 2 = 2 — ⟨1/5⟩이 2개예요.","그래서 ⟨4/5⟩ ÷ 2 = ⟨2/5⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L05_basic#2','math',6,1,'u1','L05','g6_1_math_u1_L05_basic','lesson_basic','M6-1-u1-C5',1,'mc','auto','⟨5/7⟩ ÷ 3을 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M6-1-u1-X06','M6-1-u1-X07']::text[],true,'{"seq":2,"concept":"M6-1-u1-C5","difficulty":1,"kind":"mc","stem":"⟨5/7⟩ ÷ 3을 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨5/7⟩ × ⟨1/3⟩","correct":true},{"t":"⟨5/7⟩ × 3","mis":"M6-1-u1-X06"},{"t":"⟨7/5⟩ × ⟨1/3⟩","mis":"M6-1-u1-X07"},{"t":"3 × ⟨5/7⟩","mis":"M6-1-u1-X06"}],"explanation":["÷ 3은 3으로 똑같이 나눈 것 중의 1이에요.","그래서 × ⟨1/3⟩과 같아요.","⟨5/7⟩ ÷ 3 = ⟨5/7⟩ × ⟨1/3⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨2/9⟩ ÷ 4를 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨2/9⟩ × ⟨1/4⟩","correct":true},{"t":"⟨2/9⟩ × 4","mis":"M6-1-u1-X06"},{"t":"⟨9/2⟩ × ⟨1/4⟩","mis":"M6-1-u1-X07"},{"t":"4 × ⟨2/9⟩","mis":"M6-1-u1-X06"}],"explanation":["÷ 4는 4로 똑같이 나눈 것 중의 1이에요.","그래서 × ⟨1/4⟩과 같아요.","⟨2/9⟩ ÷ 4 = ⟨2/9⟩ × ⟨1/4⟩이에요."]},{"stem":"⟨3/8⟩ ÷ 5를 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨3/8⟩ × ⟨1/5⟩","correct":true},{"t":"⟨3/8⟩ × 5","mis":"M6-1-u1-X06"},{"t":"⟨8/3⟩ × ⟨1/5⟩","mis":"M6-1-u1-X07"},{"t":"5 × ⟨3/8⟩","mis":"M6-1-u1-X06"}],"explanation":["÷ 5는 5로 똑같이 나눈 것 중의 1이에요.","그래서 × ⟨1/5⟩과 같아요.","⟨3/8⟩ ÷ 5 = ⟨3/8⟩ × ⟨1/5⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L05_basic#3','math',6,1,'u1','L05','g6_1_math_u1_L05_basic','lesson_basic','M6-1-u1-C5',1,'sa','auto','⟨6/7⟩ ÷ 2의 몫은 ⟨1/7⟩이 몇 개인 수인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M6-1-u1-C5","difficulty":1,"kind":"sa","stem":"⟨6/7⟩ ÷ 2의 몫은 ⟨1/7⟩이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["⟨6/7⟩은 ⟨1/7⟩이 6개예요.","6개를 2로 똑같이 나누면 6 ÷ 2 = 3개예요.","⟨6/7⟩ ÷ 2 = ⟨3/7⟩ — ⟨1/7⟩이 3개예요."],"mis":"M6-1-u1-X08","variant_rule":{"alt":[{"stem":"⟨9/10⟩ ÷ 3의 몫은 ⟨1/10⟩이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["⟨9/10⟩는 ⟨1/10⟩이 9개예요.","9개를 3으로 똑같이 나누면 9 ÷ 3 = 3개예요.","⟨9/10⟩ ÷ 3 = ⟨3/10⟩ — ⟨1/10⟩이 3개예요."]},{"stem":"⟨8/11⟩ ÷ 4의 몫은 ⟨1/11⟩이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["⟨8/11⟩은 ⟨1/11⟩이 8개예요.","8개를 4로 똑같이 나누면 8 ÷ 4 = 2개예요.","⟨8/11⟩ ÷ 4 = ⟨2/11⟩ — ⟨1/11⟩이 2개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L05_basic#4','math',6,1,'u1','L05','g6_1_math_u1_L05_basic','lesson_basic','M6-1-u1-C5',1,'ox','auto','⟨6/7⟩ ÷ 2 = ⟨3/7⟩이에요.',ARRAY['M6-1-u1-X08']::text[],true,'{"seq":4,"concept":"M6-1-u1-C5","difficulty":1,"kind":"ox","stem":"⟨6/7⟩ ÷ 2 = ⟨3/7⟩이에요.","answer":"O","reason_options":[{"t":"분자 6을 2로 나누어 ⟨1/7⟩이 3개가 되므로","correct":true},{"t":"분모 7을 2로 나누어야 하므로","mis":"M6-1-u1-X08"}],"mis":"M6-1-u1-X08","explanation":["⟨6/7⟩은 ⟨1/7⟩이 6개예요.","6 ÷ 2 = 3이에요.","⟨6/7⟩ ÷ 2 = ⟨3/7⟩ — 맞아요."],"variant_rule":{"alt":[{"stem":"⟨3/5⟩ ÷ 4 = ⟨3/5⟩ × ⟨1/4⟩이에요.","answer":"O","reason_options":[{"t":"÷ 4는 4로 나눈 것 중의 1, × ⟨1/4⟩과 같으므로","correct":true},{"t":"× 4와 ÷ 4는 같으므로","mis":"M6-1-u1-X06"}],"explanation":["÷ 4는 4로 똑같이 나눈 것 중의 1이에요.","⟨3/5⟩ ÷ 4 = ⟨3/5⟩ × ⟨1/4⟩ = ⟨3/20⟩이에요.","그래서 맞아요."]},{"stem":"⟨4/5⟩ ÷ 3은 분자 4가 3으로 나누어떨어지지 않으므로 계산할 수 없어요.","answer":"X","reason_options":[{"t":"⟨4/5⟩ × ⟨1/3⟩ = ⟨4/15⟩로 계산할 수 있으므로","correct":true},{"t":"분자가 나누어떨어져야만 나눌 수 있으므로","mis":"M6-1-u1-X02"}],"explanation":["분자가 나누어떨어지지 않아도 단위분수를 곱하면 돼요.","⟨4/5⟩ ÷ 3 = ⟨4/5⟩ × ⟨1/3⟩이에요.","⟨4/5⟩ × ⟨1/3⟩ = ⟨4/15⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L05_basic#5','math',6,1,'u1','L05','g6_1_math_u1_L05_basic','lesson_basic','M6-1-u1-C5',2,'mc','auto','⟨4/5⟩ ÷ 3을 계산하면 얼마인가요?',ARRAY['M6-1-u1-X06','M6-1-u1-X09','M6-1-u1-X07']::text[],true,'{"seq":5,"concept":"M6-1-u1-C5","difficulty":2,"kind":"mc","stem":"⟨4/5⟩ ÷ 3을 계산하면 얼마인가요?","options":[{"t":"⟨4/15⟩","correct":true},{"t":"⟨2 2/5⟩","mis":"M6-1-u1-X06"},{"t":"⟨1/2⟩","mis":"M6-1-u1-X09"},{"t":"⟨5/12⟩","mis":"M6-1-u1-X07"}],"explanation":["분자 4는 3으로 나누어떨어지지 않아요.","⟨4/5⟩ ÷ 3 = ⟨4/5⟩ × ⟨1/3⟩로 바꾸어요.","⟨4/5⟩ × ⟨1/3⟩ = ⟨4/15⟩예요."],"variant_rule":{"alt":[{"stem":"⟨3/7⟩ ÷ 2를 계산하면 얼마인가요?","options":[{"t":"⟨3/14⟩","correct":true},{"t":"⟨6/7⟩","mis":"M6-1-u1-X06"},{"t":"⟨1/3⟩","mis":"M6-1-u1-X09"},{"t":"⟨1 1/6⟩","mis":"M6-1-u1-X07"}],"explanation":["분자 3은 2로 나누어떨어지지 않아요.","⟨3/7⟩ ÷ 2 = ⟨3/7⟩ × ⟨1/2⟩로 바꾸어요.","⟨3/7⟩ × ⟨1/2⟩ = ⟨3/14⟩이에요."]},{"stem":"⟨5/6⟩ ÷ 4를 계산하면 얼마인가요?","options":[{"t":"⟨5/24⟩","correct":true},{"t":"⟨3 1/3⟩","mis":"M6-1-u1-X06"},{"t":"⟨1/2⟩","mis":"M6-1-u1-X09"},{"t":"⟨3/10⟩","mis":"M6-1-u1-X07"}],"explanation":["분자 5는 4로 나누어떨어지지 않아요.","⟨5/6⟩ ÷ 4 = ⟨5/6⟩ × ⟨1/4⟩로 바꾸어요.","⟨5/6⟩ × ⟨1/4⟩ = ⟨5/24⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L05_basic#6','math',6,1,'u1','L05','g6_1_math_u1_L05_basic','lesson_basic','M6-1-u1-C5',2,'sa','auto','⟨2/11⟩ ÷ 5를 분수의 곱셈으로 바꾸어 계산하면 몫의 분모는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M6-1-u1-C5","difficulty":2,"kind":"sa","stem":"⟨2/11⟩ ÷ 5를 분수의 곱셈으로 바꾸어 계산하면 몫의 분모는 얼마인가요? 숫자로 쓰세요.","answer":["55"],"explanation":["⟨2/11⟩ ÷ 5 = ⟨2/11⟩ × ⟨1/5⟩이에요.","분모끼리 곱하면 11 × 5 = 55예요.","⟨2/11⟩ × ⟨1/5⟩ = ⟨2/55⟩ — 분모는 55예요."],"mis":"M6-1-u1-X08","variant_rule":{"alt":[{"stem":"⟨3/8⟩ ÷ 7을 분수의 곱셈으로 바꾸어 계산하면 몫의 분모는 얼마인가요? 숫자로 쓰세요.","answer":["56"],"explanation":["⟨3/8⟩ ÷ 7 = ⟨3/8⟩ × ⟨1/7⟩이에요.","분모끼리 곱하면 8 × 7 = 56이에요.","⟨3/8⟩ × ⟨1/7⟩ = ⟨3/56⟩ — 분모는 56이에요."]},{"stem":"⟨5/9⟩ ÷ 4를 분수의 곱셈으로 바꾸어 계산하면 몫의 분모는 얼마인가요? 숫자로 쓰세요.","answer":["36"],"explanation":["⟨5/9⟩ ÷ 4 = ⟨5/9⟩ × ⟨1/4⟩이에요.","분모끼리 곱하면 9 × 4 = 36이에요.","⟨5/9⟩ × ⟨1/4⟩ = ⟨5/36⟩ — 분모는 36이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L05_basic#7','math',6,1,'u1','L05','g6_1_math_u1_L05_basic','lesson_basic','M6-1-u1-C5',2,'sa','auto','물 ⟨9/10⟩ L를 3명이 똑같이 나누어 마셨어요. 한 명이 마신 물은 ⟨1/10⟩이 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M6-1-u1-C5","difficulty":2,"kind":"sa","stem":"물 ⟨9/10⟩ L를 3명이 똑같이 나누어 마셨어요. 한 명이 마신 물은 ⟨1/10⟩이 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["⟨9/10⟩는 ⟨1/10⟩이 9개예요.","9개를 3으로 나누면 9 ÷ 3 = 3개예요.","한 명이 마신 물은 ⟨3/10⟩ L — ⟨1/10⟩이 3개예요."],"mis":"M6-1-u1-X08","variant_rule":{"alt":[{"stem":"주스 ⟨8/9⟩ L를 4명이 똑같이 나누어 마셨어요. 한 명이 마신 주스는 ⟨1/9⟩이 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["⟨8/9⟩은 ⟨1/9⟩이 8개예요.","8개를 4로 나누면 8 ÷ 4 = 2개예요.","한 명이 마신 주스는 ⟨2/9⟩ L — ⟨1/9⟩이 2개예요."]},{"stem":"색 모래 ⟨6/7⟩ kg을 2모둠이 똑같이 나누어 가졌어요. 한 모둠이 가진 색 모래는 ⟨1/7⟩이 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["⟨6/7⟩은 ⟨1/7⟩이 6개예요.","6개를 2로 나누면 6 ÷ 2 = 3개예요.","한 모둠이 가진 색 모래는 ⟨3/7⟩ kg — ⟨1/7⟩이 3개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L05_basic#8','math',6,1,'u1','L05','g6_1_math_u1_L05_basic','lesson_basic','M6-1-u1-C5',2,'match','auto','나눗셈과 몫을 알맞게 이으세요.','{}'::text[],true,'{"seq":8,"concept":"M6-1-u1-C5","difficulty":2,"kind":"match","stem":"나눗셈과 몫을 알맞게 이으세요.","pairs":[{"l":"⟨6/7⟩ ÷ 3","r":"⟨2/7⟩"},{"l":"⟨4/5⟩ ÷ 3","r":"⟨4/15⟩"},{"l":"⟨2/9⟩ ÷ 2","r":"⟨1/9⟩"}],"mis":"M6-1-u1-X06","explanation":["분자가 나누어떨어지면 분자만, 아니면 단위분수를 곱해요.","⟨6/7⟩ ÷ 3 = ⟨2/7⟩, ⟨4/5⟩ ÷ 3 = ⟨4/15⟩, ⟨2/9⟩ ÷ 2 = ⟨1/9⟩이에요.","나누는 수를 그대로 곱하지 않도록 해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 나눗셈과 몫을 알맞게 이으세요.","pairs":[{"l":"⟨8/9⟩ ÷ 4","r":"⟨2/9⟩"},{"l":"⟨3/4⟩ ÷ 2","r":"⟨3/8⟩"},{"l":"⟨5/6⟩ ÷ 5","r":"⟨1/6⟩"}],"explanation":["분자가 나누어떨어지면 분자만, 아니면 단위분수를 곱해요.","⟨8/9⟩ ÷ 4 = ⟨2/9⟩, ⟨3/4⟩ ÷ 2 = ⟨3/8⟩, ⟨5/6⟩ ÷ 5 = ⟨1/6⟩이에요.","나누는 수를 그대로 곱하지 않도록 해요."]},{"stem":"이번에는 다른 보기예요. 나눗셈과 몫을 알맞게 이으세요.","pairs":[{"l":"⟨9/10⟩ ÷ 3","r":"⟨3/10⟩"},{"l":"⟨1/3⟩ ÷ 4","r":"⟨1/12⟩"},{"l":"⟨4/7⟩ ÷ 2","r":"⟨2/7⟩"}],"explanation":["분자가 나누어떨어지면 분자만, 아니면 단위분수를 곱해요.","⟨9/10⟩ ÷ 3 = ⟨3/10⟩, ⟨1/3⟩ ÷ 4 = ⟨1/12⟩, ⟨4/7⟩ ÷ 2 = ⟨2/7⟩예요.","나누는 수를 그대로 곱하지 않도록 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L05_basic#9','math',6,1,'u1','L05','g6_1_math_u1_L05_basic','lesson_basic','M6-1-u1-C5',2,'mc','auto','⟨4/5⟩ ÷ 2와 ⟨4/5⟩ ÷ 3 가운데 몫이 더 큰 것은 어느 것인가요?',ARRAY['M6-1-u1-X11','M6-1-u1-X15']::text[],true,'{"seq":9,"concept":"M6-1-u1-C5","difficulty":2,"kind":"mc","stem":"⟨4/5⟩ ÷ 2와 ⟨4/5⟩ ÷ 3 가운데 몫이 더 큰 것은 어느 것인가요?","options":[{"t":"⟨4/5⟩ ÷ 2","correct":true},{"t":"⟨4/5⟩ ÷ 3","mis":"M6-1-u1-X11"},{"t":"두 몫이 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X15"}],"explanation":["⟨4/5⟩ ÷ 2 = ⟨2/5⟩, ⟨4/5⟩ ÷ 3 = ⟨4/15⟩예요.","15로 통분하면 ⟨2/5⟩ = ⟨6/15⟩, ⟨4/15⟩ = ⟨4/15⟩예요.","같은 양을 더 적게 나눌수록 몫이 커요 — ⟨4/5⟩ ÷ 2가 더 커요."],"variant_rule":{"alt":[{"stem":"⟨6/7⟩ ÷ 2와 ⟨6/7⟩ ÷ 3 가운데 몫이 더 큰 것은 어느 것인가요?","options":[{"t":"⟨6/7⟩ ÷ 2","correct":true},{"t":"⟨6/7⟩ ÷ 3","mis":"M6-1-u1-X11"},{"t":"두 몫이 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X15"}],"explanation":["⟨6/7⟩ ÷ 2 = ⟨3/7⟩, ⟨6/7⟩ ÷ 3 = ⟨2/7⟩예요.","7로 통분하면 ⟨3/7⟩ = ⟨3/7⟩, ⟨2/7⟩ = ⟨2/7⟩예요.","같은 양을 더 적게 나눌수록 몫이 커요 — ⟨6/7⟩ ÷ 2가 더 커요."]},{"stem":"⟨3/4⟩ ÷ 2와 ⟨3/4⟩ ÷ 5 가운데 몫이 더 큰 것은 어느 것인가요?","options":[{"t":"⟨3/4⟩ ÷ 2","correct":true},{"t":"⟨3/4⟩ ÷ 5","mis":"M6-1-u1-X11"},{"t":"두 몫이 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X15"}],"explanation":["⟨3/4⟩ ÷ 2 = ⟨3/8⟩, ⟨3/4⟩ ÷ 5 = ⟨3/20⟩이에요.","40으로 통분하면 ⟨3/8⟩ = ⟨15/40⟩, ⟨3/20⟩ = ⟨6/40⟩이에요.","같은 양을 더 적게 나눌수록 몫이 커요 — ⟨3/4⟩ ÷ 2가 더 커요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L05_basic#10','math',6,1,'u1','L05','g6_1_math_u1_L05_basic','lesson_basic','M6-1-u1-C5',3,'mc','auto','진분수를 1보다 큰 자연수로 나눌 때 몫에 대한 설명으로 옳은 것은 어느 것인가요?',ARRAY['M6-1-u1-X06','M6-1-u1-X11','M6-1-u1-X03']::text[],true,'{"seq":10,"concept":"M6-1-u1-C5","difficulty":3,"kind":"mc","stem":"진분수를 1보다 큰 자연수로 나눌 때 몫에 대한 설명으로 옳은 것은 어느 것인가요?","options":[{"t":"몫은 처음 진분수보다 항상 작다","correct":true},{"t":"몫은 처음 진분수보다 항상 크다","mis":"M6-1-u1-X06"},{"t":"나누는 수가 클수록 몫이 커진다","mis":"M6-1-u1-X11"},{"t":"몫은 언제나 자연수가 된다","mis":"M6-1-u1-X03"}],"explanation":["(진분수)÷(자연수)는 (진분수) × (단위분수)로 바꾸어 계산해요.","1보다 큰 수로 나누면 처음보다 작아지고, 더 큰 수로 나눌수록 더 작아져요.","그래서 답은 「몫은 처음 진분수보다 항상 작다」예요."],"variant_rule":{"alt":[{"stem":"진분수를 1보다 큰 자연수로 나눌 때 몫에 대한 설명으로 옳지 않은 것은 어느 것인가요?","options":[{"t":"나누는 수가 클수록 몫이 커진다","correct":true},{"t":"몫은 처음 진분수보다 작다","mis":"M6-1-u1-X15"},{"t":"단위분수를 곱해 구할 수 있다","mis":"M6-1-u1-X15"},{"t":"분자가 나누어떨어지면 분자만 나누어도 된다","mis":"M6-1-u1-X15"}],"explanation":["(진분수)÷(자연수)는 (진분수) × (단위분수)로 바꾸어 계산해요.","1보다 큰 수로 나누면 처음보다 작아지고, 더 큰 수로 나눌수록 더 작아져요.","그래서 답은 「나누는 수가 클수록 몫이 커진다」예요."]},{"stem":"(진분수)÷(자연수)를 계산하는 방법으로 언제나 쓸 수 있는 것은 어느 것인가요?","options":[{"t":"(진분수) × (나누는 수를 분모로 하는 단위분수)","correct":true},{"t":"(진분수) × (나누는 수)","mis":"M6-1-u1-X06"},{"t":"분모만 나누는 수로 나누기","mis":"M6-1-u1-X08"},{"t":"분모에 나누는 수를 더하기","mis":"M6-1-u1-X09"}],"explanation":["(진분수)÷(자연수)는 (진분수) × (단위분수)로 바꾸어 계산해요.","1보다 큰 수로 나누면 처음보다 작아지고, 더 큰 수로 나눌수록 더 작아져요.","그래서 답은 「(진분수) × (나누는 수를 분모로 하는 단위분수)」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L05_challenge#1','math',6,1,'u1','L05','g6_1_math_u1_L05_challenge','lesson_challenge','M6-1-u1-C5',2,'sa','auto','손 세정제 ⟨4/5⟩ L를 3병에 똑같이 나누어 담았어요. 한 병에 담은 손 세정제를 분수로 나타낼 때 분모는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M6-1-u1-C5","difficulty":2,"kind":"sa","stem":"손 세정제 ⟨4/5⟩ L를 3병에 똑같이 나누어 담았어요. 한 병에 담은 손 세정제를 분수로 나타낼 때 분모는 얼마인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["분자 4는 3으로 나누어떨어지지 않아요.","⟨4/5⟩ ÷ 3 = ⟨4/5⟩ × ⟨1/3⟩ = ⟨4/15⟩예요.","한 병에 담은 손 세정제는 ⟨4/15⟩ L — 분모는 15예요."],"mis":"M6-1-u1-X08","variant_rule":{"alt":[{"stem":"주스 ⟨5/6⟩ L를 2명이 똑같이 나누어 마셨어요. 한 명이 마신 주스를 분수로 나타낼 때 분모는 얼마인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["분자 5는 2로 나누어떨어지지 않아요.","⟨5/6⟩ ÷ 2 = ⟨5/6⟩ × ⟨1/2⟩ = ⟨5/12⟩예요.","한 명이 마신 주스는 ⟨5/12⟩ L — 분모는 12예요."]},{"stem":"물 ⟨3/8⟩ L를 4명이 똑같이 나누어 마셨어요. 한 명이 마신 물을 분수로 나타낼 때 분모는 얼마인가요? 숫자로 쓰세요.","answer":["32"],"explanation":["분자 3은 4로 나누어떨어지지 않아요.","⟨3/8⟩ ÷ 4 = ⟨3/8⟩ × ⟨1/4⟩ = ⟨3/32⟩이에요.","한 명이 마신 물은 ⟨3/32⟩ L — 분모는 32예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L05_challenge#2','math',6,1,'u1','L05','g6_1_math_u1_L05_challenge','lesson_challenge','M6-1-u1-C5',2,'mc','auto','⟨7/9⟩ ÷ 3을 계산하면 얼마인가요?',ARRAY['M6-1-u1-X06','M6-1-u1-X09','M6-1-u1-X07']::text[],true,'{"seq":2,"concept":"M6-1-u1-C5","difficulty":2,"kind":"mc","stem":"⟨7/9⟩ ÷ 3을 계산하면 얼마인가요?","options":[{"t":"⟨7/27⟩","correct":true},{"t":"⟨2 1/3⟩","mis":"M6-1-u1-X06"},{"t":"⟨7/12⟩","mis":"M6-1-u1-X09"},{"t":"⟨3/7⟩","mis":"M6-1-u1-X07"}],"explanation":["분자 7은 3으로 나누어떨어지지 않아요.","⟨7/9⟩ ÷ 3 = ⟨7/9⟩ × ⟨1/3⟩로 바꾸어요.","⟨7/9⟩ × ⟨1/3⟩ = ⟨7/27⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨9/11⟩ ÷ 3을 계산하면 얼마인가요?","options":[{"t":"⟨3/11⟩","correct":true},{"t":"⟨2 5/11⟩","mis":"M6-1-u1-X06"},{"t":"⟨9/14⟩","mis":"M6-1-u1-X09"},{"t":"⟨11/27⟩","mis":"M6-1-u1-X07"}],"explanation":["⟨9/11⟩는 ⟨1/11⟩이 9개예요.","분자 9를 3으로 나누면 9 ÷ 3 = 3 — ⟨1/11⟩이 3개예요.","그래서 ⟨9/11⟩ ÷ 3 = ⟨3/11⟩이에요."]},{"stem":"⟨5/8⟩ ÷ 3을 계산하면 얼마인가요?","options":[{"t":"⟨5/24⟩","correct":true},{"t":"⟨1 7/8⟩","mis":"M6-1-u1-X06"},{"t":"⟨5/11⟩","mis":"M6-1-u1-X09"},{"t":"⟨8/15⟩","mis":"M6-1-u1-X07"}],"explanation":["분자 5는 3으로 나누어떨어지지 않아요.","⟨5/8⟩ ÷ 3 = ⟨5/8⟩ × ⟨1/3⟩로 바꾸어요.","⟨5/8⟩ × ⟨1/3⟩ = ⟨5/24⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L05_challenge#3','math',6,1,'u1','L05','g6_1_math_u1_L05_challenge','lesson_challenge','M6-1-u1-C5',3,'error','auto','⟨3/5⟩ ÷ 4에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u1-X06','M6-1-u1-X15']::text[],true,'{"seq":3,"concept":"M6-1-u1-C5","difficulty":3,"kind":"error","stem":"⟨3/5⟩ ÷ 4에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「⟨3/5⟩ × 4 = ⟨2 2/5⟩로 계산해.」","correct":true,"mis_target":"M6-1-u1-X06"},{"t":"도윤 — 「⟨3/5⟩ × ⟨1/4⟩로 바꾸어 계산하면 돼.」","mis":"M6-1-u1-X15"},{"t":"하린 — 「몫은 ⟨3/5⟩보다 작아.」","mis":"M6-1-u1-X15"}],"explanation":["4로 나누면 양이 작아져야 해요.","⟨3/5⟩ × 4 = ⟨2 2/5⟩는 오히려 커요.","⟨3/5⟩ ÷ 4 = ⟨3/5⟩ × ⟨1/4⟩ = ⟨3/20⟩ — 수아는 나누는 수를 그대로 곱했어요."],"variant_rule":{"alt":[{"stem":"⟨2/7⟩ ÷ 3에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민준 — 「⟨2/7⟩ × 3 = ⟨6/7⟩으로 계산해.」","correct":true,"mis_target":"M6-1-u1-X06"},{"t":"서연 — 「⟨2/7⟩ × ⟨1/3⟩로 바꾸어 계산하면 돼.」","mis":"M6-1-u1-X15"},{"t":"지호 — 「몫은 ⟨2/7⟩보다 작아.」","mis":"M6-1-u1-X15"}],"explanation":["3으로 나누면 양이 작아져야 해요.","⟨2/7⟩ × 3 = ⟨6/7⟩은 오히려 커요.","⟨2/7⟩ ÷ 3 = ⟨2/7⟩ × ⟨1/3⟩ = ⟨2/21⟩ — 민준은 나누는 수를 그대로 곱했어요."]},{"stem":"⟨5/9⟩ ÷ 2에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「⟨5/9⟩ × 2 = ⟨1 1/9⟩로 계산해.」","correct":true,"mis_target":"M6-1-u1-X06"},{"t":"나린 — 「⟨5/9⟩ × ⟨1/2⟩로 바꾸어 계산하면 돼.」","mis":"M6-1-u1-X15"},{"t":"유진 — 「몫은 ⟨5/9⟩보다 작아.」","mis":"M6-1-u1-X15"}],"explanation":["2로 나누면 양이 작아져야 해요.","⟨5/9⟩ × 2 = ⟨1 1/9⟩은 오히려 커요.","⟨5/9⟩ ÷ 2 = ⟨5/9⟩ × ⟨1/2⟩ = ⟨5/18⟩ — 가온은 나누는 수를 그대로 곱했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L05_challenge#4','math',6,1,'u1','L05','g6_1_math_u1_L05_challenge','lesson_challenge','M6-1-u1-C5',3,'mc','auto','⟨6/7⟩ ÷ 3을 「분자만 나누기」와 「단위분수 곱하기」 두 방법으로 계산했어요. 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u1-X12','M6-1-u1-X02','M6-1-u1-X06']::text[],true,'{"seq":4,"concept":"M6-1-u1-C5","difficulty":3,"kind":"mc","stem":"⟨6/7⟩ ÷ 3을 「분자만 나누기」와 「단위분수 곱하기」 두 방법으로 계산했어요. 알맞은 것은 어느 것인가요?","options":[{"t":"두 방법의 몫은 ⟨2/7⟩로 같다","correct":true},{"t":"분자만 나누면 ⟨2/7⟩, 곱하면 ⟨6/21⟩이라 몫이 다르다","mis":"M6-1-u1-X12"},{"t":"분자만 나누는 방법은 쓸 수 없다","mis":"M6-1-u1-X02"},{"t":"곱하는 방법은 ⟨6/7⟩ × 3으로 해야 한다","mis":"M6-1-u1-X06"}],"explanation":["분자만 나누면 6 ÷ 3 = 2라 ⟨2/7⟩예요.","곱하면 ⟨6/7⟩ × ⟨1/3⟩ = ⟨6/21⟩이에요.","⟨6/21⟩ = ⟨2/7⟩ — 약분하면 같은 수예요."],"variant_rule":{"alt":[{"stem":"⟨8/9⟩ ÷ 4를 「분자만 나누기」와 「단위분수 곱하기」 두 방법으로 계산했어요. 알맞은 것은 어느 것인가요?","options":[{"t":"두 방법의 몫은 ⟨2/9⟩로 같다","correct":true},{"t":"분자만 나누면 ⟨2/9⟩, 곱하면 ⟨8/36⟩이라 몫이 다르다","mis":"M6-1-u1-X12"},{"t":"분자만 나누는 방법은 쓸 수 없다","mis":"M6-1-u1-X02"},{"t":"곱하는 방법은 ⟨8/9⟩ × 4로 해야 한다","mis":"M6-1-u1-X06"}],"explanation":["분자만 나누면 8 ÷ 4 = 2라 ⟨2/9⟩예요.","곱하면 ⟨8/9⟩ × ⟨1/4⟩ = ⟨8/36⟩이에요.","⟨8/36⟩ = ⟨2/9⟩ — 약분하면 같은 수예요."]},{"stem":"⟨10/11⟩ ÷ 5를 「분자만 나누기」와 「단위분수 곱하기」 두 방법으로 계산했어요. 알맞은 것은 어느 것인가요?","options":[{"t":"두 방법의 몫은 ⟨2/11⟩로 같다","correct":true},{"t":"분자만 나누면 ⟨2/11⟩, 곱하면 ⟨10/55⟩이라 몫이 다르다","mis":"M6-1-u1-X12"},{"t":"분자만 나누는 방법은 쓸 수 없다","mis":"M6-1-u1-X02"},{"t":"곱하는 방법은 ⟨10/11⟩ × 5로 해야 한다","mis":"M6-1-u1-X06"}],"explanation":["분자만 나누면 10 ÷ 5 = 2라 ⟨2/11⟩예요.","곱하면 ⟨10/11⟩ × ⟨1/5⟩ = ⟨10/55⟩이에요.","⟨10/55⟩ = ⟨2/11⟩ — 약분하면 같은 수예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L05_challenge#5','math',6,1,'u1','L05','g6_1_math_u1_L05_challenge','lesson_challenge','M6-1-u1-C5',3,'mc','auto','⟨5/8⟩ ÷ 3과 ⟨5/8⟩ ÷ 4 가운데 몫이 더 큰 것은 어느 것인가요?',ARRAY['M6-1-u1-X11','M6-1-u1-X15']::text[],true,'{"seq":5,"concept":"M6-1-u1-C5","difficulty":3,"kind":"mc","stem":"⟨5/8⟩ ÷ 3과 ⟨5/8⟩ ÷ 4 가운데 몫이 더 큰 것은 어느 것인가요?","options":[{"t":"⟨5/8⟩ ÷ 3","correct":true},{"t":"⟨5/8⟩ ÷ 4","mis":"M6-1-u1-X11"},{"t":"두 몫이 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X15"}],"explanation":["⟨5/8⟩ ÷ 3 = ⟨5/24⟩, ⟨5/8⟩ ÷ 4 = ⟨5/32⟩예요.","96으로 통분하면 ⟨5/24⟩ = ⟨20/96⟩, ⟨5/32⟩ = ⟨15/96⟩예요.","같은 양을 더 적게 나눌수록 몫이 커요 — ⟨5/8⟩ ÷ 3이 더 커요."],"variant_rule":{"alt":[{"stem":"⟨7/9⟩ ÷ 2와 ⟨7/9⟩ ÷ 5 가운데 몫이 더 큰 것은 어느 것인가요?","options":[{"t":"⟨7/9⟩ ÷ 2","correct":true},{"t":"⟨7/9⟩ ÷ 5","mis":"M6-1-u1-X11"},{"t":"두 몫이 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X15"}],"explanation":["⟨7/9⟩ ÷ 2 = ⟨7/18⟩, ⟨7/9⟩ ÷ 5 = ⟨7/45⟩이에요.","90으로 통분하면 ⟨7/18⟩ = ⟨35/90⟩, ⟨7/45⟩ = ⟨14/90⟩예요.","같은 양을 더 적게 나눌수록 몫이 커요 — ⟨7/9⟩ ÷ 2가 더 커요."]},{"stem":"⟨9/10⟩ ÷ 3과 ⟨9/10⟩ ÷ 4 가운데 몫이 더 큰 것은 어느 것인가요?","options":[{"t":"⟨9/10⟩ ÷ 3","correct":true},{"t":"⟨9/10⟩ ÷ 4","mis":"M6-1-u1-X11"},{"t":"두 몫이 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X15"}],"explanation":["⟨9/10⟩ ÷ 3 = ⟨3/10⟩, ⟨9/10⟩ ÷ 4 = ⟨9/40⟩예요.","40으로 통분하면 ⟨3/10⟩ = ⟨12/40⟩, ⟨9/40⟩ = ⟨9/40⟩예요.","같은 양을 더 적게 나눌수록 몫이 커요 — ⟨9/10⟩ ÷ 3이 더 커요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L05_challenge#6','math',6,1,'u1','L05','g6_1_math_u1_L05_challenge','lesson_challenge','M6-1-u1-C5',3,'ox','auto','⟨2/9⟩ ÷ 3 = ⟨2/3⟩예요.',ARRAY['M6-1-u1-X08']::text[],true,'{"seq":6,"concept":"M6-1-u1-C5","difficulty":3,"kind":"ox","stem":"⟨2/9⟩ ÷ 3 = ⟨2/3⟩예요.","answer":"X","reason_options":[{"t":"분모를 나누면 몫이 커지므로 ⟨2/9⟩ × ⟨1/3⟩ = ⟨2/27⟩이어야 하므로","correct":true},{"t":"분모 9를 3으로 나누면 되므로","mis":"M6-1-u1-X08"}],"mis":"M6-1-u1-X08","explanation":["⟨2/3⟩는 ⟨2/9⟩보다 커요 — 나누었는데 커질 수 없어요.","⟨2/9⟩ ÷ 3 = ⟨2/9⟩ × ⟨1/3⟩이에요.","몫은 ⟨2/27⟩예요."],"variant_rule":{"alt":[{"stem":"⟨5/6⟩ ÷ 2의 몫은 ⟨5/6⟩보다 커요.","answer":"X","reason_options":[{"t":"1보다 큰 수로 나누면 몫이 처음보다 작아지므로","correct":true},{"t":"나눗셈을 하면 몫이 커지므로","mis":"M6-1-u1-X11"}],"explanation":["⟨5/6⟩ ÷ 2 = ⟨5/12⟩예요.","⟨5/6⟩ = ⟨10/12⟩이고 ⟨5/12⟩ < ⟨10/12⟩이에요.","그래서 몫은 처음보다 작아요."]},{"stem":"⟨3/4⟩ ÷ 5 = ⟨3/9⟩이에요.","answer":"X","reason_options":[{"t":"분모에 5를 더한 것이라 ⟨3/4⟩ × ⟨1/5⟩ = ⟨3/20⟩이어야 하므로","correct":true},{"t":"나누는 수를 분모에 더하면 되므로","mis":"M6-1-u1-X09"}],"explanation":["⟨3/4⟩ ÷ 5 = ⟨3/4⟩ × ⟨1/5⟩이에요.","분모끼리 곱해 4 × 5 = 20이에요.","몫은 ⟨3/20⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L05_challenge#7','math',6,1,'u1','L05','g6_1_math_u1_L05_challenge','lesson_challenge','M6-1-u1-C5',3,'mc','auto','어떤 진분수를 3으로 나누었더니 ⟨2/15⟩가 되었어요. 어떤 진분수는 얼마인가요?',ARRAY['M6-1-u1-X14','M6-1-u1-X09']::text[],true,'{"seq":7,"concept":"M6-1-u1-C5","difficulty":3,"kind":"mc","stem":"어떤 진분수를 3으로 나누었더니 ⟨2/15⟩가 되었어요. 어떤 진분수는 얼마인가요?","options":[{"t":"⟨2/5⟩","correct":true},{"t":"⟨2/45⟩","mis":"M6-1-u1-X14"},{"t":"⟨3 2/15⟩","mis":"M6-1-u1-X14"},{"t":"⟨1/9⟩","mis":"M6-1-u1-X09"}],"explanation":["어떤 진분수 ÷ 3 = ⟨2/15⟩예요.","거꾸로 생각하면 어떤 진분수 = ⟨2/15⟩ × 3이에요.","⟨2/15⟩ × 3 = ⟨2/5⟩예요."],"variant_rule":{"alt":[{"stem":"어떤 진분수를 2로 나누었더니 ⟨3/14⟩이 되었어요. 어떤 진분수는 얼마인가요?","options":[{"t":"⟨3/7⟩","correct":true},{"t":"⟨3/28⟩","mis":"M6-1-u1-X14"},{"t":"⟨2 3/14⟩","mis":"M6-1-u1-X14"},{"t":"⟨3/16⟩","mis":"M6-1-u1-X09"}],"explanation":["어떤 진분수 ÷ 2 = ⟨3/14⟩이에요.","거꾸로 생각하면 어떤 진분수 = ⟨3/14⟩ × 2예요.","⟨3/14⟩ × 2 = ⟨3/7⟩이에요."]},{"stem":"어떤 진분수를 5로 나누었더니 ⟨4/45⟩가 되었어요. 어떤 진분수는 얼마인가요?","options":[{"t":"⟨4/9⟩","correct":true},{"t":"⟨4/225⟩","mis":"M6-1-u1-X14"},{"t":"⟨5 4/45⟩","mis":"M6-1-u1-X14"},{"t":"⟨2/25⟩","mis":"M6-1-u1-X09"}],"explanation":["어떤 진분수 ÷ 5 = ⟨4/45⟩예요.","거꾸로 생각하면 어떤 진분수 = ⟨4/45⟩ × 5예요.","⟨4/45⟩ × 5 = ⟨4/9⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L05_challenge#8','math',6,1,'u1','L05','g6_1_math_u1_L05_challenge','lesson_challenge','M6-1-u1-C5',4,'sa','auto','⟨□/9⟩ ÷ 4 = ⟨2/9⟩일 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M6-1-u1-C5","difficulty":4,"kind":"sa","stem":"⟨□/9⟩ ÷ 4 = ⟨2/9⟩일 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["분모가 그대로 9니 분자만 4로 나눈 거예요.","4로 나누어 2가 된 수는 2 × 4 = 8이에요.","⟨8/9⟩ ÷ 4 = ⟨2/9⟩ — □는 8이에요."],"mis":"M6-1-u1-X06","variant_rule":{"alt":[{"stem":"⟨3/5⟩ ÷ □ = ⟨3/20⟩일 때 □에 알맞은 자연수는 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["⟨3/5⟩ ÷ □ = ⟨3/5⟩ × ⟨1/□⟩이에요.","분자는 그대로이고 분모가 5에서 20으로 4배가 되었어요.","⟨3/5⟩ ÷ 4 = ⟨3/20⟩ — □는 4예요."]},{"stem":"⟨□/11⟩ ÷ 5 = ⟨2/11⟩일 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["분모가 그대로 11이니 분자만 5로 나눈 거예요.","5로 나누어 2가 된 수는 2 × 5 = 10이에요.","⟨10/11⟩ ÷ 5 = ⟨2/11⟩ — □는 10이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L05_challenge#9','math',6,1,'u1','L05','g6_1_math_u1_L05_challenge','lesson_challenge','M6-1-u1-C5',4,'sa','auto','⟨8/9⟩ ÷ □의 몫이 ⟨1/9⟩보다 클 때, □에 들어갈 수 있는 가장 큰 자연수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M6-1-u1-C5","difficulty":4,"kind":"sa","stem":"⟨8/9⟩ ÷ □의 몫이 ⟨1/9⟩보다 클 때, □에 들어갈 수 있는 가장 큰 자연수는 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["⟨8/9⟩은 ⟨1/9⟩이 8개예요.","□로 나눈 몫이 ⟨1/9⟩보다 크려면 8개를 □로 나눈 수가 1보다 커야 해요.","□는 8보다 작아야 하니 가장 큰 수는 7이에요."],"mis":"M6-1-u1-X11","variant_rule":{"alt":[{"stem":"⟨6/7⟩ ÷ □의 몫이 ⟨1/7⟩보다 클 때, □에 들어갈 수 있는 가장 큰 자연수는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["⟨6/7⟩은 ⟨1/7⟩이 6개예요.","□로 나눈 몫이 ⟨1/7⟩보다 크려면 6개를 □로 나눈 수가 1보다 커야 해요.","□는 6보다 작아야 하니 가장 큰 수는 5예요."]},{"stem":"⟨10/11⟩ ÷ □의 몫이 ⟨1/11⟩보다 클 때, □에 들어갈 수 있는 가장 큰 자연수는 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["⟨10/11⟩은 ⟨1/11⟩이 10개예요.","□로 나눈 몫이 ⟨1/11⟩보다 크려면 10개를 □로 나눈 수가 1보다 커야 해요.","□는 10보다 작아야 하니 가장 큰 수는 9예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L05_challenge#10','math',6,1,'u1','L05','g6_1_math_u1_L05_challenge','lesson_challenge','M6-1-u1-C5',4,'essay','teacher','손 세정제 ⟨4/5⟩ L를 3병에 똑같이 나누어 담으려고 해요. 분자 4가 3으로 나누어떨어지지 않을 때 한 병에 담는 양을 구하는 방법을 설명하고 답을 구해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-1-u1-C5","difficulty":4,"kind":"essay","stem":"손 세정제 ⟨4/5⟩ L를 3병에 똑같이 나누어 담으려고 해요. 분자 4가 3으로 나누어떨어지지 않을 때 한 병에 담는 양을 구하는 방법을 설명하고 답을 구해 보세요.","answer_guide":{"answer":"예: 분자 4는 3으로 나누어떨어지지 않으므로 ⟨4/5⟩ 전체를 3등분한 것 중의 1을 구한다. 이것은 ⟨4/5⟩에 ⟨1/3⟩을 곱하는 것과 같아 ⟨4/5⟩ ÷ 3 = ⟨4/5⟩ × ⟨1/3⟩ = ⟨4/15⟩이다. 한 병에는 ⟨4/15⟩ L를 담는다.","scoring_points":["분자가 나누어떨어지지 않음을 짚었는가","÷ 3을 × ⟨1/3⟩로 바꾸는 방법을 썼는가","⟨4/15⟩ L를 구했는가"]},"explanation":["분자 4는 3으로 나누어떨어지지 않아요.","⟨4/5⟩ ÷ 3 = ⟨4/5⟩ × ⟨1/3⟩이에요.","한 병에는 ⟨4/15⟩ L예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L06_basic#1','math',6,1,'u1','L06','g6_1_math_u1_L06_basic','lesson_basic','M6-1-u1-C6',1,'mc','auto','⟨1 1/6⟩을 가분수로 나타내면 어느 것인가요?',ARRAY['M6-1-u1-X01','M6-1-u1-X05']::text[],true,'{"seq":1,"concept":"M6-1-u1-C6","difficulty":1,"kind":"mc","stem":"⟨1 1/6⟩을 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨7/6⟩","correct":true},{"t":"⟨6/7⟩","mis":"M6-1-u1-X01"},{"t":"⟨2/6⟩","mis":"M6-1-u1-X05"},{"t":"⟨1/6⟩","mis":"M6-1-u1-X05"}],"explanation":["자연수 1은 ⟨6/6⟩이에요 — 1 × 6 = 6.","여기에 ⟨1/6⟩을 더하면 분자는 6 + 1 = 7이에요.","⟨1 1/6⟩ = ⟨7/6⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨2 3/4⟩을 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨11/4⟩","correct":true},{"t":"⟨4/11⟩","mis":"M6-1-u1-X01"},{"t":"⟨5/4⟩","mis":"M6-1-u1-X05"},{"t":"⟨6/4⟩","mis":"M6-1-u1-X05"}],"explanation":["자연수 2는 ⟨8/4⟩이에요 — 2 × 4 = 8.","여기에 ⟨3/4⟩을 더하면 분자는 8 + 3 = 11이에요.","⟨2 3/4⟩ = ⟨11/4⟩이에요."]},{"stem":"⟨1 4/7⟩를 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨11/7⟩","correct":true},{"t":"⟨7/11⟩","mis":"M6-1-u1-X01"},{"t":"⟨5/7⟩","mis":"M6-1-u1-X05"},{"t":"⟨4/7⟩","mis":"M6-1-u1-X05"}],"explanation":["자연수 1은 ⟨7/7⟩이에요 — 1 × 7 = 7.","여기에 ⟨4/7⟩를 더하면 분자는 7 + 4 = 11이에요.","⟨1 4/7⟩ = ⟨11/7⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L06_basic#2','math',6,1,'u1','L06','g6_1_math_u1_L06_basic','lesson_basic','M6-1-u1-C6',1,'sa','auto','⟨2 4/9⟩ ÷ 3을 계산하려고 ⟨2 4/9⟩를 가분수로 고쳤어요. 가분수의 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-1-u1-C6","difficulty":1,"kind":"sa","stem":"⟨2 4/9⟩ ÷ 3을 계산하려고 ⟨2 4/9⟩를 가분수로 고쳤어요. 가분수의 분자는 얼마인가요? 숫자로 쓰세요.","answer":["22"],"explanation":["대분수는 먼저 가분수로 고쳐요.","2 × 9 + 4 = 22예요.","⟨2 4/9⟩ = ⟨22/9⟩ — 분자는 22예요."],"mis":"M6-1-u1-X05","variant_rule":{"alt":[{"stem":"⟨3 2/5⟩ ÷ 4를 계산하려고 ⟨3 2/5⟩를 가분수로 고쳤어요. 가분수의 분자는 얼마인가요? 숫자로 쓰세요.","answer":["17"],"explanation":["대분수는 먼저 가분수로 고쳐요.","3 × 5 + 2 = 17이에요.","⟨3 2/5⟩ = ⟨17/5⟩ — 분자는 17이에요."]},{"stem":"⟨1 5/8⟩ ÷ 2를 계산하려고 ⟨1 5/8⟩를 가분수로 고쳤어요. 가분수의 분자는 얼마인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["대분수는 먼저 가분수로 고쳐요.","1 × 8 + 5 = 13이에요.","⟨1 5/8⟩ = ⟨13/8⟩ — 분자는 13이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L06_basic#3','math',6,1,'u1','L06','g6_1_math_u1_L06_basic','lesson_basic','M6-1-u1-C6',1,'sa','auto','⟨1 2/3⟩ ÷ 3을 계산하여 기약분수로 나타내면 몫의 분모는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M6-1-u1-C6","difficulty":1,"kind":"sa","stem":"⟨1 2/3⟩ ÷ 3을 계산하여 기약분수로 나타내면 몫의 분모는 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["⟨1 2/3⟩ = ⟨5/3⟩예요.","⟨5/3⟩ ÷ 3 = ⟨5/3⟩ × ⟨1/3⟩ = ⟨5/9⟩예요.","그래서 몫의 분모는 9예요."],"mis":"M6-1-u1-X15","variant_rule":{"alt":[{"stem":"⟨2 1/4⟩ ÷ 3을 계산하여 기약분수로 나타내면 몫의 분모는 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["⟨2 1/4⟩ = ⟨9/4⟩예요.","⟨9/4⟩ ÷ 3 = ⟨9/4⟩ × ⟨1/3⟩ = ⟨3/4⟩이에요.","그래서 몫의 분모는 4예요."]},{"stem":"⟨1 3/5⟩ ÷ 2를 계산하여 기약분수로 나타내면 몫의 분모는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["⟨1 3/5⟩ = ⟨8/5⟩이에요.","⟨8/5⟩ ÷ 2 = ⟨8/5⟩ × ⟨1/2⟩ = ⟨4/5⟩예요.","그래서 몫의 분모는 5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L06_basic#4','math',6,1,'u1','L06','g6_1_math_u1_L06_basic','lesson_basic','M6-1-u1-C6',1,'ox','auto','⟨2 1/4⟩ = ⟨9/4⟩예요.',ARRAY['M6-1-u1-X05']::text[],true,'{"seq":4,"concept":"M6-1-u1-C6","difficulty":1,"kind":"ox","stem":"⟨2 1/4⟩ = ⟨9/4⟩예요.","answer":"O","reason_options":[{"t":"2 × 4 + 1 = 9이므로","correct":true},{"t":"자연수와 분자를 더하므로","mis":"M6-1-u1-X05"}],"mis":"M6-1-u1-X05","explanation":["자연수 2는 ⟨8/4⟩이에요.","⟨8/4⟩ + ⟨1/4⟩ = ⟨9/4⟩예요.","그래서 맞아요."],"variant_rule":{"alt":[{"stem":"⟨1 2/3⟩ ÷ 3을 계산할 때 자연수 1만 3으로 나누고 ⟨2/3⟩는 그대로 두어도 돼요.","answer":"X","reason_options":[{"t":"분수 부분도 함께 나누어야 하니 ⟨5/3⟩ × ⟨1/3⟩로 계산해야 하므로","correct":true},{"t":"자연수 부분만 나누면 되므로","mis":"M6-1-u1-X10"}],"explanation":["⟨1 2/3⟩ = ⟨5/3⟩예요.","⟨5/3⟩ ÷ 3 = ⟨5/3⟩ × ⟨1/3⟩ = ⟨5/9⟩예요.","분수 부분을 그대로 두면 틀려요."]},{"stem":"⟨1 3/5⟩을 가분수로 고치면 ⟨4/5⟩예요.","answer":"X","reason_options":[{"t":"1 × 5 + 3 = 8이라 ⟨8/5⟩이므로","correct":true},{"t":"자연수와 분자를 더하면 되므로","mis":"M6-1-u1-X05"}],"explanation":["자연수 1은 ⟨5/5⟩예요.","⟨5/5⟩ + ⟨3/5⟩ = ⟨8/5⟩이에요.","⟨4/5⟩는 자연수와 분자를 더한 실수예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L06_basic#5','math',6,1,'u1','L06','g6_1_math_u1_L06_basic','lesson_basic','M6-1-u1-C6',2,'mc','auto','⟨1 1/6⟩ ÷ 7을 계산하면 얼마인가요?',ARRAY['M6-1-u1-X10','M6-1-u1-X06']::text[],true,'{"seq":5,"concept":"M6-1-u1-C6","difficulty":2,"kind":"mc","stem":"⟨1 1/6⟩ ÷ 7을 계산하면 얼마인가요?","options":[{"t":"⟨1/6⟩","correct":true},{"t":"⟨1 1/42⟩","mis":"M6-1-u1-X10"},{"t":"⟨13/42⟩","mis":"M6-1-u1-X10"},{"t":"⟨8 1/6⟩","mis":"M6-1-u1-X06"}],"explanation":["⟨1 1/6⟩을 가분수로 고치면 ⟨7/6⟩이에요.","⟨7/6⟩ ÷ 7 = ⟨7/6⟩ × ⟨1/7⟩이에요.","⟨7/6⟩ × ⟨1/7⟩ = ⟨1/6⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨2 3/7⟩ ÷ 4를 계산하면 얼마인가요?","options":[{"t":"⟨17/28⟩","correct":true},{"t":"⟨2 3/28⟩","mis":"M6-1-u1-X10"},{"t":"⟨13/14⟩","mis":"M6-1-u1-X10"},{"t":"⟨9 5/7⟩","mis":"M6-1-u1-X06"}],"explanation":["⟨2 3/7⟩을 가분수로 고치면 ⟨17/7⟩이에요.","⟨17/7⟩ ÷ 4 = ⟨17/7⟩ × ⟨1/4⟩이에요.","⟨17/7⟩ × ⟨1/4⟩ = ⟨17/28⟩이에요."]},{"stem":"⟨1 2/3⟩ ÷ 3을 계산하면 얼마인가요?","options":[{"t":"⟨5/9⟩","correct":true},{"t":"⟨1 2/9⟩","mis":"M6-1-u1-X10"},{"t":"1","mis":"M6-1-u1-X10"},{"t":"5","mis":"M6-1-u1-X06"}],"explanation":["⟨1 2/3⟩를 가분수로 고치면 ⟨5/3⟩예요.","⟨5/3⟩ ÷ 3 = ⟨5/3⟩ × ⟨1/3⟩이에요.","⟨5/3⟩ × ⟨1/3⟩ = ⟨5/9⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L06_basic#6','math',6,1,'u1','L06','g6_1_math_u1_L06_basic','lesson_basic','M6-1-u1-C6',2,'mc','auto','(대분수)÷(자연수)를 계산하는 순서로 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u1-X10','M6-1-u1-X07']::text[],true,'{"seq":6,"concept":"M6-1-u1-C6","difficulty":2,"kind":"mc","stem":"(대분수)÷(자연수)를 계산하는 순서로 알맞은 것은 어느 것인가요?","options":[{"t":"대분수를 가분수로 고친 뒤 나누는 수의 단위분수를 곱한다","correct":true},{"t":"대분수의 분모에만 나누는 수를 곱한다","mis":"M6-1-u1-X10"},{"t":"자연수 부분만 나누는 수로 나누고 분수 부분은 그대로 둔다","mis":"M6-1-u1-X10"},{"t":"대분수를 뒤집은 뒤 나누는 수를 곱한다","mis":"M6-1-u1-X07"}],"explanation":["(대분수)÷(자연수)는 두 걸음이에요.","① 대분수를 가분수로 고치고 ② 나누는 수의 단위분수를 곱해요.","그래서 답은 「대분수를 가분수로 고친 뒤 나누는 수의 단위분수를 곱한다」예요."],"variant_rule":{"alt":[{"stem":"(대분수)÷(자연수)를 계산할 때 가장 먼저 할 일은 무엇인가요?","options":[{"t":"대분수를 가분수로 고친다","correct":true},{"t":"나누는 수를 그대로 곱한다","mis":"M6-1-u1-X06"},{"t":"분모를 나누는 수로 나눈다","mis":"M6-1-u1-X08"},{"t":"자연수 부분을 지운다","mis":"M6-1-u1-X10"}],"explanation":["(대분수)÷(자연수)는 두 걸음이에요.","① 대분수를 가분수로 고치고 ② 나누는 수의 단위분수를 곱해요.","그래서 답은 「대분수를 가분수로 고친다」예요."]},{"stem":"(대분수)÷(자연수)를 계산할 때 대분수를 가분수로 먼저 고치는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"두 덩어리를 한 덩어리로 모아 한 번에 나누려고","correct":true},{"t":"대분수는 곱할 수 없어서","mis":"M6-1-u1-X15"},{"t":"가분수로 고치면 몫이 커져서","mis":"M6-1-u1-X11"},{"t":"나누는 수를 그대로 곱하려고","mis":"M6-1-u1-X06"}],"explanation":["(대분수)÷(자연수)는 두 걸음이에요.","① 대분수를 가분수로 고치고 ② 나누는 수의 단위분수를 곱해요.","그래서 답은 「두 덩어리를 한 덩어리로 모아 한 번에 나누려고」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L06_basic#7','math',6,1,'u1','L06','g6_1_math_u1_L06_basic','lesson_basic','M6-1-u1-C6',2,'sa','auto','페인트 ⟨3 2/5⟩ L를 4명이 똑같이 나누어 가졌어요. 한 명이 가지는 페인트를 분수로 나타낼 때 분모와 분자의 합은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M6-1-u1-C6","difficulty":2,"kind":"sa","stem":"페인트 ⟨3 2/5⟩ L를 4명이 똑같이 나누어 가졌어요. 한 명이 가지는 페인트를 분수로 나타낼 때 분모와 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["37"],"explanation":["⟨3 2/5⟩ = ⟨17/5⟩이에요.","⟨17/5⟩ ÷ 4 = ⟨17/5⟩ × ⟨1/4⟩ = ⟨17/20⟩이에요.","한 명이 가지는 페인트는 ⟨17/20⟩ L — 분모와 분자의 합은 20 + 17 = 37이에요."],"mis":"M6-1-u1-X15","variant_rule":{"alt":[{"stem":"유기견 보호소에서 사료 ⟨1 2/3⟩통을 3곳에 똑같이 나누어 주려고 해요. 한 곳에 주는 사료를 분수로 나타낼 때 분모와 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["⟨1 2/3⟩ = ⟨5/3⟩예요.","⟨5/3⟩ ÷ 3 = ⟨5/3⟩ × ⟨1/3⟩ = ⟨5/9⟩예요.","한 곳에 주는 사료는 ⟨5/9⟩통 — 분모와 분자의 합은 9 + 5 = 14예요."]},{"stem":"찰흙 ⟨2 1/4⟩ kg을 5모둠이 똑같이 나누어 가졌어요. 한 모둠이 가지는 찰흙을 분수로 나타낼 때 분모와 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["29"],"explanation":["⟨2 1/4⟩ = ⟨9/4⟩예요.","⟨9/4⟩ ÷ 5 = ⟨9/4⟩ × ⟨1/5⟩ = ⟨9/20⟩예요.","한 모둠이 가지는 찰흙은 ⟨9/20⟩ kg — 분모와 분자의 합은 20 + 9 = 29예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L06_basic#8','math',6,1,'u1','L06','g6_1_math_u1_L06_basic','lesson_basic','M6-1-u1-C6',2,'mc','auto','⟨2 3/7⟩ ÷ 4를 바르게 계산한 것은 어느 것인가요?',ARRAY['M6-1-u1-X06','M6-1-u1-X10','M6-1-u1-X07']::text[],true,'{"seq":8,"concept":"M6-1-u1-C6","difficulty":2,"kind":"mc","stem":"⟨2 3/7⟩ ÷ 4를 바르게 계산한 것은 어느 것인가요?","options":[{"t":"⟨17/7⟩ × ⟨1/4⟩ = ⟨17/28⟩","correct":true},{"t":"⟨2 3/7⟩ × 4","mis":"M6-1-u1-X06"},{"t":"⟨2 3/7⟩의 분모에만 4를 곱해 ⟨2 3/28⟩","mis":"M6-1-u1-X10"},{"t":"⟨7/17⟩ × ⟨1/4⟩","mis":"M6-1-u1-X07"}],"explanation":["먼저 ⟨2 3/7⟩ = ⟨17/7⟩로 고쳐요.","⟨17/7⟩ ÷ 4 = ⟨17/7⟩ × ⟨1/4⟩이에요.","⟨17/7⟩ × ⟨1/4⟩ = ⟨17/28⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨1 1/5⟩ ÷ 3을 바르게 계산한 것은 어느 것인가요?","options":[{"t":"⟨6/5⟩ × ⟨1/3⟩ = ⟨2/5⟩","correct":true},{"t":"⟨1 1/5⟩ × 3","mis":"M6-1-u1-X06"},{"t":"⟨1 1/5⟩의 분모에만 3을 곱해 ⟨1 1/15⟩","mis":"M6-1-u1-X10"},{"t":"⟨5/6⟩ × ⟨1/3⟩","mis":"M6-1-u1-X07"}],"explanation":["먼저 ⟨1 1/5⟩ = ⟨6/5⟩으로 고쳐요.","⟨6/5⟩ ÷ 3 = ⟨6/5⟩ × ⟨1/3⟩이에요.","⟨6/5⟩ × ⟨1/3⟩ = ⟨2/5⟩예요."]},{"stem":"⟨3 1/2⟩ ÷ 5를 바르게 계산한 것은 어느 것인가요?","options":[{"t":"⟨7/2⟩ × ⟨1/5⟩ = ⟨7/10⟩","correct":true},{"t":"⟨3 1/2⟩ × 5","mis":"M6-1-u1-X06"},{"t":"⟨3 1/2⟩의 분모에만 5를 곱해 ⟨3 1/10⟩","mis":"M6-1-u1-X10"},{"t":"⟨2/7⟩ × ⟨1/5⟩","mis":"M6-1-u1-X07"}],"explanation":["먼저 ⟨3 1/2⟩ = ⟨7/2⟩로 고쳐요.","⟨7/2⟩ ÷ 5 = ⟨7/2⟩ × ⟨1/5⟩이에요.","⟨7/2⟩ × ⟨1/5⟩ = ⟨7/10⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L06_basic#9','math',6,1,'u1','L06','g6_1_math_u1_L06_basic','lesson_basic','M6-1-u1-C6',2,'match','auto','나눗셈과 몫을 알맞게 이으세요.','{}'::text[],true,'{"seq":9,"concept":"M6-1-u1-C6","difficulty":2,"kind":"match","stem":"나눗셈과 몫을 알맞게 이으세요.","pairs":[{"l":"⟨1 1/2⟩ ÷ 3","r":"⟨1/2⟩"},{"l":"⟨2 2/3⟩ ÷ 4","r":"⟨2/3⟩"},{"l":"⟨1 3/4⟩ ÷ 7","r":"⟨1/4⟩"}],"mis":"M6-1-u1-X10","explanation":["대분수를 먼저 가분수로 고쳐요.","⟨1 1/2⟩ ÷ 3 = ⟨1/2⟩, ⟨2 2/3⟩ ÷ 4 = ⟨2/3⟩, ⟨1 3/4⟩ ÷ 7 = ⟨1/4⟩이에요.","자연수 부분만 나누지 않도록 해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 나눗셈과 몫을 알맞게 이으세요.","pairs":[{"l":"⟨2 1/2⟩ ÷ 5","r":"⟨1/2⟩"},{"l":"⟨1 1/3⟩ ÷ 2","r":"⟨2/3⟩"},{"l":"⟨3 3/4⟩ ÷ 5","r":"⟨3/4⟩"}],"explanation":["대분수를 먼저 가분수로 고쳐요.","⟨2 1/2⟩ ÷ 5 = ⟨1/2⟩, ⟨1 1/3⟩ ÷ 2 = ⟨2/3⟩, ⟨3 3/4⟩ ÷ 5 = ⟨3/4⟩이에요.","자연수 부분만 나누지 않도록 해요."]},{"stem":"이번에는 다른 보기예요. 나눗셈과 몫을 알맞게 이으세요.","pairs":[{"l":"⟨1 4/5⟩ ÷ 3","r":"⟨3/5⟩"},{"l":"⟨2 1/3⟩ ÷ 7","r":"⟨1/3⟩"},{"l":"⟨4 1/2⟩ ÷ 3","r":"⟨1 1/2⟩"}],"explanation":["대분수를 먼저 가분수로 고쳐요.","⟨1 4/5⟩ ÷ 3 = ⟨3/5⟩, ⟨2 1/3⟩ ÷ 7 = ⟨1/3⟩, ⟨4 1/2⟩ ÷ 3 = ⟨1 1/2⟩이에요.","자연수 부분만 나누지 않도록 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L06_basic#10','math',6,1,'u1','L06','g6_1_math_u1_L06_basic','lesson_basic','M6-1-u1-C6',3,'mc','auto','몫이 1보다 작은 것은 어느 것인가요?',ARRAY['M6-1-u1-X11']::text[],true,'{"seq":10,"concept":"M6-1-u1-C6","difficulty":3,"kind":"mc","stem":"몫이 1보다 작은 것은 어느 것인가요?","options":[{"t":"⟨1 1/5⟩ ÷ 2","correct":true},{"t":"⟨3 1/2⟩ ÷ 2","mis":"M6-1-u1-X11"},{"t":"⟨2 2/3⟩ ÷ 2","mis":"M6-1-u1-X11"},{"t":"⟨4 1/2⟩ ÷ 3","mis":"M6-1-u1-X11"}],"explanation":["대분수를 가분수로 고쳐 단위분수를 곱해요.","⟨3 1/2⟩ ÷ 2 = ⟨1 3/4⟩, ⟨2 2/3⟩ ÷ 2 = ⟨1 1/3⟩, ⟨1 1/5⟩ ÷ 2 = ⟨3/5⟩, ⟨4 1/2⟩ ÷ 3 = ⟨1 1/2⟩이에요.","몫이 1보다 작은 것은 ⟨1 1/5⟩ ÷ 2예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 몫이 1보다 작은 것은 어느 것인가요?","options":[{"t":"⟨1 2/7⟩ ÷ 3","correct":true},{"t":"⟨2 1/4⟩ ÷ 2","mis":"M6-1-u1-X11"},{"t":"⟨3 1/3⟩ ÷ 3","mis":"M6-1-u1-X11"},{"t":"⟨5 1/2⟩ ÷ 4","mis":"M6-1-u1-X11"}],"explanation":["대분수를 가분수로 고쳐 단위분수를 곱해요.","⟨2 1/4⟩ ÷ 2 = ⟨1 1/8⟩, ⟨3 1/3⟩ ÷ 3 = ⟨1 1/9⟩, ⟨1 2/7⟩ ÷ 3 = ⟨3/7⟩, ⟨5 1/2⟩ ÷ 4 = ⟨1 3/8⟩이에요.","몫이 1보다 작은 것은 ⟨1 2/7⟩ ÷ 3이에요."]},{"stem":"이번에는 다른 보기예요. 몫이 1보다 작은 것은 어느 것인가요?","options":[{"t":"⟨1 1/2⟩ ÷ 2","correct":true},{"t":"⟨2 3/5⟩ ÷ 2","mis":"M6-1-u1-X11"},{"t":"⟨3 3/4⟩ ÷ 3","mis":"M6-1-u1-X11"},{"t":"⟨4 2/3⟩ ÷ 4","mis":"M6-1-u1-X11"}],"explanation":["대분수를 가분수로 고쳐 단위분수를 곱해요.","⟨1 1/2⟩ ÷ 2 = ⟨3/4⟩, ⟨2 3/5⟩ ÷ 2 = ⟨1 3/10⟩, ⟨3 3/4⟩ ÷ 3 = ⟨1 1/4⟩, ⟨4 2/3⟩ ÷ 4 = ⟨1 1/6⟩이에요.","몫이 1보다 작은 것은 ⟨1 1/2⟩ ÷ 2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L06_challenge#1','math',6,1,'u1','L06','g6_1_math_u1_L06_challenge','lesson_challenge','M6-1-u1-C6',2,'mc','auto','⟨3 1/3⟩ ÷ 5를 계산하면 얼마인가요?',ARRAY['M6-1-u1-X10','M6-1-u1-X06']::text[],true,'{"seq":1,"concept":"M6-1-u1-C6","difficulty":2,"kind":"mc","stem":"⟨3 1/3⟩ ÷ 5를 계산하면 얼마인가요?","options":[{"t":"⟨2/3⟩","correct":true},{"t":"⟨3 1/15⟩","mis":"M6-1-u1-X10"},{"t":"⟨14/15⟩","mis":"M6-1-u1-X10"},{"t":"⟨16 2/3⟩","mis":"M6-1-u1-X06"}],"explanation":["⟨3 1/3⟩을 가분수로 고치면 ⟨10/3⟩이에요.","⟨10/3⟩ ÷ 5 = ⟨10/3⟩ × ⟨1/5⟩이에요.","⟨10/3⟩ × ⟨1/5⟩ = ⟨2/3⟩예요."],"variant_rule":{"alt":[{"stem":"⟨2 2/5⟩ ÷ 4를 계산하면 얼마인가요?","options":[{"t":"⟨3/5⟩","correct":true},{"t":"⟨2 1/10⟩","mis":"M6-1-u1-X10"},{"t":"⟨9/10⟩","mis":"M6-1-u1-X10"},{"t":"⟨9 3/5⟩","mis":"M6-1-u1-X06"}],"explanation":["⟨2 2/5⟩를 가분수로 고치면 ⟨12/5⟩예요.","⟨12/5⟩ ÷ 4 = ⟨12/5⟩ × ⟨1/4⟩이에요.","⟨12/5⟩ × ⟨1/4⟩ = ⟨3/5⟩이에요."]},{"stem":"⟨4 1/2⟩ ÷ 6을 계산하면 얼마인가요?","options":[{"t":"⟨3/4⟩","correct":true},{"t":"⟨4 1/12⟩","mis":"M6-1-u1-X10"},{"t":"⟨1 1/6⟩","mis":"M6-1-u1-X10"},{"t":"27","mis":"M6-1-u1-X06"}],"explanation":["⟨4 1/2⟩을 가분수로 고치면 ⟨9/2⟩예요.","⟨9/2⟩ ÷ 6 = ⟨9/2⟩ × ⟨1/6⟩이에요.","⟨9/2⟩ × ⟨1/6⟩ = ⟨3/4⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L06_challenge#2','math',6,1,'u1','L06','g6_1_math_u1_L06_challenge','lesson_challenge','M6-1-u1-C6',2,'sa','auto','⟨3 4/7⟩ ÷ 5를 계산하려고 ⟨3 4/7⟩를 가분수로 고쳤어요. 가분수의 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-1-u1-C6","difficulty":2,"kind":"sa","stem":"⟨3 4/7⟩ ÷ 5를 계산하려고 ⟨3 4/7⟩를 가분수로 고쳤어요. 가분수의 분자는 얼마인가요? 숫자로 쓰세요.","answer":["25"],"explanation":["대분수는 먼저 가분수로 고쳐요.","3 × 7 + 4 = 25예요.","⟨3 4/7⟩ = ⟨25/7⟩ — 분자는 25예요."],"mis":"M6-1-u1-X05","variant_rule":{"alt":[{"stem":"⟨4 2/9⟩ ÷ 3을 계산하려고 ⟨4 2/9⟩를 가분수로 고쳤어요. 가분수의 분자는 얼마인가요? 숫자로 쓰세요.","answer":["38"],"explanation":["대분수는 먼저 가분수로 고쳐요.","4 × 9 + 2 = 38이에요.","⟨4 2/9⟩ = ⟨38/9⟩ — 분자는 38이에요."]},{"stem":"⟨5 1/6⟩ ÷ 4를 계산하려고 ⟨5 1/6⟩을 가분수로 고쳤어요. 가분수의 분자는 얼마인가요? 숫자로 쓰세요.","answer":["31"],"explanation":["대분수는 먼저 가분수로 고쳐요.","5 × 6 + 1 = 31이에요.","⟨5 1/6⟩ = ⟨31/6⟩ — 분자는 31이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L06_challenge#3','math',6,1,'u1','L06','g6_1_math_u1_L06_challenge','lesson_challenge','M6-1-u1-C6',3,'mc','auto','넓이가 ⟨5 3/4⟩ m²이고 가로가 2 m인 직사각형이 있어요. 세로는 몇 m인가요?',ARRAY['M6-1-u1-X10','M6-1-u1-X06']::text[],true,'{"seq":3,"concept":"M6-1-u1-C6","difficulty":3,"kind":"mc","stem":"넓이가 ⟨5 3/4⟩ m²이고 가로가 2 m인 직사각형이 있어요. 세로는 몇 m인가요?","options":[{"t":"⟨2 7/8⟩","correct":true},{"t":"⟨5 3/8⟩","mis":"M6-1-u1-X10"},{"t":"⟨3 1/4⟩","mis":"M6-1-u1-X10"},{"t":"⟨11 1/2⟩","mis":"M6-1-u1-X06"}],"explanation":["(직사각형의 넓이) = (가로) × (세로)이니 세로 = 넓이 ÷ 가로예요.","⟨5 3/4⟩ ÷ 2 = ⟨23/4⟩ × ⟨1/2⟩이에요.","⟨23/4⟩ × ⟨1/2⟩ = ⟨2 7/8⟩ — 세로는 ⟨2 7/8⟩ m예요."],"variant_rule":{"alt":[{"stem":"넓이가 ⟨6 2/3⟩ m²이고 가로가 4 m인 직사각형이 있어요. 세로는 몇 m인가요?","options":[{"t":"⟨1 2/3⟩","correct":true},{"t":"⟨6 1/6⟩","mis":"M6-1-u1-X10"},{"t":"⟨2 1/6⟩","mis":"M6-1-u1-X10"},{"t":"⟨26 2/3⟩","mis":"M6-1-u1-X06"}],"explanation":["(직사각형의 넓이) = (가로) × (세로)이니 세로 = 넓이 ÷ 가로예요.","⟨6 2/3⟩ ÷ 4 = ⟨20/3⟩ × ⟨1/4⟩이에요.","⟨20/3⟩ × ⟨1/4⟩ = ⟨1 2/3⟩ — 세로는 ⟨1 2/3⟩ m예요."]},{"stem":"넓이가 ⟨7 1/2⟩ m²이고 가로가 3 m인 직사각형이 있어요. 세로는 몇 m인가요?","options":[{"t":"⟨2 1/2⟩","correct":true},{"t":"⟨7 1/6⟩","mis":"M6-1-u1-X10"},{"t":"⟨2 5/6⟩","mis":"M6-1-u1-X10"},{"t":"⟨22 1/2⟩","mis":"M6-1-u1-X06"}],"explanation":["(직사각형의 넓이) = (가로) × (세로)이니 세로 = 넓이 ÷ 가로예요.","⟨7 1/2⟩ ÷ 3 = ⟨15/2⟩ × ⟨1/3⟩이에요.","⟨15/2⟩ × ⟨1/3⟩ = ⟨2 1/2⟩ — 세로는 ⟨2 1/2⟩ m예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L06_challenge#4','math',6,1,'u1','L06','g6_1_math_u1_L06_challenge','lesson_challenge','M6-1-u1-C6',3,'error','auto','⟨2 3/7⟩ ÷ 4를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u1-X10','M6-1-u1-X15']::text[],true,'{"seq":4,"concept":"M6-1-u1-C6","difficulty":3,"kind":"error","stem":"⟨2 3/7⟩ ÷ 4를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「자연수 2만 4로 나누고 ⟨3/7⟩은 그대로 두면 돼.」","correct":true,"mis_target":"M6-1-u1-X10"},{"t":"도윤 — 「먼저 ⟨17/7⟩로 고쳐야 해.」","mis":"M6-1-u1-X15"},{"t":"하린 — 「몫은 ⟨17/28⟩이야.」","mis":"M6-1-u1-X15"}],"explanation":["⟨2 3/7⟩의 분수 부분 ⟨3/7⟩도 함께 나누어야 해요.","⟨17/7⟩ ÷ 4 = ⟨17/7⟩ × ⟨1/4⟩ = ⟨17/28⟩이에요.","수아는 자연수 부분만 나누었어요."],"variant_rule":{"alt":[{"stem":"⟨3 1/2⟩ ÷ 4를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민준 — 「자연수 3만 4로 나누고 ⟨1/2⟩은 그대로 두면 돼.」","correct":true,"mis_target":"M6-1-u1-X10"},{"t":"서연 — 「먼저 ⟨7/2⟩로 고쳐야 해.」","mis":"M6-1-u1-X15"},{"t":"지호 — 「몫은 ⟨7/8⟩이야.」","mis":"M6-1-u1-X15"}],"explanation":["⟨3 1/2⟩의 분수 부분 ⟨1/2⟩도 함께 나누어야 해요.","⟨7/2⟩ ÷ 4 = ⟨7/2⟩ × ⟨1/4⟩ = ⟨7/8⟩이에요.","민준은 자연수 부분만 나누었어요."]},{"stem":"⟨1 2/3⟩ ÷ 3을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「자연수 1만 3으로 나누고 ⟨2/3⟩는 그대로 두면 돼.」","correct":true,"mis_target":"M6-1-u1-X10"},{"t":"나린 — 「먼저 ⟨5/3⟩로 고쳐야 해.」","mis":"M6-1-u1-X15"},{"t":"유진 — 「몫은 ⟨5/9⟩야.」","mis":"M6-1-u1-X15"}],"explanation":["⟨1 2/3⟩의 분수 부분 ⟨2/3⟩도 함께 나누어야 해요.","⟨5/3⟩ ÷ 3 = ⟨5/3⟩ × ⟨1/3⟩ = ⟨5/9⟩예요.","가온은 자연수 부분만 나누었어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L06_challenge#5','math',6,1,'u1','L06','g6_1_math_u1_L06_challenge','lesson_challenge','M6-1-u1-C6',3,'sa','auto','우유 ⟨2 1/3⟩ L를 4명이 똑같이 나누어 마셨어요. 한 명이 마신 우유를 분수로 나타낼 때 분모와 분자의 합은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M6-1-u1-C6","difficulty":3,"kind":"sa","stem":"우유 ⟨2 1/3⟩ L를 4명이 똑같이 나누어 마셨어요. 한 명이 마신 우유를 분수로 나타낼 때 분모와 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["19"],"explanation":["⟨2 1/3⟩ = ⟨7/3⟩이에요.","⟨7/3⟩ ÷ 4 = ⟨7/3⟩ × ⟨1/4⟩ = ⟨7/12⟩이에요.","한 명이 마신 우유는 ⟨7/12⟩ L — 분모와 분자의 합은 12 + 7 = 19예요."],"mis":"M6-1-u1-X15","variant_rule":{"alt":[{"stem":"페인트 ⟨4 1/2⟩ L를 3명이 똑같이 나누어 가졌어요. 한 명이 가지는 페인트를 분수로 나타낼 때 분모와 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["⟨4 1/2⟩ = ⟨9/2⟩예요.","⟨9/2⟩ ÷ 3 = ⟨9/2⟩ × ⟨1/3⟩ = ⟨3/2⟩이에요.","한 명이 가지는 페인트는 ⟨1 1/2⟩ L — 분모와 분자의 합은 2 + 3 = 5예요."]},{"stem":"유기견 보호소에서 사료 ⟨3 3/5⟩통을 6곳에 똑같이 나누어 주려고 해요. 한 곳에 주는 사료를 분수로 나타낼 때 분모와 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["⟨3 3/5⟩ = ⟨18/5⟩이에요.","⟨18/5⟩ ÷ 6 = ⟨18/5⟩ × ⟨1/6⟩ = ⟨3/5⟩이에요.","한 곳에 주는 사료는 ⟨3/5⟩통 — 분모와 분자의 합은 5 + 3 = 8이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L06_challenge#6','math',6,1,'u1','L06','g6_1_math_u1_L06_challenge','lesson_challenge','M6-1-u1-C6',3,'ox','auto','⟨2 2/3⟩ ÷ 2 = ⟨1 1/3⟩이에요.',ARRAY['M6-1-u1-X10']::text[],true,'{"seq":6,"concept":"M6-1-u1-C6","difficulty":3,"kind":"ox","stem":"⟨2 2/3⟩ ÷ 2 = ⟨1 1/3⟩이에요.","answer":"O","reason_options":[{"t":"⟨8/3⟩ × ⟨1/2⟩ = ⟨4/3⟩ = ⟨1 1/3⟩이므로","correct":true},{"t":"자연수 2를 2로 나누면 1이므로","mis":"M6-1-u1-X10"}],"mis":"M6-1-u1-X10","explanation":["⟨2 2/3⟩ = ⟨8/3⟩이에요.","⟨8/3⟩ × ⟨1/2⟩ = ⟨4/3⟩예요.","⟨4/3⟩ = ⟨1 1/3⟩ — 맞아요."],"variant_rule":{"alt":[{"stem":"⟨3 1/2⟩ ÷ 4 = ⟨3 1/8⟩이에요.","answer":"X","reason_options":[{"t":"⟨7/2⟩ × ⟨1/4⟩ = ⟨7/8⟩이어야 하므로","correct":true},{"t":"분수 부분의 분모에 4를 곱하면 되므로","mis":"M6-1-u1-X10"}],"explanation":["⟨3 1/2⟩ = ⟨7/2⟩이에요.","⟨7/2⟩ × ⟨1/4⟩ = ⟨7/8⟩이에요.","⟨3 1/8⟩은 분수 부분만 나눈 거예요."]},{"stem":"⟨2 1/3⟩ ÷ 3의 몫은 1보다 작아요.","answer":"O","reason_options":[{"t":"⟨7/3⟩ × ⟨1/3⟩ = ⟨7/9⟩이고 이것은 1보다 작으므로","correct":true},{"t":"대분수를 나누면 몫이 늘 1보다 크므로","mis":"M6-1-u1-X11"}],"explanation":["⟨2 1/3⟩ = ⟨7/3⟩이에요.","⟨7/3⟩ × ⟨1/3⟩ = ⟨7/9⟩이에요.","⟨7/9⟩ < 1 — 맞아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L06_challenge#7','math',6,1,'u1','L06','g6_1_math_u1_L06_challenge','lesson_challenge','M6-1-u1-C6',3,'mc','auto','몫이 1보다 작은 것은 어느 것인가요?',ARRAY['M6-1-u1-X11']::text[],true,'{"seq":7,"concept":"M6-1-u1-C6","difficulty":3,"kind":"mc","stem":"몫이 1보다 작은 것은 어느 것인가요?","options":[{"t":"⟨2 1/2⟩ ÷ 3","correct":true},{"t":"⟨3 1/4⟩ ÷ 2","mis":"M6-1-u1-X11"},{"t":"⟨4 1/3⟩ ÷ 3","mis":"M6-1-u1-X11"},{"t":"⟨5 1/2⟩ ÷ 5","mis":"M6-1-u1-X11"}],"explanation":["대분수를 가분수로 고쳐 단위분수를 곱해요.","⟨2 1/2⟩ ÷ 3 = ⟨5/6⟩, ⟨3 1/4⟩ ÷ 2 = ⟨1 5/8⟩, ⟨4 1/3⟩ ÷ 3 = ⟨1 4/9⟩, ⟨5 1/2⟩ ÷ 5 = ⟨1 1/10⟩이에요.","몫이 1보다 작은 것은 ⟨2 1/2⟩ ÷ 3이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 몫이 1보다 작은 것은 어느 것인가요?","options":[{"t":"⟨1 3/4⟩ ÷ 2","correct":true},{"t":"⟨2 4/5⟩ ÷ 2","mis":"M6-1-u1-X11"},{"t":"⟨3 2/3⟩ ÷ 2","mis":"M6-1-u1-X11"},{"t":"⟨4 3/4⟩ ÷ 4","mis":"M6-1-u1-X11"}],"explanation":["대분수를 가분수로 고쳐 단위분수를 곱해요.","⟨1 3/4⟩ ÷ 2 = ⟨7/8⟩, ⟨2 4/5⟩ ÷ 2 = ⟨1 2/5⟩, ⟨3 2/3⟩ ÷ 2 = ⟨1 5/6⟩, ⟨4 3/4⟩ ÷ 4 = ⟨1 3/16⟩이에요.","몫이 1보다 작은 것은 ⟨1 3/4⟩ ÷ 2예요."]},{"stem":"이번에는 다른 보기예요. 몫이 1보다 작은 것은 어느 것인가요?","options":[{"t":"⟨2 2/5⟩ ÷ 3","correct":true},{"t":"⟨2 5/6⟩ ÷ 2","mis":"M6-1-u1-X11"},{"t":"⟨3 1/6⟩ ÷ 2","mis":"M6-1-u1-X11"},{"t":"⟨6 1/3⟩ ÷ 5","mis":"M6-1-u1-X11"}],"explanation":["대분수를 가분수로 고쳐 단위분수를 곱해요.","⟨2 2/5⟩ ÷ 3 = ⟨4/5⟩, ⟨2 5/6⟩ ÷ 2 = ⟨1 5/12⟩, ⟨3 1/6⟩ ÷ 2 = ⟨1 7/12⟩, ⟨6 1/3⟩ ÷ 5 = ⟨1 4/15⟩예요.","몫이 1보다 작은 것은 ⟨2 2/5⟩ ÷ 3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L06_challenge#8','math',6,1,'u1','L06','g6_1_math_u1_L06_challenge','lesson_challenge','M6-1-u1-C6',4,'mc','auto','수 카드 7, 5, 6, 2를 한 번씩만 써서 (대분수)÷(자연수)를 만들 때, 몫이 가장 큰 것은 어느 것인가요?',ARRAY['M6-1-u1-X11']::text[],true,'{"seq":8,"concept":"M6-1-u1-C6","difficulty":4,"kind":"mc","stem":"수 카드 7, 5, 6, 2를 한 번씩만 써서 (대분수)÷(자연수)를 만들 때, 몫이 가장 큰 것은 어느 것인가요?","options":[{"t":"⟨7 5/6⟩ ÷ 2","correct":true},{"t":"⟨5 6/7⟩ ÷ 2","mis":"M6-1-u1-X11"},{"t":"⟨6 5/7⟩ ÷ 2","mis":"M6-1-u1-X11"},{"t":"⟨5 2/6⟩ ÷ 7","mis":"M6-1-u1-X11"}],"explanation":["몫이 크려면 나누어지는 대분수는 크게, 나누는 수는 작게 해야 해요.","⟨7 5/6⟩ ÷ 2 = ⟨47/6⟩ × ⟨1/2⟩ = ⟨3 11/12⟩이에요.","다른 식의 몫은 이보다 작아요 — 답은 ⟨7 5/6⟩ ÷ 2예요."],"variant_rule":{"alt":[{"stem":"수 카드 3, 8, 4, 5를 한 번씩만 써서 (대분수)÷(자연수)를 만들 때, 몫이 가장 큰 것은 어느 것인가요?","options":[{"t":"⟨8 4/5⟩ ÷ 3","correct":true},{"t":"⟨5 4/8⟩ ÷ 3","mis":"M6-1-u1-X11"},{"t":"⟨8 3/5⟩ ÷ 4","mis":"M6-1-u1-X11"},{"t":"⟨5 3/4⟩ ÷ 8","mis":"M6-1-u1-X11"}],"explanation":["몫이 크려면 나누어지는 대분수는 크게, 나누는 수는 작게 해야 해요.","⟨8 4/5⟩ ÷ 3 = ⟨44/5⟩ × ⟨1/3⟩ = ⟨2 14/15⟩예요.","다른 식의 몫은 이보다 작아요 — 답은 ⟨8 4/5⟩ ÷ 3이에요."]},{"stem":"수 카드 2, 9, 4, 7을 한 번씩만 써서 (대분수)÷(자연수)를 만들 때, 몫이 가장 작은 것은 어느 것인가요?","options":[{"t":"⟨2 4/7⟩ ÷ 9","correct":true},{"t":"⟨4 2/7⟩ ÷ 9","mis":"M6-1-u1-X11"},{"t":"⟨2 4/9⟩ ÷ 7","mis":"M6-1-u1-X11"},{"t":"⟨9 2/7⟩ ÷ 4","mis":"M6-1-u1-X11"}],"explanation":["몫이 작려면 나누어지는 대분수는 작게, 나누는 수는 크게 해야 해요.","⟨2 4/7⟩ ÷ 9 = ⟨18/7⟩ × ⟨1/9⟩ = ⟨2/7⟩예요.","다른 식의 몫은 이보다 커요 — 답은 ⟨2 4/7⟩ ÷ 9예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L06_challenge#9','math',6,1,'u1','L06','g6_1_math_u1_L06_challenge','lesson_challenge','M6-1-u1-C6',4,'sa','auto','자연수 부분이 □이고 분수 부분이 ⟨1/4⟩인 대분수를 3으로 나누었더니 ⟨3/4⟩이 되었어요. □에 알맞은 자연수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M6-1-u1-C6","difficulty":4,"kind":"sa","stem":"자연수 부분이 □이고 분수 부분이 ⟨1/4⟩인 대분수를 3으로 나누었더니 ⟨3/4⟩이 되었어요. □에 알맞은 자연수는 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["나누기 전의 수는 ⟨3/4⟩ × 3이에요.","⟨3/4⟩ × 3 = ⟨9/4⟩ = ⟨2 1/4⟩이에요.","그래서 □는 2예요."],"mis":"M6-1-u1-X10","variant_rule":{"alt":[{"stem":"⟨2 □/5⟩ ÷ 4 = ⟨13/20⟩일 때 □에 알맞은 자연수는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["나누기 전의 수는 ⟨13/20⟩ × 4예요.","⟨13/20⟩ × 4 = ⟨13/5⟩ = ⟨2 3/5⟩이에요.","그래서 □는 3이에요."]},{"stem":"자연수 부분이 □이고 분수 부분이 ⟨1/2⟩인 대분수를 7로 나누었더니 ⟨1/2⟩이 되었어요. □에 알맞은 자연수는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["나누기 전의 수는 ⟨1/2⟩ × 7이에요.","⟨1/2⟩ × 7 = ⟨7/2⟩ = ⟨3 1/2⟩이에요.","그래서 □는 3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L06_challenge#10','math',6,1,'u1','L06','g6_1_math_u1_L06_challenge','lesson_challenge','M6-1-u1-C6',4,'essay','teacher','⟨2 3/7⟩ ÷ 4를 계산하는 과정을 쓰고, 대분수를 먼저 가분수로 고치는 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-1-u1-C6","difficulty":4,"kind":"essay","stem":"⟨2 3/7⟩ ÷ 4를 계산하는 과정을 쓰고, 대분수를 먼저 가분수로 고치는 까닭을 설명해 보세요.","answer_guide":{"answer":"예: ⟨2 3/7⟩을 가분수로 고치면 2 × 7 + 3 = 17이므로 ⟨17/7⟩이다. ⟨17/7⟩ ÷ 4 = ⟨17/7⟩ × ⟨1/4⟩ = ⟨17/28⟩이다. 대분수는 자연수와 분수 두 덩어리라 그대로 나누면 자연수 부분만 나누는 실수를 하기 쉬우므로, 한 덩어리인 가분수로 모아 한 번에 나눈다.","scoring_points":["⟨2 3/7⟩ = ⟨17/7⟩로 고쳤는가","⟨17/7⟩ × ⟨1/4⟩ = ⟨17/28⟩을 구했는가","두 덩어리를 한 덩어리로 모으려고 가분수로 고친다고 설명했는가"]},"explanation":["⟨2 3/7⟩ = ⟨17/7⟩이에요.","⟨17/7⟩ × ⟨1/4⟩ = ⟨17/28⟩이에요.","가분수로 모으면 한 번에 나눌 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L07_basic#1','math',6,1,'u1','L07','g6_1_math_u1_L07_basic','lesson_basic','M6-1-u1-C7',1,'mc','auto','저울에서 파란 뚜껑 2개와 노란 뚜껑 1개의 무게가 파란 뚜껑 5개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개는 파란 뚜껑 몇 개와 무게가 같나요?',ARRAY['M6-1-u1-X13']::text[],true,'{"seq":1,"concept":"M6-1-u1-C7","difficulty":1,"kind":"mc","stem":"저울에서 파란 뚜껑 2개와 노란 뚜껑 1개의 무게가 파란 뚜껑 5개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개는 파란 뚜껑 몇 개와 무게가 같나요?","options":[{"t":"3개","correct":true},{"t":"2개","mis":"M6-1-u1-X13"},{"t":"5개","mis":"M6-1-u1-X13"},{"t":"7개","mis":"M6-1-u1-X13"}],"explanation":["양쪽에서 파란 뚜껑 2개씩을 덜어 내도 저울은 수평이에요.","왼쪽엔 노란 뚜껑 1개, 오른쪽엔 파란 뚜껑 5 − 2 = 3개가 남아요.","그래서 노란 뚜껑 1개는 파란 뚜껑 3개와 같아요."],"variant_rule":{"alt":[{"stem":"저울에서 파란 뚜껑 1개와 노란 뚜껑 1개의 무게가 파란 뚜껑 4개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개는 파란 뚜껑 몇 개와 무게가 같나요?","options":[{"t":"3개","correct":true},{"t":"1개","mis":"M6-1-u1-X13"},{"t":"4개","mis":"M6-1-u1-X13"},{"t":"5개","mis":"M6-1-u1-X13"}],"explanation":["양쪽에서 파란 뚜껑 1개씩을 덜어 내도 저울은 수평이에요.","왼쪽엔 노란 뚜껑 1개, 오른쪽엔 파란 뚜껑 4 − 1 = 3개가 남아요.","그래서 노란 뚜껑 1개는 파란 뚜껑 3개와 같아요."]},{"stem":"저울에서 파란 뚜껑 3개와 노란 뚜껑 1개의 무게가 파란 뚜껑 7개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개는 파란 뚜껑 몇 개와 무게가 같나요?","options":[{"t":"4개","correct":true},{"t":"3개","mis":"M6-1-u1-X13"},{"t":"7개","mis":"M6-1-u1-X13"},{"t":"10개","mis":"M6-1-u1-X13"}],"explanation":["양쪽에서 파란 뚜껑 3개씩을 덜어 내도 저울은 수평이에요.","왼쪽엔 노란 뚜껑 1개, 오른쪽엔 파란 뚜껑 7 − 3 = 4개가 남아요.","그래서 노란 뚜껑 1개는 파란 뚜껑 4개와 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L07_basic#2','math',6,1,'u1','L07','g6_1_math_u1_L07_basic','lesson_basic','M6-1-u1-C7',1,'sa','auto','노란 뚜껑 1개의 무게는 ⟨4 1/3⟩ g이에요. 이 무게를 가분수로 나타낼 때 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-1-u1-C7","difficulty":1,"kind":"sa","stem":"노란 뚜껑 1개의 무게는 ⟨4 1/3⟩ g이에요. 이 무게를 가분수로 나타낼 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["자연수 4는 ⟨12/3⟩예요.","4 × 3 + 1 = 13이에요.","⟨4 1/3⟩ = ⟨13/3⟩ — 분자는 13이에요."],"mis":"M6-1-u1-X05","variant_rule":{"alt":[{"stem":"노란 뚜껑 1개의 무게는 ⟨3 1/2⟩ g이에요. 이 무게를 가분수로 나타낼 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["자연수 3은 ⟨6/2⟩이에요.","3 × 2 + 1 = 7이에요.","⟨3 1/2⟩ = ⟨7/2⟩ — 분자는 7이에요."]},{"stem":"노란 뚜껑 1개의 무게는 ⟨5 2/3⟩ g이에요. 이 무게를 가분수로 나타낼 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["17"],"explanation":["자연수 5는 ⟨15/3⟩예요.","5 × 3 + 2 = 17이에요.","⟨5 2/3⟩ = ⟨17/3⟩ — 분자는 17이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L07_basic#3','math',6,1,'u1','L07','g6_1_math_u1_L07_basic','lesson_basic','M6-1-u1-C7',1,'mc','auto','노란 뚜껑 1개(⟨4 1/3⟩ g)가 파란 뚜껑 3개와 무게가 같아요. 파란 뚜껑 1개의 무게를 구하는 곱셈식으로 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u1-X06','M6-1-u1-X05','M6-1-u1-X07']::text[],true,'{"seq":3,"concept":"M6-1-u1-C7","difficulty":1,"kind":"mc","stem":"노란 뚜껑 1개(⟨4 1/3⟩ g)가 파란 뚜껑 3개와 무게가 같아요. 파란 뚜껑 1개의 무게를 구하는 곱셈식으로 알맞은 것은 어느 것인가요?","options":[{"t":"⟨13/3⟩ × ⟨1/3⟩","correct":true},{"t":"⟨13/3⟩ × 3","mis":"M6-1-u1-X06"},{"t":"13 × ⟨1/3⟩","mis":"M6-1-u1-X05"},{"t":"⟨1/3⟩ × ⟨3/13⟩","mis":"M6-1-u1-X07"}],"explanation":["파란 뚜껑 1개는 노란 뚜껑 무게를 3으로 나눈 거예요.","⟨4 1/3⟩ = ⟨13/3⟩이고 ÷ 3은 × ⟨1/3⟩이에요.","그래서 식은 ⟨13/3⟩ × ⟨1/3⟩이에요."],"variant_rule":{"alt":[{"stem":"노란 뚜껑 1개(⟨3 1/2⟩ g)가 파란 뚜껑 2개와 무게가 같아요. 파란 뚜껑 1개의 무게를 구하는 곱셈식으로 알맞은 것은 어느 것인가요?","options":[{"t":"⟨7/2⟩ × ⟨1/2⟩","correct":true},{"t":"⟨7/2⟩ × 2","mis":"M6-1-u1-X06"},{"t":"7 × ⟨1/2⟩","mis":"M6-1-u1-X05"},{"t":"⟨1/2⟩ × ⟨2/7⟩","mis":"M6-1-u1-X07"}],"explanation":["파란 뚜껑 1개는 노란 뚜껑 무게를 2로 나눈 거예요.","⟨3 1/2⟩ = ⟨7/2⟩이고 ÷ 2는 × ⟨1/2⟩이에요.","그래서 식은 ⟨7/2⟩ × ⟨1/2⟩이에요."]},{"stem":"노란 뚜껑 1개(⟨5 1/4⟩ g)가 파란 뚜껑 3개와 무게가 같아요. 파란 뚜껑 1개의 무게를 구하는 곱셈식으로 알맞은 것은 어느 것인가요?","options":[{"t":"⟨21/4⟩ × ⟨1/3⟩","correct":true},{"t":"⟨21/4⟩ × 3","mis":"M6-1-u1-X06"},{"t":"21 × ⟨1/3⟩","mis":"M6-1-u1-X05"},{"t":"⟨1/3⟩ × ⟨4/21⟩","mis":"M6-1-u1-X07"}],"explanation":["파란 뚜껑 1개는 노란 뚜껑 무게를 3으로 나눈 거예요.","⟨5 1/4⟩ = ⟨21/4⟩이고 ÷ 3은 × ⟨1/3⟩이에요.","그래서 식은 ⟨21/4⟩ × ⟨1/3⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L07_basic#4','math',6,1,'u1','L07','g6_1_math_u1_L07_basic','lesson_basic','M6-1-u1-C7',1,'ox','auto','수평인 저울의 양쪽에서 같은 무게를 똑같이 덜어 내도 저울은 수평이에요.',ARRAY['M6-1-u1-X13']::text[],true,'{"seq":4,"concept":"M6-1-u1-C7","difficulty":1,"kind":"ox","stem":"수평인 저울의 양쪽에서 같은 무게를 똑같이 덜어 내도 저울은 수평이에요.","answer":"O","reason_options":[{"t":"양쪽이 똑같이 줄어 균형이 그대로이므로","correct":true},{"t":"한쪽만 무거워지므로","mis":"M6-1-u1-X13"}],"mis":"M6-1-u1-X13","explanation":["수평이면 양쪽 무게가 같아요.","양쪽에서 같은 무게를 빼도 남은 무게는 서로 같아요.","그래서 맞아요."],"variant_rule":{"alt":[{"stem":"수평인 저울의 한쪽에서만 뚜껑을 덜어 내도 저울은 수평이에요.","answer":"X","reason_options":[{"t":"한쪽만 가벼워져 균형이 깨지므로","correct":true},{"t":"뚜껑 무게는 아주 가벼워 상관없으므로","mis":"M6-1-u1-X13"}],"explanation":["한쪽만 덜어 내면 그쪽이 가벼워져요.","균형을 지키려면 양쪽에서 똑같이 덜어 내야 해요.","그래서 틀렸어요."]},{"stem":"노란 뚜껑 1개가 파란 뚜껑 3개와 무게가 같으면, 파란 뚜껑 1개의 무게는 노란 뚜껑 무게 ÷ 3이에요.","answer":"O","reason_options":[{"t":"노란 뚜껑 무게를 파란 3개가 똑같이 나눈 것이므로","correct":true},{"t":"노란 뚜껑 무게 × 3이 파란 1개이므로","mis":"M6-1-u1-X06"}],"explanation":["노란 1개 = 파란 3개예요.","파란 1개는 노란 1개 무게를 3으로 똑같이 나눈 거예요.","그래서 맞아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L07_basic#5','math',6,1,'u1','L07','g6_1_math_u1_L07_basic','lesson_basic','M6-1-u1-C7',2,'mc','auto','파란 뚜껑 2개와 노란 뚜껑 1개의 무게가 파란 뚜껑 5개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개의 무게가 ⟨4 1/3⟩ g일 때, 파란 뚜껑 1개의 무게는 몇 g인가요?',ARRAY['M6-1-u1-X13','M6-1-u1-X06']::text[],true,'{"seq":5,"concept":"M6-1-u1-C7","difficulty":2,"kind":"mc","stem":"파란 뚜껑 2개와 노란 뚜껑 1개의 무게가 파란 뚜껑 5개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개의 무게가 ⟨4 1/3⟩ g일 때, 파란 뚜껑 1개의 무게는 몇 g인가요?","options":[{"t":"⟨1 4/9⟩","correct":true},{"t":"⟨13/15⟩","mis":"M6-1-u1-X13"},{"t":"⟨2 1/6⟩","mis":"M6-1-u1-X13"},{"t":"13","mis":"M6-1-u1-X06"}],"explanation":["양쪽에서 파란 2개씩 덜어 내면 노란 1개 = 파란 3개예요.","⟨4 1/3⟩ = ⟨13/3⟩이에요.","⟨13/3⟩ × ⟨1/3⟩ = ⟨1 4/9⟩ — 파란 뚜껑 1개는 ⟨1 4/9⟩ g이에요."],"variant_rule":{"alt":[{"stem":"파란 뚜껑 1개와 노란 뚜껑 1개의 무게가 파란 뚜껑 4개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개의 무게가 ⟨3 3/4⟩ g일 때, 파란 뚜껑 1개의 무게는 몇 g인가요?","options":[{"t":"⟨1 1/4⟩","correct":true},{"t":"⟨15/16⟩","mis":"M6-1-u1-X13"},{"t":"⟨3 3/4⟩","mis":"M6-1-u1-X13"},{"t":"⟨11 1/4⟩","mis":"M6-1-u1-X06"}],"explanation":["양쪽에서 파란 1개씩 덜어 내면 노란 1개 = 파란 3개예요.","⟨3 3/4⟩ = ⟨15/4⟩예요.","⟨15/4⟩ × ⟨1/3⟩ = ⟨1 1/4⟩ — 파란 뚜껑 1개는 ⟨1 1/4⟩ g이에요."]},{"stem":"파란 뚜껑 3개와 노란 뚜껑 1개의 무게가 파란 뚜껑 5개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개의 무게가 ⟨2 1/3⟩ g일 때, 파란 뚜껑 1개의 무게는 몇 g인가요?","options":[{"t":"⟨1 1/6⟩","correct":true},{"t":"⟨7/15⟩","mis":"M6-1-u1-X13"},{"t":"⟨7/9⟩","mis":"M6-1-u1-X13"},{"t":"⟨4 2/3⟩","mis":"M6-1-u1-X06"}],"explanation":["양쪽에서 파란 3개씩 덜어 내면 노란 1개 = 파란 2개예요.","⟨2 1/3⟩ = ⟨7/3⟩이에요.","⟨7/3⟩ × ⟨1/2⟩ = ⟨1 1/6⟩ — 파란 뚜껑 1개는 ⟨1 1/6⟩ g이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L07_basic#6','math',6,1,'u1','L07','g6_1_math_u1_L07_basic','lesson_basic','M6-1-u1-C7',2,'mc','auto','저울 문제에서 파란 뚜껑 1개의 무게를 구할 때 가장 먼저 할 일은 무엇인가요?',ARRAY['M6-1-u1-X13','M6-1-u1-X06','M6-1-u1-X10']::text[],true,'{"seq":6,"concept":"M6-1-u1-C7","difficulty":2,"kind":"mc","stem":"저울 문제에서 파란 뚜껑 1개의 무게를 구할 때 가장 먼저 할 일은 무엇인가요?","options":[{"t":"양쪽에서 같은 뚜껑을 덜어 내 노란 뚜껑과 파란 뚜껑의 관계를 찾는다","correct":true},{"t":"노란 뚜껑 무게를 파란 뚜껑 전체 수로 바로 나눈다","mis":"M6-1-u1-X13"},{"t":"노란 뚜껑 무게에 파란 뚜껑 수를 곱한다","mis":"M6-1-u1-X06"},{"t":"대분수의 자연수 부분만 나눈다","mis":"M6-1-u1-X10"}],"explanation":["저울에서 양쪽의 같은 것을 덜어 내면 관계가 보여요.","노란 1개 = 파란 □개이면 파란 1개 = 노란 무게 ÷ □예요.","그래서 답은 「양쪽에서 같은 뚜껑을 덜어 내 노란 뚜껑과 파란 뚜껑의 관계를 찾는다」예요."],"variant_rule":{"alt":[{"stem":"저울 문제를 푸는 순서로 알맞은 것은 어느 것인가요?","options":[{"t":"관계 찾기 → 대분수를 가분수로 → 단위분수 곱하기","correct":true},{"t":"단위분수 곱하기 → 관계 찾기 → 가분수로","mis":"M6-1-u1-X13"},{"t":"가분수로 → 뚜껑 수 곱하기 → 관계 찾기","mis":"M6-1-u1-X06"},{"t":"관계 찾기 → 자연수 부분만 나누기","mis":"M6-1-u1-X10"}],"explanation":["저울에서 양쪽의 같은 것을 덜어 내면 관계가 보여요.","노란 1개 = 파란 □개이면 파란 1개 = 노란 무게 ÷ □예요.","그래서 답은 「관계 찾기 → 대분수를 가분수로 → 단위분수 곱하기」예요."]},{"stem":"노란 뚜껑 1개가 파란 뚜껑 몇 개와 같은지 알았어요. 그다음 할 일로 알맞은 것은 어느 것인가요?","options":[{"t":"노란 뚜껑 무게를 그 개수로 나눈다","correct":true},{"t":"노란 뚜껑 무게에 그 개수를 곱한다","mis":"M6-1-u1-X06"},{"t":"노란 뚜껑 무게를 저울 오른쪽 뚜껑 수로 나눈다","mis":"M6-1-u1-X13"},{"t":"노란 뚜껑 무게에서 그 개수를 뺀다","mis":"M6-1-u1-X09"}],"explanation":["저울에서 양쪽의 같은 것을 덜어 내면 관계가 보여요.","노란 1개 = 파란 □개이면 파란 1개 = 노란 무게 ÷ □예요.","그래서 답은 「노란 뚜껑 무게를 그 개수로 나눈다」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L07_basic#7','math',6,1,'u1','L07','g6_1_math_u1_L07_basic','lesson_basic','M6-1-u1-C7',2,'sa','auto','조건을 바꾸어 보아요. 노란 뚜껑 1개가 ⟨3 1/2⟩ g이고 파란 뚜껑 2개와 무게가 같아요. 파란 뚜껑 1개의 무게를 기약분수(가분수)로 나타낼 때 분모와 분자의 합은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M6-1-u1-C7","difficulty":2,"kind":"sa","stem":"조건을 바꾸어 보아요. 노란 뚜껑 1개가 ⟨3 1/2⟩ g이고 파란 뚜껑 2개와 무게가 같아요. 파란 뚜껑 1개의 무게를 기약분수(가분수)로 나타낼 때 분모와 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["파란 뚜껑 1개 = ⟨3 1/2⟩ ÷ 2예요.","⟨7/2⟩ ÷ 2 = ⟨7/2⟩ × ⟨1/2⟩ = ⟨7/4⟩이에요.","분모와 분자의 합은 4 + 7 = 11이에요."],"mis":"M6-1-u1-X15","variant_rule":{"alt":[{"stem":"조건을 바꾸어 보아요. 노란 뚜껑 1개가 ⟨2 2/5⟩ g이고 파란 뚜껑 3개와 무게가 같아요. 파란 뚜껑 1개의 무게를 기약분수(가분수)로 나타낼 때 분모와 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["파란 뚜껑 1개 = ⟨2 2/5⟩ ÷ 3이에요.","⟨12/5⟩ ÷ 3 = ⟨12/5⟩ × ⟨1/3⟩ = ⟨4/5⟩예요.","분모와 분자의 합은 5 + 4 = 9예요."]},{"stem":"조건을 바꾸어 보아요. 노란 뚜껑 1개가 ⟨4 1/2⟩ g이고 파란 뚜껑 5개와 무게가 같아요. 파란 뚜껑 1개의 무게를 기약분수(가분수)로 나타낼 때 분모와 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["19"],"explanation":["파란 뚜껑 1개 = ⟨4 1/2⟩ ÷ 5예요.","⟨9/2⟩ ÷ 5 = ⟨9/2⟩ × ⟨1/5⟩ = ⟨9/10⟩예요.","분모와 분자의 합은 10 + 9 = 19예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L07_basic#8','math',6,1,'u1','L07','g6_1_math_u1_L07_basic','lesson_basic','M6-1-u1-C7',2,'mc','auto','파란 뚜껑 1개의 무게가 ⟨1 4/9⟩ g이에요. 파란 뚜껑 3개의 무게는 몇 g인가요?',ARRAY['M6-1-u1-X10','M6-1-u1-X14','M6-1-u1-X12']::text[],true,'{"seq":8,"concept":"M6-1-u1-C7","difficulty":2,"kind":"mc","stem":"파란 뚜껑 1개의 무게가 ⟨1 4/9⟩ g이에요. 파란 뚜껑 3개의 무게는 몇 g인가요?","options":[{"t":"⟨4 1/3⟩","correct":true},{"t":"⟨3 4/9⟩","mis":"M6-1-u1-X10"},{"t":"⟨13/27⟩","mis":"M6-1-u1-X14"},{"t":"⟨4 4/9⟩","mis":"M6-1-u1-X12"}],"explanation":["⟨1 4/9⟩ = ⟨13/9⟩이에요.","⟨13/9⟩ × 3 = ⟨13/3⟩이에요.","⟨13/3⟩ = ⟨4 1/3⟩ — 파란 뚜껑 3개는 ⟨4 1/3⟩ g이에요."],"variant_rule":{"alt":[{"stem":"파란 뚜껑 1개의 무게가 ⟨1 2/5⟩ g이에요. 파란 뚜껑 2개의 무게는 몇 g인가요?","options":[{"t":"⟨2 4/5⟩","correct":true},{"t":"⟨2 2/5⟩","mis":"M6-1-u1-X10"},{"t":"⟨7/10⟩","mis":"M6-1-u1-X14"},{"t":"⟨1 4/5⟩","mis":"M6-1-u1-X10"}],"explanation":["⟨1 2/5⟩ = ⟨7/5⟩이에요.","⟨7/5⟩ × 2 = ⟨14/5⟩예요.","⟨14/5⟩ = ⟨2 4/5⟩ — 파란 뚜껑 2개는 ⟨2 4/5⟩ g이에요."]},{"stem":"파란 뚜껑 1개의 무게가 ⟨2 1/3⟩ g이에요. 파란 뚜껑 4개의 무게는 몇 g인가요?","options":[{"t":"⟨9 1/3⟩","correct":true},{"t":"⟨8 1/3⟩","mis":"M6-1-u1-X10"},{"t":"⟨7/12⟩","mis":"M6-1-u1-X14"},{"t":"⟨9 2/3⟩","mis":"M6-1-u1-X12"}],"explanation":["⟨2 1/3⟩ = ⟨7/3⟩이에요.","⟨7/3⟩ × 4 = ⟨28/3⟩이에요.","⟨28/3⟩ = ⟨9 1/3⟩ — 파란 뚜껑 4개는 ⟨9 1/3⟩ g이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L07_basic#9','math',6,1,'u1','L07','g6_1_math_u1_L07_basic','lesson_basic','M6-1-u1-C7',2,'mc','auto','모은 페트병 뚜껑 ⟨6 3/4⟩ g을 5묶음으로 똑같이 나누면 한 묶음은 몇 g인가요?',ARRAY['M6-1-u1-X10','M6-1-u1-X06']::text[],true,'{"seq":9,"concept":"M6-1-u1-C7","difficulty":2,"kind":"mc","stem":"모은 페트병 뚜껑 ⟨6 3/4⟩ g을 5묶음으로 똑같이 나누면 한 묶음은 몇 g인가요?","options":[{"t":"⟨1 7/20⟩","correct":true},{"t":"⟨6 3/20⟩","mis":"M6-1-u1-X10"},{"t":"⟨1 19/20⟩","mis":"M6-1-u1-X10"},{"t":"⟨33 3/4⟩","mis":"M6-1-u1-X06"}],"explanation":["⟨6 3/4⟩ = ⟨27/4⟩이에요.","⟨27/4⟩ ÷ 5 = ⟨27/4⟩ × ⟨1/5⟩이에요.","⟨27/4⟩ × ⟨1/5⟩ = ⟨1 7/20⟩ — 한 묶음은 ⟨1 7/20⟩ g이에요."],"variant_rule":{"alt":[{"stem":"모은 페트병 뚜껑 ⟨4 2/3⟩ g을 2묶음으로 똑같이 나누면 한 묶음은 몇 g인가요?","options":[{"t":"⟨2 1/3⟩","correct":true},{"t":"⟨4 1/3⟩","mis":"M6-1-u1-X10"},{"t":"⟨2 2/3⟩","mis":"M6-1-u1-X10"},{"t":"⟨9 1/3⟩","mis":"M6-1-u1-X06"}],"explanation":["⟨4 2/3⟩ = ⟨14/3⟩예요.","⟨14/3⟩ ÷ 2 = ⟨14/3⟩ × ⟨1/2⟩이에요.","⟨14/3⟩ × ⟨1/2⟩ = ⟨2 1/3⟩ — 한 묶음은 ⟨2 1/3⟩ g이에요."]},{"stem":"모은 페트병 뚜껑 ⟨5 1/2⟩ g을 3묶음으로 똑같이 나누면 한 묶음은 몇 g인가요?","options":[{"t":"⟨1 5/6⟩","correct":true},{"t":"⟨5 1/6⟩","mis":"M6-1-u1-X10"},{"t":"⟨2 1/6⟩","mis":"M6-1-u1-X10"},{"t":"⟨16 1/2⟩","mis":"M6-1-u1-X06"}],"explanation":["⟨5 1/2⟩ = ⟨11/2⟩이에요.","⟨11/2⟩ ÷ 3 = ⟨11/2⟩ × ⟨1/3⟩이에요.","⟨11/2⟩ × ⟨1/3⟩ = ⟨1 5/6⟩ — 한 묶음은 ⟨1 5/6⟩ g이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L07_basic#10','math',6,1,'u1','L07','g6_1_math_u1_L07_basic','lesson_basic','M6-1-u1-C7',3,'sa','auto','조건을 바꾸어 보아요. 노란 뚜껑 1개가 ⟨5 1/3⟩ g이고 파란 뚜껑 4개와 무게가 같아요. 파란 뚜껑 1개의 무게를 기약분수(가분수)로 나타낼 때 분모와 분자의 합은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M6-1-u1-C7","difficulty":3,"kind":"sa","stem":"조건을 바꾸어 보아요. 노란 뚜껑 1개가 ⟨5 1/3⟩ g이고 파란 뚜껑 4개와 무게가 같아요. 파란 뚜껑 1개의 무게를 기약분수(가분수)로 나타낼 때 분모와 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["파란 뚜껑 1개 = ⟨5 1/3⟩ ÷ 4예요.","⟨16/3⟩ ÷ 4 = ⟨16/3⟩ × ⟨1/4⟩ = ⟨4/3⟩예요.","분모와 분자의 합은 3 + 4 = 7이에요."],"mis":"M6-1-u1-X15","variant_rule":{"alt":[{"stem":"조건을 바꾸어 보아요. 노란 뚜껑 1개가 ⟨4 2/3⟩ g이고 파란 뚜껑 7개와 무게가 같아요. 파란 뚜껑 1개의 무게를 기약분수(가분수)로 나타낼 때 분모와 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["파란 뚜껑 1개 = ⟨4 2/3⟩ ÷ 7이에요.","⟨14/3⟩ ÷ 7 = ⟨14/3⟩ × ⟨1/7⟩ = ⟨2/3⟩예요.","분모와 분자의 합은 3 + 2 = 5예요."]},{"stem":"조건을 바꾸어 보아요. 노란 뚜껑 1개가 ⟨2 4/7⟩ g이고 파란 뚜껑 6개와 무게가 같아요. 파란 뚜껑 1개의 무게를 기약분수(가분수)로 나타낼 때 분모와 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["파란 뚜껑 1개 = ⟨2 4/7⟩ ÷ 6이에요.","⟨18/7⟩ ÷ 6 = ⟨18/7⟩ × ⟨1/6⟩ = ⟨3/7⟩이에요.","분모와 분자의 합은 7 + 3 = 10이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L07_challenge#1','math',6,1,'u1','L07','g6_1_math_u1_L07_challenge','lesson_challenge','M6-1-u1-C7',2,'mc','auto','저울에서 파란 뚜껑 3개와 노란 뚜껑 1개의 무게가 파란 뚜껑 8개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개는 파란 뚜껑 몇 개와 무게가 같나요?',ARRAY['M6-1-u1-X13']::text[],true,'{"seq":1,"concept":"M6-1-u1-C7","difficulty":2,"kind":"mc","stem":"저울에서 파란 뚜껑 3개와 노란 뚜껑 1개의 무게가 파란 뚜껑 8개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개는 파란 뚜껑 몇 개와 무게가 같나요?","options":[{"t":"5개","correct":true},{"t":"3개","mis":"M6-1-u1-X13"},{"t":"8개","mis":"M6-1-u1-X13"},{"t":"11개","mis":"M6-1-u1-X13"}],"explanation":["양쪽에서 파란 뚜껑 3개씩을 덜어 내도 저울은 수평이에요.","왼쪽엔 노란 뚜껑 1개, 오른쪽엔 파란 뚜껑 8 − 3 = 5개가 남아요.","그래서 노란 뚜껑 1개는 파란 뚜껑 5개와 같아요."],"variant_rule":{"alt":[{"stem":"저울에서 파란 뚜껑 2개와 노란 뚜껑 1개의 무게가 파란 뚜껑 6개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개는 파란 뚜껑 몇 개와 무게가 같나요?","options":[{"t":"4개","correct":true},{"t":"2개","mis":"M6-1-u1-X13"},{"t":"6개","mis":"M6-1-u1-X13"},{"t":"8개","mis":"M6-1-u1-X13"}],"explanation":["양쪽에서 파란 뚜껑 2개씩을 덜어 내도 저울은 수평이에요.","왼쪽엔 노란 뚜껑 1개, 오른쪽엔 파란 뚜껑 6 − 2 = 4개가 남아요.","그래서 노란 뚜껑 1개는 파란 뚜껑 4개와 같아요."]},{"stem":"저울에서 파란 뚜껑 4개와 노란 뚜껑 1개의 무게가 파란 뚜껑 9개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개는 파란 뚜껑 몇 개와 무게가 같나요?","options":[{"t":"5개","correct":true},{"t":"4개","mis":"M6-1-u1-X13"},{"t":"9개","mis":"M6-1-u1-X13"},{"t":"13개","mis":"M6-1-u1-X13"}],"explanation":["양쪽에서 파란 뚜껑 4개씩을 덜어 내도 저울은 수평이에요.","왼쪽엔 노란 뚜껑 1개, 오른쪽엔 파란 뚜껑 9 − 4 = 5개가 남아요.","그래서 노란 뚜껑 1개는 파란 뚜껑 5개와 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L07_challenge#2','math',6,1,'u1','L07','g6_1_math_u1_L07_challenge','lesson_challenge','M6-1-u1-C7',2,'mc','auto','파란 뚜껑 1개와 노란 뚜껑 1개의 무게가 파란 뚜껑 3개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개의 무게가 ⟨3 1/2⟩ g일 때, 파란 뚜껑 1개의 무게는 몇 g인가요?',ARRAY['M6-1-u1-X13','M6-1-u1-X06']::text[],true,'{"seq":2,"concept":"M6-1-u1-C7","difficulty":2,"kind":"mc","stem":"파란 뚜껑 1개와 노란 뚜껑 1개의 무게가 파란 뚜껑 3개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개의 무게가 ⟨3 1/2⟩ g일 때, 파란 뚜껑 1개의 무게는 몇 g인가요?","options":[{"t":"⟨1 3/4⟩","correct":true},{"t":"⟨1 1/6⟩","mis":"M6-1-u1-X13"},{"t":"⟨3 1/2⟩","mis":"M6-1-u1-X13"},{"t":"7","mis":"M6-1-u1-X06"}],"explanation":["양쪽에서 파란 1개씩 덜어 내면 노란 1개 = 파란 2개예요.","⟨3 1/2⟩ = ⟨7/2⟩이에요.","⟨7/2⟩ × ⟨1/2⟩ = ⟨1 3/4⟩ — 파란 뚜껑 1개는 ⟨1 3/4⟩ g이에요."],"variant_rule":{"alt":[{"stem":"파란 뚜껑 2개와 노란 뚜껑 1개의 무게가 파란 뚜껑 6개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개의 무게가 ⟨5 1/3⟩ g일 때, 파란 뚜껑 1개의 무게는 몇 g인가요?","options":[{"t":"⟨1 1/3⟩","correct":true},{"t":"⟨8/9⟩","mis":"M6-1-u1-X13"},{"t":"⟨2 2/3⟩","mis":"M6-1-u1-X13"},{"t":"⟨21 1/3⟩","mis":"M6-1-u1-X06"}],"explanation":["양쪽에서 파란 2개씩 덜어 내면 노란 1개 = 파란 4개예요.","⟨5 1/3⟩ = ⟨16/3⟩이에요.","⟨16/3⟩ × ⟨1/4⟩ = ⟨1 1/3⟩ — 파란 뚜껑 1개는 ⟨1 1/3⟩ g이에요."]},{"stem":"파란 뚜껑 3개와 노란 뚜껑 1개의 무게가 파란 뚜껑 8개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개의 무게가 ⟨6 1/4⟩ g일 때, 파란 뚜껑 1개의 무게는 몇 g인가요?","options":[{"t":"⟨1 1/4⟩","correct":true},{"t":"⟨25/32⟩","mis":"M6-1-u1-X13"},{"t":"⟨2 1/12⟩","mis":"M6-1-u1-X13"},{"t":"⟨31 1/4⟩","mis":"M6-1-u1-X06"}],"explanation":["양쪽에서 파란 3개씩 덜어 내면 노란 1개 = 파란 5개예요.","⟨6 1/4⟩ = ⟨25/4⟩예요.","⟨25/4⟩ × ⟨1/5⟩ = ⟨1 1/4⟩ — 파란 뚜껑 1개는 ⟨1 1/4⟩ g이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L07_challenge#3','math',6,1,'u1','L07','g6_1_math_u1_L07_challenge','lesson_challenge','M6-1-u1-C7',3,'error','auto','파란 뚜껑 2개와 노란 뚜껑 1개의 무게가 파란 뚜껑 5개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개는 ⟨4 1/3⟩ g이에요. 친구들의 풀이 가운데 잘못된 것은 누구의 것인가요?',ARRAY['M6-1-u1-X13','M6-1-u1-X15']::text[],true,'{"seq":3,"concept":"M6-1-u1-C7","difficulty":3,"kind":"error","stem":"파란 뚜껑 2개와 노란 뚜껑 1개의 무게가 파란 뚜껑 5개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개는 ⟨4 1/3⟩ g이에요. 친구들의 풀이 가운데 잘못된 것은 누구의 것인가요?","options":[{"t":"수아 — 「파란 뚜껑이 5개니까 ⟨4 1/3⟩ ÷ 5를 계산해.」","correct":true,"mis_target":"M6-1-u1-X13"},{"t":"도윤 — 「양쪽에서 파란 2개씩 덜어 내면 노란 1개 = 파란 3개야.」","mis":"M6-1-u1-X15"},{"t":"하린 — 「파란 1개는 ⟨13/3⟩ × ⟨1/3⟩이야.」","mis":"M6-1-u1-X15"}],"explanation":["양쪽에서 파란 2개씩 덜어 내야 해요.","노란 1개 = 파란 3개이니 ⟨4 1/3⟩ ÷ 3이에요.","수아는 덜어 내지 않고 5로 나누었어요."],"variant_rule":{"alt":[{"stem":"파란 뚜껑 1개와 노란 뚜껑 1개의 무게가 파란 뚜껑 4개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개는 ⟨3 3/4⟩ g이에요. 친구들의 풀이 가운데 잘못된 것은 누구의 것인가요?","options":[{"t":"민준 — 「파란 뚜껑이 4개니까 ⟨3 3/4⟩ ÷ 4를 계산해.」","correct":true,"mis_target":"M6-1-u1-X13"},{"t":"서연 — 「양쪽에서 파란 1개씩 덜어 내면 노란 1개 = 파란 3개야.」","mis":"M6-1-u1-X15"},{"t":"지호 — 「파란 1개는 ⟨15/4⟩ × ⟨1/3⟩이야.」","mis":"M6-1-u1-X15"}],"explanation":["양쪽에서 파란 1개씩 덜어 내야 해요.","노란 1개 = 파란 3개이니 ⟨3 3/4⟩ ÷ 3이에요.","민준은 덜어 내지 않고 4로 나누었어요."]},{"stem":"파란 뚜껑 2개와 노란 뚜껑 1개의 무게가 파란 뚜껑 6개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개는 ⟨5 1/3⟩ g이에요. 친구들의 풀이 가운데 잘못된 것은 누구의 것인가요?","options":[{"t":"가온 — 「파란 뚜껑이 6개니까 ⟨5 1/3⟩ ÷ 6을 계산해.」","correct":true,"mis_target":"M6-1-u1-X13"},{"t":"나린 — 「양쪽에서 파란 2개씩 덜어 내면 노란 1개 = 파란 4개야.」","mis":"M6-1-u1-X15"},{"t":"유진 — 「파란 1개는 ⟨16/3⟩ × ⟨1/4⟩이야.」","mis":"M6-1-u1-X15"}],"explanation":["양쪽에서 파란 2개씩 덜어 내야 해요.","노란 1개 = 파란 4개이니 ⟨5 1/3⟩ ÷ 4예요.","가온은 덜어 내지 않고 6으로 나누었어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L07_challenge#4','math',6,1,'u1','L07','g6_1_math_u1_L07_challenge','lesson_challenge','M6-1-u1-C7',3,'sa','auto','조건을 바꾸어 보아요. 노란 뚜껑 1개가 ⟨3 3/4⟩ g이고 파란 뚜껑 5개와 무게가 같아요. 파란 뚜껑 1개의 무게를 기약분수(가분수)로 나타낼 때 분모와 분자의 합은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M6-1-u1-C7","difficulty":3,"kind":"sa","stem":"조건을 바꾸어 보아요. 노란 뚜껑 1개가 ⟨3 3/4⟩ g이고 파란 뚜껑 5개와 무게가 같아요. 파란 뚜껑 1개의 무게를 기약분수(가분수)로 나타낼 때 분모와 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["파란 뚜껑 1개 = ⟨3 3/4⟩ ÷ 5예요.","⟨15/4⟩ ÷ 5 = ⟨15/4⟩ × ⟨1/5⟩ = ⟨3/4⟩이에요.","분모와 분자의 합은 4 + 3 = 7이에요."],"mis":"M6-1-u1-X15","variant_rule":{"alt":[{"stem":"조건을 바꾸어 보아요. 노란 뚜껑 1개가 ⟨2 1/3⟩ g이고 파란 뚜껑 7개와 무게가 같아요. 파란 뚜껑 1개의 무게를 기약분수(가분수)로 나타낼 때 분모와 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["파란 뚜껑 1개 = ⟨2 1/3⟩ ÷ 7이에요.","⟨7/3⟩ ÷ 7 = ⟨7/3⟩ × ⟨1/7⟩ = ⟨1/3⟩이에요.","분모와 분자의 합은 3 + 1 = 4예요."]},{"stem":"조건을 바꾸어 보아요. 노란 뚜껑 1개가 ⟨5 2/5⟩ g이고 파란 뚜껑 9개와 무게가 같아요. 파란 뚜껑 1개의 무게를 기약분수(가분수)로 나타낼 때 분모와 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["파란 뚜껑 1개 = ⟨5 2/5⟩ ÷ 9예요.","⟨27/5⟩ ÷ 9 = ⟨27/5⟩ × ⟨1/9⟩ = ⟨3/5⟩이에요.","분모와 분자의 합은 5 + 3 = 8이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L07_challenge#5','math',6,1,'u1','L07','g6_1_math_u1_L07_challenge','lesson_challenge','M6-1-u1-C7',3,'mc','auto','파란 뚜껑 1개의 무게가 ⟨2 3/4⟩ g이에요. 파란 뚜껑 3개의 무게는 몇 g인가요?',ARRAY['M6-1-u1-X10','M6-1-u1-X14','M6-1-u1-X12']::text[],true,'{"seq":5,"concept":"M6-1-u1-C7","difficulty":3,"kind":"mc","stem":"파란 뚜껑 1개의 무게가 ⟨2 3/4⟩ g이에요. 파란 뚜껑 3개의 무게는 몇 g인가요?","options":[{"t":"⟨8 1/4⟩","correct":true},{"t":"⟨6 3/4⟩","mis":"M6-1-u1-X10"},{"t":"⟨11/12⟩","mis":"M6-1-u1-X14"},{"t":"⟨8 1/2⟩","mis":"M6-1-u1-X12"}],"explanation":["⟨2 3/4⟩ = ⟨11/4⟩이에요.","⟨11/4⟩ × 3 = ⟨33/4⟩이에요.","⟨33/4⟩ = ⟨8 1/4⟩ — 파란 뚜껑 3개는 ⟨8 1/4⟩ g이에요."],"variant_rule":{"alt":[{"stem":"파란 뚜껑 1개의 무게가 ⟨1 5/6⟩ g이에요. 파란 뚜껑 4개의 무게는 몇 g인가요?","options":[{"t":"⟨7 1/3⟩","correct":true},{"t":"⟨4 5/6⟩","mis":"M6-1-u1-X10"},{"t":"⟨11/24⟩","mis":"M6-1-u1-X14"},{"t":"⟨7 1/2⟩","mis":"M6-1-u1-X12"}],"explanation":["⟨1 5/6⟩ = ⟨11/6⟩이에요.","⟨11/6⟩ × 4 = ⟨22/3⟩예요.","⟨22/3⟩ = ⟨7 1/3⟩ — 파란 뚜껑 4개는 ⟨7 1/3⟩ g이에요."]},{"stem":"파란 뚜껑 1개의 무게가 ⟨3 2/7⟩ g이에요. 파란 뚜껑 2개의 무게는 몇 g인가요?","options":[{"t":"⟨6 4/7⟩","correct":true},{"t":"⟨6 2/7⟩","mis":"M6-1-u1-X10"},{"t":"⟨1 9/14⟩","mis":"M6-1-u1-X14"},{"t":"⟨3 4/7⟩","mis":"M6-1-u1-X10"}],"explanation":["⟨3 2/7⟩ = ⟨23/7⟩이에요.","⟨23/7⟩ × 2 = ⟨46/7⟩이에요.","⟨46/7⟩ = ⟨6 4/7⟩ — 파란 뚜껑 2개는 ⟨6 4/7⟩ g이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L07_challenge#6','math',6,1,'u1','L07','g6_1_math_u1_L07_challenge','lesson_challenge','M6-1-u1-C7',3,'mc','auto','모은 페트병 뚜껑 ⟨7 1/2⟩ g을 6묶음으로 똑같이 나누면 한 묶음은 몇 g인가요?',ARRAY['M6-1-u1-X10','M6-1-u1-X06']::text[],true,'{"seq":6,"concept":"M6-1-u1-C7","difficulty":3,"kind":"mc","stem":"모은 페트병 뚜껑 ⟨7 1/2⟩ g을 6묶음으로 똑같이 나누면 한 묶음은 몇 g인가요?","options":[{"t":"⟨1 1/4⟩","correct":true},{"t":"⟨7 1/12⟩","mis":"M6-1-u1-X10"},{"t":"⟨1 2/3⟩","mis":"M6-1-u1-X10"},{"t":"45","mis":"M6-1-u1-X06"}],"explanation":["⟨7 1/2⟩ = ⟨15/2⟩예요.","⟨15/2⟩ ÷ 6 = ⟨15/2⟩ × ⟨1/6⟩이에요.","⟨15/2⟩ × ⟨1/6⟩ = ⟨1 1/4⟩ — 한 묶음은 ⟨1 1/4⟩ g이에요."],"variant_rule":{"alt":[{"stem":"모은 페트병 뚜껑 ⟨8 2/3⟩ g을 4묶음으로 똑같이 나누면 한 묶음은 몇 g인가요?","options":[{"t":"⟨2 1/6⟩","correct":true},{"t":"⟨8 1/6⟩","mis":"M6-1-u1-X10"},{"t":"⟨2 2/3⟩","mis":"M6-1-u1-X10"},{"t":"⟨34 2/3⟩","mis":"M6-1-u1-X06"}],"explanation":["⟨8 2/3⟩ = ⟨26/3⟩이에요.","⟨26/3⟩ ÷ 4 = ⟨26/3⟩ × ⟨1/4⟩이에요.","⟨26/3⟩ × ⟨1/4⟩ = ⟨2 1/6⟩ — 한 묶음은 ⟨2 1/6⟩ g이에요."]},{"stem":"모은 페트병 뚜껑 ⟨5 3/5⟩ g을 7묶음으로 똑같이 나누면 한 묶음은 몇 g인가요?","options":[{"t":"⟨4/5⟩","correct":true},{"t":"⟨5 3/35⟩","mis":"M6-1-u1-X10"},{"t":"⟨1 11/35⟩","mis":"M6-1-u1-X10"},{"t":"⟨39 1/5⟩","mis":"M6-1-u1-X06"}],"explanation":["⟨5 3/5⟩ = ⟨28/5⟩이에요.","⟨28/5⟩ ÷ 7 = ⟨28/5⟩ × ⟨1/7⟩이에요.","⟨28/5⟩ × ⟨1/7⟩ = ⟨4/5⟩ — 한 묶음은 ⟨4/5⟩ g이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L07_challenge#7','math',6,1,'u1','L07','g6_1_math_u1_L07_challenge','lesson_challenge','M6-1-u1-C7',3,'ox','auto','파란 뚜껑 2개와 노란 뚜껑 1개가 파란 뚜껑 5개와 무게가 같으면, 노란 뚜껑 1개는 파란 뚜껑 5개와 무게가 같아요.',ARRAY['M6-1-u1-X13']::text[],true,'{"seq":7,"concept":"M6-1-u1-C7","difficulty":3,"kind":"ox","stem":"파란 뚜껑 2개와 노란 뚜껑 1개가 파란 뚜껑 5개와 무게가 같으면, 노란 뚜껑 1개는 파란 뚜껑 5개와 무게가 같아요.","answer":"X","reason_options":[{"t":"양쪽에서 파란 2개씩 덜어 내면 노란 1개 = 파란 3개이므로","correct":true},{"t":"오른쪽 파란 뚜껑의 수가 5개이므로","mis":"M6-1-u1-X13"}],"mis":"M6-1-u1-X13","explanation":["양쪽에서 파란 뚜껑 2개씩 덜어 내요.","노란 1개, 파란 5 − 2 = 3개가 남아요.","노란 뚜껑 1개는 파란 뚜껑 3개와 같아요."],"variant_rule":{"alt":[{"stem":"노란 뚜껑 1개가 ⟨4 1/3⟩ g이고 파란 뚜껑 3개와 같으면 파란 뚜껑 1개는 ⟨1 4/9⟩ g이에요.","answer":"O","reason_options":[{"t":"⟨13/3⟩ × ⟨1/3⟩ = ⟨13/9⟩ = ⟨1 4/9⟩이므로","correct":true},{"t":"4를 3으로 나누면 되므로","mis":"M6-1-u1-X10"}],"explanation":["⟨4 1/3⟩ = ⟨13/3⟩이에요.","⟨13/3⟩ × ⟨1/3⟩ = ⟨13/9⟩이에요.","⟨13/9⟩ = ⟨1 4/9⟩ — 맞아요."]},{"stem":"파란 뚜껑 1개가 ⟨1 3/4⟩ g이면 파란 뚜껑 2개는 ⟨2 3/4⟩ g이에요.","answer":"X","reason_options":[{"t":"⟨7/4⟩ × 2 = ⟨14/4⟩ = ⟨3 1/2⟩이므로","correct":true},{"t":"자연수 부분만 2배 하면 되므로","mis":"M6-1-u1-X10"}],"explanation":["⟨1 3/4⟩ = ⟨7/4⟩이에요.","⟨7/4⟩ × 2 = ⟨14/4⟩예요.","⟨14/4⟩ = ⟨3 1/2⟩ — 분수 부분도 2배 해야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L07_challenge#8','math',6,1,'u1','L07','g6_1_math_u1_L07_challenge','lesson_challenge','M6-1-u1-C7',4,'mc','auto','파란 뚜껑 2개와 노란 뚜껑 1개의 무게가 파란 뚜껑 6개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개의 무게가 ⟨2 2/3⟩ g일 때, 파란 뚜껑 5개의 무게는 몇 g인가요?',ARRAY['M6-1-u1-X13','M6-1-u1-X15']::text[],true,'{"seq":8,"concept":"M6-1-u1-C7","difficulty":4,"kind":"mc","stem":"파란 뚜껑 2개와 노란 뚜껑 1개의 무게가 파란 뚜껑 6개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개의 무게가 ⟨2 2/3⟩ g일 때, 파란 뚜껑 5개의 무게는 몇 g인가요?","options":[{"t":"⟨3 1/3⟩","correct":true},{"t":"⟨2 2/9⟩","mis":"M6-1-u1-X13"},{"t":"⟨2/3⟩","mis":"M6-1-u1-X15"},{"t":"⟨13 1/3⟩","mis":"M6-1-u1-X13"}],"explanation":["양쪽에서 파란 2개씩 덜어 내면 노란 1개 = 파란 4개예요.","파란 1개는 ⟨8/3⟩ × ⟨1/4⟩ = ⟨2/3⟩ g이에요.","파란 5개는 ⟨2/3⟩ × 5 = ⟨3 1/3⟩ g이에요."],"variant_rule":{"alt":[{"stem":"파란 뚜껑 1개와 노란 뚜껑 1개의 무게가 파란 뚜껑 4개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개의 무게가 ⟨4 1/2⟩ g일 때, 파란 뚜껑 2개의 무게는 몇 g인가요?","options":[{"t":"3","correct":true},{"t":"⟨2 1/4⟩","mis":"M6-1-u1-X13"},{"t":"⟨1 1/2⟩","mis":"M6-1-u1-X15"},{"t":"9","mis":"M6-1-u1-X13"}],"explanation":["양쪽에서 파란 1개씩 덜어 내면 노란 1개 = 파란 3개예요.","파란 1개는 ⟨9/2⟩ × ⟨1/3⟩ = ⟨1 1/2⟩ g이에요.","파란 2개는 ⟨1 1/2⟩ × 2 = 3 g이에요."]},{"stem":"파란 뚜껑 3개와 노란 뚜껑 1개의 무게가 파란 뚜껑 7개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개의 무게가 ⟨3 1/5⟩ g일 때, 파란 뚜껑 3개의 무게는 몇 g인가요?","options":[{"t":"⟨2 2/5⟩","correct":true},{"t":"⟨1 13/35⟩","mis":"M6-1-u1-X13"},{"t":"⟨4/5⟩","mis":"M6-1-u1-X15"},{"t":"⟨9 3/5⟩","mis":"M6-1-u1-X13"}],"explanation":["양쪽에서 파란 3개씩 덜어 내면 노란 1개 = 파란 4개예요.","파란 1개는 ⟨16/5⟩ × ⟨1/4⟩ = ⟨4/5⟩ g이에요.","파란 3개는 ⟨4/5⟩ × 3 = ⟨2 2/5⟩ g이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L07_challenge#9','math',6,1,'u1','L07','g6_1_math_u1_L07_challenge','lesson_challenge','M6-1-u1-C7',4,'mc','auto','빨간 뚜껑 1개는 노란 뚜껑 2개와, 노란 뚜껑 1개는 파란 뚜껑 3개와 무게가 같아요. 빨간 뚜껑 1개가 ⟨4 2/3⟩ g이면 파란 뚜껑 1개는 몇 g인가요?',ARRAY['M6-1-u1-X15','M6-1-u1-X09']::text[],true,'{"seq":9,"concept":"M6-1-u1-C7","difficulty":4,"kind":"mc","stem":"빨간 뚜껑 1개는 노란 뚜껑 2개와, 노란 뚜껑 1개는 파란 뚜껑 3개와 무게가 같아요. 빨간 뚜껑 1개가 ⟨4 2/3⟩ g이면 파란 뚜껑 1개는 몇 g인가요?","options":[{"t":"⟨7/9⟩","correct":true},{"t":"⟨2 1/3⟩","mis":"M6-1-u1-X15"},{"t":"⟨1 5/9⟩","mis":"M6-1-u1-X15"},{"t":"⟨14/15⟩","mis":"M6-1-u1-X09"}],"explanation":["빨간 1개 = 노란 2개 = 파란 2 × 3 = 6개예요.","⟨4 2/3⟩ = ⟨14/3⟩예요.","⟨14/3⟩ × ⟨1/6⟩ = ⟨7/9⟩ — 파란 뚜껑 1개는 ⟨7/9⟩ g이에요."],"variant_rule":{"alt":[{"stem":"빨간 뚜껑 1개는 노란 뚜껑 3개와, 노란 뚜껑 1개는 파란 뚜껑 2개와 무게가 같아요. 빨간 뚜껑 1개가 ⟨5 1/4⟩ g이면 파란 뚜껑 1개는 몇 g인가요?","options":[{"t":"⟨7/8⟩","correct":true},{"t":"⟨1 3/4⟩","mis":"M6-1-u1-X15"},{"t":"⟨2 5/8⟩","mis":"M6-1-u1-X15"},{"t":"⟨1 1/20⟩","mis":"M6-1-u1-X09"}],"explanation":["빨간 1개 = 노란 3개 = 파란 3 × 2 = 6개예요.","⟨5 1/4⟩ = ⟨21/4⟩이에요.","⟨21/4⟩ × ⟨1/6⟩ = ⟨7/8⟩ — 파란 뚜껑 1개는 ⟨7/8⟩ g이에요."]},{"stem":"빨간 뚜껑 1개는 노란 뚜껑 2개와, 노란 뚜껑 1개는 파란 뚜껑 4개와 무게가 같아요. 빨간 뚜껑 1개가 ⟨6 2/5⟩ g이면 파란 뚜껑 1개는 몇 g인가요?","options":[{"t":"⟨4/5⟩","correct":true},{"t":"⟨3 1/5⟩","mis":"M6-1-u1-X15"},{"t":"⟨1 3/5⟩","mis":"M6-1-u1-X15"},{"t":"⟨1 1/15⟩","mis":"M6-1-u1-X09"}],"explanation":["빨간 1개 = 노란 2개 = 파란 2 × 4 = 8개예요.","⟨6 2/5⟩ = ⟨32/5⟩예요.","⟨32/5⟩ × ⟨1/8⟩ = ⟨4/5⟩ — 파란 뚜껑 1개는 ⟨4/5⟩ g이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L07_challenge#10','math',6,1,'u1','L07','g6_1_math_u1_L07_challenge','lesson_challenge','M6-1-u1-C7',4,'essay','teacher','저울에서 파란 뚜껑 2개와 노란 뚜껑 1개의 무게가 파란 뚜껑 5개의 무게와 같아요. 노란 뚜껑 1개가 ⟨4 1/3⟩ g일 때 파란 뚜껑 1개의 무게를 구하는 과정을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M6-1-u1-C7","difficulty":4,"kind":"essay","stem":"저울에서 파란 뚜껑 2개와 노란 뚜껑 1개의 무게가 파란 뚜껑 5개의 무게와 같아요. 노란 뚜껑 1개가 ⟨4 1/3⟩ g일 때 파란 뚜껑 1개의 무게를 구하는 과정을 쓰세요.","answer_guide":{"answer":"예: 저울 양쪽에서 파란 뚜껑 2개씩을 덜어 내도 수평이므로 노란 뚜껑 1개는 파란 뚜껑 3개와 무게가 같다. 그래서 파란 뚜껑 1개는 ⟨4 1/3⟩ ÷ 3이다. ⟨4 1/3⟩ = ⟨13/3⟩이므로 ⟨13/3⟩ × ⟨1/3⟩ = ⟨13/9⟩ = ⟨1 4/9⟩ g이다.","scoring_points":["양쪽에서 같은 것을 덜어 내 노란 1개 = 파란 3개를 찾았는가","⟨4 1/3⟩ ÷ 3을 세우고 가분수로 고쳤는가","⟨1 4/9⟩ g을 구했는가"]},"explanation":["양쪽에서 파란 2개씩 덜어 내면 노란 1개 = 파란 3개예요.","⟨4 1/3⟩ = ⟨13/3⟩이에요.","⟨13/3⟩ × ⟨1/3⟩ = ⟨1 4/9⟩ g이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_a#1','math',6,1,'u1','','g6_1_math_u1_review_a','unit_review','M6-1-u1-C2',1,'mc','auto','시루떡 3개를 4명이 똑같이 나누어 먹으려고 해요. 한 명이 먹는 시루떡은 몇 개인지 분수로 나타내면 얼마인가요?',ARRAY['M6-1-u1-X01','M6-1-u1-X09']::text[],true,'{"seq":1,"concept":"M6-1-u1-C2","difficulty":1,"kind":"mc","stem":"시루떡 3개를 4명이 똑같이 나누어 먹으려고 해요. 한 명이 먹는 시루떡은 몇 개인지 분수로 나타내면 얼마인가요?","options":[{"t":"⟨3/4⟩","correct":true},{"t":"⟨1 1/3⟩","mis":"M6-1-u1-X01"},{"t":"⟨1/4⟩","mis":"M6-1-u1-X01"},{"t":"⟨3/7⟩","mis":"M6-1-u1-X09"}],"explanation":["시루떡 3개를 4로 똑같이 나누는 것은 3 ÷ 4예요.","나누어지는 수 3은 분자, 나누는 수 4는 분모가 돼요.","3 ÷ 4 = ⟨3/4⟩ — ⟨3/4⟩개예요."],"variant_rule":{"alt":[{"stem":"과자 반죽 2개를 5명이 똑같이 나누어 가지려고 해요. 한 명이 가지는 과자 반죽은 몇 개인지 분수로 나타내면 얼마인가요?","options":[{"t":"⟨2/5⟩","correct":true},{"t":"⟨2 1/2⟩","mis":"M6-1-u1-X01"},{"t":"⟨1/5⟩","mis":"M6-1-u1-X01"},{"t":"⟨2/7⟩","mis":"M6-1-u1-X09"}],"explanation":["과자 반죽 2개를 5로 똑같이 나누는 것은 2 ÷ 5예요.","나누어지는 수 2는 분자, 나누는 수 5는 분모가 돼요.","2 ÷ 5 = ⟨2/5⟩ — ⟨2/5⟩개예요."]},{"stem":"주스 3 L를 7명이 똑같이 나누어 마시려고 해요. 한 명이 마시는 주스는 몇 L인지 분수로 나타내면 얼마인가요?","options":[{"t":"⟨3/7⟩","correct":true},{"t":"⟨2 1/3⟩","mis":"M6-1-u1-X01"},{"t":"⟨1/7⟩","mis":"M6-1-u1-X01"},{"t":"⟨3/10⟩","mis":"M6-1-u1-X09"}],"explanation":["주스 3 L를 7로 똑같이 나누는 것은 3 ÷ 7이에요.","나누어지는 수 3은 분자, 나누는 수 7은 분모가 돼요.","3 ÷ 7 = ⟨3/7⟩ — ⟨3/7⟩ L예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_a#2','math',6,1,'u1','','g6_1_math_u1_review_a','unit_review','M6-1-u1-C2',1,'sa','auto','4 ÷ 7의 몫을 분수로 나타낼 때 분자에 오는 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-1-u1-C2","difficulty":1,"kind":"sa","stem":"4 ÷ 7의 몫을 분수로 나타낼 때 분자에 오는 수는 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["(자연수)÷(자연수)의 몫은 분수로 나타낼 수 있어요.","나누어지는 수 4는 분자, 나누는 수 7은 분모예요.","4 ÷ 7 = ⟨4/7⟩니 분자는 4예요."],"mis":"M6-1-u1-X01","variant_rule":{"alt":[{"stem":"5 ÷ 9의 몫을 분수로 나타낼 때 분모에 오는 수는 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["(자연수)÷(자연수)의 몫은 분수로 나타낼 수 있어요.","나누어지는 수 5는 분자, 나누는 수 9는 분모예요.","5 ÷ 9 = ⟨5/9⟩니 분모는 9예요."]},{"stem":"2 ÷ 11의 몫을 분수로 나타낼 때 분자에 오는 수는 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["(자연수)÷(자연수)의 몫은 분수로 나타낼 수 있어요.","나누어지는 수 2는 분자, 나누는 수 11은 분모예요.","2 ÷ 11 = ⟨2/11⟩니 분자는 2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_a#3','math',6,1,'u1','','g6_1_math_u1_review_a','unit_review','M6-1-u1-C3',1,'mc','auto','⟨1 3/4⟩을 가분수로 나타내면 어느 것인가요?',ARRAY['M6-1-u1-X01','M6-1-u1-X05']::text[],true,'{"seq":3,"concept":"M6-1-u1-C3","difficulty":1,"kind":"mc","stem":"⟨1 3/4⟩을 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨7/4⟩","correct":true},{"t":"⟨4/7⟩","mis":"M6-1-u1-X01"},{"t":"⟨4/4⟩","mis":"M6-1-u1-X05"},{"t":"⟨3/4⟩","mis":"M6-1-u1-X05"}],"explanation":["자연수 1은 ⟨4/4⟩예요 — 1 × 4 = 4.","여기에 ⟨3/4⟩을 더하면 분자는 4 + 3 = 7이에요.","⟨1 3/4⟩ = ⟨7/4⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨2 2/5⟩를 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨12/5⟩","correct":true},{"t":"⟨5/12⟩","mis":"M6-1-u1-X01"},{"t":"⟨4/5⟩","mis":"M6-1-u1-X05"},{"t":"⟨22/5⟩","mis":"M6-1-u1-X05"}],"explanation":["자연수 2는 ⟨10/5⟩이에요 — 2 × 5 = 10.","여기에 ⟨2/5⟩를 더하면 분자는 10 + 2 = 12예요.","⟨2 2/5⟩ = ⟨12/5⟩예요."]},{"stem":"⟨3 1/3⟩을 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨10/3⟩","correct":true},{"t":"⟨3/10⟩","mis":"M6-1-u1-X01"},{"t":"⟨4/3⟩","mis":"M6-1-u1-X05"},{"t":"⟨3/3⟩","mis":"M6-1-u1-X05"}],"explanation":["자연수 3은 ⟨9/3⟩예요 — 3 × 3 = 9.","여기에 ⟨1/3⟩을 더하면 분자는 9 + 1 = 10이에요.","⟨3 1/3⟩ = ⟨10/3⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_a#4','math',6,1,'u1','','g6_1_math_u1_review_a','unit_review','M6-1-u1-C3',1,'sa','auto','15 ÷ 4의 몫을 대분수로 나타낼 때 자연수 부분에 오는 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M6-1-u1-C3","difficulty":1,"kind":"sa","stem":"15 ÷ 4의 몫을 대분수로 나타낼 때 자연수 부분에 오는 수는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["15 ÷ 4는 몫 3, 나머지 3이에요.","남은 3도 4로 나누면 ⟨3/4⟩ — 몫은 ⟨3 3/4⟩이에요.","그래서 자연수 부분은 3이에요."],"mis":"M6-1-u1-X04","variant_rule":{"alt":[{"stem":"14 ÷ 3의 몫을 대분수로 나타낼 때 분자에 오는 수는 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["14 ÷ 3은 몫 4, 나머지 2예요.","남은 2도 3으로 나누면 ⟨2/3⟩ — 몫은 ⟨4 2/3⟩예요.","그래서 분자는 2예요."]},{"stem":"19 ÷ 5의 몫을 대분수로 나타낼 때 자연수 부분에 오는 수는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["19 ÷ 5는 몫 3, 나머지 4예요.","남은 4도 5로 나누면 ⟨4/5⟩ — 몫은 ⟨3 4/5⟩예요.","그래서 자연수 부분은 3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_a#5','math',6,1,'u1','','g6_1_math_u1_review_a','unit_review','M6-1-u1-C4',1,'mc','auto','6 ÷ 5를 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M6-1-u1-X06','M6-1-u1-X07']::text[],true,'{"seq":5,"concept":"M6-1-u1-C4","difficulty":1,"kind":"mc","stem":"6 ÷ 5를 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"6 × ⟨1/5⟩","correct":true},{"t":"6 × 5","mis":"M6-1-u1-X06"},{"t":"5 × ⟨1/6⟩","mis":"M6-1-u1-X07"},{"t":"⟨1/6⟩ × ⟨1/5⟩","mis":"M6-1-u1-X07"}],"explanation":["÷ 5는 5로 똑같이 나눈 것 중의 1이에요.","× ⟨1/5⟩도 5로 똑같이 나눈 것 중의 1이에요.","그래서 6 ÷ 5 = 6 × ⟨1/5⟩ = ⟨1 1/5⟩이에요."],"variant_rule":{"alt":[{"stem":"2 ÷ 9를 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"2 × ⟨1/9⟩","correct":true},{"t":"2 × 9","mis":"M6-1-u1-X06"},{"t":"9 × ⟨1/2⟩","mis":"M6-1-u1-X07"},{"t":"⟨1/2⟩ × ⟨1/9⟩","mis":"M6-1-u1-X07"}],"explanation":["÷ 9는 9로 똑같이 나눈 것 중의 1이에요.","× ⟨1/9⟩도 9로 똑같이 나눈 것 중의 1이에요.","그래서 2 ÷ 9 = 2 × ⟨1/9⟩ = ⟨2/9⟩예요."]},{"stem":"8 ÷ 3을 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"8 × ⟨1/3⟩","correct":true},{"t":"8 × 3","mis":"M6-1-u1-X06"},{"t":"3 × ⟨1/8⟩","mis":"M6-1-u1-X07"},{"t":"⟨1/8⟩ × ⟨1/3⟩","mis":"M6-1-u1-X07"}],"explanation":["÷ 3은 3으로 똑같이 나눈 것 중의 1이에요.","× ⟨1/3⟩도 3으로 똑같이 나눈 것 중의 1이에요.","그래서 8 ÷ 3 = 8 × ⟨1/3⟩ = ⟨2 2/3⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_a#6','math',6,1,'u1','','g6_1_math_u1_review_a','unit_review','M6-1-u1-C5',1,'mc','auto','⟨6/11⟩ ÷ 3을 계산하면 얼마인가요?',ARRAY['M6-1-u1-X06','M6-1-u1-X09','M6-1-u1-X07']::text[],true,'{"seq":6,"concept":"M6-1-u1-C5","difficulty":1,"kind":"mc","stem":"⟨6/11⟩ ÷ 3을 계산하면 얼마인가요?","options":[{"t":"⟨2/11⟩","correct":true},{"t":"⟨1 7/11⟩","mis":"M6-1-u1-X06"},{"t":"⟨3/7⟩","mis":"M6-1-u1-X09"},{"t":"⟨11/18⟩","mis":"M6-1-u1-X07"}],"explanation":["⟨6/11⟩은 ⟨1/11⟩이 6개예요.","분자 6을 3으로 나누면 6 ÷ 3 = 2 — ⟨1/11⟩이 2개예요.","그래서 ⟨6/11⟩ ÷ 3 = ⟨2/11⟩예요."],"variant_rule":{"alt":[{"stem":"⟨4/9⟩ ÷ 2를 계산하면 얼마인가요?","options":[{"t":"⟨2/9⟩","correct":true},{"t":"⟨8/9⟩","mis":"M6-1-u1-X06"},{"t":"⟨4/11⟩","mis":"M6-1-u1-X09"},{"t":"⟨1 1/8⟩","mis":"M6-1-u1-X07"}],"explanation":["⟨4/9⟩는 ⟨1/9⟩이 4개예요.","분자 4를 2로 나누면 4 ÷ 2 = 2 — ⟨1/9⟩이 2개예요.","그래서 ⟨4/9⟩ ÷ 2 = ⟨2/9⟩예요."]},{"stem":"⟨10/13⟩ ÷ 5를 계산하면 얼마인가요?","options":[{"t":"⟨2/13⟩","correct":true},{"t":"⟨3 11/13⟩","mis":"M6-1-u1-X06"},{"t":"⟨5/9⟩","mis":"M6-1-u1-X09"},{"t":"⟨13/50⟩","mis":"M6-1-u1-X07"}],"explanation":["⟨10/13⟩은 ⟨1/13⟩이 10개예요.","분자 10을 5로 나누면 10 ÷ 5 = 2 — ⟨1/13⟩이 2개예요.","그래서 ⟨10/13⟩ ÷ 5 = ⟨2/13⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_a#7','math',6,1,'u1','','g6_1_math_u1_review_a','unit_review','M6-1-u1-C6',1,'mc','auto','⟨1 5/6⟩를 가분수로 나타내면 어느 것인가요?',ARRAY['M6-1-u1-X01','M6-1-u1-X05']::text[],true,'{"seq":7,"concept":"M6-1-u1-C6","difficulty":1,"kind":"mc","stem":"⟨1 5/6⟩를 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨11/6⟩","correct":true},{"t":"⟨6/11⟩","mis":"M6-1-u1-X01"},{"t":"⟨6/6⟩","mis":"M6-1-u1-X05"},{"t":"⟨5/6⟩","mis":"M6-1-u1-X05"}],"explanation":["자연수 1은 ⟨6/6⟩이에요 — 1 × 6 = 6.","여기에 ⟨5/6⟩를 더하면 분자는 6 + 5 = 11이에요.","⟨1 5/6⟩ = ⟨11/6⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨3 2/7⟩를 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨23/7⟩","correct":true},{"t":"⟨7/23⟩","mis":"M6-1-u1-X01"},{"t":"⟨5/7⟩","mis":"M6-1-u1-X05"},{"t":"⟨6/7⟩","mis":"M6-1-u1-X05"}],"explanation":["자연수 3은 ⟨21/7⟩이에요 — 3 × 7 = 21.","여기에 ⟨2/7⟩를 더하면 분자는 21 + 2 = 23이에요.","⟨3 2/7⟩ = ⟨23/7⟩이에요."]},{"stem":"⟨2 4/5⟩를 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨14/5⟩","correct":true},{"t":"⟨5/14⟩","mis":"M6-1-u1-X01"},{"t":"⟨6/5⟩","mis":"M6-1-u1-X05"},{"t":"⟨8/5⟩","mis":"M6-1-u1-X05"}],"explanation":["자연수 2는 ⟨10/5⟩이에요 — 2 × 5 = 10.","여기에 ⟨4/5⟩를 더하면 분자는 10 + 4 = 14예요.","⟨2 4/5⟩ = ⟨14/5⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_a#8','math',6,1,'u1','','g6_1_math_u1_review_a','unit_review','M6-1-u1-C7',1,'mc','auto','저울에서 파란 뚜껑 2개와 노란 뚜껑 1개의 무게가 파란 뚜껑 5개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개는 파란 뚜껑 몇 개와 무게가 같나요?',ARRAY['M6-1-u1-X13']::text[],true,'{"seq":8,"concept":"M6-1-u1-C7","difficulty":1,"kind":"mc","stem":"저울에서 파란 뚜껑 2개와 노란 뚜껑 1개의 무게가 파란 뚜껑 5개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개는 파란 뚜껑 몇 개와 무게가 같나요?","options":[{"t":"3개","correct":true},{"t":"2개","mis":"M6-1-u1-X13"},{"t":"5개","mis":"M6-1-u1-X13"},{"t":"7개","mis":"M6-1-u1-X13"}],"explanation":["양쪽에서 파란 뚜껑 2개씩을 덜어 내도 저울은 수평이에요.","왼쪽엔 노란 뚜껑 1개, 오른쪽엔 파란 뚜껑 5 − 2 = 3개가 남아요.","그래서 노란 뚜껑 1개는 파란 뚜껑 3개와 같아요."],"variant_rule":{"alt":[{"stem":"저울에서 파란 뚜껑 1개와 노란 뚜껑 1개의 무게가 파란 뚜껑 5개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개는 파란 뚜껑 몇 개와 무게가 같나요?","options":[{"t":"4개","correct":true},{"t":"1개","mis":"M6-1-u1-X13"},{"t":"5개","mis":"M6-1-u1-X13"},{"t":"6개","mis":"M6-1-u1-X13"}],"explanation":["양쪽에서 파란 뚜껑 1개씩을 덜어 내도 저울은 수평이에요.","왼쪽엔 노란 뚜껑 1개, 오른쪽엔 파란 뚜껑 5 − 1 = 4개가 남아요.","그래서 노란 뚜껑 1개는 파란 뚜껑 4개와 같아요."]},{"stem":"저울에서 파란 뚜껑 3개와 노란 뚜껑 1개의 무게가 파란 뚜껑 6개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개는 파란 뚜껑 몇 개와 무게가 같나요?","options":[{"t":"3개","correct":true},{"t":"6개","mis":"M6-1-u1-X13"},{"t":"9개","mis":"M6-1-u1-X13"},{"t":"4개","mis":"M6-1-u1-X13"}],"explanation":["양쪽에서 파란 뚜껑 3개씩을 덜어 내도 저울은 수평이에요.","왼쪽엔 노란 뚜껑 1개, 오른쪽엔 파란 뚜껑 6 − 3 = 3개가 남아요.","그래서 노란 뚜껑 1개는 파란 뚜껑 3개와 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_a#9','math',6,1,'u1','','g6_1_math_u1_review_a','unit_review','M6-1-u1-C1',2,'mc','auto','시루떡 2개를 5명이 똑같이 나누어 먹으려고 해요. 한 명이 먹는 시루떡을 구하는 식으로 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u1-X14']::text[],true,'{"seq":9,"concept":"M6-1-u1-C1","difficulty":2,"kind":"mc","stem":"시루떡 2개를 5명이 똑같이 나누어 먹으려고 해요. 한 명이 먹는 시루떡을 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"2 ÷ 5","correct":true},{"t":"5 ÷ 2","mis":"M6-1-u1-X14"},{"t":"2 × 5","mis":"M6-1-u1-X14"},{"t":"2 + 5","mis":"M6-1-u1-X14"}],"explanation":["전체 2개를 5로 똑같이 나누는 거예요.","나누어지는 수 2가 앞, 나누는 수 5가 뒤에 와요.","그래서 식은 2 ÷ 5예요."],"variant_rule":{"alt":[{"stem":"과자 반죽 3개를 7명이 똑같이 나누어 가지려고 해요. 한 명이 가지는 과자 반죽을 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"3 ÷ 7","correct":true},{"t":"7 ÷ 3","mis":"M6-1-u1-X14"},{"t":"3 × 7","mis":"M6-1-u1-X14"},{"t":"3 + 7","mis":"M6-1-u1-X14"}],"explanation":["전체 3개를 7로 똑같이 나누는 거예요.","나누어지는 수 3이 앞, 나누는 수 7이 뒤에 와요.","그래서 식은 3 ÷ 7이에요."]},{"stem":"피자 4판을 9명이 똑같이 나누어 먹으려고 해요. 한 명이 먹는 피자를 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"4 ÷ 9","correct":true},{"t":"9 ÷ 4","mis":"M6-1-u1-X14"},{"t":"4 × 9","mis":"M6-1-u1-X14"},{"t":"4 + 9","mis":"M6-1-u1-X14"}],"explanation":["전체 4판을 9로 똑같이 나누는 거예요.","나누어지는 수 4가 앞, 나누는 수 9가 뒤에 와요.","그래서 식은 4 ÷ 9예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_a#10','math',6,1,'u1','','g6_1_math_u1_review_a','unit_review','M6-1-u1-C3',2,'mc','auto','흰 종이 5장을 3명이 똑같이 나누어 가지려고 해요. 한 명이 가지는 흰 종이를 대분수로 나타내면 몇 장인가요?',ARRAY['M6-1-u1-X01','M6-1-u1-X02','M6-1-u1-X04']::text[],true,'{"seq":10,"concept":"M6-1-u1-C3","difficulty":2,"kind":"mc","stem":"흰 종이 5장을 3명이 똑같이 나누어 가지려고 해요. 한 명이 가지는 흰 종이를 대분수로 나타내면 몇 장인가요?","options":[{"t":"⟨1 2/3⟩","correct":true},{"t":"⟨3/5⟩","mis":"M6-1-u1-X01"},{"t":"⟨2/3⟩","mis":"M6-1-u1-X02"},{"t":"⟨1 2/5⟩","mis":"M6-1-u1-X04"}],"explanation":["먼저 1씩 나누어 주면 2가 남아요 — 5 ÷ 3은 몫 1, 나머지 2예요.","남은 2도 3으로 똑같이 나누면 ⟨2/3⟩씩 더 가져요.","5 ÷ 3 = ⟨1 2/3⟩ — ⟨1 2/3⟩장예요."],"variant_rule":{"alt":[{"stem":"빵 9개를 4명이 똑같이 나누어 먹으려고 해요. 한 명이 먹는 빵을 대분수로 나타내면 몇 개인가요?","options":[{"t":"⟨2 1/4⟩","correct":true},{"t":"⟨4/9⟩","mis":"M6-1-u1-X01"},{"t":"⟨1/4⟩","mis":"M6-1-u1-X02"},{"t":"⟨2 1/9⟩","mis":"M6-1-u1-X04"}],"explanation":["먼저 2씩 나누어 주면 1이 남아요 — 9 ÷ 4는 몫 2, 나머지 1이에요.","남은 1도 4로 똑같이 나누면 ⟨1/4⟩씩 더 가져요.","9 ÷ 4 = ⟨2 1/4⟩ — ⟨2 1/4⟩개예요."]},{"stem":"시루떡 7개를 2명이 똑같이 나누어 먹으려고 해요. 한 명이 먹는 시루떡을 대분수로 나타내면 몇 개인가요?","options":[{"t":"⟨3 1/2⟩","correct":true},{"t":"⟨2/7⟩","mis":"M6-1-u1-X01"},{"t":"⟨1/2⟩","mis":"M6-1-u1-X02"},{"t":"⟨3 1/7⟩","mis":"M6-1-u1-X04"}],"explanation":["먼저 3씩 나누어 주면 1이 남아요 — 7 ÷ 2는 몫 3, 나머지 1이에요.","남은 1도 2로 똑같이 나누면 ⟨1/2⟩씩 더 가져요.","7 ÷ 2 = ⟨3 1/2⟩ — ⟨3 1/2⟩개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_a#11','math',6,1,'u1','','g6_1_math_u1_review_a','unit_review','M6-1-u1-C4',2,'sa','auto','7 ÷ 8 = 7 × ⟨1/□⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":11,"concept":"M6-1-u1-C4","difficulty":2,"kind":"sa","stem":"7 ÷ 8 = 7 × ⟨1/□⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["÷ 8은 8로 나눈 것 중의 1이에요.","그래서 ⟨1/8⟩을 곱하는 것과 같아요.","7 ÷ 8 = 7 × ⟨1/8⟩ — □는 8이에요."],"mis":"M6-1-u1-X07","variant_rule":{"alt":[{"stem":"10 ÷ 3 = 10 × ⟨1/□⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["÷ 3은 3으로 나눈 것 중의 1이에요.","그래서 ⟨1/3⟩을 곱하는 것과 같아요.","10 ÷ 3 = 10 × ⟨1/3⟩ — □는 3이에요."]},{"stem":"4 ÷ 13 = 4 × ⟨1/□⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["÷ 13은 13으로 나눈 것 중의 1이에요.","그래서 ⟨1/13⟩을 곱하는 것과 같아요.","4 ÷ 13 = 4 × ⟨1/13⟩ — □는 13이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_a#12','math',6,1,'u1','','g6_1_math_u1_review_a','unit_review','M6-1-u1-C5',2,'sa','auto','⟨8/9⟩ ÷ 4의 몫은 ⟨1/9⟩이 몇 개인 수인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":12,"concept":"M6-1-u1-C5","difficulty":2,"kind":"sa","stem":"⟨8/9⟩ ÷ 4의 몫은 ⟨1/9⟩이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["⟨8/9⟩은 ⟨1/9⟩이 8개예요.","8개를 4로 똑같이 나누면 8 ÷ 4 = 2개예요.","⟨8/9⟩ ÷ 4 = ⟨2/9⟩ — ⟨1/9⟩이 2개예요."],"mis":"M6-1-u1-X08","variant_rule":{"alt":[{"stem":"⟨10/11⟩ ÷ 2의 몫은 ⟨1/11⟩이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["⟨10/11⟩은 ⟨1/11⟩이 10개예요.","10개를 2로 똑같이 나누면 10 ÷ 2 = 5개예요.","⟨10/11⟩ ÷ 2 = ⟨5/11⟩ — ⟨1/11⟩이 5개예요."]},{"stem":"⟨9/13⟩ ÷ 3의 몫은 ⟨1/13⟩이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["⟨9/13⟩는 ⟨1/13⟩이 9개예요.","9개를 3으로 똑같이 나누면 9 ÷ 3 = 3개예요.","⟨9/13⟩ ÷ 3 = ⟨3/13⟩ — ⟨1/13⟩이 3개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_a#13','math',6,1,'u1','','g6_1_math_u1_review_a','unit_review','M6-1-u1-C5',2,'mc','auto','⟨4/9⟩ ÷ 5를 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M6-1-u1-X06','M6-1-u1-X07']::text[],true,'{"seq":13,"concept":"M6-1-u1-C5","difficulty":2,"kind":"mc","stem":"⟨4/9⟩ ÷ 5를 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨4/9⟩ × ⟨1/5⟩","correct":true},{"t":"⟨4/9⟩ × 5","mis":"M6-1-u1-X06"},{"t":"⟨9/4⟩ × ⟨1/5⟩","mis":"M6-1-u1-X07"},{"t":"5 × ⟨4/9⟩","mis":"M6-1-u1-X06"}],"explanation":["÷ 5는 5로 똑같이 나눈 것 중의 1이에요.","그래서 × ⟨1/5⟩과 같아요.","⟨4/9⟩ ÷ 5 = ⟨4/9⟩ × ⟨1/5⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨7/10⟩ ÷ 2를 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨7/10⟩ × ⟨1/2⟩","correct":true},{"t":"⟨7/10⟩ × 2","mis":"M6-1-u1-X06"},{"t":"⟨10/7⟩ × ⟨1/2⟩","mis":"M6-1-u1-X07"},{"t":"2 × ⟨7/10⟩","mis":"M6-1-u1-X06"}],"explanation":["÷ 2는 2로 똑같이 나눈 것 중의 1이에요.","그래서 × ⟨1/2⟩과 같아요.","⟨7/10⟩ ÷ 2 = ⟨7/10⟩ × ⟨1/2⟩이에요."]},{"stem":"⟨1/6⟩ ÷ 3을 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨1/6⟩ × ⟨1/3⟩","correct":true},{"t":"⟨1/6⟩ × 3","mis":"M6-1-u1-X06"},{"t":"⟨6/1⟩ × ⟨1/3⟩","mis":"M6-1-u1-X07"},{"t":"3 × ⟨1/6⟩","mis":"M6-1-u1-X06"}],"explanation":["÷ 3은 3으로 똑같이 나눈 것 중의 1이에요.","그래서 × ⟨1/3⟩과 같아요.","⟨1/6⟩ ÷ 3 = ⟨1/6⟩ × ⟨1/3⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_a#14','math',6,1,'u1','','g6_1_math_u1_review_a','unit_review','M6-1-u1-C6',2,'mc','auto','⟨1 1/4⟩ ÷ 5를 계산하면 얼마인가요?',ARRAY['M6-1-u1-X10','M6-1-u1-X06']::text[],true,'{"seq":14,"concept":"M6-1-u1-C6","difficulty":2,"kind":"mc","stem":"⟨1 1/4⟩ ÷ 5를 계산하면 얼마인가요?","options":[{"t":"⟨1/4⟩","correct":true},{"t":"⟨1 1/20⟩","mis":"M6-1-u1-X10"},{"t":"⟨9/20⟩","mis":"M6-1-u1-X10"},{"t":"⟨6 1/4⟩","mis":"M6-1-u1-X06"}],"explanation":["⟨1 1/4⟩을 가분수로 고치면 ⟨5/4⟩예요.","⟨5/4⟩ ÷ 5 = ⟨5/4⟩ × ⟨1/5⟩이에요.","⟨5/4⟩ × ⟨1/5⟩ = ⟨1/4⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨2 1/3⟩ ÷ 7을 계산하면 얼마인가요?","options":[{"t":"⟨1/3⟩","correct":true},{"t":"⟨2 1/21⟩","mis":"M6-1-u1-X10"},{"t":"⟨13/21⟩","mis":"M6-1-u1-X10"},{"t":"⟨16 1/3⟩","mis":"M6-1-u1-X06"}],"explanation":["⟨2 1/3⟩을 가분수로 고치면 ⟨7/3⟩이에요.","⟨7/3⟩ ÷ 7 = ⟨7/3⟩ × ⟨1/7⟩이에요.","⟨7/3⟩ × ⟨1/7⟩ = ⟨1/3⟩이에요."]},{"stem":"⟨3 3/5⟩ ÷ 6을 계산하면 얼마인가요?","options":[{"t":"⟨3/5⟩","correct":true},{"t":"⟨3 1/10⟩","mis":"M6-1-u1-X10"},{"t":"⟨1 1/10⟩","mis":"M6-1-u1-X10"},{"t":"⟨21 3/5⟩","mis":"M6-1-u1-X06"}],"explanation":["⟨3 3/5⟩을 가분수로 고치면 ⟨18/5⟩이에요.","⟨18/5⟩ ÷ 6 = ⟨18/5⟩ × ⟨1/6⟩이에요.","⟨18/5⟩ × ⟨1/6⟩ = ⟨3/5⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_a#15','math',6,1,'u1','','g6_1_math_u1_review_a','unit_review','M6-1-u1-C6',2,'sa','auto','⟨2 3/8⟩ ÷ 5를 계산하려고 ⟨2 3/8⟩을 가분수로 고쳤어요. 가분수의 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":15,"concept":"M6-1-u1-C6","difficulty":2,"kind":"sa","stem":"⟨2 3/8⟩ ÷ 5를 계산하려고 ⟨2 3/8⟩을 가분수로 고쳤어요. 가분수의 분자는 얼마인가요? 숫자로 쓰세요.","answer":["19"],"explanation":["대분수는 먼저 가분수로 고쳐요.","2 × 8 + 3 = 19예요.","⟨2 3/8⟩ = ⟨19/8⟩ — 분자는 19예요."],"mis":"M6-1-u1-X05","variant_rule":{"alt":[{"stem":"⟨3 4/5⟩ ÷ 2를 계산하려고 ⟨3 4/5⟩를 가분수로 고쳤어요. 가분수의 분자는 얼마인가요? 숫자로 쓰세요.","answer":["19"],"explanation":["대분수는 먼저 가분수로 고쳐요.","3 × 5 + 4 = 19예요.","⟨3 4/5⟩ = ⟨19/5⟩ — 분자는 19예요."]},{"stem":"⟨1 7/9⟩ ÷ 4를 계산하려고 ⟨1 7/9⟩을 가분수로 고쳤어요. 가분수의 분자는 얼마인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["대분수는 먼저 가분수로 고쳐요.","1 × 9 + 7 = 16이에요.","⟨1 7/9⟩ = ⟨16/9⟩ — 분자는 16이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_a#16','math',6,1,'u1','','g6_1_math_u1_review_a','unit_review','M6-1-u1-C7',2,'mc','auto','파란 뚜껑 2개와 노란 뚜껑 1개의 무게가 파란 뚜껑 5개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개의 무게가 ⟨5 1/4⟩ g일 때, 파란 뚜껑 1개의 무게는 몇 g인가요?',ARRAY['M6-1-u1-X13','M6-1-u1-X06']::text[],true,'{"seq":16,"concept":"M6-1-u1-C7","difficulty":2,"kind":"mc","stem":"파란 뚜껑 2개와 노란 뚜껑 1개의 무게가 파란 뚜껑 5개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개의 무게가 ⟨5 1/4⟩ g일 때, 파란 뚜껑 1개의 무게는 몇 g인가요?","options":[{"t":"⟨1 3/4⟩","correct":true},{"t":"⟨1 1/20⟩","mis":"M6-1-u1-X13"},{"t":"⟨2 5/8⟩","mis":"M6-1-u1-X13"},{"t":"⟨15 3/4⟩","mis":"M6-1-u1-X06"}],"explanation":["양쪽에서 파란 2개씩 덜어 내면 노란 1개 = 파란 3개예요.","⟨5 1/4⟩ = ⟨21/4⟩이에요.","⟨21/4⟩ × ⟨1/3⟩ = ⟨1 3/4⟩ — 파란 뚜껑 1개는 ⟨1 3/4⟩ g이에요."],"variant_rule":{"alt":[{"stem":"파란 뚜껑 1개와 노란 뚜껑 1개의 무게가 파란 뚜껑 3개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개의 무게가 ⟨2 2/3⟩ g일 때, 파란 뚜껑 1개의 무게는 몇 g인가요?","options":[{"t":"⟨1 1/3⟩","correct":true},{"t":"⟨8/9⟩","mis":"M6-1-u1-X13"},{"t":"⟨2 2/3⟩","mis":"M6-1-u1-X13"},{"t":"⟨5 1/3⟩","mis":"M6-1-u1-X06"}],"explanation":["양쪽에서 파란 1개씩 덜어 내면 노란 1개 = 파란 2개예요.","⟨2 2/3⟩ = ⟨8/3⟩이에요.","⟨8/3⟩ × ⟨1/2⟩ = ⟨1 1/3⟩ — 파란 뚜껑 1개는 ⟨1 1/3⟩ g이에요."]},{"stem":"파란 뚜껑 3개와 노란 뚜껑 1개의 무게가 파란 뚜껑 7개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개의 무게가 ⟨6 2/3⟩ g일 때, 파란 뚜껑 1개의 무게는 몇 g인가요?","options":[{"t":"⟨1 2/3⟩","correct":true},{"t":"⟨20/21⟩","mis":"M6-1-u1-X13"},{"t":"⟨2 2/9⟩","mis":"M6-1-u1-X13"},{"t":"⟨26 2/3⟩","mis":"M6-1-u1-X06"}],"explanation":["양쪽에서 파란 3개씩 덜어 내면 노란 1개 = 파란 4개예요.","⟨6 2/3⟩ = ⟨20/3⟩이에요.","⟨20/3⟩ × ⟨1/4⟩ = ⟨1 2/3⟩ — 파란 뚜껑 1개는 ⟨1 2/3⟩ g이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_a#17','math',6,1,'u1','','g6_1_math_u1_review_a','unit_review','M6-1-u1-C2',3,'mc','auto','가 모둠은 시루떡 2개를 5명이, 나 모둠은 시루떡 3개를 7명이 똑같이 나누었어요. 한 명이 가지는 시루떡이 더 많은 모둠은 어디인가요?',ARRAY['M6-1-u1-X11','M6-1-u1-X03']::text[],true,'{"seq":17,"concept":"M6-1-u1-C2","difficulty":3,"kind":"mc","stem":"가 모둠은 시루떡 2개를 5명이, 나 모둠은 시루떡 3개를 7명이 똑같이 나누었어요. 한 명이 가지는 시루떡이 더 많은 모둠은 어디인가요?","options":[{"t":"나 모둠","correct":true},{"t":"가 모둠","mis":"M6-1-u1-X11"},{"t":"두 모둠이 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X03"}],"explanation":["가 모둠 한 명 몫은 2 ÷ 5 = ⟨2/5⟩, 나 모둠은 3 ÷ 7 = ⟨3/7⟩이에요.","35로 통분하면 ⟨2/5⟩ = ⟨14/35⟩, ⟨3/7⟩ = ⟨15/35⟩예요.","⟨2/5⟩ < ⟨3/7⟩이라 나 모둠이 더 많아요."],"variant_rule":{"alt":[{"stem":"가 모둠은 주스 4 L를 9명이, 나 모둠은 주스 3 L를 8명이 똑같이 나누었어요. 한 명이 가지는 주스가 더 많은 모둠은 어디인가요?","options":[{"t":"가 모둠","correct":true},{"t":"나 모둠","mis":"M6-1-u1-X11"},{"t":"두 모둠이 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X03"}],"explanation":["가 모둠 한 명 몫은 4 ÷ 9 = ⟨4/9⟩, 나 모둠은 3 ÷ 8 = ⟨3/8⟩이에요.","72로 통분하면 ⟨4/9⟩ = ⟨32/72⟩, ⟨3/8⟩ = ⟨27/72⟩이에요.","⟨4/9⟩ > ⟨3/8⟩이라 가 모둠이 더 많아요."]},{"stem":"가 모둠은 빵 5개를 7명이, 나 모둠은 빵 3개를 4명이 똑같이 나누었어요. 한 명이 가지는 빵이 더 많은 모둠은 어디인가요?","options":[{"t":"나 모둠","correct":true},{"t":"가 모둠","mis":"M6-1-u1-X11"},{"t":"두 모둠이 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X03"}],"explanation":["가 모둠 한 명 몫은 5 ÷ 7 = ⟨5/7⟩, 나 모둠은 3 ÷ 4 = ⟨3/4⟩이에요.","28로 통분하면 ⟨5/7⟩ = ⟨20/28⟩, ⟨3/4⟩ = ⟨21/28⟩이에요.","⟨5/7⟩ < ⟨3/4⟩이라 나 모둠이 더 많아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_a#18','math',6,1,'u1','','g6_1_math_u1_review_a','unit_review','M6-1-u1-C3',3,'sa','auto','쌀 19 kg을 4봉지에 똑같이 나누어 담으려고 해요. 한 봉지에 담는 쌀을 대분수로 나타낼 때, 자연수 부분과 분자의 합은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":18,"concept":"M6-1-u1-C3","difficulty":3,"kind":"sa","stem":"쌀 19 kg을 4봉지에 똑같이 나누어 담으려고 해요. 한 봉지에 담는 쌀을 대분수로 나타낼 때, 자연수 부분과 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["19 ÷ 4는 몫 4, 나머지 3이에요.","남은 3도 나누면 19 ÷ 4 = ⟨4 3/4⟩이에요.","자연수 부분과 분자의 합은 4 + 3 = 7이에요."],"mis":"M6-1-u1-X15","variant_rule":{"alt":[{"stem":"끈 17 m를 6도막으로 똑같이 나누어 자르려고 해요. 한 도막의 길이를 대분수로 나타낼 때, 자연수 부분과 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["17 ÷ 6은 몫 2, 나머지 5예요.","남은 5도 나누면 17 ÷ 6 = ⟨2 5/6⟩예요.","자연수 부분과 분자의 합은 2 + 5 = 7이에요."]},{"stem":"색 모래 25 kg을 7모둠이 똑같이 나누어 가지려고 해요. 한 모둠이 가지는 색 모래를 대분수로 나타낼 때, 자연수 부분과 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["25 ÷ 7은 몫 3, 나머지 4예요.","남은 4도 나누면 25 ÷ 7 = ⟨3 4/7⟩예요.","자연수 부분과 분자의 합은 3 + 4 = 7이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_a#19','math',6,1,'u1','','g6_1_math_u1_review_a','unit_review','M6-1-u1-C4',3,'mc','auto','끈 9 m를 4도막으로 나눈 한 도막과 끈 7 m를 3도막으로 나눈 한 도막 가운데 더 긴 것은 어느 것인가요?',ARRAY['M6-1-u1-X11','M6-1-u1-X03']::text[],true,'{"seq":19,"concept":"M6-1-u1-C4","difficulty":3,"kind":"mc","stem":"끈 9 m를 4도막으로 나눈 한 도막과 끈 7 m를 3도막으로 나눈 한 도막 가운데 더 긴 것은 어느 것인가요?","options":[{"t":"끈 7 m를 3도막으로 나눈 한 도막","correct":true},{"t":"끈 9 m를 4도막으로 나눈 한 도막","mis":"M6-1-u1-X11"},{"t":"두 도막의 길이가 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X03"}],"explanation":["9 ÷ 4 = 9 × ⟨1/4⟩ = ⟨2 1/4⟩, 7 ÷ 3 = 7 × ⟨1/3⟩ = ⟨2 1/3⟩이에요.","12로 통분하면 ⟨2 1/4⟩ = ⟨27/12⟩, ⟨2 1/3⟩ = ⟨28/12⟩이에요.","그래서 더 긴 것은 끈 7 m를 3도막으로 나눈 한 도막이에요."],"variant_rule":{"alt":[{"stem":"끈 6 m를 5도막으로 나눈 한 도막과 끈 5 m를 4도막으로 나눈 한 도막 가운데 더 긴 것은 어느 것인가요?","options":[{"t":"끈 5 m를 4도막으로 나눈 한 도막","correct":true},{"t":"끈 6 m를 5도막으로 나눈 한 도막","mis":"M6-1-u1-X11"},{"t":"두 도막의 길이가 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X03"}],"explanation":["6 ÷ 5 = 6 × ⟨1/5⟩ = ⟨1 1/5⟩, 5 ÷ 4 = 5 × ⟨1/4⟩ = ⟨1 1/4⟩이에요.","20으로 통분하면 ⟨1 1/5⟩ = ⟨24/20⟩, ⟨1 1/4⟩ = ⟨25/20⟩예요.","그래서 더 긴 것은 끈 5 m를 4도막으로 나눈 한 도막이에요."]},{"stem":"끈 10 m를 3도막으로 나눈 한 도막과 끈 13 m를 4도막으로 나눈 한 도막 가운데 더 긴 것은 어느 것인가요?","options":[{"t":"끈 10 m를 3도막으로 나눈 한 도막","correct":true},{"t":"끈 13 m를 4도막으로 나눈 한 도막","mis":"M6-1-u1-X11"},{"t":"두 도막의 길이가 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X03"}],"explanation":["10 ÷ 3 = 10 × ⟨1/3⟩ = ⟨3 1/3⟩, 13 ÷ 4 = 13 × ⟨1/4⟩ = ⟨3 1/4⟩이에요.","12로 통분하면 ⟨3 1/3⟩ = ⟨40/12⟩, ⟨3 1/4⟩ = ⟨39/12⟩예요.","그래서 더 긴 것은 끈 10 m를 3도막으로 나눈 한 도막이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_a#20','math',6,1,'u1','','g6_1_math_u1_review_a','unit_review','M6-1-u1-C5',3,'error','auto','⟨4/7⟩ ÷ 3에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u1-X06','M6-1-u1-X15']::text[],true,'{"seq":20,"concept":"M6-1-u1-C5","difficulty":3,"kind":"error","stem":"⟨4/7⟩ ÷ 3에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「⟨4/7⟩ × 3 = ⟨1 5/7⟩로 계산해.」","correct":true,"mis_target":"M6-1-u1-X06"},{"t":"도윤 — 「⟨4/7⟩ × ⟨1/3⟩로 바꾸어 계산하면 돼.」","mis":"M6-1-u1-X15"},{"t":"하린 — 「몫은 ⟨4/7⟩보다 작아.」","mis":"M6-1-u1-X15"}],"explanation":["3으로 나누면 양이 작아져야 해요.","⟨4/7⟩ × 3 = ⟨1 5/7⟩는 오히려 커요.","⟨4/7⟩ ÷ 3 = ⟨4/7⟩ × ⟨1/3⟩ = ⟨4/21⟩ — 수아는 나누는 수를 그대로 곱했어요."],"variant_rule":{"alt":[{"stem":"⟨5/6⟩ ÷ 2에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민준 — 「⟨5/6⟩ × 2 = ⟨1 2/3⟩로 계산해.」","correct":true,"mis_target":"M6-1-u1-X06"},{"t":"서연 — 「⟨5/6⟩ × ⟨1/2⟩로 바꾸어 계산하면 돼.」","mis":"M6-1-u1-X15"},{"t":"지호 — 「몫은 ⟨5/6⟩보다 작아.」","mis":"M6-1-u1-X15"}],"explanation":["2로 나누면 양이 작아져야 해요.","⟨5/6⟩ × 2 = ⟨1 2/3⟩는 오히려 커요.","⟨5/6⟩ ÷ 2 = ⟨5/6⟩ × ⟨1/2⟩ = ⟨5/12⟩ — 민준은 나누는 수를 그대로 곱했어요."]},{"stem":"⟨3/10⟩ ÷ 4에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「⟨3/10⟩ × 4 = ⟨1 1/5⟩로 계산해.」","correct":true,"mis_target":"M6-1-u1-X06"},{"t":"나린 — 「⟨3/10⟩ × ⟨1/4⟩로 바꾸어 계산하면 돼.」","mis":"M6-1-u1-X15"},{"t":"유진 — 「몫은 ⟨3/10⟩보다 작아.」","mis":"M6-1-u1-X15"}],"explanation":["4로 나누면 양이 작아져야 해요.","⟨3/10⟩ × 4 = ⟨1 1/5⟩은 오히려 커요.","⟨3/10⟩ ÷ 4 = ⟨3/10⟩ × ⟨1/4⟩ = ⟨3/40⟩ — 가온은 나누는 수를 그대로 곱했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_a#21','math',6,1,'u1','','g6_1_math_u1_review_a','unit_review','M6-1-u1-C6',3,'mc','auto','넓이가 ⟨4 2/3⟩ m²이고 가로가 3 m인 직사각형이 있어요. 세로는 몇 m인가요?',ARRAY['M6-1-u1-X10','M6-1-u1-X06']::text[],true,'{"seq":21,"concept":"M6-1-u1-C6","difficulty":3,"kind":"mc","stem":"넓이가 ⟨4 2/3⟩ m²이고 가로가 3 m인 직사각형이 있어요. 세로는 몇 m인가요?","options":[{"t":"⟨1 5/9⟩","correct":true},{"t":"⟨4 2/9⟩","mis":"M6-1-u1-X10"},{"t":"2","mis":"M6-1-u1-X10"},{"t":"14","mis":"M6-1-u1-X06"}],"explanation":["(직사각형의 넓이) = (가로) × (세로)이니 세로 = 넓이 ÷ 가로예요.","⟨4 2/3⟩ ÷ 3 = ⟨14/3⟩ × ⟨1/3⟩이에요.","⟨14/3⟩ × ⟨1/3⟩ = ⟨1 5/9⟩ — 세로는 ⟨1 5/9⟩ m예요."],"variant_rule":{"alt":[{"stem":"넓이가 ⟨5 1/4⟩ m²이고 가로가 2 m인 직사각형이 있어요. 세로는 몇 m인가요?","options":[{"t":"⟨2 5/8⟩","correct":true},{"t":"⟨5 1/8⟩","mis":"M6-1-u1-X10"},{"t":"⟨2 3/4⟩","mis":"M6-1-u1-X10"},{"t":"⟨10 1/2⟩","mis":"M6-1-u1-X06"}],"explanation":["(직사각형의 넓이) = (가로) × (세로)이니 세로 = 넓이 ÷ 가로예요.","⟨5 1/4⟩ ÷ 2 = ⟨21/4⟩ × ⟨1/2⟩이에요.","⟨21/4⟩ × ⟨1/2⟩ = ⟨2 5/8⟩ — 세로는 ⟨2 5/8⟩ m예요."]},{"stem":"넓이가 ⟨3 3/5⟩ m²이고 가로가 4 m인 직사각형이 있어요. 세로는 몇 m인가요?","options":[{"t":"⟨9/10⟩","correct":true},{"t":"⟨3 3/20⟩","mis":"M6-1-u1-X10"},{"t":"⟨1 7/20⟩","mis":"M6-1-u1-X10"},{"t":"⟨14 2/5⟩","mis":"M6-1-u1-X06"}],"explanation":["(직사각형의 넓이) = (가로) × (세로)이니 세로 = 넓이 ÷ 가로예요.","⟨3 3/5⟩ ÷ 4 = ⟨18/5⟩ × ⟨1/4⟩이에요.","⟨18/5⟩ × ⟨1/4⟩ = ⟨9/10⟩ — 세로는 ⟨9/10⟩ m예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_a#22','math',6,1,'u1','','g6_1_math_u1_review_a','unit_review','M6-1-u1-C7',3,'sa','auto','조건을 바꾸어 보아요. 노란 뚜껑 1개가 ⟨2 1/3⟩ g이고 파란 뚜껑 7개와 무게가 같아요. 파란 뚜껑 1개의 무게를 기약분수(가분수)로 나타낼 때 분모와 분자의 합은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":22,"concept":"M6-1-u1-C7","difficulty":3,"kind":"sa","stem":"조건을 바꾸어 보아요. 노란 뚜껑 1개가 ⟨2 1/3⟩ g이고 파란 뚜껑 7개와 무게가 같아요. 파란 뚜껑 1개의 무게를 기약분수(가분수)로 나타낼 때 분모와 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["파란 뚜껑 1개 = ⟨2 1/3⟩ ÷ 7이에요.","⟨7/3⟩ ÷ 7 = ⟨7/3⟩ × ⟨1/7⟩ = ⟨1/3⟩이에요.","분모와 분자의 합은 3 + 1 = 4예요."],"mis":"M6-1-u1-X15","variant_rule":{"alt":[{"stem":"조건을 바꾸어 보아요. 노란 뚜껑 1개가 ⟨3 3/4⟩ g이고 파란 뚜껑 5개와 무게가 같아요. 파란 뚜껑 1개의 무게를 기약분수(가분수)로 나타낼 때 분모와 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["파란 뚜껑 1개 = ⟨3 3/4⟩ ÷ 5예요.","⟨15/4⟩ ÷ 5 = ⟨15/4⟩ × ⟨1/5⟩ = ⟨3/4⟩이에요.","분모와 분자의 합은 4 + 3 = 7이에요."]},{"stem":"조건을 바꾸어 보아요. 노란 뚜껑 1개가 ⟨4 4/5⟩ g이고 파란 뚜껑 6개와 무게가 같아요. 파란 뚜껑 1개의 무게를 기약분수(가분수)로 나타낼 때 분모와 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["파란 뚜껑 1개 = ⟨4 4/5⟩ ÷ 6이에요.","⟨24/5⟩ ÷ 6 = ⟨24/5⟩ × ⟨1/6⟩ = ⟨4/5⟩예요.","분모와 분자의 합은 5 + 4 = 9예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_a#23','math',6,1,'u1','','g6_1_math_u1_review_a','unit_review','M6-1-u1-C2',4,'sa','auto','□ ÷ 11의 몫이 1보다 작을 때, □에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":23,"concept":"M6-1-u1-C2","difficulty":4,"kind":"sa","stem":"□ ÷ 11의 몫이 1보다 작을 때, □에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["□ ÷ 11 = ⟨□/11⟩이에요.","몫이 1보다 작으려면 □가 11보다 작아야 해요.","1부터 10까지 10개예요."],"mis":"M6-1-u1-X03","variant_rule":{"alt":[{"stem":"□ ÷ 7의 몫이 3보다 크고 4보다 작을 때, □에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["21 ÷ 7 = 3, 28 ÷ 7 = 4예요.","□는 21보다 크고 28보다 작아야 해요.","22부터 27까지 6개예요."]},{"stem":"⟨9/13⟩ ÷ □의 몫이 ⟨1/13⟩보다 클 때, □에 들어갈 수 있는 가장 큰 자연수는 얼마인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["⟨9/13⟩는 ⟨1/13⟩이 9개예요.","□로 나눈 몫이 ⟨1/13⟩보다 크려면 9개를 □로 나눈 수가 1보다 커야 해요.","□는 9보다 작아야 하니 가장 큰 수는 8이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_a#24','math',6,1,'u1','','g6_1_math_u1_review_a','unit_review','M6-1-u1-C1',4,'essay','teacher','(자연수)÷(자연수)가 나누어떨어지지 않을 때에도 몫을 하나의 수로 나타낼 수 있는 까닭을 7 ÷ 2를 예로 들어 설명해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M6-1-u1-C1","difficulty":4,"kind":"essay","stem":"(자연수)÷(자연수)가 나누어떨어지지 않을 때에도 몫을 하나의 수로 나타낼 수 있는 까닭을 7 ÷ 2를 예로 들어 설명해 보세요.","answer_guide":{"answer":"예: 7 ÷ 2는 몫 3, 나머지 1이지만 남은 1도 2로 똑같이 나눌 수 있다. 남은 1을 나누면 ⟨1/2⟩씩 더 가지므로 한 사람 몫은 ⟨3 1/2⟩이다. 이렇게 남은 것까지 마저 나누면 몫을 분수인 하나의 수 ⟨3 1/2⟩(= ⟨7/2⟩)로 나타낼 수 있다.","scoring_points":["나머지 1도 나눌 수 있다고 썼는가","7 ÷ 2 = ⟨3 1/2⟩(또는 ⟨7/2⟩)을 구했는가","남은 것을 마저 나누면 하나의 수가 된다고 설명했는가"]},"explanation":["7 ÷ 2는 몫 3, 나머지 1이에요.","남은 1을 2로 나누면 ⟨1/2⟩이에요.","7 ÷ 2 = ⟨3 1/2⟩ — 하나의 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_a#25','math',6,1,'u1','','g6_1_math_u1_review_a','unit_review','M6-1-u1-C4',4,'essay','teacher','「÷ 6」을 「× ⟨1/6⟩」로 바꾸어 계산해도 되는 까닭을 쓰고, 4 ÷ 6을 분수의 곱셈으로 계산해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M6-1-u1-C4","difficulty":4,"kind":"essay","stem":"「÷ 6」을 「× ⟨1/6⟩」로 바꾸어 계산해도 되는 까닭을 쓰고, 4 ÷ 6을 분수의 곱셈으로 계산해 보세요.","answer_guide":{"answer":"예: ÷ 6은 6으로 똑같이 나눈 것 중의 1을 구하는 것이고, × ⟨1/6⟩도 전체의 ⟨1/6⟩, 곧 6으로 나눈 것 중의 1을 구하는 것이라 뜻이 같다. 4 ÷ 6 = 4 × ⟨1/6⟩ = ⟨4/6⟩ = ⟨2/3⟩이다.","scoring_points":["÷ 6과 × ⟨1/6⟩이 모두 6으로 나눈 것 중의 1이라고 썼는가","4 × ⟨1/6⟩ = ⟨4/6⟩를 썼는가","약분해 ⟨2/3⟩를 구했는가"]},"explanation":["÷ 6은 6으로 나눈 것 중의 1이에요.","× ⟨1/6⟩도 6으로 나눈 것 중의 1이에요.","4 ÷ 6 = 4 × ⟨1/6⟩ = ⟨2/3⟩예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_b#1','math',6,1,'u1','','g6_1_math_u1_review_b','unit_review','M6-1-u1-C2',1,'mc','auto','과자 반죽 2개를 5명이 똑같이 나누어 가지려고 해요. 한 명이 가지는 과자 반죽은 몇 개인지 분수로 나타내면 얼마인가요?',ARRAY['M6-1-u1-X01','M6-1-u1-X09']::text[],true,'{"seq":1,"concept":"M6-1-u1-C2","difficulty":1,"kind":"mc","stem":"과자 반죽 2개를 5명이 똑같이 나누어 가지려고 해요. 한 명이 가지는 과자 반죽은 몇 개인지 분수로 나타내면 얼마인가요?","options":[{"t":"⟨2/5⟩","correct":true},{"t":"⟨2 1/2⟩","mis":"M6-1-u1-X01"},{"t":"⟨1/5⟩","mis":"M6-1-u1-X01"},{"t":"⟨2/7⟩","mis":"M6-1-u1-X09"}],"explanation":["과자 반죽 2개를 5로 똑같이 나누는 것은 2 ÷ 5예요.","나누어지는 수 2는 분자, 나누는 수 5는 분모가 돼요.","2 ÷ 5 = ⟨2/5⟩ — ⟨2/5⟩개예요."],"variant_rule":{"alt":[{"stem":"주스 3 L를 7명이 똑같이 나누어 마시려고 해요. 한 명이 마시는 주스는 몇 L인지 분수로 나타내면 얼마인가요?","options":[{"t":"⟨3/7⟩","correct":true},{"t":"⟨2 1/3⟩","mis":"M6-1-u1-X01"},{"t":"⟨1/7⟩","mis":"M6-1-u1-X01"},{"t":"⟨3/10⟩","mis":"M6-1-u1-X09"}],"explanation":["주스 3 L를 7로 똑같이 나누는 것은 3 ÷ 7이에요.","나누어지는 수 3은 분자, 나누는 수 7은 분모가 돼요.","3 ÷ 7 = ⟨3/7⟩ — ⟨3/7⟩ L예요."]},{"stem":"식빵 1개를 3명이 똑같이 나누어 먹으려고 해요. 한 명이 먹는 식빵은 몇 개인지 분수로 나타내면 얼마인가요?","options":[{"t":"⟨1/3⟩","correct":true},{"t":"3","mis":"M6-1-u1-X01"},{"t":"⟨1/4⟩","mis":"M6-1-u1-X09"},{"t":"1","mis":"M6-1-u1-X01"}],"explanation":["식빵 1개를 3으로 똑같이 나누는 것은 1 ÷ 3이에요.","나누어지는 수 1은 분자, 나누는 수 3은 분모가 돼요.","1 ÷ 3 = ⟨1/3⟩ — ⟨1/3⟩개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_b#2','math',6,1,'u1','','g6_1_math_u1_review_b','unit_review','M6-1-u1-C2',1,'sa','auto','5 ÷ 9의 몫을 분수로 나타낼 때 분모에 오는 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-1-u1-C2","difficulty":1,"kind":"sa","stem":"5 ÷ 9의 몫을 분수로 나타낼 때 분모에 오는 수는 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["(자연수)÷(자연수)의 몫은 분수로 나타낼 수 있어요.","나누어지는 수 5는 분자, 나누는 수 9는 분모예요.","5 ÷ 9 = ⟨5/9⟩니 분모는 9예요."],"mis":"M6-1-u1-X01","variant_rule":{"alt":[{"stem":"2 ÷ 11의 몫을 분수로 나타낼 때 분자에 오는 수는 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["(자연수)÷(자연수)의 몫은 분수로 나타낼 수 있어요.","나누어지는 수 2는 분자, 나누는 수 11은 분모예요.","2 ÷ 11 = ⟨2/11⟩니 분자는 2예요."]},{"stem":"6 ÷ 13의 몫을 분수로 나타낼 때 분모에 오는 수는 얼마인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["(자연수)÷(자연수)의 몫은 분수로 나타낼 수 있어요.","나누어지는 수 6은 분자, 나누는 수 13은 분모예요.","6 ÷ 13 = ⟨6/13⟩이니 분모는 13이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_b#3','math',6,1,'u1','','g6_1_math_u1_review_b','unit_review','M6-1-u1-C3',1,'mc','auto','⟨2 2/5⟩를 가분수로 나타내면 어느 것인가요?',ARRAY['M6-1-u1-X01','M6-1-u1-X05']::text[],true,'{"seq":3,"concept":"M6-1-u1-C3","difficulty":1,"kind":"mc","stem":"⟨2 2/5⟩를 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨12/5⟩","correct":true},{"t":"⟨5/12⟩","mis":"M6-1-u1-X01"},{"t":"⟨4/5⟩","mis":"M6-1-u1-X05"},{"t":"⟨22/5⟩","mis":"M6-1-u1-X05"}],"explanation":["자연수 2는 ⟨10/5⟩이에요 — 2 × 5 = 10.","여기에 ⟨2/5⟩를 더하면 분자는 10 + 2 = 12예요.","⟨2 2/5⟩ = ⟨12/5⟩예요."],"variant_rule":{"alt":[{"stem":"⟨3 1/3⟩을 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨10/3⟩","correct":true},{"t":"⟨3/10⟩","mis":"M6-1-u1-X01"},{"t":"⟨4/3⟩","mis":"M6-1-u1-X05"},{"t":"⟨3/3⟩","mis":"M6-1-u1-X05"}],"explanation":["자연수 3은 ⟨9/3⟩예요 — 3 × 3 = 9.","여기에 ⟨1/3⟩을 더하면 분자는 9 + 1 = 10이에요.","⟨3 1/3⟩ = ⟨10/3⟩이에요."]},{"stem":"⟨2 5/6⟩를 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨17/6⟩","correct":true},{"t":"⟨6/17⟩","mis":"M6-1-u1-X01"},{"t":"⟨7/6⟩","mis":"M6-1-u1-X05"},{"t":"⟨10/6⟩","mis":"M6-1-u1-X05"}],"explanation":["자연수 2는 ⟨12/6⟩예요 — 2 × 6 = 12.","여기에 ⟨5/6⟩를 더하면 분자는 12 + 5 = 17이에요.","⟨2 5/6⟩ = ⟨17/6⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_b#4','math',6,1,'u1','','g6_1_math_u1_review_b','unit_review','M6-1-u1-C3',1,'sa','auto','14 ÷ 3의 몫을 대분수로 나타낼 때 분자에 오는 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M6-1-u1-C3","difficulty":1,"kind":"sa","stem":"14 ÷ 3의 몫을 대분수로 나타낼 때 분자에 오는 수는 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["14 ÷ 3은 몫 4, 나머지 2예요.","남은 2도 3으로 나누면 ⟨2/3⟩ — 몫은 ⟨4 2/3⟩예요.","그래서 분자는 2예요."],"mis":"M6-1-u1-X04","variant_rule":{"alt":[{"stem":"19 ÷ 5의 몫을 대분수로 나타낼 때 자연수 부분에 오는 수는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["19 ÷ 5는 몫 3, 나머지 4예요.","남은 4도 5로 나누면 ⟨4/5⟩ — 몫은 ⟨3 4/5⟩예요.","그래서 자연수 부분은 3이에요."]},{"stem":"23 ÷ 7의 몫을 대분수로 나타낼 때 분자에 오는 수는 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["23 ÷ 7은 몫 3, 나머지 2예요.","남은 2도 7로 나누면 ⟨2/7⟩ — 몫은 ⟨3 2/7⟩예요.","그래서 분자는 2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_b#5','math',6,1,'u1','','g6_1_math_u1_review_b','unit_review','M6-1-u1-C4',1,'mc','auto','2 ÷ 9를 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M6-1-u1-X06','M6-1-u1-X07']::text[],true,'{"seq":5,"concept":"M6-1-u1-C4","difficulty":1,"kind":"mc","stem":"2 ÷ 9를 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"2 × ⟨1/9⟩","correct":true},{"t":"2 × 9","mis":"M6-1-u1-X06"},{"t":"9 × ⟨1/2⟩","mis":"M6-1-u1-X07"},{"t":"⟨1/2⟩ × ⟨1/9⟩","mis":"M6-1-u1-X07"}],"explanation":["÷ 9는 9로 똑같이 나눈 것 중의 1이에요.","× ⟨1/9⟩도 9로 똑같이 나눈 것 중의 1이에요.","그래서 2 ÷ 9 = 2 × ⟨1/9⟩ = ⟨2/9⟩예요."],"variant_rule":{"alt":[{"stem":"8 ÷ 3을 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"8 × ⟨1/3⟩","correct":true},{"t":"8 × 3","mis":"M6-1-u1-X06"},{"t":"3 × ⟨1/8⟩","mis":"M6-1-u1-X07"},{"t":"⟨1/8⟩ × ⟨1/3⟩","mis":"M6-1-u1-X07"}],"explanation":["÷ 3은 3으로 똑같이 나눈 것 중의 1이에요.","× ⟨1/3⟩도 3으로 똑같이 나눈 것 중의 1이에요.","그래서 8 ÷ 3 = 8 × ⟨1/3⟩ = ⟨2 2/3⟩예요."]},{"stem":"4 ÷ 11을 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"4 × ⟨1/11⟩","correct":true},{"t":"4 × 11","mis":"M6-1-u1-X06"},{"t":"11 × ⟨1/4⟩","mis":"M6-1-u1-X07"},{"t":"⟨1/4⟩ × ⟨1/11⟩","mis":"M6-1-u1-X07"}],"explanation":["÷ 11은 11로 똑같이 나눈 것 중의 1이에요.","× ⟨1/11⟩도 11로 똑같이 나눈 것 중의 1이에요.","그래서 4 ÷ 11 = 4 × ⟨1/11⟩ = ⟨4/11⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_b#6','math',6,1,'u1','','g6_1_math_u1_review_b','unit_review','M6-1-u1-C5',1,'mc','auto','⟨4/9⟩ ÷ 2를 계산하면 얼마인가요?',ARRAY['M6-1-u1-X06','M6-1-u1-X09','M6-1-u1-X07']::text[],true,'{"seq":6,"concept":"M6-1-u1-C5","difficulty":1,"kind":"mc","stem":"⟨4/9⟩ ÷ 2를 계산하면 얼마인가요?","options":[{"t":"⟨2/9⟩","correct":true},{"t":"⟨8/9⟩","mis":"M6-1-u1-X06"},{"t":"⟨4/11⟩","mis":"M6-1-u1-X09"},{"t":"⟨1 1/8⟩","mis":"M6-1-u1-X07"}],"explanation":["⟨4/9⟩는 ⟨1/9⟩이 4개예요.","분자 4를 2로 나누면 4 ÷ 2 = 2 — ⟨1/9⟩이 2개예요.","그래서 ⟨4/9⟩ ÷ 2 = ⟨2/9⟩예요."],"variant_rule":{"alt":[{"stem":"⟨10/13⟩ ÷ 5를 계산하면 얼마인가요?","options":[{"t":"⟨2/13⟩","correct":true},{"t":"⟨3 11/13⟩","mis":"M6-1-u1-X06"},{"t":"⟨5/9⟩","mis":"M6-1-u1-X09"},{"t":"⟨13/50⟩","mis":"M6-1-u1-X07"}],"explanation":["⟨10/13⟩은 ⟨1/13⟩이 10개예요.","분자 10을 5로 나누면 10 ÷ 5 = 2 — ⟨1/13⟩이 2개예요.","그래서 ⟨10/13⟩ ÷ 5 = ⟨2/13⟩예요."]},{"stem":"⟨9/10⟩ ÷ 3을 계산하면 얼마인가요?","options":[{"t":"⟨3/10⟩","correct":true},{"t":"⟨2 7/10⟩","mis":"M6-1-u1-X06"},{"t":"⟨9/13⟩","mis":"M6-1-u1-X09"},{"t":"⟨10/27⟩","mis":"M6-1-u1-X07"}],"explanation":["⟨9/10⟩는 ⟨1/10⟩이 9개예요.","분자 9를 3으로 나누면 9 ÷ 3 = 3 — ⟨1/10⟩이 3개예요.","그래서 ⟨9/10⟩ ÷ 3 = ⟨3/10⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_b#7','math',6,1,'u1','','g6_1_math_u1_review_b','unit_review','M6-1-u1-C6',1,'mc','auto','⟨3 2/7⟩를 가분수로 나타내면 어느 것인가요?',ARRAY['M6-1-u1-X01','M6-1-u1-X05']::text[],true,'{"seq":7,"concept":"M6-1-u1-C6","difficulty":1,"kind":"mc","stem":"⟨3 2/7⟩를 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨23/7⟩","correct":true},{"t":"⟨7/23⟩","mis":"M6-1-u1-X01"},{"t":"⟨5/7⟩","mis":"M6-1-u1-X05"},{"t":"⟨6/7⟩","mis":"M6-1-u1-X05"}],"explanation":["자연수 3은 ⟨21/7⟩이에요 — 3 × 7 = 21.","여기에 ⟨2/7⟩를 더하면 분자는 21 + 2 = 23이에요.","⟨3 2/7⟩ = ⟨23/7⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨2 4/5⟩를 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨14/5⟩","correct":true},{"t":"⟨5/14⟩","mis":"M6-1-u1-X01"},{"t":"⟨6/5⟩","mis":"M6-1-u1-X05"},{"t":"⟨8/5⟩","mis":"M6-1-u1-X05"}],"explanation":["자연수 2는 ⟨10/5⟩이에요 — 2 × 5 = 10.","여기에 ⟨4/5⟩를 더하면 분자는 10 + 4 = 14예요.","⟨2 4/5⟩ = ⟨14/5⟩예요."]},{"stem":"⟨4 1/3⟩을 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨13/3⟩","correct":true},{"t":"⟨3/13⟩","mis":"M6-1-u1-X01"},{"t":"⟨5/3⟩","mis":"M6-1-u1-X05"},{"t":"⟨4/3⟩","mis":"M6-1-u1-X05"}],"explanation":["자연수 4는 ⟨12/3⟩예요 — 4 × 3 = 12.","여기에 ⟨1/3⟩을 더하면 분자는 12 + 1 = 13이에요.","⟨4 1/3⟩ = ⟨13/3⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_b#8','math',6,1,'u1','','g6_1_math_u1_review_b','unit_review','M6-1-u1-C7',1,'mc','auto','저울에서 파란 뚜껑 1개와 노란 뚜껑 1개의 무게가 파란 뚜껑 5개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개는 파란 뚜껑 몇 개와 무게가 같나요?',ARRAY['M6-1-u1-X13']::text[],true,'{"seq":8,"concept":"M6-1-u1-C7","difficulty":1,"kind":"mc","stem":"저울에서 파란 뚜껑 1개와 노란 뚜껑 1개의 무게가 파란 뚜껑 5개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개는 파란 뚜껑 몇 개와 무게가 같나요?","options":[{"t":"4개","correct":true},{"t":"1개","mis":"M6-1-u1-X13"},{"t":"5개","mis":"M6-1-u1-X13"},{"t":"6개","mis":"M6-1-u1-X13"}],"explanation":["양쪽에서 파란 뚜껑 1개씩을 덜어 내도 저울은 수평이에요.","왼쪽엔 노란 뚜껑 1개, 오른쪽엔 파란 뚜껑 5 − 1 = 4개가 남아요.","그래서 노란 뚜껑 1개는 파란 뚜껑 4개와 같아요."],"variant_rule":{"alt":[{"stem":"저울에서 파란 뚜껑 3개와 노란 뚜껑 1개의 무게가 파란 뚜껑 6개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개는 파란 뚜껑 몇 개와 무게가 같나요?","options":[{"t":"3개","correct":true},{"t":"6개","mis":"M6-1-u1-X13"},{"t":"9개","mis":"M6-1-u1-X13"},{"t":"4개","mis":"M6-1-u1-X13"}],"explanation":["양쪽에서 파란 뚜껑 3개씩을 덜어 내도 저울은 수평이에요.","왼쪽엔 노란 뚜껑 1개, 오른쪽엔 파란 뚜껑 6 − 3 = 3개가 남아요.","그래서 노란 뚜껑 1개는 파란 뚜껑 3개와 같아요."]},{"stem":"저울에서 파란 뚜껑 2개와 노란 뚜껑 1개의 무게가 파란 뚜껑 7개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개는 파란 뚜껑 몇 개와 무게가 같나요?","options":[{"t":"5개","correct":true},{"t":"2개","mis":"M6-1-u1-X13"},{"t":"7개","mis":"M6-1-u1-X13"},{"t":"9개","mis":"M6-1-u1-X13"}],"explanation":["양쪽에서 파란 뚜껑 2개씩을 덜어 내도 저울은 수평이에요.","왼쪽엔 노란 뚜껑 1개, 오른쪽엔 파란 뚜껑 7 − 2 = 5개가 남아요.","그래서 노란 뚜껑 1개는 파란 뚜껑 5개와 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_b#9','math',6,1,'u1','','g6_1_math_u1_review_b','unit_review','M6-1-u1-C1',2,'mc','auto','과자 반죽 3개를 7명이 똑같이 나누어 가지려고 해요. 한 명이 가지는 과자 반죽을 구하는 식으로 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u1-X14']::text[],true,'{"seq":9,"concept":"M6-1-u1-C1","difficulty":2,"kind":"mc","stem":"과자 반죽 3개를 7명이 똑같이 나누어 가지려고 해요. 한 명이 가지는 과자 반죽을 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"3 ÷ 7","correct":true},{"t":"7 ÷ 3","mis":"M6-1-u1-X14"},{"t":"3 × 7","mis":"M6-1-u1-X14"},{"t":"3 + 7","mis":"M6-1-u1-X14"}],"explanation":["전체 3개를 7로 똑같이 나누는 거예요.","나누어지는 수 3이 앞, 나누는 수 7이 뒤에 와요.","그래서 식은 3 ÷ 7이에요."],"variant_rule":{"alt":[{"stem":"피자 4판을 9명이 똑같이 나누어 먹으려고 해요. 한 명이 먹는 피자를 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"4 ÷ 9","correct":true},{"t":"9 ÷ 4","mis":"M6-1-u1-X14"},{"t":"4 × 9","mis":"M6-1-u1-X14"},{"t":"4 + 9","mis":"M6-1-u1-X14"}],"explanation":["전체 4판을 9로 똑같이 나누는 거예요.","나누어지는 수 4가 앞, 나누는 수 9가 뒤에 와요.","그래서 식은 4 ÷ 9예요."]},{"stem":"흰 종이 3장을 8명이 똑같이 나누어 가지려고 해요. 한 명이 가지는 흰 종이를 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"3 ÷ 8","correct":true},{"t":"8 ÷ 3","mis":"M6-1-u1-X14"},{"t":"3 × 8","mis":"M6-1-u1-X14"},{"t":"3 + 8","mis":"M6-1-u1-X14"}],"explanation":["전체 3장을 8로 똑같이 나누는 거예요.","나누어지는 수 3이 앞, 나누는 수 8이 뒤에 와요.","그래서 식은 3 ÷ 8이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_b#10','math',6,1,'u1','','g6_1_math_u1_review_b','unit_review','M6-1-u1-C3',2,'mc','auto','빵 9개를 4명이 똑같이 나누어 먹으려고 해요. 한 명이 먹는 빵을 대분수로 나타내면 몇 개인가요?',ARRAY['M6-1-u1-X01','M6-1-u1-X02','M6-1-u1-X04']::text[],true,'{"seq":10,"concept":"M6-1-u1-C3","difficulty":2,"kind":"mc","stem":"빵 9개를 4명이 똑같이 나누어 먹으려고 해요. 한 명이 먹는 빵을 대분수로 나타내면 몇 개인가요?","options":[{"t":"⟨2 1/4⟩","correct":true},{"t":"⟨4/9⟩","mis":"M6-1-u1-X01"},{"t":"⟨1/4⟩","mis":"M6-1-u1-X02"},{"t":"⟨2 1/9⟩","mis":"M6-1-u1-X04"}],"explanation":["먼저 2씩 나누어 주면 1이 남아요 — 9 ÷ 4는 몫 2, 나머지 1이에요.","남은 1도 4로 똑같이 나누면 ⟨1/4⟩씩 더 가져요.","9 ÷ 4 = ⟨2 1/4⟩ — ⟨2 1/4⟩개예요."],"variant_rule":{"alt":[{"stem":"시루떡 7개를 2명이 똑같이 나누어 먹으려고 해요. 한 명이 먹는 시루떡을 대분수로 나타내면 몇 개인가요?","options":[{"t":"⟨3 1/2⟩","correct":true},{"t":"⟨2/7⟩","mis":"M6-1-u1-X01"},{"t":"⟨1/2⟩","mis":"M6-1-u1-X02"},{"t":"⟨3 1/7⟩","mis":"M6-1-u1-X04"}],"explanation":["먼저 3씩 나누어 주면 1이 남아요 — 7 ÷ 2는 몫 3, 나머지 1이에요.","남은 1도 2로 똑같이 나누면 ⟨1/2⟩씩 더 가져요.","7 ÷ 2 = ⟨3 1/2⟩ — ⟨3 1/2⟩개예요."]},{"stem":"피자 8판을 3명이 똑같이 나누어 먹으려고 해요. 한 명이 먹는 피자를 대분수로 나타내면 몇 판인가요?","options":[{"t":"⟨2 2/3⟩","correct":true},{"t":"⟨3/8⟩","mis":"M6-1-u1-X01"},{"t":"⟨2/3⟩","mis":"M6-1-u1-X02"},{"t":"⟨2 1/4⟩","mis":"M6-1-u1-X04"}],"explanation":["먼저 2씩 나누어 주면 2가 남아요 — 8 ÷ 3은 몫 2, 나머지 2예요.","남은 2도 3으로 똑같이 나누면 ⟨2/3⟩씩 더 가져요.","8 ÷ 3 = ⟨2 2/3⟩ — ⟨2 2/3⟩판예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_b#11','math',6,1,'u1','','g6_1_math_u1_review_b','unit_review','M6-1-u1-C4',2,'sa','auto','10 ÷ 3 = 10 × ⟨1/□⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":11,"concept":"M6-1-u1-C4","difficulty":2,"kind":"sa","stem":"10 ÷ 3 = 10 × ⟨1/□⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["÷ 3은 3으로 나눈 것 중의 1이에요.","그래서 ⟨1/3⟩을 곱하는 것과 같아요.","10 ÷ 3 = 10 × ⟨1/3⟩ — □는 3이에요."],"mis":"M6-1-u1-X07","variant_rule":{"alt":[{"stem":"4 ÷ 13 = 4 × ⟨1/□⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["÷ 13은 13으로 나눈 것 중의 1이에요.","그래서 ⟨1/13⟩을 곱하는 것과 같아요.","4 ÷ 13 = 4 × ⟨1/13⟩ — □는 13이에요."]},{"stem":"12 ÷ 5 = 12 × ⟨1/□⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["÷ 5는 5로 나눈 것 중의 1이에요.","그래서 ⟨1/5⟩을 곱하는 것과 같아요.","12 ÷ 5 = 12 × ⟨1/5⟩ — □는 5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_b#12','math',6,1,'u1','','g6_1_math_u1_review_b','unit_review','M6-1-u1-C5',2,'sa','auto','⟨10/11⟩ ÷ 2의 몫은 ⟨1/11⟩이 몇 개인 수인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":12,"concept":"M6-1-u1-C5","difficulty":2,"kind":"sa","stem":"⟨10/11⟩ ÷ 2의 몫은 ⟨1/11⟩이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["⟨10/11⟩은 ⟨1/11⟩이 10개예요.","10개를 2로 똑같이 나누면 10 ÷ 2 = 5개예요.","⟨10/11⟩ ÷ 2 = ⟨5/11⟩ — ⟨1/11⟩이 5개예요."],"mis":"M6-1-u1-X08","variant_rule":{"alt":[{"stem":"⟨9/13⟩ ÷ 3의 몫은 ⟨1/13⟩이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["⟨9/13⟩는 ⟨1/13⟩이 9개예요.","9개를 3으로 똑같이 나누면 9 ÷ 3 = 3개예요.","⟨9/13⟩ ÷ 3 = ⟨3/13⟩ — ⟨1/13⟩이 3개예요."]},{"stem":"⟨12/13⟩ ÷ 4의 몫은 ⟨1/13⟩이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["⟨12/13⟩는 ⟨1/13⟩이 12개예요.","12개를 4로 똑같이 나누면 12 ÷ 4 = 3개예요.","⟨12/13⟩ ÷ 4 = ⟨3/13⟩ — ⟨1/13⟩이 3개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_b#13','math',6,1,'u1','','g6_1_math_u1_review_b','unit_review','M6-1-u1-C5',2,'mc','auto','⟨7/10⟩ ÷ 2를 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M6-1-u1-X06','M6-1-u1-X07']::text[],true,'{"seq":13,"concept":"M6-1-u1-C5","difficulty":2,"kind":"mc","stem":"⟨7/10⟩ ÷ 2를 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨7/10⟩ × ⟨1/2⟩","correct":true},{"t":"⟨7/10⟩ × 2","mis":"M6-1-u1-X06"},{"t":"⟨10/7⟩ × ⟨1/2⟩","mis":"M6-1-u1-X07"},{"t":"2 × ⟨7/10⟩","mis":"M6-1-u1-X06"}],"explanation":["÷ 2는 2로 똑같이 나눈 것 중의 1이에요.","그래서 × ⟨1/2⟩과 같아요.","⟨7/10⟩ ÷ 2 = ⟨7/10⟩ × ⟨1/2⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨1/6⟩ ÷ 3을 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨1/6⟩ × ⟨1/3⟩","correct":true},{"t":"⟨1/6⟩ × 3","mis":"M6-1-u1-X06"},{"t":"⟨6/1⟩ × ⟨1/3⟩","mis":"M6-1-u1-X07"},{"t":"3 × ⟨1/6⟩","mis":"M6-1-u1-X06"}],"explanation":["÷ 3은 3으로 똑같이 나눈 것 중의 1이에요.","그래서 × ⟨1/3⟩과 같아요.","⟨1/6⟩ ÷ 3 = ⟨1/6⟩ × ⟨1/3⟩이에요."]},{"stem":"⟨5/12⟩ ÷ 7을 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨5/12⟩ × ⟨1/7⟩","correct":true},{"t":"⟨5/12⟩ × 7","mis":"M6-1-u1-X06"},{"t":"⟨12/5⟩ × ⟨1/7⟩","mis":"M6-1-u1-X07"},{"t":"7 × ⟨5/12⟩","mis":"M6-1-u1-X06"}],"explanation":["÷ 7은 7로 똑같이 나눈 것 중의 1이에요.","그래서 × ⟨1/7⟩과 같아요.","⟨5/12⟩ ÷ 7 = ⟨5/12⟩ × ⟨1/7⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_b#14','math',6,1,'u1','','g6_1_math_u1_review_b','unit_review','M6-1-u1-C6',2,'mc','auto','⟨2 1/3⟩ ÷ 7을 계산하면 얼마인가요?',ARRAY['M6-1-u1-X10','M6-1-u1-X06']::text[],true,'{"seq":14,"concept":"M6-1-u1-C6","difficulty":2,"kind":"mc","stem":"⟨2 1/3⟩ ÷ 7을 계산하면 얼마인가요?","options":[{"t":"⟨1/3⟩","correct":true},{"t":"⟨2 1/21⟩","mis":"M6-1-u1-X10"},{"t":"⟨13/21⟩","mis":"M6-1-u1-X10"},{"t":"⟨16 1/3⟩","mis":"M6-1-u1-X06"}],"explanation":["⟨2 1/3⟩을 가분수로 고치면 ⟨7/3⟩이에요.","⟨7/3⟩ ÷ 7 = ⟨7/3⟩ × ⟨1/7⟩이에요.","⟨7/3⟩ × ⟨1/7⟩ = ⟨1/3⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨3 3/5⟩ ÷ 6을 계산하면 얼마인가요?","options":[{"t":"⟨3/5⟩","correct":true},{"t":"⟨3 1/10⟩","mis":"M6-1-u1-X10"},{"t":"⟨1 1/10⟩","mis":"M6-1-u1-X10"},{"t":"⟨21 3/5⟩","mis":"M6-1-u1-X06"}],"explanation":["⟨3 3/5⟩을 가분수로 고치면 ⟨18/5⟩이에요.","⟨18/5⟩ ÷ 6 = ⟨18/5⟩ × ⟨1/6⟩이에요.","⟨18/5⟩ × ⟨1/6⟩ = ⟨3/5⟩이에요."]},{"stem":"⟨1 4/5⟩ ÷ 3을 계산하면 얼마인가요?","options":[{"t":"⟨3/5⟩","correct":true},{"t":"⟨1 4/15⟩","mis":"M6-1-u1-X10"},{"t":"⟨1 2/15⟩","mis":"M6-1-u1-X10"},{"t":"⟨5 2/5⟩","mis":"M6-1-u1-X06"}],"explanation":["⟨1 4/5⟩를 가분수로 고치면 ⟨9/5⟩예요.","⟨9/5⟩ ÷ 3 = ⟨9/5⟩ × ⟨1/3⟩이에요.","⟨9/5⟩ × ⟨1/3⟩ = ⟨3/5⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_b#15','math',6,1,'u1','','g6_1_math_u1_review_b','unit_review','M6-1-u1-C6',2,'sa','auto','⟨3 4/5⟩ ÷ 2를 계산하려고 ⟨3 4/5⟩를 가분수로 고쳤어요. 가분수의 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":15,"concept":"M6-1-u1-C6","difficulty":2,"kind":"sa","stem":"⟨3 4/5⟩ ÷ 2를 계산하려고 ⟨3 4/5⟩를 가분수로 고쳤어요. 가분수의 분자는 얼마인가요? 숫자로 쓰세요.","answer":["19"],"explanation":["대분수는 먼저 가분수로 고쳐요.","3 × 5 + 4 = 19예요.","⟨3 4/5⟩ = ⟨19/5⟩ — 분자는 19예요."],"mis":"M6-1-u1-X05","variant_rule":{"alt":[{"stem":"⟨1 7/9⟩ ÷ 4를 계산하려고 ⟨1 7/9⟩을 가분수로 고쳤어요. 가분수의 분자는 얼마인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["대분수는 먼저 가분수로 고쳐요.","1 × 9 + 7 = 16이에요.","⟨1 7/9⟩ = ⟨16/9⟩ — 분자는 16이에요."]},{"stem":"⟨4 3/7⟩ ÷ 6을 계산하려고 ⟨4 3/7⟩을 가분수로 고쳤어요. 가분수의 분자는 얼마인가요? 숫자로 쓰세요.","answer":["31"],"explanation":["대분수는 먼저 가분수로 고쳐요.","4 × 7 + 3 = 31이에요.","⟨4 3/7⟩ = ⟨31/7⟩ — 분자는 31이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_b#16','math',6,1,'u1','','g6_1_math_u1_review_b','unit_review','M6-1-u1-C7',2,'mc','auto','파란 뚜껑 1개와 노란 뚜껑 1개의 무게가 파란 뚜껑 3개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개의 무게가 ⟨2 2/3⟩ g일 때, 파란 뚜껑 1개의 무게는 몇 g인가요?',ARRAY['M6-1-u1-X13','M6-1-u1-X06']::text[],true,'{"seq":16,"concept":"M6-1-u1-C7","difficulty":2,"kind":"mc","stem":"파란 뚜껑 1개와 노란 뚜껑 1개의 무게가 파란 뚜껑 3개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개의 무게가 ⟨2 2/3⟩ g일 때, 파란 뚜껑 1개의 무게는 몇 g인가요?","options":[{"t":"⟨1 1/3⟩","correct":true},{"t":"⟨8/9⟩","mis":"M6-1-u1-X13"},{"t":"⟨2 2/3⟩","mis":"M6-1-u1-X13"},{"t":"⟨5 1/3⟩","mis":"M6-1-u1-X06"}],"explanation":["양쪽에서 파란 1개씩 덜어 내면 노란 1개 = 파란 2개예요.","⟨2 2/3⟩ = ⟨8/3⟩이에요.","⟨8/3⟩ × ⟨1/2⟩ = ⟨1 1/3⟩ — 파란 뚜껑 1개는 ⟨1 1/3⟩ g이에요."],"variant_rule":{"alt":[{"stem":"파란 뚜껑 3개와 노란 뚜껑 1개의 무게가 파란 뚜껑 7개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개의 무게가 ⟨6 2/3⟩ g일 때, 파란 뚜껑 1개의 무게는 몇 g인가요?","options":[{"t":"⟨1 2/3⟩","correct":true},{"t":"⟨20/21⟩","mis":"M6-1-u1-X13"},{"t":"⟨2 2/9⟩","mis":"M6-1-u1-X13"},{"t":"⟨26 2/3⟩","mis":"M6-1-u1-X06"}],"explanation":["양쪽에서 파란 3개씩 덜어 내면 노란 1개 = 파란 4개예요.","⟨6 2/3⟩ = ⟨20/3⟩이에요.","⟨20/3⟩ × ⟨1/4⟩ = ⟨1 2/3⟩ — 파란 뚜껑 1개는 ⟨1 2/3⟩ g이에요."]},{"stem":"파란 뚜껑 2개와 노란 뚜껑 1개의 무게가 파란 뚜껑 4개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개의 무게가 ⟨3 1/5⟩ g일 때, 파란 뚜껑 1개의 무게는 몇 g인가요?","options":[{"t":"⟨1 3/5⟩","correct":true},{"t":"⟨4/5⟩","mis":"M6-1-u1-X13"},{"t":"⟨6 2/5⟩","mis":"M6-1-u1-X06"},{"t":"⟨8/15⟩","mis":"M6-1-u1-X13"}],"explanation":["양쪽에서 파란 2개씩 덜어 내면 노란 1개 = 파란 2개예요.","⟨3 1/5⟩ = ⟨16/5⟩이에요.","⟨16/5⟩ × ⟨1/2⟩ = ⟨1 3/5⟩ — 파란 뚜껑 1개는 ⟨1 3/5⟩ g이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_b#17','math',6,1,'u1','','g6_1_math_u1_review_b','unit_review','M6-1-u1-C2',3,'mc','auto','가 모둠은 주스 4 L를 9명이, 나 모둠은 주스 3 L를 8명이 똑같이 나누었어요. 한 명이 가지는 주스가 더 많은 모둠은 어디인가요?',ARRAY['M6-1-u1-X11','M6-1-u1-X03']::text[],true,'{"seq":17,"concept":"M6-1-u1-C2","difficulty":3,"kind":"mc","stem":"가 모둠은 주스 4 L를 9명이, 나 모둠은 주스 3 L를 8명이 똑같이 나누었어요. 한 명이 가지는 주스가 더 많은 모둠은 어디인가요?","options":[{"t":"가 모둠","correct":true},{"t":"나 모둠","mis":"M6-1-u1-X11"},{"t":"두 모둠이 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X03"}],"explanation":["가 모둠 한 명 몫은 4 ÷ 9 = ⟨4/9⟩, 나 모둠은 3 ÷ 8 = ⟨3/8⟩이에요.","72로 통분하면 ⟨4/9⟩ = ⟨32/72⟩, ⟨3/8⟩ = ⟨27/72⟩이에요.","⟨4/9⟩ > ⟨3/8⟩이라 가 모둠이 더 많아요."],"variant_rule":{"alt":[{"stem":"가 모둠은 빵 5개를 7명이, 나 모둠은 빵 3개를 4명이 똑같이 나누었어요. 한 명이 가지는 빵이 더 많은 모둠은 어디인가요?","options":[{"t":"나 모둠","correct":true},{"t":"가 모둠","mis":"M6-1-u1-X11"},{"t":"두 모둠이 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X03"}],"explanation":["가 모둠 한 명 몫은 5 ÷ 7 = ⟨5/7⟩, 나 모둠은 3 ÷ 4 = ⟨3/4⟩이에요.","28로 통분하면 ⟨5/7⟩ = ⟨20/28⟩, ⟨3/4⟩ = ⟨21/28⟩이에요.","⟨5/7⟩ < ⟨3/4⟩이라 나 모둠이 더 많아요."]},{"stem":"가 모둠은 피자 3판을 5명이, 나 모둠은 피자 5판을 8명이 똑같이 나누었어요. 한 명이 가지는 피자가 더 많은 모둠은 어디인가요?","options":[{"t":"나 모둠","correct":true},{"t":"가 모둠","mis":"M6-1-u1-X11"},{"t":"두 모둠이 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X03"}],"explanation":["가 모둠 한 명 몫은 3 ÷ 5 = ⟨3/5⟩, 나 모둠은 5 ÷ 8 = ⟨5/8⟩예요.","40으로 통분하면 ⟨3/5⟩ = ⟨24/40⟩, ⟨5/8⟩ = ⟨25/40⟩예요.","⟨3/5⟩ < ⟨5/8⟩라 나 모둠이 더 많아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_b#18','math',6,1,'u1','','g6_1_math_u1_review_b','unit_review','M6-1-u1-C3',3,'sa','auto','끈 17 m를 6도막으로 똑같이 나누어 자르려고 해요. 한 도막의 길이를 대분수로 나타낼 때, 자연수 부분과 분자의 합은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":18,"concept":"M6-1-u1-C3","difficulty":3,"kind":"sa","stem":"끈 17 m를 6도막으로 똑같이 나누어 자르려고 해요. 한 도막의 길이를 대분수로 나타낼 때, 자연수 부분과 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["17 ÷ 6은 몫 2, 나머지 5예요.","남은 5도 나누면 17 ÷ 6 = ⟨2 5/6⟩예요.","자연수 부분과 분자의 합은 2 + 5 = 7이에요."],"mis":"M6-1-u1-X15","variant_rule":{"alt":[{"stem":"색 모래 25 kg을 7모둠이 똑같이 나누어 가지려고 해요. 한 모둠이 가지는 색 모래를 대분수로 나타낼 때, 자연수 부분과 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["25 ÷ 7은 몫 3, 나머지 4예요.","남은 4도 나누면 25 ÷ 7 = ⟨3 4/7⟩예요.","자연수 부분과 분자의 합은 3 + 4 = 7이에요."]},{"stem":"주스 13 L를 3명이 똑같이 나누어 마시려고 해요. 한 명이 마시는 주스를 대분수로 나타낼 때, 자연수 부분과 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["13 ÷ 3은 몫 4, 나머지 1이에요.","남은 1도 나누면 13 ÷ 3 = ⟨4 1/3⟩이에요.","자연수 부분과 분자의 합은 4 + 1 = 5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_b#19','math',6,1,'u1','','g6_1_math_u1_review_b','unit_review','M6-1-u1-C4',3,'mc','auto','끈 6 m를 5도막으로 나눈 한 도막과 끈 5 m를 4도막으로 나눈 한 도막 가운데 더 긴 것은 어느 것인가요?',ARRAY['M6-1-u1-X11','M6-1-u1-X03']::text[],true,'{"seq":19,"concept":"M6-1-u1-C4","difficulty":3,"kind":"mc","stem":"끈 6 m를 5도막으로 나눈 한 도막과 끈 5 m를 4도막으로 나눈 한 도막 가운데 더 긴 것은 어느 것인가요?","options":[{"t":"끈 5 m를 4도막으로 나눈 한 도막","correct":true},{"t":"끈 6 m를 5도막으로 나눈 한 도막","mis":"M6-1-u1-X11"},{"t":"두 도막의 길이가 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X03"}],"explanation":["6 ÷ 5 = 6 × ⟨1/5⟩ = ⟨1 1/5⟩, 5 ÷ 4 = 5 × ⟨1/4⟩ = ⟨1 1/4⟩이에요.","20으로 통분하면 ⟨1 1/5⟩ = ⟨24/20⟩, ⟨1 1/4⟩ = ⟨25/20⟩예요.","그래서 더 긴 것은 끈 5 m를 4도막으로 나눈 한 도막이에요."],"variant_rule":{"alt":[{"stem":"끈 10 m를 3도막으로 나눈 한 도막과 끈 13 m를 4도막으로 나눈 한 도막 가운데 더 긴 것은 어느 것인가요?","options":[{"t":"끈 10 m를 3도막으로 나눈 한 도막","correct":true},{"t":"끈 13 m를 4도막으로 나눈 한 도막","mis":"M6-1-u1-X11"},{"t":"두 도막의 길이가 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X03"}],"explanation":["10 ÷ 3 = 10 × ⟨1/3⟩ = ⟨3 1/3⟩, 13 ÷ 4 = 13 × ⟨1/4⟩ = ⟨3 1/4⟩이에요.","12로 통분하면 ⟨3 1/3⟩ = ⟨40/12⟩, ⟨3 1/4⟩ = ⟨39/12⟩예요.","그래서 더 긴 것은 끈 10 m를 3도막으로 나눈 한 도막이에요."]},{"stem":"끈 8 m를 7도막으로 나눈 한 도막과 끈 9 m를 8도막으로 나눈 한 도막 가운데 더 긴 것은 어느 것인가요?","options":[{"t":"끈 8 m를 7도막으로 나눈 한 도막","correct":true},{"t":"끈 9 m를 8도막으로 나눈 한 도막","mis":"M6-1-u1-X11"},{"t":"두 도막의 길이가 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X03"}],"explanation":["8 ÷ 7 = 8 × ⟨1/7⟩ = ⟨1 1/7⟩, 9 ÷ 8 = 9 × ⟨1/8⟩ = ⟨1 1/8⟩이에요.","56으로 통분하면 ⟨1 1/7⟩ = ⟨64/56⟩, ⟨1 1/8⟩ = ⟨63/56⟩이에요.","그래서 더 긴 것은 끈 8 m를 7도막으로 나눈 한 도막이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_b#20','math',6,1,'u1','','g6_1_math_u1_review_b','unit_review','M6-1-u1-C5',3,'error','auto','⟨5/6⟩ ÷ 2에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u1-X06','M6-1-u1-X15']::text[],true,'{"seq":20,"concept":"M6-1-u1-C5","difficulty":3,"kind":"error","stem":"⟨5/6⟩ ÷ 2에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민준 — 「⟨5/6⟩ × 2 = ⟨1 2/3⟩로 계산해.」","correct":true,"mis_target":"M6-1-u1-X06"},{"t":"서연 — 「⟨5/6⟩ × ⟨1/2⟩로 바꾸어 계산하면 돼.」","mis":"M6-1-u1-X15"},{"t":"지호 — 「몫은 ⟨5/6⟩보다 작아.」","mis":"M6-1-u1-X15"}],"explanation":["2로 나누면 양이 작아져야 해요.","⟨5/6⟩ × 2 = ⟨1 2/3⟩는 오히려 커요.","⟨5/6⟩ ÷ 2 = ⟨5/6⟩ × ⟨1/2⟩ = ⟨5/12⟩ — 민준은 나누는 수를 그대로 곱했어요."],"variant_rule":{"alt":[{"stem":"⟨3/10⟩ ÷ 4에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「⟨3/10⟩ × 4 = ⟨1 1/5⟩로 계산해.」","correct":true,"mis_target":"M6-1-u1-X06"},{"t":"나린 — 「⟨3/10⟩ × ⟨1/4⟩로 바꾸어 계산하면 돼.」","mis":"M6-1-u1-X15"},{"t":"유진 — 「몫은 ⟨3/10⟩보다 작아.」","mis":"M6-1-u1-X15"}],"explanation":["4로 나누면 양이 작아져야 해요.","⟨3/10⟩ × 4 = ⟨1 1/5⟩은 오히려 커요.","⟨3/10⟩ ÷ 4 = ⟨3/10⟩ × ⟨1/4⟩ = ⟨3/40⟩ — 가온은 나누는 수를 그대로 곱했어요."]},{"stem":"⟨7/8⟩ ÷ 2에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"여울 — 「⟨7/8⟩ × 2 = ⟨1 3/4⟩으로 계산해.」","correct":true,"mis_target":"M6-1-u1-X06"},{"t":"라온 — 「⟨7/8⟩ × ⟨1/2⟩로 바꾸어 계산하면 돼.」","mis":"M6-1-u1-X15"},{"t":"예준 — 「몫은 ⟨7/8⟩보다 작아.」","mis":"M6-1-u1-X15"}],"explanation":["2로 나누면 양이 작아져야 해요.","⟨7/8⟩ × 2 = ⟨1 3/4⟩은 오히려 커요.","⟨7/8⟩ ÷ 2 = ⟨7/8⟩ × ⟨1/2⟩ = ⟨7/16⟩ — 여울은 나누는 수를 그대로 곱했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_b#21','math',6,1,'u1','','g6_1_math_u1_review_b','unit_review','M6-1-u1-C6',3,'mc','auto','넓이가 ⟨5 1/4⟩ m²이고 가로가 2 m인 직사각형이 있어요. 세로는 몇 m인가요?',ARRAY['M6-1-u1-X10','M6-1-u1-X06']::text[],true,'{"seq":21,"concept":"M6-1-u1-C6","difficulty":3,"kind":"mc","stem":"넓이가 ⟨5 1/4⟩ m²이고 가로가 2 m인 직사각형이 있어요. 세로는 몇 m인가요?","options":[{"t":"⟨2 5/8⟩","correct":true},{"t":"⟨5 1/8⟩","mis":"M6-1-u1-X10"},{"t":"⟨2 3/4⟩","mis":"M6-1-u1-X10"},{"t":"⟨10 1/2⟩","mis":"M6-1-u1-X06"}],"explanation":["(직사각형의 넓이) = (가로) × (세로)이니 세로 = 넓이 ÷ 가로예요.","⟨5 1/4⟩ ÷ 2 = ⟨21/4⟩ × ⟨1/2⟩이에요.","⟨21/4⟩ × ⟨1/2⟩ = ⟨2 5/8⟩ — 세로는 ⟨2 5/8⟩ m예요."],"variant_rule":{"alt":[{"stem":"넓이가 ⟨3 3/5⟩ m²이고 가로가 4 m인 직사각형이 있어요. 세로는 몇 m인가요?","options":[{"t":"⟨9/10⟩","correct":true},{"t":"⟨3 3/20⟩","mis":"M6-1-u1-X10"},{"t":"⟨1 7/20⟩","mis":"M6-1-u1-X10"},{"t":"⟨14 2/5⟩","mis":"M6-1-u1-X06"}],"explanation":["(직사각형의 넓이) = (가로) × (세로)이니 세로 = 넓이 ÷ 가로예요.","⟨3 3/5⟩ ÷ 4 = ⟨18/5⟩ × ⟨1/4⟩이에요.","⟨18/5⟩ × ⟨1/4⟩ = ⟨9/10⟩ — 세로는 ⟨9/10⟩ m예요."]},{"stem":"넓이가 ⟨6 2/3⟩ m²이고 가로가 5 m인 직사각형이 있어요. 세로는 몇 m인가요?","options":[{"t":"⟨1 1/3⟩","correct":true},{"t":"⟨6 2/15⟩","mis":"M6-1-u1-X10"},{"t":"⟨1 13/15⟩","mis":"M6-1-u1-X10"},{"t":"⟨33 1/3⟩","mis":"M6-1-u1-X06"}],"explanation":["(직사각형의 넓이) = (가로) × (세로)이니 세로 = 넓이 ÷ 가로예요.","⟨6 2/3⟩ ÷ 5 = ⟨20/3⟩ × ⟨1/5⟩이에요.","⟨20/3⟩ × ⟨1/5⟩ = ⟨1 1/3⟩ — 세로는 ⟨1 1/3⟩ m예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_b#22','math',6,1,'u1','','g6_1_math_u1_review_b','unit_review','M6-1-u1-C7',3,'sa','auto','조건을 바꾸어 보아요. 노란 뚜껑 1개가 ⟨3 3/4⟩ g이고 파란 뚜껑 5개와 무게가 같아요. 파란 뚜껑 1개의 무게를 기약분수(가분수)로 나타낼 때 분모와 분자의 합은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":22,"concept":"M6-1-u1-C7","difficulty":3,"kind":"sa","stem":"조건을 바꾸어 보아요. 노란 뚜껑 1개가 ⟨3 3/4⟩ g이고 파란 뚜껑 5개와 무게가 같아요. 파란 뚜껑 1개의 무게를 기약분수(가분수)로 나타낼 때 분모와 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["파란 뚜껑 1개 = ⟨3 3/4⟩ ÷ 5예요.","⟨15/4⟩ ÷ 5 = ⟨15/4⟩ × ⟨1/5⟩ = ⟨3/4⟩이에요.","분모와 분자의 합은 4 + 3 = 7이에요."],"mis":"M6-1-u1-X15","variant_rule":{"alt":[{"stem":"조건을 바꾸어 보아요. 노란 뚜껑 1개가 ⟨4 4/5⟩ g이고 파란 뚜껑 6개와 무게가 같아요. 파란 뚜껑 1개의 무게를 기약분수(가분수)로 나타낼 때 분모와 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["파란 뚜껑 1개 = ⟨4 4/5⟩ ÷ 6이에요.","⟨24/5⟩ ÷ 6 = ⟨24/5⟩ × ⟨1/6⟩ = ⟨4/5⟩예요.","분모와 분자의 합은 5 + 4 = 9예요."]},{"stem":"조건을 바꾸어 보아요. 노란 뚜껑 1개가 ⟨1 5/7⟩ g이고 파란 뚜껑 4개와 무게가 같아요. 파란 뚜껑 1개의 무게를 기약분수(가분수)로 나타낼 때 분모와 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["파란 뚜껑 1개 = ⟨1 5/7⟩ ÷ 4예요.","⟨12/7⟩ ÷ 4 = ⟨12/7⟩ × ⟨1/4⟩ = ⟨3/7⟩이에요.","분모와 분자의 합은 7 + 3 = 10이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_b#23','math',6,1,'u1','','g6_1_math_u1_review_b','unit_review','M6-1-u1-C3',4,'sa','auto','□ ÷ 7의 몫이 3보다 크고 4보다 작을 때, □에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":23,"concept":"M6-1-u1-C3","difficulty":4,"kind":"sa","stem":"□ ÷ 7의 몫이 3보다 크고 4보다 작을 때, □에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["21 ÷ 7 = 3, 28 ÷ 7 = 4예요.","□는 21보다 크고 28보다 작아야 해요.","22부터 27까지 6개예요."],"mis":"M6-1-u1-X03","variant_rule":{"alt":[{"stem":"⟨9/13⟩ ÷ □의 몫이 ⟨1/13⟩보다 클 때, □에 들어갈 수 있는 가장 큰 자연수는 얼마인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["⟨9/13⟩는 ⟨1/13⟩이 9개예요.","□로 나눈 몫이 ⟨1/13⟩보다 크려면 9개를 □로 나눈 수가 1보다 커야 해요.","□는 9보다 작아야 하니 가장 큰 수는 8이에요."]},{"stem":"자연수 부분이 □이고 분수 부분이 ⟨2/5⟩인 대분수를 4로 나누었더니 ⟨17/20⟩이 되었어요. □에 알맞은 자연수는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["나누기 전의 수는 ⟨17/20⟩ × 4예요.","⟨17/20⟩ × 4 = ⟨17/5⟩ = ⟨3 2/5⟩예요.","그래서 □는 3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_b#24','math',6,1,'u1','','g6_1_math_u1_review_b','unit_review','M6-1-u1-C3',4,'essay','teacher','13 ÷ 5의 몫을 대분수와 가분수로 각각 나타내고, 대분수로 나타내는 과정을 설명해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M6-1-u1-C3","difficulty":4,"kind":"essay","stem":"13 ÷ 5의 몫을 대분수와 가분수로 각각 나타내고, 대분수로 나타내는 과정을 설명해 보세요.","answer_guide":{"answer":"예: 13 ÷ 5는 몫 2, 나머지 3이다. 남은 3을 5로 나누면 ⟨3/5⟩이므로 대분수로 ⟨2 3/5⟩이다. 나누어지는 수를 분자, 나누는 수를 분모로 하면 가분수 ⟨13/5⟩이고, ⟨13/5⟩ = ⟨2 3/5⟩으로 같은 수이다.","scoring_points":["몫 2, 나머지 3을 구했는가","대분수 ⟨2 3/5⟩을 구했는가","가분수 ⟨13/5⟩을 쓰고 같은 수라고 했는가"]},"explanation":["13 ÷ 5는 몫 2, 나머지 3이에요.","남은 3을 5로 나누면 ⟨2 3/5⟩이에요.","가분수로는 ⟨13/5⟩ — 같은 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_b#25','math',6,1,'u1','','g6_1_math_u1_review_b','unit_review','M6-1-u1-C6',4,'essay','teacher','넓이가 ⟨5 3/4⟩ m²이고 가로가 2 m인 직사각형의 세로를 구하는 식을 세우고, 계산 과정을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"M6-1-u1-C6","difficulty":4,"kind":"essay","stem":"넓이가 ⟨5 3/4⟩ m²이고 가로가 2 m인 직사각형의 세로를 구하는 식을 세우고, 계산 과정을 쓰세요.","answer_guide":{"answer":"예: 직사각형의 넓이는 가로 × 세로이므로 세로 = 넓이 ÷ 가로 = ⟨5 3/4⟩ ÷ 2이다. ⟨5 3/4⟩ = ⟨23/4⟩이므로 ⟨23/4⟩ × ⟨1/2⟩ = ⟨23/8⟩ = ⟨2 7/8⟩ m이다.","scoring_points":["세로 = 넓이 ÷ 가로로 식을 세웠는가","⟨5 3/4⟩ = ⟨23/4⟩으로 고쳤는가","⟨2 7/8⟩ m를 구했는가"]},"explanation":["세로 = 넓이 ÷ 가로예요.","⟨5 3/4⟩ = ⟨23/4⟩이에요.","⟨23/4⟩ × ⟨1/2⟩ = ⟨2 7/8⟩ m예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_c#1','math',6,1,'u1','','g6_1_math_u1_review_c','unit_review','M6-1-u1-C2',1,'mc','auto','주스 3 L를 7명이 똑같이 나누어 마시려고 해요. 한 명이 마시는 주스는 몇 L인지 분수로 나타내면 얼마인가요?',ARRAY['M6-1-u1-X01','M6-1-u1-X09']::text[],true,'{"seq":1,"concept":"M6-1-u1-C2","difficulty":1,"kind":"mc","stem":"주스 3 L를 7명이 똑같이 나누어 마시려고 해요. 한 명이 마시는 주스는 몇 L인지 분수로 나타내면 얼마인가요?","options":[{"t":"⟨3/7⟩","correct":true},{"t":"⟨2 1/3⟩","mis":"M6-1-u1-X01"},{"t":"⟨1/7⟩","mis":"M6-1-u1-X01"},{"t":"⟨3/10⟩","mis":"M6-1-u1-X09"}],"explanation":["주스 3 L를 7로 똑같이 나누는 것은 3 ÷ 7이에요.","나누어지는 수 3은 분자, 나누는 수 7은 분모가 돼요.","3 ÷ 7 = ⟨3/7⟩ — ⟨3/7⟩ L예요."],"variant_rule":{"alt":[{"stem":"식빵 1개를 3명이 똑같이 나누어 먹으려고 해요. 한 명이 먹는 식빵은 몇 개인지 분수로 나타내면 얼마인가요?","options":[{"t":"⟨1/3⟩","correct":true},{"t":"3","mis":"M6-1-u1-X01"},{"t":"⟨1/4⟩","mis":"M6-1-u1-X09"},{"t":"1","mis":"M6-1-u1-X01"}],"explanation":["식빵 1개를 3으로 똑같이 나누는 것은 1 ÷ 3이에요.","나누어지는 수 1은 분자, 나누는 수 3은 분모가 돼요.","1 ÷ 3 = ⟨1/3⟩ — ⟨1/3⟩개예요."]},{"stem":"시루떡 3개를 4명이 똑같이 나누어 먹으려고 해요. 한 명이 먹는 시루떡은 몇 개인지 분수로 나타내면 얼마인가요?","options":[{"t":"⟨3/4⟩","correct":true},{"t":"⟨1 1/3⟩","mis":"M6-1-u1-X01"},{"t":"⟨1/4⟩","mis":"M6-1-u1-X01"},{"t":"⟨3/7⟩","mis":"M6-1-u1-X09"}],"explanation":["시루떡 3개를 4로 똑같이 나누는 것은 3 ÷ 4예요.","나누어지는 수 3은 분자, 나누는 수 4는 분모가 돼요.","3 ÷ 4 = ⟨3/4⟩ — ⟨3/4⟩개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_c#2','math',6,1,'u1','','g6_1_math_u1_review_c','unit_review','M6-1-u1-C2',1,'sa','auto','2 ÷ 11의 몫을 분수로 나타낼 때 분자에 오는 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-1-u1-C2","difficulty":1,"kind":"sa","stem":"2 ÷ 11의 몫을 분수로 나타낼 때 분자에 오는 수는 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["(자연수)÷(자연수)의 몫은 분수로 나타낼 수 있어요.","나누어지는 수 2는 분자, 나누는 수 11은 분모예요.","2 ÷ 11 = ⟨2/11⟩니 분자는 2예요."],"mis":"M6-1-u1-X01","variant_rule":{"alt":[{"stem":"6 ÷ 13의 몫을 분수로 나타낼 때 분모에 오는 수는 얼마인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["(자연수)÷(자연수)의 몫은 분수로 나타낼 수 있어요.","나누어지는 수 6은 분자, 나누는 수 13은 분모예요.","6 ÷ 13 = ⟨6/13⟩이니 분모는 13이에요."]},{"stem":"4 ÷ 7의 몫을 분수로 나타낼 때 분자에 오는 수는 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["(자연수)÷(자연수)의 몫은 분수로 나타낼 수 있어요.","나누어지는 수 4는 분자, 나누는 수 7은 분모예요.","4 ÷ 7 = ⟨4/7⟩니 분자는 4예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_c#3','math',6,1,'u1','','g6_1_math_u1_review_c','unit_review','M6-1-u1-C3',1,'mc','auto','⟨3 1/3⟩을 가분수로 나타내면 어느 것인가요?',ARRAY['M6-1-u1-X01','M6-1-u1-X05']::text[],true,'{"seq":3,"concept":"M6-1-u1-C3","difficulty":1,"kind":"mc","stem":"⟨3 1/3⟩을 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨10/3⟩","correct":true},{"t":"⟨3/10⟩","mis":"M6-1-u1-X01"},{"t":"⟨4/3⟩","mis":"M6-1-u1-X05"},{"t":"⟨3/3⟩","mis":"M6-1-u1-X05"}],"explanation":["자연수 3은 ⟨9/3⟩예요 — 3 × 3 = 9.","여기에 ⟨1/3⟩을 더하면 분자는 9 + 1 = 10이에요.","⟨3 1/3⟩ = ⟨10/3⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨2 5/6⟩를 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨17/6⟩","correct":true},{"t":"⟨6/17⟩","mis":"M6-1-u1-X01"},{"t":"⟨7/6⟩","mis":"M6-1-u1-X05"},{"t":"⟨10/6⟩","mis":"M6-1-u1-X05"}],"explanation":["자연수 2는 ⟨12/6⟩예요 — 2 × 6 = 12.","여기에 ⟨5/6⟩를 더하면 분자는 12 + 5 = 17이에요.","⟨2 5/6⟩ = ⟨17/6⟩이에요."]},{"stem":"⟨1 3/4⟩을 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨7/4⟩","correct":true},{"t":"⟨4/7⟩","mis":"M6-1-u1-X01"},{"t":"⟨4/4⟩","mis":"M6-1-u1-X05"},{"t":"⟨3/4⟩","mis":"M6-1-u1-X05"}],"explanation":["자연수 1은 ⟨4/4⟩예요 — 1 × 4 = 4.","여기에 ⟨3/4⟩을 더하면 분자는 4 + 3 = 7이에요.","⟨1 3/4⟩ = ⟨7/4⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_c#4','math',6,1,'u1','','g6_1_math_u1_review_c','unit_review','M6-1-u1-C3',1,'sa','auto','19 ÷ 5의 몫을 대분수로 나타낼 때 자연수 부분에 오는 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M6-1-u1-C3","difficulty":1,"kind":"sa","stem":"19 ÷ 5의 몫을 대분수로 나타낼 때 자연수 부분에 오는 수는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["19 ÷ 5는 몫 3, 나머지 4예요.","남은 4도 5로 나누면 ⟨4/5⟩ — 몫은 ⟨3 4/5⟩예요.","그래서 자연수 부분은 3이에요."],"mis":"M6-1-u1-X04","variant_rule":{"alt":[{"stem":"23 ÷ 7의 몫을 대분수로 나타낼 때 분자에 오는 수는 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["23 ÷ 7은 몫 3, 나머지 2예요.","남은 2도 7로 나누면 ⟨2/7⟩ — 몫은 ⟨3 2/7⟩예요.","그래서 분자는 2예요."]},{"stem":"15 ÷ 4의 몫을 대분수로 나타낼 때 자연수 부분에 오는 수는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["15 ÷ 4는 몫 3, 나머지 3이에요.","남은 3도 4로 나누면 ⟨3/4⟩ — 몫은 ⟨3 3/4⟩이에요.","그래서 자연수 부분은 3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_c#5','math',6,1,'u1','','g6_1_math_u1_review_c','unit_review','M6-1-u1-C4',1,'mc','auto','8 ÷ 3을 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M6-1-u1-X06','M6-1-u1-X07']::text[],true,'{"seq":5,"concept":"M6-1-u1-C4","difficulty":1,"kind":"mc","stem":"8 ÷ 3을 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"8 × ⟨1/3⟩","correct":true},{"t":"8 × 3","mis":"M6-1-u1-X06"},{"t":"3 × ⟨1/8⟩","mis":"M6-1-u1-X07"},{"t":"⟨1/8⟩ × ⟨1/3⟩","mis":"M6-1-u1-X07"}],"explanation":["÷ 3은 3으로 똑같이 나눈 것 중의 1이에요.","× ⟨1/3⟩도 3으로 똑같이 나눈 것 중의 1이에요.","그래서 8 ÷ 3 = 8 × ⟨1/3⟩ = ⟨2 2/3⟩예요."],"variant_rule":{"alt":[{"stem":"4 ÷ 11을 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"4 × ⟨1/11⟩","correct":true},{"t":"4 × 11","mis":"M6-1-u1-X06"},{"t":"11 × ⟨1/4⟩","mis":"M6-1-u1-X07"},{"t":"⟨1/4⟩ × ⟨1/11⟩","mis":"M6-1-u1-X07"}],"explanation":["÷ 11은 11로 똑같이 나눈 것 중의 1이에요.","× ⟨1/11⟩도 11로 똑같이 나눈 것 중의 1이에요.","그래서 4 ÷ 11 = 4 × ⟨1/11⟩ = ⟨4/11⟩예요."]},{"stem":"6 ÷ 5를 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"6 × ⟨1/5⟩","correct":true},{"t":"6 × 5","mis":"M6-1-u1-X06"},{"t":"5 × ⟨1/6⟩","mis":"M6-1-u1-X07"},{"t":"⟨1/6⟩ × ⟨1/5⟩","mis":"M6-1-u1-X07"}],"explanation":["÷ 5는 5로 똑같이 나눈 것 중의 1이에요.","× ⟨1/5⟩도 5로 똑같이 나눈 것 중의 1이에요.","그래서 6 ÷ 5 = 6 × ⟨1/5⟩ = ⟨1 1/5⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_c#6','math',6,1,'u1','','g6_1_math_u1_review_c','unit_review','M6-1-u1-C5',1,'mc','auto','⟨10/13⟩ ÷ 5를 계산하면 얼마인가요?',ARRAY['M6-1-u1-X06','M6-1-u1-X09','M6-1-u1-X07']::text[],true,'{"seq":6,"concept":"M6-1-u1-C5","difficulty":1,"kind":"mc","stem":"⟨10/13⟩ ÷ 5를 계산하면 얼마인가요?","options":[{"t":"⟨2/13⟩","correct":true},{"t":"⟨3 11/13⟩","mis":"M6-1-u1-X06"},{"t":"⟨5/9⟩","mis":"M6-1-u1-X09"},{"t":"⟨13/50⟩","mis":"M6-1-u1-X07"}],"explanation":["⟨10/13⟩은 ⟨1/13⟩이 10개예요.","분자 10을 5로 나누면 10 ÷ 5 = 2 — ⟨1/13⟩이 2개예요.","그래서 ⟨10/13⟩ ÷ 5 = ⟨2/13⟩예요."],"variant_rule":{"alt":[{"stem":"⟨9/10⟩ ÷ 3을 계산하면 얼마인가요?","options":[{"t":"⟨3/10⟩","correct":true},{"t":"⟨2 7/10⟩","mis":"M6-1-u1-X06"},{"t":"⟨9/13⟩","mis":"M6-1-u1-X09"},{"t":"⟨10/27⟩","mis":"M6-1-u1-X07"}],"explanation":["⟨9/10⟩는 ⟨1/10⟩이 9개예요.","분자 9를 3으로 나누면 9 ÷ 3 = 3 — ⟨1/10⟩이 3개예요.","그래서 ⟨9/10⟩ ÷ 3 = ⟨3/10⟩이에요."]},{"stem":"⟨6/11⟩ ÷ 3을 계산하면 얼마인가요?","options":[{"t":"⟨2/11⟩","correct":true},{"t":"⟨1 7/11⟩","mis":"M6-1-u1-X06"},{"t":"⟨3/7⟩","mis":"M6-1-u1-X09"},{"t":"⟨11/18⟩","mis":"M6-1-u1-X07"}],"explanation":["⟨6/11⟩은 ⟨1/11⟩이 6개예요.","분자 6을 3으로 나누면 6 ÷ 3 = 2 — ⟨1/11⟩이 2개예요.","그래서 ⟨6/11⟩ ÷ 3 = ⟨2/11⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_c#7','math',6,1,'u1','','g6_1_math_u1_review_c','unit_review','M6-1-u1-C6',1,'mc','auto','⟨2 4/5⟩를 가분수로 나타내면 어느 것인가요?',ARRAY['M6-1-u1-X01','M6-1-u1-X05']::text[],true,'{"seq":7,"concept":"M6-1-u1-C6","difficulty":1,"kind":"mc","stem":"⟨2 4/5⟩를 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨14/5⟩","correct":true},{"t":"⟨5/14⟩","mis":"M6-1-u1-X01"},{"t":"⟨6/5⟩","mis":"M6-1-u1-X05"},{"t":"⟨8/5⟩","mis":"M6-1-u1-X05"}],"explanation":["자연수 2는 ⟨10/5⟩이에요 — 2 × 5 = 10.","여기에 ⟨4/5⟩를 더하면 분자는 10 + 4 = 14예요.","⟨2 4/5⟩ = ⟨14/5⟩예요."],"variant_rule":{"alt":[{"stem":"⟨4 1/3⟩을 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨13/3⟩","correct":true},{"t":"⟨3/13⟩","mis":"M6-1-u1-X01"},{"t":"⟨5/3⟩","mis":"M6-1-u1-X05"},{"t":"⟨4/3⟩","mis":"M6-1-u1-X05"}],"explanation":["자연수 4는 ⟨12/3⟩예요 — 4 × 3 = 12.","여기에 ⟨1/3⟩을 더하면 분자는 12 + 1 = 13이에요.","⟨4 1/3⟩ = ⟨13/3⟩이에요."]},{"stem":"⟨1 5/6⟩를 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨11/6⟩","correct":true},{"t":"⟨6/11⟩","mis":"M6-1-u1-X01"},{"t":"⟨6/6⟩","mis":"M6-1-u1-X05"},{"t":"⟨5/6⟩","mis":"M6-1-u1-X05"}],"explanation":["자연수 1은 ⟨6/6⟩이에요 — 1 × 6 = 6.","여기에 ⟨5/6⟩를 더하면 분자는 6 + 5 = 11이에요.","⟨1 5/6⟩ = ⟨11/6⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_c#8','math',6,1,'u1','','g6_1_math_u1_review_c','unit_review','M6-1-u1-C7',1,'mc','auto','저울에서 파란 뚜껑 3개와 노란 뚜껑 1개의 무게가 파란 뚜껑 6개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개는 파란 뚜껑 몇 개와 무게가 같나요?',ARRAY['M6-1-u1-X13']::text[],true,'{"seq":8,"concept":"M6-1-u1-C7","difficulty":1,"kind":"mc","stem":"저울에서 파란 뚜껑 3개와 노란 뚜껑 1개의 무게가 파란 뚜껑 6개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개는 파란 뚜껑 몇 개와 무게가 같나요?","options":[{"t":"3개","correct":true},{"t":"6개","mis":"M6-1-u1-X13"},{"t":"9개","mis":"M6-1-u1-X13"},{"t":"4개","mis":"M6-1-u1-X13"}],"explanation":["양쪽에서 파란 뚜껑 3개씩을 덜어 내도 저울은 수평이에요.","왼쪽엔 노란 뚜껑 1개, 오른쪽엔 파란 뚜껑 6 − 3 = 3개가 남아요.","그래서 노란 뚜껑 1개는 파란 뚜껑 3개와 같아요."],"variant_rule":{"alt":[{"stem":"저울에서 파란 뚜껑 2개와 노란 뚜껑 1개의 무게가 파란 뚜껑 7개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개는 파란 뚜껑 몇 개와 무게가 같나요?","options":[{"t":"5개","correct":true},{"t":"2개","mis":"M6-1-u1-X13"},{"t":"7개","mis":"M6-1-u1-X13"},{"t":"9개","mis":"M6-1-u1-X13"}],"explanation":["양쪽에서 파란 뚜껑 2개씩을 덜어 내도 저울은 수평이에요.","왼쪽엔 노란 뚜껑 1개, 오른쪽엔 파란 뚜껑 7 − 2 = 5개가 남아요.","그래서 노란 뚜껑 1개는 파란 뚜껑 5개와 같아요."]},{"stem":"저울에서 파란 뚜껑 2개와 노란 뚜껑 1개의 무게가 파란 뚜껑 5개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개는 파란 뚜껑 몇 개와 무게가 같나요?","options":[{"t":"3개","correct":true},{"t":"2개","mis":"M6-1-u1-X13"},{"t":"5개","mis":"M6-1-u1-X13"},{"t":"7개","mis":"M6-1-u1-X13"}],"explanation":["양쪽에서 파란 뚜껑 2개씩을 덜어 내도 저울은 수평이에요.","왼쪽엔 노란 뚜껑 1개, 오른쪽엔 파란 뚜껑 5 − 2 = 3개가 남아요.","그래서 노란 뚜껑 1개는 파란 뚜껑 3개와 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_c#9','math',6,1,'u1','','g6_1_math_u1_review_c','unit_review','M6-1-u1-C1',2,'mc','auto','피자 4판을 9명이 똑같이 나누어 먹으려고 해요. 한 명이 먹는 피자를 구하는 식으로 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u1-X14']::text[],true,'{"seq":9,"concept":"M6-1-u1-C1","difficulty":2,"kind":"mc","stem":"피자 4판을 9명이 똑같이 나누어 먹으려고 해요. 한 명이 먹는 피자를 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"4 ÷ 9","correct":true},{"t":"9 ÷ 4","mis":"M6-1-u1-X14"},{"t":"4 × 9","mis":"M6-1-u1-X14"},{"t":"4 + 9","mis":"M6-1-u1-X14"}],"explanation":["전체 4판을 9로 똑같이 나누는 거예요.","나누어지는 수 4가 앞, 나누는 수 9가 뒤에 와요.","그래서 식은 4 ÷ 9예요."],"variant_rule":{"alt":[{"stem":"흰 종이 3장을 8명이 똑같이 나누어 가지려고 해요. 한 명이 가지는 흰 종이를 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"3 ÷ 8","correct":true},{"t":"8 ÷ 3","mis":"M6-1-u1-X14"},{"t":"3 × 8","mis":"M6-1-u1-X14"},{"t":"3 + 8","mis":"M6-1-u1-X14"}],"explanation":["전체 3장을 8로 똑같이 나누는 거예요.","나누어지는 수 3이 앞, 나누는 수 8이 뒤에 와요.","그래서 식은 3 ÷ 8이에요."]},{"stem":"시루떡 2개를 5명이 똑같이 나누어 먹으려고 해요. 한 명이 먹는 시루떡을 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"2 ÷ 5","correct":true},{"t":"5 ÷ 2","mis":"M6-1-u1-X14"},{"t":"2 × 5","mis":"M6-1-u1-X14"},{"t":"2 + 5","mis":"M6-1-u1-X14"}],"explanation":["전체 2개를 5로 똑같이 나누는 거예요.","나누어지는 수 2가 앞, 나누는 수 5가 뒤에 와요.","그래서 식은 2 ÷ 5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_c#10','math',6,1,'u1','','g6_1_math_u1_review_c','unit_review','M6-1-u1-C3',2,'mc','auto','시루떡 7개를 2명이 똑같이 나누어 먹으려고 해요. 한 명이 먹는 시루떡을 대분수로 나타내면 몇 개인가요?',ARRAY['M6-1-u1-X01','M6-1-u1-X02','M6-1-u1-X04']::text[],true,'{"seq":10,"concept":"M6-1-u1-C3","difficulty":2,"kind":"mc","stem":"시루떡 7개를 2명이 똑같이 나누어 먹으려고 해요. 한 명이 먹는 시루떡을 대분수로 나타내면 몇 개인가요?","options":[{"t":"⟨3 1/2⟩","correct":true},{"t":"⟨2/7⟩","mis":"M6-1-u1-X01"},{"t":"⟨1/2⟩","mis":"M6-1-u1-X02"},{"t":"⟨3 1/7⟩","mis":"M6-1-u1-X04"}],"explanation":["먼저 3씩 나누어 주면 1이 남아요 — 7 ÷ 2는 몫 3, 나머지 1이에요.","남은 1도 2로 똑같이 나누면 ⟨1/2⟩씩 더 가져요.","7 ÷ 2 = ⟨3 1/2⟩ — ⟨3 1/2⟩개예요."],"variant_rule":{"alt":[{"stem":"피자 8판을 3명이 똑같이 나누어 먹으려고 해요. 한 명이 먹는 피자를 대분수로 나타내면 몇 판인가요?","options":[{"t":"⟨2 2/3⟩","correct":true},{"t":"⟨3/8⟩","mis":"M6-1-u1-X01"},{"t":"⟨2/3⟩","mis":"M6-1-u1-X02"},{"t":"⟨2 1/4⟩","mis":"M6-1-u1-X04"}],"explanation":["먼저 2씩 나누어 주면 2가 남아요 — 8 ÷ 3은 몫 2, 나머지 2예요.","남은 2도 3으로 똑같이 나누면 ⟨2/3⟩씩 더 가져요.","8 ÷ 3 = ⟨2 2/3⟩ — ⟨2 2/3⟩판예요."]},{"stem":"흰 종이 5장을 3명이 똑같이 나누어 가지려고 해요. 한 명이 가지는 흰 종이를 대분수로 나타내면 몇 장인가요?","options":[{"t":"⟨1 2/3⟩","correct":true},{"t":"⟨3/5⟩","mis":"M6-1-u1-X01"},{"t":"⟨2/3⟩","mis":"M6-1-u1-X02"},{"t":"⟨1 2/5⟩","mis":"M6-1-u1-X04"}],"explanation":["먼저 1씩 나누어 주면 2가 남아요 — 5 ÷ 3은 몫 1, 나머지 2예요.","남은 2도 3으로 똑같이 나누면 ⟨2/3⟩씩 더 가져요.","5 ÷ 3 = ⟨1 2/3⟩ — ⟨1 2/3⟩장예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_c#11','math',6,1,'u1','','g6_1_math_u1_review_c','unit_review','M6-1-u1-C4',2,'sa','auto','4 ÷ 13 = 4 × ⟨1/□⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":11,"concept":"M6-1-u1-C4","difficulty":2,"kind":"sa","stem":"4 ÷ 13 = 4 × ⟨1/□⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["÷ 13은 13으로 나눈 것 중의 1이에요.","그래서 ⟨1/13⟩을 곱하는 것과 같아요.","4 ÷ 13 = 4 × ⟨1/13⟩ — □는 13이에요."],"mis":"M6-1-u1-X07","variant_rule":{"alt":[{"stem":"12 ÷ 5 = 12 × ⟨1/□⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["÷ 5는 5로 나눈 것 중의 1이에요.","그래서 ⟨1/5⟩을 곱하는 것과 같아요.","12 ÷ 5 = 12 × ⟨1/5⟩ — □는 5예요."]},{"stem":"7 ÷ 8 = 7 × ⟨1/□⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["÷ 8은 8로 나눈 것 중의 1이에요.","그래서 ⟨1/8⟩을 곱하는 것과 같아요.","7 ÷ 8 = 7 × ⟨1/8⟩ — □는 8이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_c#12','math',6,1,'u1','','g6_1_math_u1_review_c','unit_review','M6-1-u1-C5',2,'sa','auto','⟨9/13⟩ ÷ 3의 몫은 ⟨1/13⟩이 몇 개인 수인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":12,"concept":"M6-1-u1-C5","difficulty":2,"kind":"sa","stem":"⟨9/13⟩ ÷ 3의 몫은 ⟨1/13⟩이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["⟨9/13⟩는 ⟨1/13⟩이 9개예요.","9개를 3으로 똑같이 나누면 9 ÷ 3 = 3개예요.","⟨9/13⟩ ÷ 3 = ⟨3/13⟩ — ⟨1/13⟩이 3개예요."],"mis":"M6-1-u1-X08","variant_rule":{"alt":[{"stem":"⟨12/13⟩ ÷ 4의 몫은 ⟨1/13⟩이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["⟨12/13⟩는 ⟨1/13⟩이 12개예요.","12개를 4로 똑같이 나누면 12 ÷ 4 = 3개예요.","⟨12/13⟩ ÷ 4 = ⟨3/13⟩ — ⟨1/13⟩이 3개예요."]},{"stem":"⟨8/9⟩ ÷ 4의 몫은 ⟨1/9⟩이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["⟨8/9⟩은 ⟨1/9⟩이 8개예요.","8개를 4로 똑같이 나누면 8 ÷ 4 = 2개예요.","⟨8/9⟩ ÷ 4 = ⟨2/9⟩ — ⟨1/9⟩이 2개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_c#13','math',6,1,'u1','','g6_1_math_u1_review_c','unit_review','M6-1-u1-C5',2,'mc','auto','⟨1/6⟩ ÷ 3을 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M6-1-u1-X06','M6-1-u1-X07']::text[],true,'{"seq":13,"concept":"M6-1-u1-C5","difficulty":2,"kind":"mc","stem":"⟨1/6⟩ ÷ 3을 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨1/6⟩ × ⟨1/3⟩","correct":true},{"t":"⟨1/6⟩ × 3","mis":"M6-1-u1-X06"},{"t":"⟨6/1⟩ × ⟨1/3⟩","mis":"M6-1-u1-X07"},{"t":"3 × ⟨1/6⟩","mis":"M6-1-u1-X06"}],"explanation":["÷ 3은 3으로 똑같이 나눈 것 중의 1이에요.","그래서 × ⟨1/3⟩과 같아요.","⟨1/6⟩ ÷ 3 = ⟨1/6⟩ × ⟨1/3⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨5/12⟩ ÷ 7을 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨5/12⟩ × ⟨1/7⟩","correct":true},{"t":"⟨5/12⟩ × 7","mis":"M6-1-u1-X06"},{"t":"⟨12/5⟩ × ⟨1/7⟩","mis":"M6-1-u1-X07"},{"t":"7 × ⟨5/12⟩","mis":"M6-1-u1-X06"}],"explanation":["÷ 7은 7로 똑같이 나눈 것 중의 1이에요.","그래서 × ⟨1/7⟩과 같아요.","⟨5/12⟩ ÷ 7 = ⟨5/12⟩ × ⟨1/7⟩이에요."]},{"stem":"⟨4/9⟩ ÷ 5를 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨4/9⟩ × ⟨1/5⟩","correct":true},{"t":"⟨4/9⟩ × 5","mis":"M6-1-u1-X06"},{"t":"⟨9/4⟩ × ⟨1/5⟩","mis":"M6-1-u1-X07"},{"t":"5 × ⟨4/9⟩","mis":"M6-1-u1-X06"}],"explanation":["÷ 5는 5로 똑같이 나눈 것 중의 1이에요.","그래서 × ⟨1/5⟩과 같아요.","⟨4/9⟩ ÷ 5 = ⟨4/9⟩ × ⟨1/5⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_c#14','math',6,1,'u1','','g6_1_math_u1_review_c','unit_review','M6-1-u1-C6',2,'mc','auto','⟨3 3/5⟩ ÷ 6을 계산하면 얼마인가요?',ARRAY['M6-1-u1-X10','M6-1-u1-X06']::text[],true,'{"seq":14,"concept":"M6-1-u1-C6","difficulty":2,"kind":"mc","stem":"⟨3 3/5⟩ ÷ 6을 계산하면 얼마인가요?","options":[{"t":"⟨3/5⟩","correct":true},{"t":"⟨3 1/10⟩","mis":"M6-1-u1-X10"},{"t":"⟨1 1/10⟩","mis":"M6-1-u1-X10"},{"t":"⟨21 3/5⟩","mis":"M6-1-u1-X06"}],"explanation":["⟨3 3/5⟩을 가분수로 고치면 ⟨18/5⟩이에요.","⟨18/5⟩ ÷ 6 = ⟨18/5⟩ × ⟨1/6⟩이에요.","⟨18/5⟩ × ⟨1/6⟩ = ⟨3/5⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨1 4/5⟩ ÷ 3을 계산하면 얼마인가요?","options":[{"t":"⟨3/5⟩","correct":true},{"t":"⟨1 4/15⟩","mis":"M6-1-u1-X10"},{"t":"⟨1 2/15⟩","mis":"M6-1-u1-X10"},{"t":"⟨5 2/5⟩","mis":"M6-1-u1-X06"}],"explanation":["⟨1 4/5⟩를 가분수로 고치면 ⟨9/5⟩예요.","⟨9/5⟩ ÷ 3 = ⟨9/5⟩ × ⟨1/3⟩이에요.","⟨9/5⟩ × ⟨1/3⟩ = ⟨3/5⟩이에요."]},{"stem":"⟨1 1/4⟩ ÷ 5를 계산하면 얼마인가요?","options":[{"t":"⟨1/4⟩","correct":true},{"t":"⟨1 1/20⟩","mis":"M6-1-u1-X10"},{"t":"⟨9/20⟩","mis":"M6-1-u1-X10"},{"t":"⟨6 1/4⟩","mis":"M6-1-u1-X06"}],"explanation":["⟨1 1/4⟩을 가분수로 고치면 ⟨5/4⟩예요.","⟨5/4⟩ ÷ 5 = ⟨5/4⟩ × ⟨1/5⟩이에요.","⟨5/4⟩ × ⟨1/5⟩ = ⟨1/4⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_c#15','math',6,1,'u1','','g6_1_math_u1_review_c','unit_review','M6-1-u1-C6',2,'sa','auto','⟨1 7/9⟩ ÷ 4를 계산하려고 ⟨1 7/9⟩을 가분수로 고쳤어요. 가분수의 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":15,"concept":"M6-1-u1-C6","difficulty":2,"kind":"sa","stem":"⟨1 7/9⟩ ÷ 4를 계산하려고 ⟨1 7/9⟩을 가분수로 고쳤어요. 가분수의 분자는 얼마인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["대분수는 먼저 가분수로 고쳐요.","1 × 9 + 7 = 16이에요.","⟨1 7/9⟩ = ⟨16/9⟩ — 분자는 16이에요."],"mis":"M6-1-u1-X05","variant_rule":{"alt":[{"stem":"⟨4 3/7⟩ ÷ 6을 계산하려고 ⟨4 3/7⟩을 가분수로 고쳤어요. 가분수의 분자는 얼마인가요? 숫자로 쓰세요.","answer":["31"],"explanation":["대분수는 먼저 가분수로 고쳐요.","4 × 7 + 3 = 31이에요.","⟨4 3/7⟩ = ⟨31/7⟩ — 분자는 31이에요."]},{"stem":"⟨2 3/8⟩ ÷ 5를 계산하려고 ⟨2 3/8⟩을 가분수로 고쳤어요. 가분수의 분자는 얼마인가요? 숫자로 쓰세요.","answer":["19"],"explanation":["대분수는 먼저 가분수로 고쳐요.","2 × 8 + 3 = 19예요.","⟨2 3/8⟩ = ⟨19/8⟩ — 분자는 19예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_c#16','math',6,1,'u1','','g6_1_math_u1_review_c','unit_review','M6-1-u1-C7',2,'mc','auto','파란 뚜껑 3개와 노란 뚜껑 1개의 무게가 파란 뚜껑 7개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개의 무게가 ⟨6 2/3⟩ g일 때, 파란 뚜껑 1개의 무게는 몇 g인가요?',ARRAY['M6-1-u1-X13','M6-1-u1-X06']::text[],true,'{"seq":16,"concept":"M6-1-u1-C7","difficulty":2,"kind":"mc","stem":"파란 뚜껑 3개와 노란 뚜껑 1개의 무게가 파란 뚜껑 7개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개의 무게가 ⟨6 2/3⟩ g일 때, 파란 뚜껑 1개의 무게는 몇 g인가요?","options":[{"t":"⟨1 2/3⟩","correct":true},{"t":"⟨20/21⟩","mis":"M6-1-u1-X13"},{"t":"⟨2 2/9⟩","mis":"M6-1-u1-X13"},{"t":"⟨26 2/3⟩","mis":"M6-1-u1-X06"}],"explanation":["양쪽에서 파란 3개씩 덜어 내면 노란 1개 = 파란 4개예요.","⟨6 2/3⟩ = ⟨20/3⟩이에요.","⟨20/3⟩ × ⟨1/4⟩ = ⟨1 2/3⟩ — 파란 뚜껑 1개는 ⟨1 2/3⟩ g이에요."],"variant_rule":{"alt":[{"stem":"파란 뚜껑 2개와 노란 뚜껑 1개의 무게가 파란 뚜껑 4개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개의 무게가 ⟨3 1/5⟩ g일 때, 파란 뚜껑 1개의 무게는 몇 g인가요?","options":[{"t":"⟨1 3/5⟩","correct":true},{"t":"⟨4/5⟩","mis":"M6-1-u1-X13"},{"t":"⟨6 2/5⟩","mis":"M6-1-u1-X06"},{"t":"⟨8/15⟩","mis":"M6-1-u1-X13"}],"explanation":["양쪽에서 파란 2개씩 덜어 내면 노란 1개 = 파란 2개예요.","⟨3 1/5⟩ = ⟨16/5⟩이에요.","⟨16/5⟩ × ⟨1/2⟩ = ⟨1 3/5⟩ — 파란 뚜껑 1개는 ⟨1 3/5⟩ g이에요."]},{"stem":"파란 뚜껑 2개와 노란 뚜껑 1개의 무게가 파란 뚜껑 5개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개의 무게가 ⟨5 1/4⟩ g일 때, 파란 뚜껑 1개의 무게는 몇 g인가요?","options":[{"t":"⟨1 3/4⟩","correct":true},{"t":"⟨1 1/20⟩","mis":"M6-1-u1-X13"},{"t":"⟨2 5/8⟩","mis":"M6-1-u1-X13"},{"t":"⟨15 3/4⟩","mis":"M6-1-u1-X06"}],"explanation":["양쪽에서 파란 2개씩 덜어 내면 노란 1개 = 파란 3개예요.","⟨5 1/4⟩ = ⟨21/4⟩이에요.","⟨21/4⟩ × ⟨1/3⟩ = ⟨1 3/4⟩ — 파란 뚜껑 1개는 ⟨1 3/4⟩ g이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_c#17','math',6,1,'u1','','g6_1_math_u1_review_c','unit_review','M6-1-u1-C2',3,'mc','auto','가 모둠은 빵 5개를 7명이, 나 모둠은 빵 3개를 4명이 똑같이 나누었어요. 한 명이 가지는 빵이 더 많은 모둠은 어디인가요?',ARRAY['M6-1-u1-X11','M6-1-u1-X03']::text[],true,'{"seq":17,"concept":"M6-1-u1-C2","difficulty":3,"kind":"mc","stem":"가 모둠은 빵 5개를 7명이, 나 모둠은 빵 3개를 4명이 똑같이 나누었어요. 한 명이 가지는 빵이 더 많은 모둠은 어디인가요?","options":[{"t":"나 모둠","correct":true},{"t":"가 모둠","mis":"M6-1-u1-X11"},{"t":"두 모둠이 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X03"}],"explanation":["가 모둠 한 명 몫은 5 ÷ 7 = ⟨5/7⟩, 나 모둠은 3 ÷ 4 = ⟨3/4⟩이에요.","28로 통분하면 ⟨5/7⟩ = ⟨20/28⟩, ⟨3/4⟩ = ⟨21/28⟩이에요.","⟨5/7⟩ < ⟨3/4⟩이라 나 모둠이 더 많아요."],"variant_rule":{"alt":[{"stem":"가 모둠은 피자 3판을 5명이, 나 모둠은 피자 5판을 8명이 똑같이 나누었어요. 한 명이 가지는 피자가 더 많은 모둠은 어디인가요?","options":[{"t":"나 모둠","correct":true},{"t":"가 모둠","mis":"M6-1-u1-X11"},{"t":"두 모둠이 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X03"}],"explanation":["가 모둠 한 명 몫은 3 ÷ 5 = ⟨3/5⟩, 나 모둠은 5 ÷ 8 = ⟨5/8⟩예요.","40으로 통분하면 ⟨3/5⟩ = ⟨24/40⟩, ⟨5/8⟩ = ⟨25/40⟩예요.","⟨3/5⟩ < ⟨5/8⟩라 나 모둠이 더 많아요."]},{"stem":"가 모둠은 시루떡 2개를 5명이, 나 모둠은 시루떡 3개를 7명이 똑같이 나누었어요. 한 명이 가지는 시루떡이 더 많은 모둠은 어디인가요?","options":[{"t":"나 모둠","correct":true},{"t":"가 모둠","mis":"M6-1-u1-X11"},{"t":"두 모둠이 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X03"}],"explanation":["가 모둠 한 명 몫은 2 ÷ 5 = ⟨2/5⟩, 나 모둠은 3 ÷ 7 = ⟨3/7⟩이에요.","35로 통분하면 ⟨2/5⟩ = ⟨14/35⟩, ⟨3/7⟩ = ⟨15/35⟩예요.","⟨2/5⟩ < ⟨3/7⟩이라 나 모둠이 더 많아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_c#18','math',6,1,'u1','','g6_1_math_u1_review_c','unit_review','M6-1-u1-C3',3,'sa','auto','색 모래 25 kg을 7모둠이 똑같이 나누어 가지려고 해요. 한 모둠이 가지는 색 모래를 대분수로 나타낼 때, 자연수 부분과 분자의 합은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":18,"concept":"M6-1-u1-C3","difficulty":3,"kind":"sa","stem":"색 모래 25 kg을 7모둠이 똑같이 나누어 가지려고 해요. 한 모둠이 가지는 색 모래를 대분수로 나타낼 때, 자연수 부분과 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["25 ÷ 7은 몫 3, 나머지 4예요.","남은 4도 나누면 25 ÷ 7 = ⟨3 4/7⟩예요.","자연수 부분과 분자의 합은 3 + 4 = 7이에요."],"mis":"M6-1-u1-X15","variant_rule":{"alt":[{"stem":"주스 13 L를 3명이 똑같이 나누어 마시려고 해요. 한 명이 마시는 주스를 대분수로 나타낼 때, 자연수 부분과 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["13 ÷ 3은 몫 4, 나머지 1이에요.","남은 1도 나누면 13 ÷ 3 = ⟨4 1/3⟩이에요.","자연수 부분과 분자의 합은 4 + 1 = 5예요."]},{"stem":"쌀 19 kg을 4봉지에 똑같이 나누어 담으려고 해요. 한 봉지에 담는 쌀을 대분수로 나타낼 때, 자연수 부분과 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["19 ÷ 4는 몫 4, 나머지 3이에요.","남은 3도 나누면 19 ÷ 4 = ⟨4 3/4⟩이에요.","자연수 부분과 분자의 합은 4 + 3 = 7이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_c#19','math',6,1,'u1','','g6_1_math_u1_review_c','unit_review','M6-1-u1-C4',3,'mc','auto','끈 10 m를 3도막으로 나눈 한 도막과 끈 13 m를 4도막으로 나눈 한 도막 가운데 더 긴 것은 어느 것인가요?',ARRAY['M6-1-u1-X11','M6-1-u1-X03']::text[],true,'{"seq":19,"concept":"M6-1-u1-C4","difficulty":3,"kind":"mc","stem":"끈 10 m를 3도막으로 나눈 한 도막과 끈 13 m를 4도막으로 나눈 한 도막 가운데 더 긴 것은 어느 것인가요?","options":[{"t":"끈 10 m를 3도막으로 나눈 한 도막","correct":true},{"t":"끈 13 m를 4도막으로 나눈 한 도막","mis":"M6-1-u1-X11"},{"t":"두 도막의 길이가 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X03"}],"explanation":["10 ÷ 3 = 10 × ⟨1/3⟩ = ⟨3 1/3⟩, 13 ÷ 4 = 13 × ⟨1/4⟩ = ⟨3 1/4⟩이에요.","12로 통분하면 ⟨3 1/3⟩ = ⟨40/12⟩, ⟨3 1/4⟩ = ⟨39/12⟩예요.","그래서 더 긴 것은 끈 10 m를 3도막으로 나눈 한 도막이에요."],"variant_rule":{"alt":[{"stem":"끈 8 m를 7도막으로 나눈 한 도막과 끈 9 m를 8도막으로 나눈 한 도막 가운데 더 긴 것은 어느 것인가요?","options":[{"t":"끈 8 m를 7도막으로 나눈 한 도막","correct":true},{"t":"끈 9 m를 8도막으로 나눈 한 도막","mis":"M6-1-u1-X11"},{"t":"두 도막의 길이가 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X03"}],"explanation":["8 ÷ 7 = 8 × ⟨1/7⟩ = ⟨1 1/7⟩, 9 ÷ 8 = 9 × ⟨1/8⟩ = ⟨1 1/8⟩이에요.","56으로 통분하면 ⟨1 1/7⟩ = ⟨64/56⟩, ⟨1 1/8⟩ = ⟨63/56⟩이에요.","그래서 더 긴 것은 끈 8 m를 7도막으로 나눈 한 도막이에요."]},{"stem":"끈 9 m를 4도막으로 나눈 한 도막과 끈 7 m를 3도막으로 나눈 한 도막 가운데 더 긴 것은 어느 것인가요?","options":[{"t":"끈 7 m를 3도막으로 나눈 한 도막","correct":true},{"t":"끈 9 m를 4도막으로 나눈 한 도막","mis":"M6-1-u1-X11"},{"t":"두 도막의 길이가 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X03"}],"explanation":["9 ÷ 4 = 9 × ⟨1/4⟩ = ⟨2 1/4⟩, 7 ÷ 3 = 7 × ⟨1/3⟩ = ⟨2 1/3⟩이에요.","12로 통분하면 ⟨2 1/4⟩ = ⟨27/12⟩, ⟨2 1/3⟩ = ⟨28/12⟩이에요.","그래서 더 긴 것은 끈 7 m를 3도막으로 나눈 한 도막이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_c#20','math',6,1,'u1','','g6_1_math_u1_review_c','unit_review','M6-1-u1-C5',3,'error','auto','⟨3/10⟩ ÷ 4에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u1-X06','M6-1-u1-X15']::text[],true,'{"seq":20,"concept":"M6-1-u1-C5","difficulty":3,"kind":"error","stem":"⟨3/10⟩ ÷ 4에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「⟨3/10⟩ × 4 = ⟨1 1/5⟩로 계산해.」","correct":true,"mis_target":"M6-1-u1-X06"},{"t":"나린 — 「⟨3/10⟩ × ⟨1/4⟩로 바꾸어 계산하면 돼.」","mis":"M6-1-u1-X15"},{"t":"유진 — 「몫은 ⟨3/10⟩보다 작아.」","mis":"M6-1-u1-X15"}],"explanation":["4로 나누면 양이 작아져야 해요.","⟨3/10⟩ × 4 = ⟨1 1/5⟩은 오히려 커요.","⟨3/10⟩ ÷ 4 = ⟨3/10⟩ × ⟨1/4⟩ = ⟨3/40⟩ — 가온은 나누는 수를 그대로 곱했어요."],"variant_rule":{"alt":[{"stem":"⟨7/8⟩ ÷ 2에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"여울 — 「⟨7/8⟩ × 2 = ⟨1 3/4⟩으로 계산해.」","correct":true,"mis_target":"M6-1-u1-X06"},{"t":"라온 — 「⟨7/8⟩ × ⟨1/2⟩로 바꾸어 계산하면 돼.」","mis":"M6-1-u1-X15"},{"t":"예준 — 「몫은 ⟨7/8⟩보다 작아.」","mis":"M6-1-u1-X15"}],"explanation":["2로 나누면 양이 작아져야 해요.","⟨7/8⟩ × 2 = ⟨1 3/4⟩은 오히려 커요.","⟨7/8⟩ ÷ 2 = ⟨7/8⟩ × ⟨1/2⟩ = ⟨7/16⟩ — 여울은 나누는 수를 그대로 곱했어요."]},{"stem":"⟨4/7⟩ ÷ 3에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「⟨4/7⟩ × 3 = ⟨1 5/7⟩로 계산해.」","correct":true,"mis_target":"M6-1-u1-X06"},{"t":"도윤 — 「⟨4/7⟩ × ⟨1/3⟩로 바꾸어 계산하면 돼.」","mis":"M6-1-u1-X15"},{"t":"하린 — 「몫은 ⟨4/7⟩보다 작아.」","mis":"M6-1-u1-X15"}],"explanation":["3으로 나누면 양이 작아져야 해요.","⟨4/7⟩ × 3 = ⟨1 5/7⟩는 오히려 커요.","⟨4/7⟩ ÷ 3 = ⟨4/7⟩ × ⟨1/3⟩ = ⟨4/21⟩ — 수아는 나누는 수를 그대로 곱했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_c#21','math',6,1,'u1','','g6_1_math_u1_review_c','unit_review','M6-1-u1-C6',3,'mc','auto','넓이가 ⟨3 3/5⟩ m²이고 가로가 4 m인 직사각형이 있어요. 세로는 몇 m인가요?',ARRAY['M6-1-u1-X10','M6-1-u1-X06']::text[],true,'{"seq":21,"concept":"M6-1-u1-C6","difficulty":3,"kind":"mc","stem":"넓이가 ⟨3 3/5⟩ m²이고 가로가 4 m인 직사각형이 있어요. 세로는 몇 m인가요?","options":[{"t":"⟨9/10⟩","correct":true},{"t":"⟨3 3/20⟩","mis":"M6-1-u1-X10"},{"t":"⟨1 7/20⟩","mis":"M6-1-u1-X10"},{"t":"⟨14 2/5⟩","mis":"M6-1-u1-X06"}],"explanation":["(직사각형의 넓이) = (가로) × (세로)이니 세로 = 넓이 ÷ 가로예요.","⟨3 3/5⟩ ÷ 4 = ⟨18/5⟩ × ⟨1/4⟩이에요.","⟨18/5⟩ × ⟨1/4⟩ = ⟨9/10⟩ — 세로는 ⟨9/10⟩ m예요."],"variant_rule":{"alt":[{"stem":"넓이가 ⟨6 2/3⟩ m²이고 가로가 5 m인 직사각형이 있어요. 세로는 몇 m인가요?","options":[{"t":"⟨1 1/3⟩","correct":true},{"t":"⟨6 2/15⟩","mis":"M6-1-u1-X10"},{"t":"⟨1 13/15⟩","mis":"M6-1-u1-X10"},{"t":"⟨33 1/3⟩","mis":"M6-1-u1-X06"}],"explanation":["(직사각형의 넓이) = (가로) × (세로)이니 세로 = 넓이 ÷ 가로예요.","⟨6 2/3⟩ ÷ 5 = ⟨20/3⟩ × ⟨1/5⟩이에요.","⟨20/3⟩ × ⟨1/5⟩ = ⟨1 1/3⟩ — 세로는 ⟨1 1/3⟩ m예요."]},{"stem":"넓이가 ⟨4 2/3⟩ m²이고 가로가 3 m인 직사각형이 있어요. 세로는 몇 m인가요?","options":[{"t":"⟨1 5/9⟩","correct":true},{"t":"⟨4 2/9⟩","mis":"M6-1-u1-X10"},{"t":"2","mis":"M6-1-u1-X10"},{"t":"14","mis":"M6-1-u1-X06"}],"explanation":["(직사각형의 넓이) = (가로) × (세로)이니 세로 = 넓이 ÷ 가로예요.","⟨4 2/3⟩ ÷ 3 = ⟨14/3⟩ × ⟨1/3⟩이에요.","⟨14/3⟩ × ⟨1/3⟩ = ⟨1 5/9⟩ — 세로는 ⟨1 5/9⟩ m예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_c#22','math',6,1,'u1','','g6_1_math_u1_review_c','unit_review','M6-1-u1-C7',3,'sa','auto','조건을 바꾸어 보아요. 노란 뚜껑 1개가 ⟨4 4/5⟩ g이고 파란 뚜껑 6개와 무게가 같아요. 파란 뚜껑 1개의 무게를 기약분수(가분수)로 나타낼 때 분모와 분자의 합은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":22,"concept":"M6-1-u1-C7","difficulty":3,"kind":"sa","stem":"조건을 바꾸어 보아요. 노란 뚜껑 1개가 ⟨4 4/5⟩ g이고 파란 뚜껑 6개와 무게가 같아요. 파란 뚜껑 1개의 무게를 기약분수(가분수)로 나타낼 때 분모와 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["파란 뚜껑 1개 = ⟨4 4/5⟩ ÷ 6이에요.","⟨24/5⟩ ÷ 6 = ⟨24/5⟩ × ⟨1/6⟩ = ⟨4/5⟩예요.","분모와 분자의 합은 5 + 4 = 9예요."],"mis":"M6-1-u1-X15","variant_rule":{"alt":[{"stem":"조건을 바꾸어 보아요. 노란 뚜껑 1개가 ⟨1 5/7⟩ g이고 파란 뚜껑 4개와 무게가 같아요. 파란 뚜껑 1개의 무게를 기약분수(가분수)로 나타낼 때 분모와 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["파란 뚜껑 1개 = ⟨1 5/7⟩ ÷ 4예요.","⟨12/7⟩ ÷ 4 = ⟨12/7⟩ × ⟨1/4⟩ = ⟨3/7⟩이에요.","분모와 분자의 합은 7 + 3 = 10이에요."]},{"stem":"조건을 바꾸어 보아요. 노란 뚜껑 1개가 ⟨2 1/3⟩ g이고 파란 뚜껑 7개와 무게가 같아요. 파란 뚜껑 1개의 무게를 기약분수(가분수)로 나타낼 때 분모와 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["파란 뚜껑 1개 = ⟨2 1/3⟩ ÷ 7이에요.","⟨7/3⟩ ÷ 7 = ⟨7/3⟩ × ⟨1/7⟩ = ⟨1/3⟩이에요.","분모와 분자의 합은 3 + 1 = 4예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_c#23','math',6,1,'u1','','g6_1_math_u1_review_c','unit_review','M6-1-u1-C5',4,'sa','auto','⟨9/13⟩ ÷ □의 몫이 ⟨1/13⟩보다 클 때, □에 들어갈 수 있는 가장 큰 자연수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":23,"concept":"M6-1-u1-C5","difficulty":4,"kind":"sa","stem":"⟨9/13⟩ ÷ □의 몫이 ⟨1/13⟩보다 클 때, □에 들어갈 수 있는 가장 큰 자연수는 얼마인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["⟨9/13⟩는 ⟨1/13⟩이 9개예요.","□로 나눈 몫이 ⟨1/13⟩보다 크려면 9개를 □로 나눈 수가 1보다 커야 해요.","□는 9보다 작아야 하니 가장 큰 수는 8이에요."],"mis":"M6-1-u1-X11","variant_rule":{"alt":[{"stem":"자연수 부분이 □이고 분수 부분이 ⟨2/5⟩인 대분수를 4로 나누었더니 ⟨17/20⟩이 되었어요. □에 알맞은 자연수는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["나누기 전의 수는 ⟨17/20⟩ × 4예요.","⟨17/20⟩ × 4 = ⟨17/5⟩ = ⟨3 2/5⟩예요.","그래서 □는 3이에요."]},{"stem":"□ ÷ 11의 몫이 1보다 작을 때, □에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["□ ÷ 11 = ⟨□/11⟩이에요.","몫이 1보다 작으려면 □가 11보다 작아야 해요.","1부터 10까지 10개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_c#24','math',6,1,'u1','','g6_1_math_u1_review_c','unit_review','M6-1-u1-C2',4,'essay','teacher','3 ÷ 4의 몫이 1보다 작은 까닭을 「1 ÷ 4」를 이용해 설명하고, 몫을 분수로 나타내 보세요.','{}'::text[],false,'{"seq":24,"concept":"M6-1-u1-C2","difficulty":4,"kind":"essay","stem":"3 ÷ 4의 몫이 1보다 작은 까닭을 「1 ÷ 4」를 이용해 설명하고, 몫을 분수로 나타내 보세요.","answer_guide":{"answer":"예: 1 ÷ 4는 1을 4로 똑같이 나눈 한 조각이라 ⟨1/4⟩이다. 3 ÷ 4는 그런 조각이 3개이므로 ⟨3/4⟩이다. 나누어지는 수 3이 나누는 수 4보다 작아 4조각 가운데 3조각만 되므로 몫은 1보다 작다.","scoring_points":["1 ÷ 4 = ⟨1/4⟩을 썼는가","3 ÷ 4 = ⟨3/4⟩을 구했는가","나누어지는 수가 더 작아 1보다 작다고 설명했는가"]},"explanation":["1 ÷ 4 = ⟨1/4⟩이에요.","3 ÷ 4는 ⟨1/4⟩이 3개 — ⟨3/4⟩이에요.","3이 4보다 작아 몫은 1보다 작아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_c#25','math',6,1,'u1','','g6_1_math_u1_review_c','unit_review','M6-1-u1-C7',4,'essay','teacher','조건을 바꾸어 문제를 만들었어요. 「파란 뚜껑 1개와 노란 뚜껑 1개의 무게가 파란 뚜껑 3개의 무게와 같고, 노란 뚜껑 1개는 ⟨3 1/2⟩ g이에요.」 파란 뚜껑 1개의 무게를 구하는 과정을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"M6-1-u1-C7","difficulty":4,"kind":"essay","stem":"조건을 바꾸어 문제를 만들었어요. 「파란 뚜껑 1개와 노란 뚜껑 1개의 무게가 파란 뚜껑 3개의 무게와 같고, 노란 뚜껑 1개는 ⟨3 1/2⟩ g이에요.」 파란 뚜껑 1개의 무게를 구하는 과정을 쓰세요.","answer_guide":{"answer":"예: 양쪽에서 파란 뚜껑 1개씩을 덜어 내면 노란 뚜껑 1개는 파란 뚜껑 2개와 무게가 같다. 그래서 파란 뚜껑 1개는 ⟨3 1/2⟩ ÷ 2이다. ⟨3 1/2⟩ = ⟨7/2⟩이므로 ⟨7/2⟩ × ⟨1/2⟩ = ⟨7/4⟩ = ⟨1 3/4⟩ g이다.","scoring_points":["양쪽에서 덜어 내 노란 1개 = 파란 2개를 찾았는가","⟨3 1/2⟩ = ⟨7/2⟩로 고쳤는가","⟨1 3/4⟩ g을 구했는가"]},"explanation":["노란 1개 = 파란 2개예요.","⟨3 1/2⟩ = ⟨7/2⟩이에요.","⟨7/2⟩ × ⟨1/2⟩ = ⟨1 3/4⟩ g이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_d#1','math',6,1,'u1','','g6_1_math_u1_review_d','unit_review','M6-1-u1-C2',1,'mc','auto','식빵 1개를 3명이 똑같이 나누어 먹으려고 해요. 한 명이 먹는 식빵은 몇 개인지 분수로 나타내면 얼마인가요?',ARRAY['M6-1-u1-X01','M6-1-u1-X09']::text[],true,'{"seq":1,"concept":"M6-1-u1-C2","difficulty":1,"kind":"mc","stem":"식빵 1개를 3명이 똑같이 나누어 먹으려고 해요. 한 명이 먹는 식빵은 몇 개인지 분수로 나타내면 얼마인가요?","options":[{"t":"⟨1/3⟩","correct":true},{"t":"3","mis":"M6-1-u1-X01"},{"t":"⟨1/4⟩","mis":"M6-1-u1-X09"},{"t":"1","mis":"M6-1-u1-X01"}],"explanation":["식빵 1개를 3으로 똑같이 나누는 것은 1 ÷ 3이에요.","나누어지는 수 1은 분자, 나누는 수 3은 분모가 돼요.","1 ÷ 3 = ⟨1/3⟩ — ⟨1/3⟩개예요."],"variant_rule":{"alt":[{"stem":"시루떡 3개를 4명이 똑같이 나누어 먹으려고 해요. 한 명이 먹는 시루떡은 몇 개인지 분수로 나타내면 얼마인가요?","options":[{"t":"⟨3/4⟩","correct":true},{"t":"⟨1 1/3⟩","mis":"M6-1-u1-X01"},{"t":"⟨1/4⟩","mis":"M6-1-u1-X01"},{"t":"⟨3/7⟩","mis":"M6-1-u1-X09"}],"explanation":["시루떡 3개를 4로 똑같이 나누는 것은 3 ÷ 4예요.","나누어지는 수 3은 분자, 나누는 수 4는 분모가 돼요.","3 ÷ 4 = ⟨3/4⟩ — ⟨3/4⟩개예요."]},{"stem":"과자 반죽 2개를 5명이 똑같이 나누어 가지려고 해요. 한 명이 가지는 과자 반죽은 몇 개인지 분수로 나타내면 얼마인가요?","options":[{"t":"⟨2/5⟩","correct":true},{"t":"⟨2 1/2⟩","mis":"M6-1-u1-X01"},{"t":"⟨1/5⟩","mis":"M6-1-u1-X01"},{"t":"⟨2/7⟩","mis":"M6-1-u1-X09"}],"explanation":["과자 반죽 2개를 5로 똑같이 나누는 것은 2 ÷ 5예요.","나누어지는 수 2는 분자, 나누는 수 5는 분모가 돼요.","2 ÷ 5 = ⟨2/5⟩ — ⟨2/5⟩개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_d#2','math',6,1,'u1','','g6_1_math_u1_review_d','unit_review','M6-1-u1-C2',1,'sa','auto','6 ÷ 13의 몫을 분수로 나타낼 때 분모에 오는 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-1-u1-C2","difficulty":1,"kind":"sa","stem":"6 ÷ 13의 몫을 분수로 나타낼 때 분모에 오는 수는 얼마인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["(자연수)÷(자연수)의 몫은 분수로 나타낼 수 있어요.","나누어지는 수 6은 분자, 나누는 수 13은 분모예요.","6 ÷ 13 = ⟨6/13⟩이니 분모는 13이에요."],"mis":"M6-1-u1-X01","variant_rule":{"alt":[{"stem":"4 ÷ 7의 몫을 분수로 나타낼 때 분자에 오는 수는 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["(자연수)÷(자연수)의 몫은 분수로 나타낼 수 있어요.","나누어지는 수 4는 분자, 나누는 수 7은 분모예요.","4 ÷ 7 = ⟨4/7⟩니 분자는 4예요."]},{"stem":"5 ÷ 9의 몫을 분수로 나타낼 때 분모에 오는 수는 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["(자연수)÷(자연수)의 몫은 분수로 나타낼 수 있어요.","나누어지는 수 5는 분자, 나누는 수 9는 분모예요.","5 ÷ 9 = ⟨5/9⟩니 분모는 9예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_d#3','math',6,1,'u1','','g6_1_math_u1_review_d','unit_review','M6-1-u1-C3',1,'mc','auto','⟨2 5/6⟩를 가분수로 나타내면 어느 것인가요?',ARRAY['M6-1-u1-X01','M6-1-u1-X05']::text[],true,'{"seq":3,"concept":"M6-1-u1-C3","difficulty":1,"kind":"mc","stem":"⟨2 5/6⟩를 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨17/6⟩","correct":true},{"t":"⟨6/17⟩","mis":"M6-1-u1-X01"},{"t":"⟨7/6⟩","mis":"M6-1-u1-X05"},{"t":"⟨10/6⟩","mis":"M6-1-u1-X05"}],"explanation":["자연수 2는 ⟨12/6⟩예요 — 2 × 6 = 12.","여기에 ⟨5/6⟩를 더하면 분자는 12 + 5 = 17이에요.","⟨2 5/6⟩ = ⟨17/6⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨1 3/4⟩을 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨7/4⟩","correct":true},{"t":"⟨4/7⟩","mis":"M6-1-u1-X01"},{"t":"⟨4/4⟩","mis":"M6-1-u1-X05"},{"t":"⟨3/4⟩","mis":"M6-1-u1-X05"}],"explanation":["자연수 1은 ⟨4/4⟩예요 — 1 × 4 = 4.","여기에 ⟨3/4⟩을 더하면 분자는 4 + 3 = 7이에요.","⟨1 3/4⟩ = ⟨7/4⟩이에요."]},{"stem":"⟨2 2/5⟩를 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨12/5⟩","correct":true},{"t":"⟨5/12⟩","mis":"M6-1-u1-X01"},{"t":"⟨4/5⟩","mis":"M6-1-u1-X05"},{"t":"⟨22/5⟩","mis":"M6-1-u1-X05"}],"explanation":["자연수 2는 ⟨10/5⟩이에요 — 2 × 5 = 10.","여기에 ⟨2/5⟩를 더하면 분자는 10 + 2 = 12예요.","⟨2 2/5⟩ = ⟨12/5⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_d#4','math',6,1,'u1','','g6_1_math_u1_review_d','unit_review','M6-1-u1-C3',1,'sa','auto','23 ÷ 7의 몫을 대분수로 나타낼 때 분자에 오는 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M6-1-u1-C3","difficulty":1,"kind":"sa","stem":"23 ÷ 7의 몫을 대분수로 나타낼 때 분자에 오는 수는 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["23 ÷ 7은 몫 3, 나머지 2예요.","남은 2도 7로 나누면 ⟨2/7⟩ — 몫은 ⟨3 2/7⟩예요.","그래서 분자는 2예요."],"mis":"M6-1-u1-X04","variant_rule":{"alt":[{"stem":"15 ÷ 4의 몫을 대분수로 나타낼 때 자연수 부분에 오는 수는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["15 ÷ 4는 몫 3, 나머지 3이에요.","남은 3도 4로 나누면 ⟨3/4⟩ — 몫은 ⟨3 3/4⟩이에요.","그래서 자연수 부분은 3이에요."]},{"stem":"14 ÷ 3의 몫을 대분수로 나타낼 때 분자에 오는 수는 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["14 ÷ 3은 몫 4, 나머지 2예요.","남은 2도 3으로 나누면 ⟨2/3⟩ — 몫은 ⟨4 2/3⟩예요.","그래서 분자는 2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_d#5','math',6,1,'u1','','g6_1_math_u1_review_d','unit_review','M6-1-u1-C4',1,'mc','auto','4 ÷ 11을 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M6-1-u1-X06','M6-1-u1-X07']::text[],true,'{"seq":5,"concept":"M6-1-u1-C4","difficulty":1,"kind":"mc","stem":"4 ÷ 11을 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"4 × ⟨1/11⟩","correct":true},{"t":"4 × 11","mis":"M6-1-u1-X06"},{"t":"11 × ⟨1/4⟩","mis":"M6-1-u1-X07"},{"t":"⟨1/4⟩ × ⟨1/11⟩","mis":"M6-1-u1-X07"}],"explanation":["÷ 11은 11로 똑같이 나눈 것 중의 1이에요.","× ⟨1/11⟩도 11로 똑같이 나눈 것 중의 1이에요.","그래서 4 ÷ 11 = 4 × ⟨1/11⟩ = ⟨4/11⟩예요."],"variant_rule":{"alt":[{"stem":"6 ÷ 5를 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"6 × ⟨1/5⟩","correct":true},{"t":"6 × 5","mis":"M6-1-u1-X06"},{"t":"5 × ⟨1/6⟩","mis":"M6-1-u1-X07"},{"t":"⟨1/6⟩ × ⟨1/5⟩","mis":"M6-1-u1-X07"}],"explanation":["÷ 5는 5로 똑같이 나눈 것 중의 1이에요.","× ⟨1/5⟩도 5로 똑같이 나눈 것 중의 1이에요.","그래서 6 ÷ 5 = 6 × ⟨1/5⟩ = ⟨1 1/5⟩이에요."]},{"stem":"2 ÷ 9를 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"2 × ⟨1/9⟩","correct":true},{"t":"2 × 9","mis":"M6-1-u1-X06"},{"t":"9 × ⟨1/2⟩","mis":"M6-1-u1-X07"},{"t":"⟨1/2⟩ × ⟨1/9⟩","mis":"M6-1-u1-X07"}],"explanation":["÷ 9는 9로 똑같이 나눈 것 중의 1이에요.","× ⟨1/9⟩도 9로 똑같이 나눈 것 중의 1이에요.","그래서 2 ÷ 9 = 2 × ⟨1/9⟩ = ⟨2/9⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_d#6','math',6,1,'u1','','g6_1_math_u1_review_d','unit_review','M6-1-u1-C5',1,'mc','auto','⟨9/10⟩ ÷ 3을 계산하면 얼마인가요?',ARRAY['M6-1-u1-X06','M6-1-u1-X09','M6-1-u1-X07']::text[],true,'{"seq":6,"concept":"M6-1-u1-C5","difficulty":1,"kind":"mc","stem":"⟨9/10⟩ ÷ 3을 계산하면 얼마인가요?","options":[{"t":"⟨3/10⟩","correct":true},{"t":"⟨2 7/10⟩","mis":"M6-1-u1-X06"},{"t":"⟨9/13⟩","mis":"M6-1-u1-X09"},{"t":"⟨10/27⟩","mis":"M6-1-u1-X07"}],"explanation":["⟨9/10⟩는 ⟨1/10⟩이 9개예요.","분자 9를 3으로 나누면 9 ÷ 3 = 3 — ⟨1/10⟩이 3개예요.","그래서 ⟨9/10⟩ ÷ 3 = ⟨3/10⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨6/11⟩ ÷ 3을 계산하면 얼마인가요?","options":[{"t":"⟨2/11⟩","correct":true},{"t":"⟨1 7/11⟩","mis":"M6-1-u1-X06"},{"t":"⟨3/7⟩","mis":"M6-1-u1-X09"},{"t":"⟨11/18⟩","mis":"M6-1-u1-X07"}],"explanation":["⟨6/11⟩은 ⟨1/11⟩이 6개예요.","분자 6을 3으로 나누면 6 ÷ 3 = 2 — ⟨1/11⟩이 2개예요.","그래서 ⟨6/11⟩ ÷ 3 = ⟨2/11⟩예요."]},{"stem":"⟨4/9⟩ ÷ 2를 계산하면 얼마인가요?","options":[{"t":"⟨2/9⟩","correct":true},{"t":"⟨8/9⟩","mis":"M6-1-u1-X06"},{"t":"⟨4/11⟩","mis":"M6-1-u1-X09"},{"t":"⟨1 1/8⟩","mis":"M6-1-u1-X07"}],"explanation":["⟨4/9⟩는 ⟨1/9⟩이 4개예요.","분자 4를 2로 나누면 4 ÷ 2 = 2 — ⟨1/9⟩이 2개예요.","그래서 ⟨4/9⟩ ÷ 2 = ⟨2/9⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_d#7','math',6,1,'u1','','g6_1_math_u1_review_d','unit_review','M6-1-u1-C6',1,'mc','auto','⟨4 1/3⟩을 가분수로 나타내면 어느 것인가요?',ARRAY['M6-1-u1-X01','M6-1-u1-X05']::text[],true,'{"seq":7,"concept":"M6-1-u1-C6","difficulty":1,"kind":"mc","stem":"⟨4 1/3⟩을 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨13/3⟩","correct":true},{"t":"⟨3/13⟩","mis":"M6-1-u1-X01"},{"t":"⟨5/3⟩","mis":"M6-1-u1-X05"},{"t":"⟨4/3⟩","mis":"M6-1-u1-X05"}],"explanation":["자연수 4는 ⟨12/3⟩예요 — 4 × 3 = 12.","여기에 ⟨1/3⟩을 더하면 분자는 12 + 1 = 13이에요.","⟨4 1/3⟩ = ⟨13/3⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨1 5/6⟩를 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨11/6⟩","correct":true},{"t":"⟨6/11⟩","mis":"M6-1-u1-X01"},{"t":"⟨6/6⟩","mis":"M6-1-u1-X05"},{"t":"⟨5/6⟩","mis":"M6-1-u1-X05"}],"explanation":["자연수 1은 ⟨6/6⟩이에요 — 1 × 6 = 6.","여기에 ⟨5/6⟩를 더하면 분자는 6 + 5 = 11이에요.","⟨1 5/6⟩ = ⟨11/6⟩이에요."]},{"stem":"⟨3 2/7⟩를 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨23/7⟩","correct":true},{"t":"⟨7/23⟩","mis":"M6-1-u1-X01"},{"t":"⟨5/7⟩","mis":"M6-1-u1-X05"},{"t":"⟨6/7⟩","mis":"M6-1-u1-X05"}],"explanation":["자연수 3은 ⟨21/7⟩이에요 — 3 × 7 = 21.","여기에 ⟨2/7⟩를 더하면 분자는 21 + 2 = 23이에요.","⟨3 2/7⟩ = ⟨23/7⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_d#8','math',6,1,'u1','','g6_1_math_u1_review_d','unit_review','M6-1-u1-C7',1,'mc','auto','저울에서 파란 뚜껑 2개와 노란 뚜껑 1개의 무게가 파란 뚜껑 7개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개는 파란 뚜껑 몇 개와 무게가 같나요?',ARRAY['M6-1-u1-X13']::text[],true,'{"seq":8,"concept":"M6-1-u1-C7","difficulty":1,"kind":"mc","stem":"저울에서 파란 뚜껑 2개와 노란 뚜껑 1개의 무게가 파란 뚜껑 7개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개는 파란 뚜껑 몇 개와 무게가 같나요?","options":[{"t":"5개","correct":true},{"t":"2개","mis":"M6-1-u1-X13"},{"t":"7개","mis":"M6-1-u1-X13"},{"t":"9개","mis":"M6-1-u1-X13"}],"explanation":["양쪽에서 파란 뚜껑 2개씩을 덜어 내도 저울은 수평이에요.","왼쪽엔 노란 뚜껑 1개, 오른쪽엔 파란 뚜껑 7 − 2 = 5개가 남아요.","그래서 노란 뚜껑 1개는 파란 뚜껑 5개와 같아요."],"variant_rule":{"alt":[{"stem":"저울에서 파란 뚜껑 2개와 노란 뚜껑 1개의 무게가 파란 뚜껑 5개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개는 파란 뚜껑 몇 개와 무게가 같나요?","options":[{"t":"3개","correct":true},{"t":"2개","mis":"M6-1-u1-X13"},{"t":"5개","mis":"M6-1-u1-X13"},{"t":"7개","mis":"M6-1-u1-X13"}],"explanation":["양쪽에서 파란 뚜껑 2개씩을 덜어 내도 저울은 수평이에요.","왼쪽엔 노란 뚜껑 1개, 오른쪽엔 파란 뚜껑 5 − 2 = 3개가 남아요.","그래서 노란 뚜껑 1개는 파란 뚜껑 3개와 같아요."]},{"stem":"저울에서 파란 뚜껑 1개와 노란 뚜껑 1개의 무게가 파란 뚜껑 5개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개는 파란 뚜껑 몇 개와 무게가 같나요?","options":[{"t":"4개","correct":true},{"t":"1개","mis":"M6-1-u1-X13"},{"t":"5개","mis":"M6-1-u1-X13"},{"t":"6개","mis":"M6-1-u1-X13"}],"explanation":["양쪽에서 파란 뚜껑 1개씩을 덜어 내도 저울은 수평이에요.","왼쪽엔 노란 뚜껑 1개, 오른쪽엔 파란 뚜껑 5 − 1 = 4개가 남아요.","그래서 노란 뚜껑 1개는 파란 뚜껑 4개와 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_d#9','math',6,1,'u1','','g6_1_math_u1_review_d','unit_review','M6-1-u1-C1',2,'mc','auto','흰 종이 3장을 8명이 똑같이 나누어 가지려고 해요. 한 명이 가지는 흰 종이를 구하는 식으로 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u1-X14']::text[],true,'{"seq":9,"concept":"M6-1-u1-C1","difficulty":2,"kind":"mc","stem":"흰 종이 3장을 8명이 똑같이 나누어 가지려고 해요. 한 명이 가지는 흰 종이를 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"3 ÷ 8","correct":true},{"t":"8 ÷ 3","mis":"M6-1-u1-X14"},{"t":"3 × 8","mis":"M6-1-u1-X14"},{"t":"3 + 8","mis":"M6-1-u1-X14"}],"explanation":["전체 3장을 8로 똑같이 나누는 거예요.","나누어지는 수 3이 앞, 나누는 수 8이 뒤에 와요.","그래서 식은 3 ÷ 8이에요."],"variant_rule":{"alt":[{"stem":"시루떡 2개를 5명이 똑같이 나누어 먹으려고 해요. 한 명이 먹는 시루떡을 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"2 ÷ 5","correct":true},{"t":"5 ÷ 2","mis":"M6-1-u1-X14"},{"t":"2 × 5","mis":"M6-1-u1-X14"},{"t":"2 + 5","mis":"M6-1-u1-X14"}],"explanation":["전체 2개를 5로 똑같이 나누는 거예요.","나누어지는 수 2가 앞, 나누는 수 5가 뒤에 와요.","그래서 식은 2 ÷ 5예요."]},{"stem":"과자 반죽 3개를 7명이 똑같이 나누어 가지려고 해요. 한 명이 가지는 과자 반죽을 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"3 ÷ 7","correct":true},{"t":"7 ÷ 3","mis":"M6-1-u1-X14"},{"t":"3 × 7","mis":"M6-1-u1-X14"},{"t":"3 + 7","mis":"M6-1-u1-X14"}],"explanation":["전체 3개를 7로 똑같이 나누는 거예요.","나누어지는 수 3이 앞, 나누는 수 7이 뒤에 와요.","그래서 식은 3 ÷ 7이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_d#10','math',6,1,'u1','','g6_1_math_u1_review_d','unit_review','M6-1-u1-C3',2,'mc','auto','피자 8판을 3명이 똑같이 나누어 먹으려고 해요. 한 명이 먹는 피자를 대분수로 나타내면 몇 판인가요?',ARRAY['M6-1-u1-X01','M6-1-u1-X02','M6-1-u1-X04']::text[],true,'{"seq":10,"concept":"M6-1-u1-C3","difficulty":2,"kind":"mc","stem":"피자 8판을 3명이 똑같이 나누어 먹으려고 해요. 한 명이 먹는 피자를 대분수로 나타내면 몇 판인가요?","options":[{"t":"⟨2 2/3⟩","correct":true},{"t":"⟨3/8⟩","mis":"M6-1-u1-X01"},{"t":"⟨2/3⟩","mis":"M6-1-u1-X02"},{"t":"⟨2 1/4⟩","mis":"M6-1-u1-X04"}],"explanation":["먼저 2씩 나누어 주면 2가 남아요 — 8 ÷ 3은 몫 2, 나머지 2예요.","남은 2도 3으로 똑같이 나누면 ⟨2/3⟩씩 더 가져요.","8 ÷ 3 = ⟨2 2/3⟩ — ⟨2 2/3⟩판예요."],"variant_rule":{"alt":[{"stem":"흰 종이 5장을 3명이 똑같이 나누어 가지려고 해요. 한 명이 가지는 흰 종이를 대분수로 나타내면 몇 장인가요?","options":[{"t":"⟨1 2/3⟩","correct":true},{"t":"⟨3/5⟩","mis":"M6-1-u1-X01"},{"t":"⟨2/3⟩","mis":"M6-1-u1-X02"},{"t":"⟨1 2/5⟩","mis":"M6-1-u1-X04"}],"explanation":["먼저 1씩 나누어 주면 2가 남아요 — 5 ÷ 3은 몫 1, 나머지 2예요.","남은 2도 3으로 똑같이 나누면 ⟨2/3⟩씩 더 가져요.","5 ÷ 3 = ⟨1 2/3⟩ — ⟨1 2/3⟩장예요."]},{"stem":"빵 9개를 4명이 똑같이 나누어 먹으려고 해요. 한 명이 먹는 빵을 대분수로 나타내면 몇 개인가요?","options":[{"t":"⟨2 1/4⟩","correct":true},{"t":"⟨4/9⟩","mis":"M6-1-u1-X01"},{"t":"⟨1/4⟩","mis":"M6-1-u1-X02"},{"t":"⟨2 1/9⟩","mis":"M6-1-u1-X04"}],"explanation":["먼저 2씩 나누어 주면 1이 남아요 — 9 ÷ 4는 몫 2, 나머지 1이에요.","남은 1도 4로 똑같이 나누면 ⟨1/4⟩씩 더 가져요.","9 ÷ 4 = ⟨2 1/4⟩ — ⟨2 1/4⟩개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_d#11','math',6,1,'u1','','g6_1_math_u1_review_d','unit_review','M6-1-u1-C4',2,'sa','auto','12 ÷ 5 = 12 × ⟨1/□⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":11,"concept":"M6-1-u1-C4","difficulty":2,"kind":"sa","stem":"12 ÷ 5 = 12 × ⟨1/□⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["÷ 5는 5로 나눈 것 중의 1이에요.","그래서 ⟨1/5⟩을 곱하는 것과 같아요.","12 ÷ 5 = 12 × ⟨1/5⟩ — □는 5예요."],"mis":"M6-1-u1-X07","variant_rule":{"alt":[{"stem":"7 ÷ 8 = 7 × ⟨1/□⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["÷ 8은 8로 나눈 것 중의 1이에요.","그래서 ⟨1/8⟩을 곱하는 것과 같아요.","7 ÷ 8 = 7 × ⟨1/8⟩ — □는 8이에요."]},{"stem":"10 ÷ 3 = 10 × ⟨1/□⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["÷ 3은 3으로 나눈 것 중의 1이에요.","그래서 ⟨1/3⟩을 곱하는 것과 같아요.","10 ÷ 3 = 10 × ⟨1/3⟩ — □는 3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_d#12','math',6,1,'u1','','g6_1_math_u1_review_d','unit_review','M6-1-u1-C5',2,'sa','auto','⟨12/13⟩ ÷ 4의 몫은 ⟨1/13⟩이 몇 개인 수인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":12,"concept":"M6-1-u1-C5","difficulty":2,"kind":"sa","stem":"⟨12/13⟩ ÷ 4의 몫은 ⟨1/13⟩이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["⟨12/13⟩는 ⟨1/13⟩이 12개예요.","12개를 4로 똑같이 나누면 12 ÷ 4 = 3개예요.","⟨12/13⟩ ÷ 4 = ⟨3/13⟩ — ⟨1/13⟩이 3개예요."],"mis":"M6-1-u1-X08","variant_rule":{"alt":[{"stem":"⟨8/9⟩ ÷ 4의 몫은 ⟨1/9⟩이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["⟨8/9⟩은 ⟨1/9⟩이 8개예요.","8개를 4로 똑같이 나누면 8 ÷ 4 = 2개예요.","⟨8/9⟩ ÷ 4 = ⟨2/9⟩ — ⟨1/9⟩이 2개예요."]},{"stem":"⟨10/11⟩ ÷ 2의 몫은 ⟨1/11⟩이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["⟨10/11⟩은 ⟨1/11⟩이 10개예요.","10개를 2로 똑같이 나누면 10 ÷ 2 = 5개예요.","⟨10/11⟩ ÷ 2 = ⟨5/11⟩ — ⟨1/11⟩이 5개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_d#13','math',6,1,'u1','','g6_1_math_u1_review_d','unit_review','M6-1-u1-C5',2,'mc','auto','⟨5/12⟩ ÷ 7을 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M6-1-u1-X06','M6-1-u1-X07']::text[],true,'{"seq":13,"concept":"M6-1-u1-C5","difficulty":2,"kind":"mc","stem":"⟨5/12⟩ ÷ 7을 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨5/12⟩ × ⟨1/7⟩","correct":true},{"t":"⟨5/12⟩ × 7","mis":"M6-1-u1-X06"},{"t":"⟨12/5⟩ × ⟨1/7⟩","mis":"M6-1-u1-X07"},{"t":"7 × ⟨5/12⟩","mis":"M6-1-u1-X06"}],"explanation":["÷ 7은 7로 똑같이 나눈 것 중의 1이에요.","그래서 × ⟨1/7⟩과 같아요.","⟨5/12⟩ ÷ 7 = ⟨5/12⟩ × ⟨1/7⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨4/9⟩ ÷ 5를 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨4/9⟩ × ⟨1/5⟩","correct":true},{"t":"⟨4/9⟩ × 5","mis":"M6-1-u1-X06"},{"t":"⟨9/4⟩ × ⟨1/5⟩","mis":"M6-1-u1-X07"},{"t":"5 × ⟨4/9⟩","mis":"M6-1-u1-X06"}],"explanation":["÷ 5는 5로 똑같이 나눈 것 중의 1이에요.","그래서 × ⟨1/5⟩과 같아요.","⟨4/9⟩ ÷ 5 = ⟨4/9⟩ × ⟨1/5⟩이에요."]},{"stem":"⟨7/10⟩ ÷ 2를 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨7/10⟩ × ⟨1/2⟩","correct":true},{"t":"⟨7/10⟩ × 2","mis":"M6-1-u1-X06"},{"t":"⟨10/7⟩ × ⟨1/2⟩","mis":"M6-1-u1-X07"},{"t":"2 × ⟨7/10⟩","mis":"M6-1-u1-X06"}],"explanation":["÷ 2는 2로 똑같이 나눈 것 중의 1이에요.","그래서 × ⟨1/2⟩과 같아요.","⟨7/10⟩ ÷ 2 = ⟨7/10⟩ × ⟨1/2⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_d#14','math',6,1,'u1','','g6_1_math_u1_review_d','unit_review','M6-1-u1-C6',2,'mc','auto','⟨1 4/5⟩ ÷ 3을 계산하면 얼마인가요?',ARRAY['M6-1-u1-X10','M6-1-u1-X06']::text[],true,'{"seq":14,"concept":"M6-1-u1-C6","difficulty":2,"kind":"mc","stem":"⟨1 4/5⟩ ÷ 3을 계산하면 얼마인가요?","options":[{"t":"⟨3/5⟩","correct":true},{"t":"⟨1 4/15⟩","mis":"M6-1-u1-X10"},{"t":"⟨1 2/15⟩","mis":"M6-1-u1-X10"},{"t":"⟨5 2/5⟩","mis":"M6-1-u1-X06"}],"explanation":["⟨1 4/5⟩를 가분수로 고치면 ⟨9/5⟩예요.","⟨9/5⟩ ÷ 3 = ⟨9/5⟩ × ⟨1/3⟩이에요.","⟨9/5⟩ × ⟨1/3⟩ = ⟨3/5⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨1 1/4⟩ ÷ 5를 계산하면 얼마인가요?","options":[{"t":"⟨1/4⟩","correct":true},{"t":"⟨1 1/20⟩","mis":"M6-1-u1-X10"},{"t":"⟨9/20⟩","mis":"M6-1-u1-X10"},{"t":"⟨6 1/4⟩","mis":"M6-1-u1-X06"}],"explanation":["⟨1 1/4⟩을 가분수로 고치면 ⟨5/4⟩예요.","⟨5/4⟩ ÷ 5 = ⟨5/4⟩ × ⟨1/5⟩이에요.","⟨5/4⟩ × ⟨1/5⟩ = ⟨1/4⟩이에요."]},{"stem":"⟨2 1/3⟩ ÷ 7을 계산하면 얼마인가요?","options":[{"t":"⟨1/3⟩","correct":true},{"t":"⟨2 1/21⟩","mis":"M6-1-u1-X10"},{"t":"⟨13/21⟩","mis":"M6-1-u1-X10"},{"t":"⟨16 1/3⟩","mis":"M6-1-u1-X06"}],"explanation":["⟨2 1/3⟩을 가분수로 고치면 ⟨7/3⟩이에요.","⟨7/3⟩ ÷ 7 = ⟨7/3⟩ × ⟨1/7⟩이에요.","⟨7/3⟩ × ⟨1/7⟩ = ⟨1/3⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_d#15','math',6,1,'u1','','g6_1_math_u1_review_d','unit_review','M6-1-u1-C6',2,'sa','auto','⟨4 3/7⟩ ÷ 6을 계산하려고 ⟨4 3/7⟩을 가분수로 고쳤어요. 가분수의 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":15,"concept":"M6-1-u1-C6","difficulty":2,"kind":"sa","stem":"⟨4 3/7⟩ ÷ 6을 계산하려고 ⟨4 3/7⟩을 가분수로 고쳤어요. 가분수의 분자는 얼마인가요? 숫자로 쓰세요.","answer":["31"],"explanation":["대분수는 먼저 가분수로 고쳐요.","4 × 7 + 3 = 31이에요.","⟨4 3/7⟩ = ⟨31/7⟩ — 분자는 31이에요."],"mis":"M6-1-u1-X05","variant_rule":{"alt":[{"stem":"⟨2 3/8⟩ ÷ 5를 계산하려고 ⟨2 3/8⟩을 가분수로 고쳤어요. 가분수의 분자는 얼마인가요? 숫자로 쓰세요.","answer":["19"],"explanation":["대분수는 먼저 가분수로 고쳐요.","2 × 8 + 3 = 19예요.","⟨2 3/8⟩ = ⟨19/8⟩ — 분자는 19예요."]},{"stem":"⟨3 4/5⟩ ÷ 2를 계산하려고 ⟨3 4/5⟩를 가분수로 고쳤어요. 가분수의 분자는 얼마인가요? 숫자로 쓰세요.","answer":["19"],"explanation":["대분수는 먼저 가분수로 고쳐요.","3 × 5 + 4 = 19예요.","⟨3 4/5⟩ = ⟨19/5⟩ — 분자는 19예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_d#16','math',6,1,'u1','','g6_1_math_u1_review_d','unit_review','M6-1-u1-C7',2,'mc','auto','파란 뚜껑 2개와 노란 뚜껑 1개의 무게가 파란 뚜껑 4개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개의 무게가 ⟨3 1/5⟩ g일 때, 파란 뚜껑 1개의 무게는 몇 g인가요?',ARRAY['M6-1-u1-X13','M6-1-u1-X06']::text[],true,'{"seq":16,"concept":"M6-1-u1-C7","difficulty":2,"kind":"mc","stem":"파란 뚜껑 2개와 노란 뚜껑 1개의 무게가 파란 뚜껑 4개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개의 무게가 ⟨3 1/5⟩ g일 때, 파란 뚜껑 1개의 무게는 몇 g인가요?","options":[{"t":"⟨1 3/5⟩","correct":true},{"t":"⟨4/5⟩","mis":"M6-1-u1-X13"},{"t":"⟨6 2/5⟩","mis":"M6-1-u1-X06"},{"t":"⟨8/15⟩","mis":"M6-1-u1-X13"}],"explanation":["양쪽에서 파란 2개씩 덜어 내면 노란 1개 = 파란 2개예요.","⟨3 1/5⟩ = ⟨16/5⟩이에요.","⟨16/5⟩ × ⟨1/2⟩ = ⟨1 3/5⟩ — 파란 뚜껑 1개는 ⟨1 3/5⟩ g이에요."],"variant_rule":{"alt":[{"stem":"파란 뚜껑 2개와 노란 뚜껑 1개의 무게가 파란 뚜껑 5개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개의 무게가 ⟨5 1/4⟩ g일 때, 파란 뚜껑 1개의 무게는 몇 g인가요?","options":[{"t":"⟨1 3/4⟩","correct":true},{"t":"⟨1 1/20⟩","mis":"M6-1-u1-X13"},{"t":"⟨2 5/8⟩","mis":"M6-1-u1-X13"},{"t":"⟨15 3/4⟩","mis":"M6-1-u1-X06"}],"explanation":["양쪽에서 파란 2개씩 덜어 내면 노란 1개 = 파란 3개예요.","⟨5 1/4⟩ = ⟨21/4⟩이에요.","⟨21/4⟩ × ⟨1/3⟩ = ⟨1 3/4⟩ — 파란 뚜껑 1개는 ⟨1 3/4⟩ g이에요."]},{"stem":"파란 뚜껑 1개와 노란 뚜껑 1개의 무게가 파란 뚜껑 3개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개의 무게가 ⟨2 2/3⟩ g일 때, 파란 뚜껑 1개의 무게는 몇 g인가요?","options":[{"t":"⟨1 1/3⟩","correct":true},{"t":"⟨8/9⟩","mis":"M6-1-u1-X13"},{"t":"⟨2 2/3⟩","mis":"M6-1-u1-X13"},{"t":"⟨5 1/3⟩","mis":"M6-1-u1-X06"}],"explanation":["양쪽에서 파란 1개씩 덜어 내면 노란 1개 = 파란 2개예요.","⟨2 2/3⟩ = ⟨8/3⟩이에요.","⟨8/3⟩ × ⟨1/2⟩ = ⟨1 1/3⟩ — 파란 뚜껑 1개는 ⟨1 1/3⟩ g이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_d#17','math',6,1,'u1','','g6_1_math_u1_review_d','unit_review','M6-1-u1-C2',3,'mc','auto','가 모둠은 피자 3판을 5명이, 나 모둠은 피자 5판을 8명이 똑같이 나누었어요. 한 명이 가지는 피자가 더 많은 모둠은 어디인가요?',ARRAY['M6-1-u1-X11','M6-1-u1-X03']::text[],true,'{"seq":17,"concept":"M6-1-u1-C2","difficulty":3,"kind":"mc","stem":"가 모둠은 피자 3판을 5명이, 나 모둠은 피자 5판을 8명이 똑같이 나누었어요. 한 명이 가지는 피자가 더 많은 모둠은 어디인가요?","options":[{"t":"나 모둠","correct":true},{"t":"가 모둠","mis":"M6-1-u1-X11"},{"t":"두 모둠이 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X03"}],"explanation":["가 모둠 한 명 몫은 3 ÷ 5 = ⟨3/5⟩, 나 모둠은 5 ÷ 8 = ⟨5/8⟩예요.","40으로 통분하면 ⟨3/5⟩ = ⟨24/40⟩, ⟨5/8⟩ = ⟨25/40⟩예요.","⟨3/5⟩ < ⟨5/8⟩라 나 모둠이 더 많아요."],"variant_rule":{"alt":[{"stem":"가 모둠은 시루떡 2개를 5명이, 나 모둠은 시루떡 3개를 7명이 똑같이 나누었어요. 한 명이 가지는 시루떡이 더 많은 모둠은 어디인가요?","options":[{"t":"나 모둠","correct":true},{"t":"가 모둠","mis":"M6-1-u1-X11"},{"t":"두 모둠이 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X03"}],"explanation":["가 모둠 한 명 몫은 2 ÷ 5 = ⟨2/5⟩, 나 모둠은 3 ÷ 7 = ⟨3/7⟩이에요.","35로 통분하면 ⟨2/5⟩ = ⟨14/35⟩, ⟨3/7⟩ = ⟨15/35⟩예요.","⟨2/5⟩ < ⟨3/7⟩이라 나 모둠이 더 많아요."]},{"stem":"가 모둠은 주스 4 L를 9명이, 나 모둠은 주스 3 L를 8명이 똑같이 나누었어요. 한 명이 가지는 주스가 더 많은 모둠은 어디인가요?","options":[{"t":"가 모둠","correct":true},{"t":"나 모둠","mis":"M6-1-u1-X11"},{"t":"두 모둠이 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X03"}],"explanation":["가 모둠 한 명 몫은 4 ÷ 9 = ⟨4/9⟩, 나 모둠은 3 ÷ 8 = ⟨3/8⟩이에요.","72로 통분하면 ⟨4/9⟩ = ⟨32/72⟩, ⟨3/8⟩ = ⟨27/72⟩이에요.","⟨4/9⟩ > ⟨3/8⟩이라 가 모둠이 더 많아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_d#18','math',6,1,'u1','','g6_1_math_u1_review_d','unit_review','M6-1-u1-C3',3,'sa','auto','주스 13 L를 3명이 똑같이 나누어 마시려고 해요. 한 명이 마시는 주스를 대분수로 나타낼 때, 자연수 부분과 분자의 합은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":18,"concept":"M6-1-u1-C3","difficulty":3,"kind":"sa","stem":"주스 13 L를 3명이 똑같이 나누어 마시려고 해요. 한 명이 마시는 주스를 대분수로 나타낼 때, 자연수 부분과 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["13 ÷ 3은 몫 4, 나머지 1이에요.","남은 1도 나누면 13 ÷ 3 = ⟨4 1/3⟩이에요.","자연수 부분과 분자의 합은 4 + 1 = 5예요."],"mis":"M6-1-u1-X15","variant_rule":{"alt":[{"stem":"쌀 19 kg을 4봉지에 똑같이 나누어 담으려고 해요. 한 봉지에 담는 쌀을 대분수로 나타낼 때, 자연수 부분과 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["19 ÷ 4는 몫 4, 나머지 3이에요.","남은 3도 나누면 19 ÷ 4 = ⟨4 3/4⟩이에요.","자연수 부분과 분자의 합은 4 + 3 = 7이에요."]},{"stem":"끈 17 m를 6도막으로 똑같이 나누어 자르려고 해요. 한 도막의 길이를 대분수로 나타낼 때, 자연수 부분과 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["17 ÷ 6은 몫 2, 나머지 5예요.","남은 5도 나누면 17 ÷ 6 = ⟨2 5/6⟩예요.","자연수 부분과 분자의 합은 2 + 5 = 7이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_d#19','math',6,1,'u1','','g6_1_math_u1_review_d','unit_review','M6-1-u1-C4',3,'mc','auto','끈 8 m를 7도막으로 나눈 한 도막과 끈 9 m를 8도막으로 나눈 한 도막 가운데 더 긴 것은 어느 것인가요?',ARRAY['M6-1-u1-X11','M6-1-u1-X03']::text[],true,'{"seq":19,"concept":"M6-1-u1-C4","difficulty":3,"kind":"mc","stem":"끈 8 m를 7도막으로 나눈 한 도막과 끈 9 m를 8도막으로 나눈 한 도막 가운데 더 긴 것은 어느 것인가요?","options":[{"t":"끈 8 m를 7도막으로 나눈 한 도막","correct":true},{"t":"끈 9 m를 8도막으로 나눈 한 도막","mis":"M6-1-u1-X11"},{"t":"두 도막의 길이가 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X03"}],"explanation":["8 ÷ 7 = 8 × ⟨1/7⟩ = ⟨1 1/7⟩, 9 ÷ 8 = 9 × ⟨1/8⟩ = ⟨1 1/8⟩이에요.","56으로 통분하면 ⟨1 1/7⟩ = ⟨64/56⟩, ⟨1 1/8⟩ = ⟨63/56⟩이에요.","그래서 더 긴 것은 끈 8 m를 7도막으로 나눈 한 도막이에요."],"variant_rule":{"alt":[{"stem":"끈 9 m를 4도막으로 나눈 한 도막과 끈 7 m를 3도막으로 나눈 한 도막 가운데 더 긴 것은 어느 것인가요?","options":[{"t":"끈 7 m를 3도막으로 나눈 한 도막","correct":true},{"t":"끈 9 m를 4도막으로 나눈 한 도막","mis":"M6-1-u1-X11"},{"t":"두 도막의 길이가 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X03"}],"explanation":["9 ÷ 4 = 9 × ⟨1/4⟩ = ⟨2 1/4⟩, 7 ÷ 3 = 7 × ⟨1/3⟩ = ⟨2 1/3⟩이에요.","12로 통분하면 ⟨2 1/4⟩ = ⟨27/12⟩, ⟨2 1/3⟩ = ⟨28/12⟩이에요.","그래서 더 긴 것은 끈 7 m를 3도막으로 나눈 한 도막이에요."]},{"stem":"끈 6 m를 5도막으로 나눈 한 도막과 끈 5 m를 4도막으로 나눈 한 도막 가운데 더 긴 것은 어느 것인가요?","options":[{"t":"끈 5 m를 4도막으로 나눈 한 도막","correct":true},{"t":"끈 6 m를 5도막으로 나눈 한 도막","mis":"M6-1-u1-X11"},{"t":"두 도막의 길이가 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X03"}],"explanation":["6 ÷ 5 = 6 × ⟨1/5⟩ = ⟨1 1/5⟩, 5 ÷ 4 = 5 × ⟨1/4⟩ = ⟨1 1/4⟩이에요.","20으로 통분하면 ⟨1 1/5⟩ = ⟨24/20⟩, ⟨1 1/4⟩ = ⟨25/20⟩예요.","그래서 더 긴 것은 끈 5 m를 4도막으로 나눈 한 도막이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_d#20','math',6,1,'u1','','g6_1_math_u1_review_d','unit_review','M6-1-u1-C5',3,'error','auto','⟨7/8⟩ ÷ 2에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u1-X06','M6-1-u1-X15']::text[],true,'{"seq":20,"concept":"M6-1-u1-C5","difficulty":3,"kind":"error","stem":"⟨7/8⟩ ÷ 2에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"여울 — 「⟨7/8⟩ × 2 = ⟨1 3/4⟩으로 계산해.」","correct":true,"mis_target":"M6-1-u1-X06"},{"t":"라온 — 「⟨7/8⟩ × ⟨1/2⟩로 바꾸어 계산하면 돼.」","mis":"M6-1-u1-X15"},{"t":"예준 — 「몫은 ⟨7/8⟩보다 작아.」","mis":"M6-1-u1-X15"}],"explanation":["2로 나누면 양이 작아져야 해요.","⟨7/8⟩ × 2 = ⟨1 3/4⟩은 오히려 커요.","⟨7/8⟩ ÷ 2 = ⟨7/8⟩ × ⟨1/2⟩ = ⟨7/16⟩ — 여울은 나누는 수를 그대로 곱했어요."],"variant_rule":{"alt":[{"stem":"⟨4/7⟩ ÷ 3에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「⟨4/7⟩ × 3 = ⟨1 5/7⟩로 계산해.」","correct":true,"mis_target":"M6-1-u1-X06"},{"t":"도윤 — 「⟨4/7⟩ × ⟨1/3⟩로 바꾸어 계산하면 돼.」","mis":"M6-1-u1-X15"},{"t":"하린 — 「몫은 ⟨4/7⟩보다 작아.」","mis":"M6-1-u1-X15"}],"explanation":["3으로 나누면 양이 작아져야 해요.","⟨4/7⟩ × 3 = ⟨1 5/7⟩는 오히려 커요.","⟨4/7⟩ ÷ 3 = ⟨4/7⟩ × ⟨1/3⟩ = ⟨4/21⟩ — 수아는 나누는 수를 그대로 곱했어요."]},{"stem":"⟨5/6⟩ ÷ 2에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민준 — 「⟨5/6⟩ × 2 = ⟨1 2/3⟩로 계산해.」","correct":true,"mis_target":"M6-1-u1-X06"},{"t":"서연 — 「⟨5/6⟩ × ⟨1/2⟩로 바꾸어 계산하면 돼.」","mis":"M6-1-u1-X15"},{"t":"지호 — 「몫은 ⟨5/6⟩보다 작아.」","mis":"M6-1-u1-X15"}],"explanation":["2로 나누면 양이 작아져야 해요.","⟨5/6⟩ × 2 = ⟨1 2/3⟩는 오히려 커요.","⟨5/6⟩ ÷ 2 = ⟨5/6⟩ × ⟨1/2⟩ = ⟨5/12⟩ — 민준은 나누는 수를 그대로 곱했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_d#21','math',6,1,'u1','','g6_1_math_u1_review_d','unit_review','M6-1-u1-C6',3,'mc','auto','넓이가 ⟨6 2/3⟩ m²이고 가로가 5 m인 직사각형이 있어요. 세로는 몇 m인가요?',ARRAY['M6-1-u1-X10','M6-1-u1-X06']::text[],true,'{"seq":21,"concept":"M6-1-u1-C6","difficulty":3,"kind":"mc","stem":"넓이가 ⟨6 2/3⟩ m²이고 가로가 5 m인 직사각형이 있어요. 세로는 몇 m인가요?","options":[{"t":"⟨1 1/3⟩","correct":true},{"t":"⟨6 2/15⟩","mis":"M6-1-u1-X10"},{"t":"⟨1 13/15⟩","mis":"M6-1-u1-X10"},{"t":"⟨33 1/3⟩","mis":"M6-1-u1-X06"}],"explanation":["(직사각형의 넓이) = (가로) × (세로)이니 세로 = 넓이 ÷ 가로예요.","⟨6 2/3⟩ ÷ 5 = ⟨20/3⟩ × ⟨1/5⟩이에요.","⟨20/3⟩ × ⟨1/5⟩ = ⟨1 1/3⟩ — 세로는 ⟨1 1/3⟩ m예요."],"variant_rule":{"alt":[{"stem":"넓이가 ⟨4 2/3⟩ m²이고 가로가 3 m인 직사각형이 있어요. 세로는 몇 m인가요?","options":[{"t":"⟨1 5/9⟩","correct":true},{"t":"⟨4 2/9⟩","mis":"M6-1-u1-X10"},{"t":"2","mis":"M6-1-u1-X10"},{"t":"14","mis":"M6-1-u1-X06"}],"explanation":["(직사각형의 넓이) = (가로) × (세로)이니 세로 = 넓이 ÷ 가로예요.","⟨4 2/3⟩ ÷ 3 = ⟨14/3⟩ × ⟨1/3⟩이에요.","⟨14/3⟩ × ⟨1/3⟩ = ⟨1 5/9⟩ — 세로는 ⟨1 5/9⟩ m예요."]},{"stem":"넓이가 ⟨5 1/4⟩ m²이고 가로가 2 m인 직사각형이 있어요. 세로는 몇 m인가요?","options":[{"t":"⟨2 5/8⟩","correct":true},{"t":"⟨5 1/8⟩","mis":"M6-1-u1-X10"},{"t":"⟨2 3/4⟩","mis":"M6-1-u1-X10"},{"t":"⟨10 1/2⟩","mis":"M6-1-u1-X06"}],"explanation":["(직사각형의 넓이) = (가로) × (세로)이니 세로 = 넓이 ÷ 가로예요.","⟨5 1/4⟩ ÷ 2 = ⟨21/4⟩ × ⟨1/2⟩이에요.","⟨21/4⟩ × ⟨1/2⟩ = ⟨2 5/8⟩ — 세로는 ⟨2 5/8⟩ m예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_d#22','math',6,1,'u1','','g6_1_math_u1_review_d','unit_review','M6-1-u1-C7',3,'sa','auto','조건을 바꾸어 보아요. 노란 뚜껑 1개가 ⟨1 5/7⟩ g이고 파란 뚜껑 4개와 무게가 같아요. 파란 뚜껑 1개의 무게를 기약분수(가분수)로 나타낼 때 분모와 분자의 합은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":22,"concept":"M6-1-u1-C7","difficulty":3,"kind":"sa","stem":"조건을 바꾸어 보아요. 노란 뚜껑 1개가 ⟨1 5/7⟩ g이고 파란 뚜껑 4개와 무게가 같아요. 파란 뚜껑 1개의 무게를 기약분수(가분수)로 나타낼 때 분모와 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["파란 뚜껑 1개 = ⟨1 5/7⟩ ÷ 4예요.","⟨12/7⟩ ÷ 4 = ⟨12/7⟩ × ⟨1/4⟩ = ⟨3/7⟩이에요.","분모와 분자의 합은 7 + 3 = 10이에요."],"mis":"M6-1-u1-X15","variant_rule":{"alt":[{"stem":"조건을 바꾸어 보아요. 노란 뚜껑 1개가 ⟨2 1/3⟩ g이고 파란 뚜껑 7개와 무게가 같아요. 파란 뚜껑 1개의 무게를 기약분수(가분수)로 나타낼 때 분모와 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["파란 뚜껑 1개 = ⟨2 1/3⟩ ÷ 7이에요.","⟨7/3⟩ ÷ 7 = ⟨7/3⟩ × ⟨1/7⟩ = ⟨1/3⟩이에요.","분모와 분자의 합은 3 + 1 = 4예요."]},{"stem":"조건을 바꾸어 보아요. 노란 뚜껑 1개가 ⟨3 3/4⟩ g이고 파란 뚜껑 5개와 무게가 같아요. 파란 뚜껑 1개의 무게를 기약분수(가분수)로 나타낼 때 분모와 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["파란 뚜껑 1개 = ⟨3 3/4⟩ ÷ 5예요.","⟨15/4⟩ ÷ 5 = ⟨15/4⟩ × ⟨1/5⟩ = ⟨3/4⟩이에요.","분모와 분자의 합은 4 + 3 = 7이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_d#23','math',6,1,'u1','','g6_1_math_u1_review_d','unit_review','M6-1-u1-C6',4,'sa','auto','자연수 부분이 □이고 분수 부분이 ⟨2/5⟩인 대분수를 4로 나누었더니 ⟨17/20⟩이 되었어요. □에 알맞은 자연수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":23,"concept":"M6-1-u1-C6","difficulty":4,"kind":"sa","stem":"자연수 부분이 □이고 분수 부분이 ⟨2/5⟩인 대분수를 4로 나누었더니 ⟨17/20⟩이 되었어요. □에 알맞은 자연수는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["나누기 전의 수는 ⟨17/20⟩ × 4예요.","⟨17/20⟩ × 4 = ⟨17/5⟩ = ⟨3 2/5⟩예요.","그래서 □는 3이에요."],"mis":"M6-1-u1-X10","variant_rule":{"alt":[{"stem":"□ ÷ 11의 몫이 1보다 작을 때, □에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["□ ÷ 11 = ⟨□/11⟩이에요.","몫이 1보다 작으려면 □가 11보다 작아야 해요.","1부터 10까지 10개예요."]},{"stem":"□ ÷ 7의 몫이 3보다 크고 4보다 작을 때, □에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["21 ÷ 7 = 3, 28 ÷ 7 = 4예요.","□는 21보다 크고 28보다 작아야 해요.","22부터 27까지 6개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_d#24','math',6,1,'u1','','g6_1_math_u1_review_d','unit_review','M6-1-u1-C5',4,'essay','teacher','친구가 ⟨3/5⟩ ÷ 4를 ⟨3/5⟩ × 4 = ⟨12/5⟩로 계산했어요. 이 답이 맞지 않음을 몫의 크기로 설명하고, 바르게 계산해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M6-1-u1-C5","difficulty":4,"kind":"essay","stem":"친구가 ⟨3/5⟩ ÷ 4를 ⟨3/5⟩ × 4 = ⟨12/5⟩로 계산했어요. 이 답이 맞지 않음을 몫의 크기로 설명하고, 바르게 계산해 보세요.","answer_guide":{"answer":"예: ⟨3/5⟩을 4로 나누면 몫은 ⟨3/5⟩보다 작아야 하는데 ⟨12/5⟩는 ⟨3/5⟩보다 커서 맞지 않는다. ÷ 4는 × ⟨1/4⟩이므로 ⟨3/5⟩ ÷ 4 = ⟨3/5⟩ × ⟨1/4⟩ = ⟨3/20⟩이다.","scoring_points":["나누면 작아져야 하는데 ⟨12/5⟩는 커졌다고 썼는가","÷ 4를 × ⟨1/4⟩로 바꾸었는가","⟨3/20⟩을 구했는가"]},"explanation":["⟨3/5⟩ ÷ 4는 ⟨3/5⟩보다 작아야 해요.","⟨12/5⟩는 오히려 커요.","⟨3/5⟩ × ⟨1/4⟩ = ⟨3/20⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_d#25','math',6,1,'u1','','g6_1_math_u1_review_d','unit_review','M6-1-u1-C5',4,'essay','teacher','손 세정제 ⟨4/5⟩ L를 3병에 똑같이 나누어 담으려고 해요. 분자 4가 3으로 나누어떨어지지 않을 때 한 병에 담는 양을 구하는 방법을 설명하고 답을 구해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M6-1-u1-C5","difficulty":4,"kind":"essay","stem":"손 세정제 ⟨4/5⟩ L를 3병에 똑같이 나누어 담으려고 해요. 분자 4가 3으로 나누어떨어지지 않을 때 한 병에 담는 양을 구하는 방법을 설명하고 답을 구해 보세요.","answer_guide":{"answer":"예: 분자 4는 3으로 나누어떨어지지 않으므로 ⟨4/5⟩ 전체를 3등분한 것 중의 1을 구한다. 이것은 ⟨4/5⟩에 ⟨1/3⟩을 곱하는 것과 같아 ⟨4/5⟩ ÷ 3 = ⟨4/5⟩ × ⟨1/3⟩ = ⟨4/15⟩이다. 한 병에는 ⟨4/15⟩ L를 담는다.","scoring_points":["분자가 나누어떨어지지 않음을 짚었는가","÷ 3을 × ⟨1/3⟩로 바꾸는 방법을 썼는가","⟨4/15⟩ L를 구했는가"]},"explanation":["분자 4는 3으로 나누어떨어지지 않아요.","⟨4/5⟩ ÷ 3 = ⟨4/5⟩ × ⟨1/3⟩이에요.","한 병에는 ⟨4/15⟩ L예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
